```openscad
// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// See-through for the screw - the hole runs from the top of the neck
// down through the flange and past the bottom face.

// ---------- Parameters ----------
flange_width = 14;   // flange width along Y (mm)
flange_thick = 2;    // flange thickness along Z (mm), z = 0..2
neck_width   = 7;    // neck width along Y (mm)
neck_top_z   = 6;    // top of neck along Z (mm)
screw_d      = 4.5;  // screw hole diameter (mm)
length_x     = 20;   // part length along X (mm)
eps          = 0.5;  // cutter overshoot past faces (mm)
$fn          = 96;   // curve resolution

// ---------- Model ----------
difference() {
    // T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);
        // Neck (overlaps flange slightly for a clean union)
        translate([-neck_width / 2, -neck_width / 2, flange_thick - 0.01])
            cube([neck_width, neck_width, neck_top_z - flange_thick + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + eps);
}
```

```openscad
// T-shaped nut for aluminium extrusion
// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// Placed using the user's coordinates (X 5..25, Y -7..7), not centred on the origin.

// ---------------- Parameters (mm) ----------------
flange_width   = 14;   // flange width along Y
flange_thick   = 2;    // flange thickness along Z (z = 0 to 2)

neck_width     = 7;    // neck width along Y
neck_height    = 4;    // neck height above flange top (z = 2 to 6)

screw_d        = 4.5;  // through-hole diameter for the screw

slot_length    = 20;   // part length along the extrusion (X)
slot_start_x   = 5;    // slot position on the extrusion (user specified)

eps            = 0.5;  // cutter overshoot past faces

$fn            = 96;   // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    // T profile: flange + neck
    union() {
        // Bottom flange
        translate([slot_start_x, -flange_width / 2, 0])
            cube([slot_length, flange_width, flange_thick]);

        // Neck, centred on the flange in X and Y, rising to z = 6
        translate([slot_start_x - neck_width / 2,
                   -neck_width / 2,
                   flange_thick])
            cube([neck_width, neck_width, neck_height]);
    }

    // Central screw hole, runs through the whole part (z = 0 to 6)
    translate([slot_start_x, 0, -eps])
        cylinder(d = screw_d, h = flange_thick + neck_height + 2 * eps);
}
