// T-shaped nut for aluminium extrusion
// Print orientation: flange flat on bed (z = 0), neck pointing up (+Z)

$fn = 48;

// ---------- Dimensions (mm) ----------
slot_len      = 12;    // flange length along slot (X)
flange_w      = 2.5;   // flange thickness (Z)
neck_w        = 6;     // neck width (Y)
neck_h        = 3;     // neck height above flange (Z)
screw_d       = 3.4;   // screw hole diameter
overcut       = 0.5;   // extra length for clean boolean cuts

// ---------- Derived ----------
total_h = flange_w + neck_h;   // top of neck (Z = 5.5)

// ---------- Model ----------
difference() {
    // T profile
    union() {
        // Flange
        translate([-slot_len/2, -flange_w/2, 0])
            cube([slot_len, flange_w, flange_w]);
        // Neck (overlaps flange slightly to fuse solidly)
        translate([-neck_w/2, -neck_w/2, flange_w - overcut])
            cube([neck_w, neck_w, neck_h + overcut]);
    }

    // Screw hole through everything
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = total_h + 2*overcut);
}
