// T-shaped nut for aluminium extrusion
// Print orientation: flange on the bed (z = 0), neck building upward.
// Placed at the user's specified coordinates: X 0..10, Y -6..6, z = 0..5.5

// ---------- Dimensions (mm) ----------
flange_w      = 12;   // flange width (Y)
flange_t      = 2.5;  // flange thickness (Z), z = 0..2.5
neck_w        = 6;    // neck width (Y)
neck_h        = 5.5;  // neck top height (Z)
screw_d       = 3.4;  // central screw hole diameter
length_x      = 10;   // overall length along X
eps           = 0.5;  // overshoot for clean boolean cuts

$fn = 64;             // smoothness of curved shapes

// ---------- Model ----------
difference() {
    // T profile (overlap between flange and neck for a clean union)
    union() {
        // Flange: rectangle in X/Y, extruded from z = 0 to z = flange_t
        translate([0, -flange_w / 2, 0])
            cube([length_x, flange_w, flange_t]);

        // Neck: centred in X and Y, runs from z = 0 up to z = neck_h
        translate([-neck_w / 2, 0, 0])
            cube([neck_w, flange_t + 1, neck_h]);  // extra 1 mm overlaps the flange
    }

    // Central vertical screw hole, through the entire part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_h + 2 * eps);
}
