    translate([-length_x/2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    // flange
                    [-flange_w/2, -flange_w/2, 0],
                    [ flange_w/2, -flange_w/2, 0],
                    [ flange_w/2,  flange_w/2, 0],
                    [-flange_w/2,  flange_w/2, 0],
                    // neck (overlaps the flange in 2D; the hull creates a solid T)
                    [0, -neck_w/2, flange_t],
                    [0,  neck_w/2, flange_t],
                    [0, -neck_w/2, neck_top_z],
                    [0,  neck_w/2, neck_top_z]
                ]);

    // central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = screw_d, h = neck_top_z + cut_extra);
