difference() {
    // Full frustum (extends 0.01 mm below bed for a clean cut)
    translate([0, 0, -0.01])
        cylinder(d1 = top_d, d2 = bottom_d, h = frustum_h + 0.01);

    // Rubber pad recess in the bottom face
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Central screw hole, through the whole part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = frustum_h + 0.01 + 2 * eps);
}
