```openscad
// Anti-vibration foot for benchtop instrument
// Print orientation: recess facing down on the bed, top face up

// ---- Dimensions (mm) ----
frustum_h     = 12;    // height of truncated cone
bottom_d      = 40;    // cone diameter at z = 0 (recess bottom)
top_d         = 32;    // cone diameter at z = 12 (top face)
recess_d      = 34;    // rubber pad recess diameter
recess_depth  = 2;     // rubber pad recess depth from bottom face
screw_d       = 4.5;   // central screw hole diameter

eps           = 0.5;   // overshoot for clean boolean cuts
$fn           = 128;   // smoothness of curved surfaces

// ---- Derived ----
total_h = frustum_h + recess_depth;   // overall height (recess floor at z = 0)

// ---- Model ----
difference() {
    // Combine cone (z = 0..12) with a small cylinder below it (z = 0..2)
    // so the recess has solid walls down to z = 0.
    union() {
        cylinder(h = frustum_h, d1 = top_d, d2 = bottom_d);
        translate([0, 0, -recess_depth])
            cylinder(h = recess_depth + 0.01, d = bottom_d);
    }

    // Rubber pad recess
    translate([0, 0, -recess_depth])
        cylinder(h = recess_depth + eps, d = recess_d);

    // Central screw hole through the full height
    translate([0, 0, -eps])
        cylinder(h = total_h + 2 * eps, d = screw_d);
}
```

