// Measuring scoop for powders
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
scoop_radius    = 12;    // outer radius of the spherical bowl (mm)
scoop_thickness = 2;     // wall thickness of the bowl (mm)
handle_width    = 12;    // handle width along Y (mm)
handle_thick    = 3;     // handle thickness along Z (mm)
handle_x0       = 10;    // start of handle along X (mm)
handle_x1       = 92;    // end of handle along X (mm)
eps             = 0.5;   // overlap / cut extension to avoid coplanar faces (mm)

$fn = 96;                // facet count for curved surfaces

// Derived
bowl_o     = scoop_radius;                     // outer bowl radius
bowl_inner = scoop_radius - scoop_thickness;   // inner bowl radius
rim_z      = scoop_radius;                     // rim height (centre of sphere)
handle_l   = handle_x1 - handle_x0;            // handle length

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half kept, opens upward
    translate([0, 0, rim_z])
        difference() {
            sphere(r = bowl_o);
            translate([0, 0, -eps])
                sphere(r = bowl_inner);
        }
    // Only the lower half of the outer sphere (z = rim_z - eps down to 0)
    translate([0, 0, -rim_z + eps])
        difference() {
            sphere(r = bowl_o);
            translate([0, 0, eps])
                sphere(r = bowl_inner + 2 * eps);   // keep outer wall above this plane
        }

    // Flat handle along +X, top face flush with the rim (z = rim_z - handle_thick)
    translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
        cube([handle_l, handle_width, handle_thick]);
}
