// Powder scoop - hollow hemisphere bowl with a straight handle along +X
// Print orientation: bowl bottom on the bed (z = 0), opening upward.

// ---------- Parameters ----------
bowl_outer_radius = 12;    // outer radius of the hemispherical bowl
bowl_wall         = 2;     // bowl wall thickness
bowl_rim_z        = 12;    // z of the bowl rim (outer equator)
handle_width      = 8;     // handle width (Y)
handle_thick      = 4;     // handle thickness (Z)
handle_x0         = 10;    // handle start (X)
handle_x1         = 112;   // handle end (X)
eps               = 0.5;   // cutter overshoot past faces

$fn = 96;                  // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Hollow hemisphere bowl
        hull() {
            for (r = [bowl_outer_radius, bowl_outer_radius - bowl_wall])
                translate([0, 0, r])
                    cylinder(r = r, h = bowl_rim_z - r + 0.001);
        }

        // Flat handle, top face flush with the rim
        translate([handle_x0, -handle_width / 2,
                    max(0, bowl_rim_z - handle_thick)])
            cube([handle_x1 - handle_x0, handle_width, handle_thick]);
    }

