// Measuring scoop for powders: half-sphere bowl with a flat handle along +X
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle on top.

$fn = 96;                 // smoothness of curved surfaces

// ---- Bowl ----
bowl_outer_r    = 12;     // outer radius of spherical bowl
bowl_wall       = 2;      // wall thickness
bowl_rim_z      = 12;     // z of rim (lower hemisphere top)
bowl_bottom_z   = 0;      // z of bowl bottom (touches bed)

