handle_t        = 4;      // handle thickness (Z)
handle_x0       = 10;     // handle start (X)
handle_x1       = 112;    // handle end (X)

// ---- Derived ----
bowl_inner_r    = bowl_outer_r - bowl_wall;
embed           = bowl_wall;   // handle sinks this far into rim for a solid union

// ---- Model ----
union() {
    // Hollow hemisphere bowl (open top)
    difference() {
        translate([0, 0, bowl_bottom_z])
            cylinder(r = bowl_outer_r, h = bowl_rim_z - bowl_bottom_z);
        translate([0, 0, bowl_bottom_z + embed])
            cylinder(r = bowl_inner_r, h = bowl_rim_z - (bowl_bottom_z + embed));
    }

    // Straight flat handle along +X
    translate([handle_x0, -handle_w / 2, bowl_rim_z - embed])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
