// Powder scoop - a small scoop for dry powders with a flanged rim and a straight handle
// Print orientation: bowl bottom on the bed (z = 0), rim at the top, handle extending along +X

// ---------- Dimensions (mm) ----------
scoop_r      = 10;    // outer radius of the spherical bowl
scoop_h      = 10;    // height of the bowl (lower hemisphere)
scoop_t      = 1.5;   // wall thickness of the bowl
scoop_rim    = 3;     // flange thickness all around the rim
scoop_handle_w = 10;  // handle width (Y)
scoop_handle_t = 4;   // handle thickness (Z)
scoop_handle_x0 = 8.5; // handle start (X), below the rim to fuse solidly
scoop_head   = 8;     // extra length of the handle at its wide end

$fn = 96;             // resolution for curved surfaces

// ---------- Model ----------
difference() {
    union() {
        // Lower half of a hollow sphere, centred at (0, 0, scoop_h) -> bottom at z = 0
        translate([0, 0, scoop_h])
            difference() {
                sphere(r = scoop_r);
                translate([0, 0, -scoop_h])
                    sphere(r = scoop_r - scoop_t);
            }

        // Horizontal flange at the rim (z = scoop_h)
        cylinder(h = scoop_rim, r = scoop_r + 2, $fn = 192);

        // Straight handle along +X from the right side of the rim
        translate([scoop_r, -scoop_handle_w / 2, scoop_h - scoop_t])
            cube([scoop_handle_x0 - scoop_r + 0.01, scoop_handle_w, scoop_t]);

        // Bulbous handle head, centred on y = 0, growing toward +X
        translate([scoop_handle_x0, -scoop_handle_w / 2, scoop_h - scoop_t])
            linear_extrude(height = scoop_t)
                polygon(points = [
                    [0, 0],
                    [scoop_head, 0],
                    [scoop_head / 2, scoop_handle_w],
                    [scoop_head / 2, -scoop_handle_w]
                ]);
    }

    // Clean up interior pockets below the flange that the cutter missed
    translate([0, 0, scoop_h * 0.7])
        difference() {
            hull() {
                translate([0, 0, -1])
                    cylinder(r = scoop_r + 2);
                translate([scoop_handle_x0 - scoop_r + 0.01, -scoop_handle_w / 2, -1])
                    cube([scoop_head + (scoop_r - 8.5), scoop_handle_w, 2]);
            }
            translate([0, 0, -10])
                cylinder(r = scoop_r - scoop_t + 0.01);
        }
}
