```openscad
// Measuring scoop for powders
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle extending along +X.

$fn = 96;

// --- Bowl ---
outer_radius   = 10;    // outer radius of the hemispherical bowl
wall_thickness = 2;     // wall thickness (liner + outer shell)
rim_radius     = outer_radius + wall_thickness;   // radius of the rim at z = 10

// --- Handle ---
handle_length  = 102;   // handle runs from x = 8 to x = 110 (102 mm)
handle_width   = 8;     // handle width along Y
handle_thick   = 3;     // handle thickness along Z
handle_x_start = 8;     // first contact of handle with the rim

// --- Helpers ---
eps            = 0.5;   // overlap / cut overshoot to avoid coplanar faces

// Upper envelope of the bowl (outer hemisphere and flat floor under it)
module bowl_envelope() {
    union() {
        translate([0, 0, wall_thickness])
            cylinder(h = rim_radius, r = rim_radius, $fn = 96);   // outer hemisphere, centred at z = 10
        translate([0, 0, 0])
            cylinder(h = wall_thickness, r = rim_radius + eps, $fn = 96);   // floor under the bowl
    }
}

module scoop() {
    difference() {
        bowl_envelope();
        // Cavity: lower half of a sphere of diameter 10 mm centred at z = 10
        translate([0, 0, wall_thickness])
            cylinder(h = rim_radius - eps, r = outer_radius / 2, $fn = 96);
    }
}

module handle() {
    translate([handle_x_start, -handle_width / 2, rim_radius - handle_thick])
        cube([handle_length, handle_width, handle_thick]);
}

union() {
    scoop();
    handle();
}
