    translate([0, -handle_width / 2, handle_z0])
        cube([handle_length + overlap, handle_width, handle_thickness]);

    // Bowl: lower half of a hollow sphere, centred at (0, 0, 15)
    translate([0, 0, bowl_rim_z]) {
        difference() {
            sphere(r = bowl_outer_radius);
            translate([0, 0, -bowl_thickness])
                sphere(r = bowl_inner_radius);
        }
    }
