handle_len   = 62;      // length along X (13 to 75)
handle_w     = 12;      // width along Y
handle_t     = 3;       // thickness along Z
handle_top_z = 12;      // top face height (flush with lower rim section)

// --- Helpers ---
eps          = 0.5;     // overlap for clean cuts/uniions
inner_r      = bowl_outer_r - bowl_wall;

difference() {
    union() {
        // Lower half of spherical bowl
        translate([0, 0, bowl_bottom_z])
            sphere(r = bowl_outer_r);
        // Upper part of bowl above rim (thin wall)
        translate([0, 0, bowl_rim_z])
            sphere(r = bowl_outer_r);
    }
    // Remove upper inner quarter sphere to leave only lower half wall
    translate([0, 0, bowl_rim_z - eps])
        sphere(r = inner_r);

    // Flat handle under the rim
    translate([0, -handle_w/2, handle_top_z])
        cube([handle_len, handle_w, handle_t]);
}
