        // Lower half of sphere (z = 0 to 15)
        hull() {
            translate([0, 0, -eps])
                sphere(d = bowl_od);
            for (a = [0, 180])
                rotate([0, 0, a])
                    translate([0, -bowl_od, -eps])
                        sphere(d = bowl_od);
        }
        // Hemispherical cavity, open upward, rim at z = 12..15
        translate([0, 0, -eps])
            sphere(d = bowl_od - 2 * bowl_wall);
    }

