// Cable bridge - rectangular block with 3 semicircular tunnels along Y
// Print orientation: flat on bed, tunnels opening downward

// ---- Dimensions (mm) ----
block_length   = 60;    // X extent
block_width    = 50;    // Y extent
block_height   = 15;    // Z height

tunnel_dia     = 10;    // tunnel diameter
tunnel_count   = 3;     // number of tunnels
tunnel_spacing = 16;    // centre-to-centre spacing along X
tunnel_r       = tunnel_dia / 2;  // 5 mm radius

eps            = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_length/2, -block_width/2, 0])
        cube([block_length, block_width, block_height]);

    // Semicircular tunnels: cylinder axis along Y at z = 0
    for (i = [0 : tunnel_count - 1]) {
        x = (i - (tunnel_count - 1)/2) * tunnel_spacing;
        translate([x, 0, 0])
            rotate([0, 90, 0])
                cylinder(r = tunnel_r, h = block_width + 2*eps, center = true);
    }
}
