// Ring weight that sits around the neck of a flask in a water bath
// Print orientation: flat on the bed, builds upward in +Z

// ---------------- Parameters ----------------
torus_radius    = 25;    // major radius (distance from Z axis to tube centre)
tube_diameter   = 16;    // minor radius * 2 (tube cross-section diameter)
middle_plane_z  = 8;     // Z height of the torus' middle plane
cut_overlap     = 0.5;   // extra length on cutting shapes past faces

$fn = 128;               // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid cylinder that becomes the torus when cut along Z
    cylinder(h = tube_diameter, r = torus_radius);

    // Two opposing half-slabs whose union removes the central core,
    // leaving a ring with its middle plane at middle_plane_z
    union() {
        translate([0, 0, -middle_plane_z])
            cube([torus_radius + cut_overlap, 2 * tube_diameter, cut_overlap]);
        translate([0, 0, middle_plane_z])
            cube([torus_radius + cut_overlap, 2 * tube_diameter, cut_overlap]);
    }
}
