// ---------------- Model ----------------
// A torus in OpenSCAD is created by rotating a circle (the cross-section)
// around the Z axis. The parameter 'major_r' is the distance from the Z
// axis to the centre of the cross-section (ring_centre_r above), and
// 'minor_r' is the cross-section radius.
module torus_body() {
    translate([0, 0, middle_plane_z])
        rotate([0, 90, 0])
            cylinder(r = cross_section_r, h = ring_outside_d, $fn = 96);
}

// Remove the central disk that runs from the middle plane down to the bed.
// Its radius is ring_centre_r + cut_margin, so the cut passes beyond the
// inner wall of the torus even after the cross-section is rotated.
module central_cut() {
    translate([0, 0, middle_plane_z - cut_margin])
        cylinder(r = ring_centre_r + cut_margin,
                 h = cross_section_r + cut_margin,
                 $fn = 96);
}

difference() {
    torus_body();
    central_cut();
}
