// Ring weight for a flask neck, printed flat in a water bath
// Units: mm. Coordinates follow the user's spec (X/Y centred, Z up).

$fn = 96;

// ---- Dimensions ----
cross_section_d = 10;    // diameter of the torus cross-section
ring_radius     = 28;    // radius of the circle the cross-section sweeps
ring_width      = cross_section_d;  // user set width = cross-section diameter
middle_z        = 5;     // height of the cross-section's centre
cut_extra       = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
cross_section_r = cross_section_d / 2;
outer_d         = 2 * (ring_radius + cross_section_r);  // 66 mm across
base_z          = middle_z - cross_section_r;          // z = 0 contact line

module ring_body() {
    // rotate([0,0,90]) maps the 2D (u,v) plane to X/Y and extrudes toward +Z
    rotate([0, 0, 90])
        linear_extrude(height = cross_section_r + cut_extra)
            circle(r = ring_radius, d = cross_section_d);
}

module ring_hole() {
    // inner space: from the axis out to the inner wall (minus overshoot)
    translate([0, 0, base_z])
        cylinder(r = ring_radius - cut_extra, h = ring_width + cut_extra);
}

difference() {
    union() {
        ring_body();
        // a flat plate under the ring so the part is solid down to z = 0
        translate([-(ring_radius + cross_section_r),
                   -(ring_width / 2),
                   0])
            cube([outer_d, ring_width, cross_section_r + cut_extra]);
    }
    ring_hole();
}
