```openscad
// Ring weight that sits around the neck of a flask in a water bath.
// Print orientation: flat on the bed, builds upward in +Z.

// ---------------- Parameters ----------------
cross_section_d   = 16;    // diameter of the torus cross-section (mm)
ring_r            = 35;    // radius of the ring (distance of cross-section centre from Z axis)
ring_h            = 8;     // height of the torus, i.e. position of its middle plane (mm)
cut_extra         = 0.5;   // extra length on cutting shapes to avoid coplanar faces (mm)
$fn               = 128;   // facet count for round features

// Derived
ring_r_outer = ring_r + cross_section_d / 2;   // outer radius of the ring (86 mm across)

// ---------------- Model ----------------
// A torus is the hull of a circle swept around the Z axis.
// The hull is taken over the angle whose cosine runs from -1 to 1,
// which places the cross-section symmetrically about the X axis
// and gives a solid with no holes (the centre is not concave).
module torus_2d() {
    // circle(d = cross_section_d) lies on z = ring_h;
    // rotate([90, 0, 0]) has no effect because the circle is in XY.
    hull() {
        for (a = [0 : 180] )
            rotate([0, 0, a])
                translate([ring_r, 0, 0])
                    circle(d = cross_section_d);
    }
}

difference() {
    torus_2d();

    // cut_out() runs from angle = -90 to angle = 90.
    // Its centre lies at (ring_r - cross_section_d/2) on the X axis,
    // so the cut stops 0.5 mm short of the outer face at angle = 0.
    module cut_out() {
        for (a = [-90 : 1 : 90])
            rotate([0, 0, a])
                translate([ring_r - cross_section_d / 2 - cut_extra, 0, -cut_extra])
                    cube([cross_section_d + 2 * cut_extra,
                          ring_r - cross_section_d / 2 - cut_extra,
                          ring_h + cut_extra]);
    }

    // The union of cut_out at every angle is a cylinder along Z:
    // axis on the X axis at y = ring_r - cross_section_d/2,
    // running from z = 0 up past the top face.
    translate([-(ring_r - cross_section_d / 2 - cut_extra),
               0,
               -cut_extra])
        rotate([90, 0, 0])
            cylinder(h = ring_r - cross_section_d / 2 - cut_extra,
                     len = ring_h + 2 * cut_extra);
}
