// Ring weight that sits around the neck of a flask in a water bath.
// Print orientation: flat on the bed, middle plane at z = 8.

// ---------------- Parameters ----------------
torus_d        = 16;    // diameter of the round cross-section (mm)
torus_r        = 35;    // radius of the Z-axis circle the cross-section centres on (mm)
cut_extra      = 0.5;   // extension of the cutting cylinder past the faces (mm)
$fn            = 128;   // facet count for curved shapes

// Derived
torus_h        = torus_d;                       // cross-section height = diameter
r_cut          = torus_r + cut_extra;          // cutter radius, extended past the faces

// ---------------- Model ----------------
difference() {
    // Flat torus: the cross-section circle sweeps around the Z axis.
    // The circle's centre is at z = torus_h / 2, so the lowest point lies on z = 0.
    rotate([0, 90, 0])
        cylinder(d = torus_d, h = 2 * r_cut, $fn = 128);

    // Central void: a cylinder along Z that runs past the top and bottom faces,
    // leaving a wall throughout the height.
    translate([0, 0, -cut_extra])
        cylinder(d = 2 * r_cut - torus_d, h = torus_h + 2 * cut_extra, $fn = 128);
}
