// Ring weight for a flask neck in a water bath
// Print orientation: flat on the bed, builds upward (+Z)

// ---------------- Parameters ----------------
cross_section_d   = 16;   // diameter of the torus cross-section (mm)
cross_section_r   = 8;    // radius of the cross-section circle (mm)
ring_centre_r     = 35;   // radius of the ring's centreline (mm)
ring_outer_d      = 86;   // overall diameter of the ring (mm)
ring_middle_z     = 8;    // height of the cross-section's centre plane (mm)
cut_margin        = 0.5;  // extra length of cutters past faces (mm)

$fn = 96;                 // facet count for round features

// ---------------- Model ----------------
difference() {
    // The torus: a circle in the X-Y plane swept around the Z axis
    // rotate([90,0,0]) maps the circle's normal to +Z, so the sweep runs along +Z
    rotate([90, 0, 0])
        rotate_extrude(r = ring_centre_r)
            circle(r = cross_section_r);

    // A cylindrical cutter along X, centred on the Z axis.
    // Its axis lies in the ring's middle plane (z = ring_middle_z),
    // so the cut passes straight through the ring (top and bottom).
    translate([0, 0, ring_middle_z])
        rotate([0, 90, 0])
            cylinder(h = ring_outer_d + 2 * cut_margin, r = cut_margin);
}
