// Leaf of a pin hinge
// Print orientation: flat plate on the bed (z = 0), knuckles pointing up

// ---------------- Parameters ----------------
plate_length   = 50;    // plate length along X
plate_width    = 25;    // plate width along Y
plate_thick    = 2.5;   // plate thickness along Z

knuckle_d      = 7;     // knuckle cylinder diameter
knuckle_h      = 10;    // height of each knuckle above plate top
knuckle_count  = 5;     // number of segments along +Y edge
knuckle_pitch  = plate_length / knuckle_count;  // 10 mm per segment

pin_d          = 3;     // pin hole diameter
pin_z          = 3.5;   // pin hole axis height (z)

eps            = 0.5;   // overshoot for clean boolean cuts

$fn = 64;               // circle resolution

// ---------------- Derived ----------------
knuckle_r      = knuckle_d / 2;
plate_top_z    = plate_thick;
knuckle_start  = -plate_length / 2;  // first segment centre X
selected       = [0, 2, 4];          // 1st, 3rd, 5th segments

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Knuckle cylinders along the +Y edge
    for (i = selected) {
        translate([knuckle_start + i * knuckle_pitch,
                   plate_width / 2,
                   plate_top_z])
            cylinder(r = knuckle_r, h = knuckle_h);
    }

    // Pin hole along the axis at y = 12.5, z = 3.5
    translate([knuckle_start, plate_width / 2, pin_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_length + 2 * eps, center = true);
}
```

