// Leaf of a pin hinge
// Print orientation: flat plate on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 50;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle diameter
knuckle_h   = 10;    // height of each knuckle cylinder
knuckle_z   = 3.5;   // bottom of knuckles is this height above bed
knuckle_xs  = [-25, -15, -5, 5, 15]; // segment centre X positions (10 mm steps)
knuckle_is  = [0, 0, 1, 0, 0];    // 1 = present (1st, 3rd, 5th), 0 = absent

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter
pin_overlap = 0.5;   // how far the hole extends past each end of the knuckles

union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckle cylinders along X, visible only in their assigned segments
    for (i = [0 : 4])
        if (knuckle_is[i] == 1)
            translate([knuckle_xs[i], 12.5, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h);
}

// Pin hole running along the axis (Y = 12.5, Z = 3.5) through every knuckle
translate([knuckle_xs[0], 12.5, knuckle_z - pin_overlap])
    rotate([0, 90, 0])
        cylinder(d = pin_d, h = knuckle_h + 2*pin_overlap);
