```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len    = 50;    // plate length along X (mm)
plate_wid    = 25;    // plate width along Y (mm)
plate_thk    = 2.5;   // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d    = 7;     // knuckle diameter (mm)
knuckle_z    = 3.5;   // height of knuckle axis above bed (mm)
knuckle_h    = 10;    // length of each knuckle segment along X (mm)
knuckle_l    = 3;     // number of knuckle segments (1st, 3rd, 5th)
knuckle_y    = plate_wid/2; // y position of knuckle axis (mm)

// ---- Pin ----
pin_d        = 3;     // pin hole diameter (mm)

// ---- Helpers ----
eps          = 0.5;   // overshoot for clean cuts (mm)
segment_span = plate_len - knuckle_h + 1; // distance between segment start/end (mm)

module knuckle() {
    difference() {
        cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
        translate([0, 0, -eps])
            cylinder(d = pin_d, h = knuckle_h + 2*eps, $fn = 96);
    }
}

module hinge_leaf() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along +Y edge: 1st, 3rd, 5th segments of 10 mm each
    for (i = [0, 2, 4]) {
        x = -plate_len/2 + i * segment_span;
        translate([x, knuckle_y, 0])
            rotate([0, 90, 0])
                knuckle();
    }
}

hinge_leaf();
```

