// Leaf of a pin hinge
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len      = 50;    // plate length along X (mm)
plate_wid      = 25;    // plate width along Y (mm)
plate_thk      = 2.5;   // plate thickness along Z (mm)

knuckle_d      = 7;     // knuckle cylinder diameter (mm)
knuckle_z      = 3.5;   // knuckle axis height above bed (mm)
knuckle_count  = 5;     // number of edge segments (1st, 3rd, 5th have knuckles)
knuckle_pitch  = plate_len / knuckle_count; // segment length (mm)

pin_d          = 3;     // pin hole diameter (mm)

eps            = 0.5;   // overlap / overshoot to avoid coplanar faces (mm)

$fn = 64;               // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, sitting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along the +Y edge
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0) { // 1st, 3rd, 5th segments
                translate([i * knuckle_pitch - knuckle_pitch / 2,
                           plate_wid / 2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_len, $fn = 64);
            }
        }
    }

    // Pin hole running along the knuckle axis
    translate([0, plate_wid / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps, $fn = 64);
}
