```openscad
// Pin hinge leaf
// Print orientation: flat plate on the bed (z = 0), centred on the origin in X and Y.
// The plate is 50 mm long (X) and 25 mm wide (Y), with a thickness of 2.5 mm.

// Knuckles are cylinders whose axes run along X, located on the +Y edge of the plate
// at y = 12.5, z = 3.5. They appear on the 1st, 3rd and 5th of 5 equal 10 mm segments.
// Each knuckle is 7 mm in diameter and has a 3 mm pin hole through its axis.

$fn = 72;

// ---------- Plate ----------
plate_len   = 50;   // plate length along X (mm)
plate_wid   = 25;   // plate width along Y (mm)
plate_thk   = 2.5;  // plate thickness along Z (mm)

// ---------- Knuckles ----------
knuckle_d   = 7;    // knuckle cylinder diameter (mm)
knuckle_hole = 3;   // pin hole diameter (mm)
knuckle_z   = 3.5;  // knuckle axis height above bed (mm)
knuckle_n   = 5;    // number of segments along the plate length
knuckle_pitch = plate_len / knuckle_n; // segment length (10 mm)

// There are 3 knuckles, on the 1st, 3rd and 5th segments (0-indexed: 0, 2, 4)
knuckle_count = 2 * knuckle_n / 4 + 1; 

// ---------- Clearances ----------
cut_overlap = 0.5;  // extra length on cutters so no faces are coplanar (mm)

module plate() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_count - 1]) {
        // 10 mm segments along X, centred on the origin
        seg_x = (i - (i < knuckle_count / 2 ? 1 : 0) - (i % 2 == 0 ? 1 : 0)) * knuckle_pitch;
        translate([seg_x, knuckle_y, knuckle_z])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2 * cut_overlap);
                translate([0, 0, -cut_overlap])
                    cylinder(d = knuckle_hole, h = plate_thk + 2 * cut_overlap);
            }
    }
}

union() {
    plate();
    knuckles();
}
```

