```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 60;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_n   = 5;     // number of segments along the edge
knuckle_x0  = -plate_len/2 + 6;  // centre of 1st segment (12 mm segment start)
knuckle_y   = plate_wid/2;       // knuckle axis Y position (12.5 mm)
knuckle_z   = plate_thk;         // knuckle axis Z position (on top face)

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([knuckle_x0 + i * 12, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10, $fn = 96);
            }
        }
    }

    // Pin hole running along X through every knuckle
    translate([knuckle_x0 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_x0 + (knuckle_n - 1) * 12 + eps + 2 * knuckle_d, $fn = 64);
}
```

