// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up

$fn = 96;

// ---- Plate ----
plate_len   = 60;   // X length of plate
plate_wid   = 25;   // Y width of plate
plate_thk   = 3;    // Z thickness of plate

// ---- Knuckles ----
knuckle_d     = 6;  // knuckle diameter
knuckle_count = 5;  // number of segments (only odd ones have knuckles)
knuckle_pitch = 12; // segment length
knuckle_y     = plate_wid / 2; // knuckle axis Y position (12.5)
knuckle_z     = plate_thk;   // knuckle axis on plate top face

// ---- Pin hole ----
pin_d = 2; // hole diameter

