eps = 0.5; // cutter overshoot

module plate() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) { // 1st, 3rd, 5th segments
            x = (i - 1) / 2 * knuckle_pitch;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 10);
        }
    }
}

difference() {
    union() {
        plate();
        knuckles();
    }
    // Pin hole along X through all knuckles
    translate([-plate_len / 2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
}
