```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed (z = 0), knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len      = 60;   // plate length along X (mm)
plate_wid      = 25;   // plate width along Y (mm)
plate_thk      = 3;    // plate thickness along Z (mm)

knuckle_count  = 5;    // number of knuckle segments
knuckle_pitch  = 12;   // spacing between knuckle centres along X (mm)
knuckle_d      = 6;    // knuckle cylinder diameter (mm)
knuckle_y      = 12.5; // knuckle axis Y position (mm)
knuckle_z      = 3;    // knuckle axis height above bed (mm)

pin_d          = 2;    // pin hole diameter (mm)

overlap        = 0.5;  // how far adjacent cylinders overlap along X (mm)
$fn            = 96;   // curve resolution

// ---------------- Derived ----------------
first_x = -knuckle_count * knuckle_pitch / 2;  // X of first (leftmost) knuckle

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles: cylinders whose axes run along X at the given height
    for (i = [0 : knuckle_count - 1]) {
        x = first_x + i * knuckle_pitch;
        // Cylinder tall enough to cover the plate plus a little above the axis
        translate([x, knuckle_y, 0])
            cylinder(d = knuckle_d, h = plate_thk + 2 * overlap, $fn = 96);
    }
}

// ---------------- Pin hole ----------------
// Hole centred on the axis of every knuckle, running along X
translate([first_x - overlap, knuckle_y, knuckle_z])
    rotate([0, 90, 0])
        translate([0, 0, -overlap])
