        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along +Y edge
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0) { // 1st, 3rd, 5th segments
                x = (i % knuckle_count) * knuckle_pitch / 2;
                translate([x, plate_wid/2 - knuckle_pitch/2, 0])
                    rotate([0, 90, 0])
                        cylinder(d = knuckle_d, h = plate_thk, center = true);
