    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            x = (i % knuckle_count) * knuckle_pitch / 2;
            translate([x, plate_wid/2 - knuckle_pitch/2, 0])
                rotate([0, 90, 0])
                    translate([0, 0, -pin_overlap])
                        cylinder(d = pin_d, h = plate_thk + 2 * pin_overlap);
