    for (i = [0 : knuckle_count - 1]) {
        x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
        translate([x, 15, 0]) {
            // Knuckle body
            rotate([0, 90, 0])
                cylinder(d = knuckle_d, h = plate_thk + 2*knuckle_embed);
