plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 7;     // knuckle cylinder diameter (mm)
knuckle_y   = 10;    // knuckle axis Y position (mm)
knuckle_z   = 3.5;   // knuckle axis height above bed (mm)
knuckle_n   = 3;     // number of knuckle segments
knuckle_w   = plate_len / knuckle_n; // segment length (20 mm)

pin_d       = 2.5;   // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments (skip the middle one)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([-knuckle_w/2 + i * knuckle_w,
                           knuckle_y,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2*eps);
            }
        }
    }

    // Pin hole running along X through every knuckle
    translate([-knuckle_w/2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
```

