// Eccentric cam for shaker mechanism
// Print orientation: disc flat on bed, hub rising upward (+Z)

// ---------------- Parameters ----------------
cam_d        = 40;    // cam disc diameter
cam_t        = 8;     // cam disc thickness
cam_e        = 5;     // cam eccentricity (cam centre at x = 5, y = 0)
hub_d        = 14;    // shaft hub diameter
hub_z0       = 8;     // shaft hub bottom height (z = 8 to 12)
shaft_d      = 6;     // shaft hole diameter
eps          = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------------- Model ----------------
difference() {
    union() {
        // Cam disc, centred at (cam_e, 0, 0), resting on z = 0
        translate([cam_e, 0, 0])
            cylinder(d = cam_d, h = cam_t);

        // Shaft hub, centred on Z axis, spanning z = 8 to 12
        translate([0, 0, hub_z0])
            cylinder(d = hub_d, h = 4 + 0.01);
    }

    // Shaft hole: runs through the hub and continues through the disc
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = cam_t + 2 * eps);
}
