                rotate([0,0,i*pitch]) [outer_r, 0],
            for (i = [0:5])
                rotate([0,0,i*pitch+pitch/2]) [inner_r, 0]
        ]);

    // centre hole
    translate([0,0,-1]) cylinder(d = hole, h = t + 2);
}
