    linear_extrude(height = plate_t)
        polygon([
            for (i = [0 : points - 1]) {
                angle = i * 360 / points + (i % 2) * 90;
                [outer_r * cos(angle), outer_r * sin(angle)];
            }
        ]);

    // Central hole, extends past top and bottom faces
    translate([0, 0, -cut_ext])
        cylinder(d = hole_d, h = plate_t + 2 * cut_ext);
}
