                        translate([r1, 0, 0]) cylinder(h = t, r = r1);
                    else
                        translate([r2, 0, 0]) cylinder(h = t, r = r2);
        }
    translate([0, 0, -eps])
        cylinder(h = t + 2 * eps, d = hole);
