```openscad
// Star-shaped indexing wheel - 8-pointed flat plate
// Print orientation: flat on bed, builds upward in +Z

// ---------------- Parameters ----------------
star_points  = 8;    // number of points (outer and inner)
outer_radius = 30;   // distance of outer points from centre
inner_radius = 18;   // distance of inner points from centre
plate_t      = 4;    // plate thickness (Z)
hole_d       = 6;    // central through-hole diameter
eps          = 0.5;  // cutter overshoot past faces
$fn          = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    // 8-pointed star outline, centred on origin, first outer point on +X
    polygon(points = star_points * 2,
            concat(
                [for (i = [0 : star_points - 1])
                    [outer_radius * cos(i * 360 / star_points),
                     outer_radius * sin(i * 360 / star_points)]],
                [for (i = [0 : star_points - 1])
                    [inner_radius * cos((i + 0.5) * 360 / star_points),
                     inner_radius * sin((i + 0.5) * 360 / star_points)])]
            )
    )

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);

    // Cut down to bed (removes any stray 0.5 mm below z = 0)
    translate([0, 0, -eps])
        cube([outer_radius * 2, inner_radius * 2, eps]);
}
