```openscad
// 8-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

// ---------------- Parameters ----------------
star_points   = 8;    // number of points (and inner vertices)
outer_radius  = 30;   // distance of outer points from centre
inner_radius  = 18;   // distance of inner points from centre
plate_thick   = 4;    // plate thickness (Z)
hole_d        = 6;    // central through-hole diameter
cut_extra     = 0.5;  // extra length on cutters past faces

$fn = 96;             // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline: alternate outer/inner points, first outer on +X axis
    polygon(points = [
        for (i = [0 : star_points - 1])
            rotate([0, 0, i * 360 / star_points])
                [outer_radius, 0]
    ])
    linear_extrude(height = plate_thick) {
        // Duplicate the same 8 inner points shifted by 180 degrees,
        // so the hull sees every vertex in convex position.
        hull() {
            polygon(points = [
                for (i = [0 : star_points - 1])
                    rotate([0, 0, i * 360 / star_points])
                        [inner_radius, 0]
            ]);
            polygon(points = [
                for (i = [0 : star_points - 1])
                    rotate([0, 0, (i + star_points / 2) * 360 / star_points])
                        [inner_radius, 0]
            ]);
        }
    }

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thick + 2 * cut_extra);
}
