            [for (i = [0 : n - 1]) each [
                [outer_r * cos(360 / n * i), outer_r * sin(360 / n * i)]
            ]],
            [for (i = [0 : n - 1]) each [
                [inner_r * cos(360 / n * i + 180 / n),
                 inner_r * sin(360 / n * i + 180 / n)]
            ]]
        ));

    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = t + 2 * eps);
}
