// Star-shaped indexing wheel
// Print orientation: flat on bed, building up in +Z

$fn = 96;

// ---- Dimensions (mm) ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 15;   // distance of inner points from centre
points    = 8;    // number of points (and inner vertices)
thickness = 5;    // plate thickness
hole_d    = 6;    // central through-hole diameter

// ---- Derived ----
angle_step = 360 / points;   // 45 deg between successive outer points
eps        = 0.5;           // overshoot for clean boolean cuts

difference() {
    // Star outline: hull between the two concentric point sets
    hull() {
        // Outer points, first on +X axis
        for (i = [0 : points - 1])
            translate([outer_r * cos(i * angle_step),
                       outer_r * sin(i * angle_step),
                       0])
                cube([1, 1, thickness]);

        // Inner points, interleaved in angle
        for (i = [0 : points - 1])
            translate([inner_r * cos(i * angle_step + angle_step / 2),
                       inner_r * sin(i * angle_step + angle_step / 2),
                       0])
                cube([1, 1, thickness]);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
