outer_radius   = 30;   // distance of outer points from centre
inner_radius   = 15;   // distance of inner points from centre
plate_thick    = 5;    // plate thickness (Z)
hole_diameter  = 6;    // central through-hole diameter
point_offset   = 0;    // angle of first outer point (deg, 0 = +X axis)
cut_extra      = 0.5;  // overshoot of cutters past faces

$fn = 96;              // smoothness for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline: hull between outer and inner point circles
    hull() {
        // Outer points
        for (i = [0 : star_points - 1])
            rotate([0, 0, point_offset + i * 360 / star_points])
                translate([outer_radius, 0, 0])
                    cylinder(h = plate_thick, $fn = 64);

        // Inner points
        for (i = [0 : star_points - 1])
            rotate([0, 0, point_offset + (i + 0.5) * 360 / star_points])
                translate([inner_radius, 0, 0])
                    cylinder(h = plate_thick, $fn = 64);
    }

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(h = plate_thick + 2 * cut_extra, d = hole_diameter, $fn = 64);
}
