eps          = 0.5; // overcut so cuts are not coplanar

// Half-width at an arbitrary height z (linear interpolation)
function half_w(z) =
    (bottom_w * (top_h - z) + top_w * (z - bottom_h)) / (2 * top_h);

difference() {
    // Solid frustum
    hull() {
        translate([-half_w(bottom_h), -half_w(bottom_h), bottom_h])
            cube([bottom_w, bottom_w, top_h - bottom_h + eps]);

        translate([-half_w(top_h), -half_w(top_h), top_h])
            cube([top_w, top_w, eps]);
    }

    // Pocket, centred, open at the top face
    translate([0, 0, top_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
