h_total   = top_h - bottom_h;
tw        = bottom_w - top_w;   // taper per side (35 mm)
tfl       = max(tw / 2, pocket_d + 2); // thickness of wall under pocket

module frustum() {
    // Hull of two equal-area end faces gives a straight-walled prism,
    // which is a square frustum with 45-degree (or steeper) sides.
    hull() {
        square([bottom_w], center = true);      // z = 0
        translate([0, 0, top_h])
            square([top_w], center = true);     // z = 30
    }
}

difference() {
    frustum();

    // Pocket in top face, open upward
    translate([0, 0, top_h - pocket_d])
        square([pocket_w], center = true);

    // Solid floor below pocket (prevents coincident faces)
    translate([0, 0, bottom_h])
        cube([bottom_w, bottom_w, tfl]);
}
