```openscad
// Tapered riser block with a square pocket
// Units: mm. Print orientation: base on bed (z = 0), pocket facing up.

$fn = 64;

// ---- Dimensions ----
base_w      = 60;    // base square side length
base_h      = 30;    // total height of the frustum
top_w       = 40;    // top square side length
pocket_w    = 32;    // pocket square side length
pocket_d    = 5;     // pocket depth from the top face
eps         = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
pocket_top_z = base_h - pocket_d;   // z of the pocket's top opening
side_len(z)  = base_w - (z / base_h) * (base_w - top_w);   // edge length at height z

module base_frustum() {
    // hull of a full base square up to the top face, then down to a
    // single point 1 mm above the top face so the hull stays solid
    hull() {
        translate([-side_len(0) / 2, -side_len(0) / 2, 0])
            cube([side_len(0), side_len(0), base_h]);
        for (s = [top_w, 1])
            translate([-s / 2, -s / 2, base_h - eps])
                cube([s, s, eps]);
    }
}

module square_pocket() {
    // cutter extends past top, bottom and side faces
    translate([-pocket_w / 2, -pocket_w / 2, pocket_top_z - eps])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}

difference() {
    base_frustum();
    square_pocket();
}
