// Tapered riser block with a square pocket
// Print orientation: bottom face on bed (z = 0), pocket opening upward

$fn = 64;

// ---- Block dimensions ----
block_w    = 60;   // bottom face width (X)
block_d    = 60;   // bottom face depth (Y)
block_h    = 30;   // top face height (Z)
slope      = 0.5;  // side slope: rise 1 mm per run 2 mm (45 deg)

// ---- Pocket dimensions ----
pocket_w   = 32;   // pocket width (X)
pocket_d   = 32;   // pocket depth (Y)
pocket_l   = 5;    // pocket length along Z (depth)

// ---- Clearance for clean cuts ----
eps        = 0.5;  // overshoot past cut faces

// Derived: top face size from taper
top_w = block_w - 2 * slope * block_h;  // 60 - 2*0.5*30 = 30
top_d = block_d - 2 * slope * block_h;  // 60 - 2*0.5*30 = 30

module block() {
    difference() {
        // Square frustum: hull between full bottom and reduced top faces
        hull() {
            translate([-block_w/2, -block_d/2, 0])
                cube([block_w, block_d, eps]);
            translate([-top_w/2, -top_d/2, block_h])
                cube([top_w, top_d, eps]);
        }
    }
}

module pocket() {
    // Centred pocket, extended above top face to avoid coplanar faces
    translate([-pocket_w/2, -pocket_d/2, block_h - pocket_l + eps])
        cube([pocket_w, pocket_d, pocket_l - eps + 0.01]);
}

union() {
    block();
    pocket();
}
