```openscad
// Tapered riser block with a square pocket
// Units: mm. Print orientation: bottom face on the bed (z = 0).

$fn = 64;

// ---- Frustum dimensions ----
bottom_w   = 60;   // bottom square side length (X and Y)
bottom_h   = 0;    // bottom face height (z = 0)
top_w      = 40;   // top square side length (X and Y)
top_h      = 30;   // top face height (z = 30)

// ---- Pocket dimensions ----
pocket_w   = 32;   // pocket square side length (X and Y)
pocket_d   = 5;    // pocket depth from the top face

// ---- Modelling helpers ----
eps        = 0.5;  // overshoot for clean boolean cuts

// Derived
total_h    = top_h - bottom_h;
slope      = (bottom_w - top_w) / 2 / total_h;  // half-width growth per mm of height

// Check: does the slope reproduce the bottom width when extrapolated to z = 0?
assert(abs((bottom_w + top_w) / 2 - slope * total_h - top_w / 2) < 0.001,
       "Riser dimensions are inconsistent");

module riser() {
    hull() {
        for (h = [bottom_h, top_h]) {
            w = top_w + (bottom_w - top_w) * (h - top_h) / total_h;
            translate([-w / 2, -w / 2, h])
                cube([w, w, 1]);
        }
    }
}

module pocket() {
    // Pocket has open top at z = top_h, closed bottom at z = top_h - pocket_d
    translate([0, 0, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}

difference() {
    riser();
    pocket();
}
