        // Frustum: bottom square at z = 0, top square at z = top_h
        hull() {
            translate([-base_w/2, -base_w/2, 0])
                cube([base_w, base_w, top_h]);
            translate([-top_w/2, -top_w/2, top_h])
                cube([top_w, top_w, 1]);
