    hull() {
        // lower cross-section at z = 0
        translate([-base_w/2, -base_w/2, 0])
            cube([base_w, base_w, 1]);
        // upper cross-section at z = top_h + 1 (keeps the same taper)
        translate([-top_w/2 - side_taper, -top_w/2 - side_taper, top_h + 1])
            cube([top_w + 2*side_taper, top_w + 2*side_taper, 1]);
    }
    difference() {
        hull() {
            translate([-base_w/2, -base_w/2, 0])
                cube([base_w, base_w, top_h + 1]);
            translate([-top_w/2, -top_w/2, top_h])
                cube([top_w, top_w, 1]);
        }
        translate([-pocket_w/2, -pocket_w/2, pocket_top_z - pocket_d])
            cube([pocket_w, pocket_w, pocket_d + 0.5]);
