pocket_d    = 8;    // pocket depth from top face (mm)
eps         = 0.5;  // cutter overshoot past faces (mm)
$fn         = 64;   // curve resolution (for consistency)

// Derived
pocket_floor_z = height - pocket_d;          // z of pocket floor
half_base      = base_size  / 2;
half_top       = top_size   / 2;
// Taper: each side widens by (half_base - half_top) over height

// ---------------- Model ----------------
difference() {
    // Frustum body, edges parallel to X and Y
    linear_extrude(height = height)
        polygon([
            [-half_base, -half_base],
            [ half_base, -half_base],
            [ half_base,  half_base],
            [-half_base,  half_base]
        ]);

    // Square pocket, centred, open to the top face
    translate([0, 0, pocket_floor_z])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
