// Tapered riser block with a square pocket
// Units: mm. Print orientation: bottom face on bed (z = 0).

$fn = 64;

// ---- Block dimensions ----
base_w    = 80;    // bottom square side (X and Y)
base_h    = 30;    // block height (Z)
top_w     = 40;    // top square side (X and Y)

// ---- Pocket dimensions ----
pocket_w  = 32;    // pocket square side (X and Y)
pocket_d  = 8;     // pocket depth from top face (Z)

// ---- Derived ----
pocket_z  = base_h - pocket_d;       // pocket floor height
eps       = 0.5;                     // overshoot for clean cuts

// Taper rate: width grows by (base_w - top_w) over height base_h
twist = (base_w - top_w) / base_h;   // per-mm growth factor for each corner

module hull_block() {
    for (x = [-base_w / 2, base_w / 2])
        for (y = [-base_w / 2, base_w / 2])
            translate([x, y, 0])
                cube([1, 1, base_h]);

    for (x = [-top_w / 2, top_w / 2])
        for (y = [-top_w / 2, top_w / 2])
            translate([x, y, base_h])
                cube([1, 1, twist]);
}

difference() {
    hull_block();

    // Square pocket centred in X/Y, open to the top face
    translate([0, 0, pocket_z])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
