// Pull handle for cabinet door
// Print orientation: posts stand on the bed (z = 0), bar on top.

$fn = 64;

// ---- Posts ----
post_d      = 12;   // post diameter (X and Y)
post_h      = 30;   // post height (z = 0 to 30)
post_x      = [-40, 40]; // post axis X positions (y = 0)
screw_d     = 3.4;  // screw hole diameter
screw_depth = 10;   // screw hole depth from bottom face

// ---- Bar ----
bar_len     = 92;   // bar length along X
bar_w       = 12;   // bar width along Y
bar_top_z   = 38;   // top of bar (z = 30 to 38)
bar_t       = bar_top_z - post_h; // bar thickness (8 mm)

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

module post(x) {
    translate([x, 0, 0])
        cylinder(d = post_d, h = post_h);
    // Screw hole from bottom face
    translate([x, 0, -eps])
        cylinder(d = screw_d, h = post_h + screw_depth + eps);
}

union() {
    for (x = post_x) post(x);
    // Bar, overlapping slightly into posts for a solid union
    translate([-bar_len / 2, -bar_w / 2, post_h - 1])
        cube([bar_len, bar_w, bar_t + 1]);
}
