eps        = 0.5;   // overshoot for clean boolean cuts
post_r     = post_d / 2;

difference() {
    union() {
        // Two round posts
        for (sx = [-1, 1])
            translate([sx * post_x, 0, 0])
                cylinder(r = post_r, h = post_h);

        // Straight bar, centred in X and Y, resting on posts
        translate([-bar_l / 2, -bar_w / 2, post_h])
            cube([bar_l, bar_w, bar_t]);
    }

    // Screw holes, up the axis from the bottom face of each post
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(r = screw_d / 2, h = screw_n + 2 * eps);
}
