$fn = 64;

// ---- Posts ----
post_d     = 14;    // post diameter
post_h     = 30;    // post height (z = 0 to 30)
post_x     = [-40, 40]; // post axis X positions (y = 0)
screw_d    = 3.4;   // screw hole diameter
screw_len  = 10;    // screw hole depth from bottom face

// ---- Bar ----
bar_l      = 94;    // bar length along X
bar_w      = 14;    // bar width along Y
bar_t      = 8;     // bar thickness (z = 30 to 38)

// ---- Misc ----
eps        = 0.5;   // overshoot for clean cuts / overlaps

union() {
    // Posts with screw holes
    for (x = post_x)
        translate([x, 0, 0])
            difference() {
                cylinder(d = post_d, h = post_h);
                translate([0, 0, -eps])
                    cylinder(d = screw_d, h = screw_len + 2 * eps);
            }

    // Bar, slightly overlapping the posts for a solid union
    translate([-bar_l / 2, -bar_w / 2, post_h - eps])
        cube([bar_l, bar_w, bar_t + eps]);
}
