// Pull handle for a cabinet door
// Print orientation: posts on the bed (z = 0), bar on top (z = 30..38)

$fn = 64;

// ---- Posts ----
post_d     = 14;    // post diameter
post_h     = 30;    // post height (z = 0 to 30)
post_x     = [-40, 40]; // post centre X positions
post_y     = 0;     // post centre Y position

// ---- Bar ----
bar_len    = 94;    // bar length along X
bar_w      = 14;    // bar width along Y
bar_t      = 8;     // bar thickness (z = 30 to 38)
bar_x      = 0;     // bar centre X
bar_y      = 0;     // bar centre Y

// ---- Screw holes ----
screw_d    = 3.4;   // screw hole diameter
screw_dep  = 10;    // screw hole depth from bottom face (z = 0 to 10)
eps        = 0.5;   // overshoot so cutters pass through faces

// Derived
bar_z0     = post_h;        // bar bottom at top of posts
overlap    = 0.01;          // small overlap so bar fuses into posts

module post() {
    cylinder(d = post_d, h = post_h);
    // screw hole from bottom face up along the axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = post_h + eps + screw_dep);
}

union() {
    // Posts
    for (x = post_x)
        translate([x, post_y, 0])
            post();

    // Bar
    translate([bar_x, bar_y, bar_z0 - overlap])
        cube([bar_len, bar_w, bar_t + overlap]);
}
