// Flat dog-bone tensile specimen
// Units: mm. Print flat on the bed, builds up in +Z.

$fn = 64;

// ---------- Dimensions ----------
specimen_length  = 110;   // overall length along X
thickness        = 3;     // specimen thickness (Z)

grip_width       = 15;    // grip section width (Y)
grip_length      = 30;    // grip section length (X)

gauge_width      = 8;     // gauge section width (Y)
gauge_length     = 30;    // gauge section length (X)

transition_length = 10;    // transition section length (X) on each side

eps              = 0.5;    // overlap for clean booleans / unions

// ---------- Derived ----------
total_grip    = grip_length * 2;               // both grip sections
mid_start     = -specimen_length / 2 + total_grip + transition_length;
mid_end       = specimen_length / 2 - transition_length;
width_profile = [grip_width, gauge_width, grip_width]; // for transition hull

// ---------- Model ----------
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * (specimen_length / 2 - grip_length),
                   -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([mid_start, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transition sections (hull between grip and gauge volumes)
    for (s = [-1, 1])
        translate([s * transition_length - (specimen_length / 2 - grip_length - transition_length),
                   -grip_width / 2, 0])
            rotate([90, 0, 0])
                hull() {
                    for (i = [0 : 1])
                        translate([i * transition_length,
                                   width_profile[s * (i - 0.5) - 0.5] / 2,
                                   0])
                            square([thickness / 2 + eps,
                                   transition_length / 2 + eps],
                                   center = true);
                }
}
