// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // grip-to-gauge transition length (X)

$fn = 64;

// ---------- Derived ----------
a     = gauge_width;    // gauge width
b     = grip_width;     // grip width
L     = total_length;   // total length
w     = grip_length;    // grip length (called w per user spec)
l     = gauge_length;   // gauge length (called l per user spec)
t     = thickness;      // thickness
R     = transition_len; // transition radius/length (called R per user spec)

// ---------- Model ----------
module flat_dogbone_2d() {
    // 2D profile in XY: grip (left) -> transition -> gauge -> transition -> grip (right)
    polygon(points = [
        [-L/2 + w, -b/2],
        [ L/2 - w, -b/2],
        [ L/2 - w,  b/2],
        [ -L/2 + w,  b/2],

        // right grip -> gauge transition
        [ R - l/2,  (a + b) * (R - l/2) / (w + l) - b/2],
        [ R - l/2,  (a + b) * (R - l/2) / (w + l) + b/2],
        [ l/2,      a],
        [-l/2,      a],
        [-R + l/2,  (a + b) * (-R + l/2) / (w + l) + b/2],
        [-R + l/2,  (a + b) * (-R + l/2) / (w + l) - b/2],

        // left grip
        [ -L/2 + w,  b/2],
        [ -L/2 + w, -b/2]
    ])
}

// ---------- Print ----------
module flat_dogbone() {
    // User said "transitions whose width changes linearly", so use 2D straight edges.
    difference() {
        linear_extrude(height = thickness)
            flat_dogbone_2d();

        // Extra cut clearance past faces
        translate([0, 0, -1])
            linear_extrude(height = thickness + 2)
                flat_dogbone_2d();
    }
}

flat_dogbone();
