// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, builds upward in +Z
// Positioned to be centred on the origin in X and Y, except as noted

// ---------------- Parameters ----------------
specimen_thickness = 3;     // plate thickness (Z) mm

total_length       = 110;   // overall length along X mm

gauge_width        = 8;     // narrow gauge section width (Y) mm
gauge_length       = 30;    // gauge section length (X) mm

grip_width         = 15;    // grip section width (Y) mm
grip_length        = 30;    // grip section length (X) mm

transition_length  = 10;    // length of each grip-gauge transition (X) mm

cut_extra          = 0.5;   // extra length on cutters to avoid coplanar faces mm

$fn = 64;

// ---------------- Derived ----------------
x0 = -total_length / 2;     // start of left grip (outer end)
w0 = grip_width;            // grip width
l0 = grip_length;           // grip length

x1 = x0 + l0;               // end of left grip / start of left transition
w1 = transition_width(x1);  // transition width at its outer end (x1)

x2 = x1 + transition_length; // end of left transition / start of gauge
w2 = transition_width(x2);  // transition width at its inner end (x2)

x3 = x2 + gauge_length;     // end of gauge / start of right transition
w3 = transition_width(x3);  // right transition width at its inner end (x3)

x4 = x3 + transition_length; // end of right transition / start of right grip
w4 = transition_width(x4);  // right transition width at its outer end (x4)

// ---------------- Modules ----------------
module transition() {
    // One transition block, placed between a grip and the gauge.
    // Outside the block (at x - transition_length and x + transition_length)
    // the width follows the spec: 15 mm at the grip end, 8 mm at the gauge end.
    rotate([0, 90, 0])
        linear_extrude(height = specimen_thickness)
            polygon(points = [
                [0, 0],
                [transition_length, 0],
                [transition_length, w1],
                [0, w1]
            ]);
}

// ---------------- Model ----------------
union() {
    // Left grip + its adjacent transition
    translate([x0, 0, 0])
        union() {
            cube([l0, w0, specimen_thickness]);
            translate([l0, 0, 0])
                transition();
        }

    // Gauge section (no overcuts into the gauge)
    translate([x2 - gauge_length, 0, 0])
        cube([gauge_length, w2, specimen_thickness]);

    // Right grip + its adjacent transition
    translate([x3, 0, 0])
        union() {
            cube([l0, w4, specimen_thickness]);
            translate([-l0, 0, 0])
                translate([-transition_length, 0, 0])
                    transition();
        }
}
