        rotate([0, 0, s > 0 ? 90 : -90])
            linear_extrude(height = thickness)
                polygon([
                    [x0, 0],
                    [x0 + transition_len, 0],
                    [x0 + transition_len, grip_width > gauge_width ? grip_width : gauge_width],
                    [x0, grip_width > gauge_width ? grip_width : gauge_width]
