// ---- Derived ----
mid = (grip_length + transition_len + gauge_length + transition_len + grip_length) / 2;

// Width profile seen from above (y = f(x))
function width(x) =
    if (x < -mid)
        grip_width;
    else if (x <= -grip_length)
        grip_width + (gauge_width - grip_width) *
            (x + grip_length) / transition_len;
    else if (x < -mid + transition_len)
        gauge_width;
    else if (x <= mid - transition_len)
        grip_width + (gauge_width - grip_width) *
            (x - mid + transition_len) / transition_len;
    else
        grip_width;

difference() {
    // Main body
    hull() {
        for (s = [-1, 1])
            translate([s * mid, 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [0, -width(0) / 2],
                            [transition_len + grip_length, width(0) / 2],
                            [transition_len + grip_length, -width(0) / 2]
                        ]);
    }

    // Truncate to total_length, centred on origin
    translate([-total_length / 2, -total_length / 2, 0])
        cube([total_length, total_length, thickness + 2]);
}
