        for (s = [-1, 1])
            translate([s * (gauge_len / 2 + transition_len) - grip_len / 2,
                       -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);

        // Gauge section (centered on origin)
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Transitions: width changes linearly from grip_w to gauge_w
        for (s = [-1, 1])
            translate([s * gauge_len / 2 - transition_len / 2, 0, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [0, 0],
                        [transition_len, 0],
                        [transition_len, s * (grip_w + (gauge_w - grip_w) * 0.5)],
                        [0, s * (grip_w + (gauge_w - grip_w) * 0.5)]
                    ]);
    }

    // Central relief: removes the central 30 mm of X down to y = +/-9,
    // which thins the gauge section and the adjacent transition regions.
    translate([-gauge_len / 2, -9, -cut_extra])
        cube([gauge_len, 18, thickness + 2 * cut_extra]);
