// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, builds upward in +Z
// Coordinates: origin at the centre of the part

$fn = 64;

// ---------- Dimensions (mm) ----------
specimen_thickness  = 4;     // total thickness (Z)
overall_length      = 120;   // total length along X
grip_width          = 15;    // grip section width (Y)
grip_length         = 30;    // grip section length (X)
gauge_width         = 8;     // gauge section width (Y)
gauge_length        = 30;    // gauge section length (X)
transition_length   = 15;    // each transition runs this far in X

eps                 = 0.5;   // overlap / cut extension (coplanar safety)

// ---------- Derived ----------
half_grip           = grip_length / 2;
half_gauge          = gauge_length / 2;
transition_start    = half_grip + transition_length;   // where transition ends / gauge begins
grip_end_offset     = overall_length / 2 - transition_start;  // grip starts this far from each end

// ---------- Model ----------
module flat_dogbone() {
    union() {
        // Grip sections at each end
        for (s = [-1, 1])
            translate([s * grip_end_offset, -grip_width / 2, 0])
                cube([grip_length, grip_width, specimen_thickness]);

        // Gauge section in the middle
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Transitions: width changes linearly from grip to gauge
        for (s = [-1, 1]) {
            w0 = grip_width;
            w1 = gauge_width;
            // polygon drawn in X-Y (2D), then extruded in Z
            translate([s * (transition_start - transition_length), 0, 0])
                linear_extrude(height = specimen_thickness)
                    polygon(points = [
                        [0, (w0 + w1) / 2 + eps],
                        [transition_length, (w0 + w1) / 2 + eps],
                        [transition_length, w1],
                        [-transition_length, w1],
                        [-transition_length, w0],
                        [0, w0]
                    ]);
        }
    }
}

flat_dogbone();
