$fn = 64;           // not strictly needed (no curves), kept per convention

// ---------- Derived ----------
half_gauge = gauge_len / 2;        // +/-15
half_grip  = grip_len  / 2;        // +/-15
// X positions of section start/end (world coordinates)
x_a = -(half_gauge + trans_len);   // left grip start
x_b = -half_gauge;                 // left gauge start / trans end
x_c =  half_gauge;                 // right gauge start / trans end
x_d =  half_grip + trans_len;      // right grip end

// ---------- Profile (top face) ----------
module top_profile() {
    linear_extrude(height = thickness)
        polygon(points = [
            [x_a, -grip_w/2], [x_a,  grip_w/2],
            [x_b,  grip_w/2], [x_b,  trans_w],
            [x_c,  trans_w], [x_c,  grip_w/2],
            [x_d,  grip_w/2], [x_d, -grip_w/2],
            [x_c, -grip_w/2], [x_c, -trans_w],
            [x_b, -trans_w], [x_b, -grip_w/2],
        ]);
}

// ---------- Linear transition widths ----------
// At each end, width drops from grip_w over trans_len, then rises back to grip_w.
// The two rising slopes meet at the origin, so the gauge section is exactly gauge_len.
module transition_widths() {
    local_x = -(half_gauge + trans_len);   // left grip start (local)
    for (s = [-1, 1])
        [for (t = [0, 1])
         local_x + t * trans_len + s * (t * trans_len + half_gauge)];
}

// ---------- Model ----------
difference() {
    // Outer block
    translate([-total_len/2, -grip_w/2, 0])
        cube([total_len, grip_w, thickness]);

    // Cut out the gauge section, with a small overlap into each transition
    // so no faces are coplanar.
    for (s = [-1, 1])
        translate([s * (half_gauge + trans_len/2), -gauge_w/2, -1])
            cube([half_gauge + trans_len/2, gauge_w, thickness + 2]);
}
