            // whose width changes linearly from 20 to 6 mm
            for (sx = [-1, 1]) {
                x0 = sx > 0 ? half_gauge + trans_len : -(half_gauge + trans_len);
                x1 = sx * half_gauge;
                w0 = grip_w;
                w1 = gauge_w + (grip_w - gauge_w) * (x0 - x1) / trans_len;
                translate([x1, -w0 / 2, 0])
                    cube([trans_len, w0, thickness]);
