            cube([grip_len + eps, grip_w, thickness + 2*eps]);

    // Gauge section
    translate([-gauge_len/2, -gauge_w/2, -eps])
        cube([gauge_len, gauge_w, thickness + 2*eps]);

    // Transition sections (width changes linearly from grip_w to gauge_w)
    for (s = [-1, 1]) {
        x0 = s > 0 ? gauge_len/2 : -gauge_len/2 - trans_len;
        x1 = s > 0 ? gauge_len/2 + trans_len : -gauge_len/2;
        w0 = grip_w;
        w1 = gauge_w;
        translate([x0, -w0/2, -eps])
            linear_extrude(height = thickness + 2*eps)
                polygon(points = [
                    [x0, w0/2],
                    [x1, w1/2],
                    [x1, -w1/2],
                    [x0, -w0/2]
                ]);
    }
}
