function trans_w(offset) = grip_w + (6 - grip_w) * offset / eps;

difference() {
    // Outer solid
    union() {
        // Grip sections
        for (sx = [grip_x0, grip_x1])
            translate([sx, -grip_w/2, 0])
                cube([grip_len, grip_w, thickness]);
        // Gauge section
        translate([-gauge_len/2, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);
        // Transition regions
        for (sx = [-grip_x0 + grip_x0 - gauge_len/2 - trans_len,   // left
                    grip_x1])                                      // right
            linear_extrude(thickness)
                polygon(points = [
