                    [sx + trans_len, -grip_w/2],
                    [sx + trans_len, gauge_w/2],
                    [sx, gauge_w/2]
                ]);
    }

    // Central relief to keep only the thinnest section (3 mm)
    translate([-total_len/2 - overcut, -grip_w/2 - overcut, -overcut])
        cube([total_len + 2*overcut, grip_w + 2*overcut, thickness + 2*overcut]);
