// Flat tensile test specimen (dog-bone shape)
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

thickness = 3;     // specimen thickness (Z)
gauge_w   = 6;     // narrow gauge width (Y)
gauge_l   = 40;    // gauge length (X)
grip_w    = 20;    // grip section width (Y)
grip_l    = 25;    // grip section length (X)
trans_l   = 15;    // transition length between grip and gauge (X)

eps = 0.5;         // cutter overshoot past faces

// overall length
total_l = 2 * grip_l + gauge_l + 2 * trans_l;

// width at a given X
function w(x) =
    if (x < -grip_l)       grip_w - (grip_w - gauge_w) * (x + grip_l) / trans_l
    else if (x <= -gauge_l) gauge_w
    else if (x < gauge_l)  gauge_w
    else if (x <= gauge_l + trans_l) gauge_w + (grip_w - gauge_w) * (x - (gauge_l - trans_l)) / trans_l
    else                   grip_w;

difference() {
    // specimen body
    translate([-total_l / 2, -thickness / 2, 0])
        linear_extrude(height = thickness)
            polygon([for (sx = [-1, 1]) for (t = [0 : 0.005 : 1]) sx * (w(sx * (total_l / 2 - grip_l - trans_l) + t * (gauge_l + 2 * trans_l))), thickness / 2]);

    // grip blocks (overlap into gauge to avoid coplanar faces)
    for (s = [-1, 1])
        translate([s * (gauge_l / 2 - trans_l - eps), -thickness / 2 - eps, -eps])
            cube([trans_l + eps, thickness + 2 * eps, 2 * eps]);
}
