// Flat dog-bone tensile specimen for FDM printing
// Units: mm. Prints flat on the bed (z = 0 up to thickness).

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip->gauge transition
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
total_length = 2 * grip_length + gauge_length + 2 * transition_len;   // 120 mm

// ---------- Model ----------
module specimen() {
    difference() {
        // Outer profile (X/Y), extruded in +Z
        linear_extrude(height = thickness)
            hull() {
                // Left grip
                translate([-total_length / 2, -grip_width / 2]) square([grip_length, grip_width]);
                // Right grip
                translate([total_length / 2 - grip_length, -grip_width / 2]) square([grip_length, grip_width]);

                // Left transition (grip end at -80, gauge centre at -20)
                translate([-grip_length - transition_len, -grip_width / 2])
                    linear_extrude(height = transition_len + 1)
                        polygon(points = [
                            [0, -grip_width / 2],
                            [transition_len + 1, -grip_width / 2],
                            [transition_len + 1, -gauge_width / 2],
                            [0, -gauge_width / 2]
                        ]);
                // Right transition (mirror about origin)
                translate([grip_length + transition_len, -grip_width / 2])
                    linear_extrude(height = transition_len + 1)
                        polygon(points = [
                            [0, -grip_width / 2],
                            [-transition_len - 1, -grip_width / 2],
                            [-transition_len - 1, -gauge_width / 2],
                            [0, -gauge_width / 2]
                        ]);
            }

        // Cutter block that overlaps the two grip centres,
        // so the hull is truly common to both ends.
        translate([-grip_length - 1, -grip_width / 2 - eps])
            cube([gauge_length + 2 + 2 * eps, grip_width + 2 * eps, thickness + 2 * eps]);
    }
}

