// Flat dog-bone tensile specimen, printed lying flat on the bed
// Units: mm

// ---------- Parameters ----------
specimen_thickness = 3;     // Z thickness of the plate
total_length       = 120;   // overall length along X
gauge_width        = 6;     // narrow gauge section width (Y)
gauge_length       = 40;    // gauge section length (X)
grip_width         = 20;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)
transition_length  = 15;    // length of each grip->gauge transition (X)
overcut            = 1;     // extra length so cutters pass through faces

// Derived dimensions
left_grip_end    = -total_length/2 + grip_length;   // -45
right_grip_end   =  total_length/2 - grip_length;   // 45
gauge_start      = left_grip_end + transition_length;  // -30
gauge_end        = right_grip_end - transition_length; // 30

// ---------- Model ----------
module dogbone() {
    difference() {
        // Plate body, centred on origin in XY, resting on z = 0
        translate([-total_length/2, -specimen_thickness/2, 0])
            linear_extrude(height = specimen_thickness)
                polygon(points = [
                    // Grip (left)
                    [left_grip_end - grip_length, -grip_width/2],
                    [left_grip_end - grip_length,  grip_width/2],
                    // Grip -> gauge transition (left)
                    for (t = [0 : transition_length : gauge_end - gauge_start])
                        [t - transition_length - gauge_end + gauge_start,
                         (grip_width - gauge_width) * t/transition_length / 2],
                    // Gauge section
                    for (s = [-gauge_length/2 : gauge_length/2])
                        [s, gauge_width/2],
                    // Gauge -> grip transition (right)
                    for (t = [gauge_end - gauge_start : transition_length : right_grip_end - gauge_start])
                        [t + transition_length + gauge_end - gauge_start,
                         (grip_width - gauge_width) * t/transition_length / 2],
                    // Grip (right)
                    [right_grip_end + grip_length,  grip_width/2],
                    [right_grip_end + grip_length, -grip_width/2]
                ]);
    }

    // Remove overlapping grips so each has only one solid end
    for (sx = [-1, 1]) {
        translate([sx * (total_length/2 - grip_length - 1), -specimen_thickness/2, -overcut])
            cube([grip_length + overcut, specimen_thickness, overcut]);
    }
}

dogbone();
