                        [for (t = [0, 1])
                            s * [(half_x - grip_l - transition_l) - transition_l * t,
                               (grip_w - gauge_w) * t + gauge_w / 2]]
                    )
            ]);

    // Grip blocks at each end, overlapping the transitions
    for (s = [-1, 1])
        translate([s * (half_x - grip_l / 2), -specimen_t / 2, -cut_extra])
            cube([grip_l, specimen_t + 2 * cut_extra, 2 * cut_extra]);
}
