```openscad
// Flat dog-bone tensile specimen for FDM printed plastic
// Units: mm. Print orientation: flat on bed, building up +Z.

// ---------- Parameters ----------
thickness   = 3;     // plate thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // narrow gauge width (Y)
gauge_len   = 50;    // gauge length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
transition  = 10;    // length of each grip-gauge transition (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
a      = grip_w;     // grip width
b      = gauge_w;    // gauge width
L      = total_len;  // total length
L_g    = gauge_len;  // gauge length
L_r    = grip_len;   // grip length
L_t    = transition; // transition length
H      = thickness;  // thickness

// check: 2*L_r + 2*L_t + L_g = 140 mm
assert(abs(2*L_r + 2*L_t + L_g - L) < 0.001, "length mismatch");

// ---------- Model ----------
difference() {
    // upper and lower faces
    hull() {
        translate([-L/2, 0, 0])   rotate([90, 0, 0])   linear_extrude(height = H)
            polygon([[-a/2, -a/2], [a/2, -a/2], [a/2, a/2], [-a/2, a/2]]);
        translate([ L/2, 0, 0])   rotate([90, 0, 0])   linear_extrude(height = H)
            polygon([[-a/2, -a/2], [a/2, -a/2], [a/2, a/2], [-a/2, a/2]]);
    }

    // grip segments (extended past the end faces)
    for (s = [-1, 1])
        translate([s*(L/2 - L_r - L_t), -a/2, -eps])
            cube([L_r + eps, a, H + 2*eps]);

    // gauge segment (extended past the end faces)
    translate([-L_g/2, -b/2, -eps])
        cube([L_g + eps, b, H + 2*eps]);

    // transition segments: width changes linearly from a to b
    for (s = [-1, 1])
        translate([s*(L/2 - L_t - L_g/2), -a/2, -eps])
            rotate([90, 0, 0])
                linear_extrude(height = H + 2*eps)
                    polygon([
                        [0, -a/2], [L_t, -a/2],
                        [L_t, (a - b)/L_t * L_t - a/2],
                        [L_t, (a - b)/L_t * L_t - a/2 + b]
                    ]);
}
