        // centred at its X position, running from z = 0 to z = specimen_thickness
        for (i = [0 : 4]) {
            w = [grip_width, grip_width, gauge_width, gauge_width, grip_width][i];
            translate([pos_0 + i * transition_length, -w / 2, 0])
                cube([w, specimen_thickness, total_length]);
