half_grip  = grip_len / 2;           // 17.5
// transition runs from x = -55 to x = -45 (width 15 -> 6)
// and from x = 45 to x = 55 (width 6 -> 15)

// ---------------- Model ----------------
module flat_dogbone() {
    hull() {
        // Left grip
        translate([-half_grip - transition_l, 0, 0])
            cube([grip_len, grip_w, thickness]);

        // Right grip
        translate([half_grip + transition_l, 0, 0])
            cube([grip_len, grip_w, thickness]);

        // Gauge section
        translate([0, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Left transition (15 -> 6)
        translate([-half_grip - transition_l / 2, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [-transition_l / 2, -grip_w / 2],
                        [ transition_l / 2, -grip_w / 2],
                        [ transition_l / 2,  gauge_w / 2],
                        [-transition_l / 2,  gauge_w / 2]
                    ]);

        // Right transition (6 -> 15)
        translate([half_grip + transition_l / 2, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [-transition_l / 2,  gauge_w / 2],
                        [ transition_l / 2,  gauge_w / 2],
                        [ transition_l / 2, -grip_w / 2],
                        [-transition_l / 2, -grip_w / 2]
                    ]);
    }

    // Remove a thin central slab to avoid any coplanar faces in the hull
    translate([0, -gauge_w / 2 - eps, -eps])
        cube([gauge_len, gauge_w + 2 * eps, thickness + 2 * eps]);
}

