difference() {
    // Body
    linear_extrude(height = specimen_thk)
        rotate([90, 0, 0])
            hull()
                for (i = [0 : 4])
                    translate([x0 + (i + 0.5) * transition_len, 0])
                        circle(d = profile_w[i], $fn = 64);

    // Central relief: removes material between the two flanged grip ends,
    // leaving a 6 mm wide core that runs through the gauge and into the
    // transitions (no faces are coplanar with the hull after this cut).
    translate([-x2, -overlap])
        rotate([-90, 0, 0])
            linear_extrude(height = specimen_thk + 2 * overlap)
                circle(d = gauge_width, $fn = 64);
