    if (x < transition_l)
        grip_w - (grip_w - gauge_w) * x / transition_l;
    else if (x < transition_l + gauge_l)
        gauge_w;
    else
        grip_w + (grip_w - gauge_w) * (x - transition_l - gauge_l) / transition_l;

module polygon_2d(pts) =
    concat([[0, 0]], pts, [pts[0]]);

difference() {
    // Main plate
    translate([-total_l / 2, -grip_w / 2, 0])
        linear_extrude(height = specimen_t)
            polygon(polygon_2d([for (i = [0 : 1]) [i * (total_l / 2 - transition_l - gauge_l),
                                                    sign(i) * width_at(transition_l + gauge_l + i * 0.001) / 2]]));

    // Central gauge section (slightly overcut in X)
    translate([-gauge_l / 2 - eps, -gauge_w / 2, -eps])
        cube([gauge_l + 2 * eps, gauge_w, specimen_t + 2 * eps]);
