        for (sx = [-1, 1])
            translate([sx * grip_start, -grip_w / 2, 0])
                cube([grip_l, grip_w, specimen_t]);

        // Gauge block
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
    }

    // Transition regions: width changes linearly from grip_w to gauge_w
    for (sx = [-1, 1]) {
        cx = sx * grip_start - transition_l;   // centre of transition
        w(x) = grip_w - (grip_w - gauge_w) * (x - cx - transition_l) / transition_l;
        translate([cx - transition_l, -w(0) / 2, -eps])
            linear_extrude(height = specimen_t + 2 * eps)
                polygon(points = [for (t = [0 : 100]) [cx - transition_l + t * transition_l,
                                                       sign(sx) * w(t / 100) / 2]]);
