// Flat dog-bone tensile specimen for FDM printing
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// --- Dimensions ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // narrow gauge width (Y)
gauge_l      = 50;    // gauge length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // each transition length (X)
eps          = 0.5;   // overshoot for clean cuts

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;

// Width profile: grip -> transition -> gauge -> transition -> grip
function y_ext(x) =
    if (x < transition_l)
        (grip_w + 15) / 2 + (15 - grip_w) / 2 * x / transition_l;
    else if (x < transition_l + gauge_l)
        15;
    else if (x < 2 * transition_l + gauge_l)
        6 + (15 - 6) * (x - transition_l - gauge_l) / transition_l;
    else if (x < total_l - transition_l)
        15;
    else
        (grip_w + 15) / 2 + (15 - grip_w) / 2 * (total_l - x) / transition_l;

difference() {
    // Plate
    linear_extrude(height = specimen_t)
        polygon(points = [for (x = [0 : 1] << 2 : [x & 1 ? -1 : 1] * (total_l / 2 - eps), y_ext(x & 1 ? total_l - x : x) : [0, 0]]));

