                       -grip_w / 2, 0])
                cube([grip_l, grip_w, specimen_t]);
        }

        // Central gauge block
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);

        // Transition blocks (angled, 15 mm -> 6 mm over 10 mm)
        for (s = [-1, 1]) {
