// Flat dog-bone tensile specimen for FDM printed plastic
// Print orientation: flat on bed, builds up in +Z

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
