// Width profile: grip -> transition -> gauge -> transition -> grip
function profile_w(x) =
    if (x < -transition_l - gauge_l / 2)
        grip_w + (grip_w - gauge_w) * (x + transition_l + gauge_l / 2) / transition_l;
    else if (x < -transition_l)
        grip_w - (grip_w - gauge_w) * (x + transition_l) / transition_l;
    else if (x < transition_l)
        gauge_w;
    else if (x < transition_l + gauge_l / 2)
        gauge_w + (grip_w - gauge_w) * (x - transition_l - gauge_l / 2) / transition_l;
    else
        grip_w - (grip_w - gauge_w) * (x - (transition_l + gauge_l / 2)) / transition_l;

module tensile_specimen() {
    hull() {
        for (s = [-1, 1])
            translate([s * (transition_l + gauge_l / 2 + 1), 0, 0])
                linear_extrude(height = specimen_t)
                    polygon([for (x = [-total_l / 2 : 1 : transition_l + gauge_l / 2])
                               [x, profile_w(x) / 2],
                     [transition_l + gauge_l / 2 + 1, 0]]);
    }
}

