right_grip_x0 = total_len / 2 - grip_len / 2;         // grip end X

// ---------- Model ----------
module width(x) {
    if (x < left_grip_x0) {
        // left grip
        return grip_w;
    } else if (x <= left_grip_x0 + trans_len) {
        // left transition: linear from grip_w down to gauge_w
        return grip_w - (grip_w - gauge_w) * (x - left_grip_x0) / trans_len;
    } else if (x <= left_grip_x0 + trans_len + gauge_len) {
        // gauge section
        return gauge_w;
    } else if (x < right_grip_x0 - trans_len) {
        // right gauge section
        return gauge_w;
    } else if (x <= right_grip_x0 - trans_len + trans_len) {
        // right transition: linear from gauge_w up to grip_w
        return gauge_w + (grip_w - gauge_w) * (x - (right_grip_x0 - trans_len)) / trans_len;
    } else {
        // right grip
        return grip_w;
    }
}

difference() {
    linear_extrude(height = thickness)
        polygon([for (x = [-(total_len / 2) : 1 : total_len / 2]) [x, width(x) / 2]]);
