    for (s = [-1, 1])
        translate([s * (spec_length/2 - grip_length), -grip_width/2, 0])
            cube([grip_length, grip_width, spec_thickness]);

    // Gauge section
    translate([-gauge_length/2, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, spec_thickness]);

    // Transitions: width = grip_width - (t/transition_length)*(grip_width-gauge_width)
    for (t = [first_x, last_x])
        linear_extrude(height = spec_thickness)
            polygon([
                [t, 0],
                [t + transition_length, 0],
                [t + transition_length,
                 grip_width - (transition_length/transition_length)
                             * (grip_width - gauge_width)],
                [t, grip_width - (transition_length/transition_length)
                               * (grip_width - gauge_width)]
