$fn = 64;

// ---- Dimensions (mm) ----
thickness  = 4;     // plate thickness (Z)
total_len  = 140;   // overall length (X)
gauge_w    = 8;     // gauge section width (Y)
gauge_len  = 50;    // gauge section length (X)
grip_w     = 19;    // grip section width (Y)
grip_len   = 35;    // grip section length (X)
trans_len  = 10;    // transition section length (X)
weps       = 0.5;   // width-based cutter overshoot

// ---- Derived ----
x0 = -(total_len / 2 + trans_len / 2);  // start of grip (left)

// ---- Modules ----
module grip() {
    hw = grip_w / 2;
    difference() {
        translate([-grip_len / 2, -hw, 0])
            cube([grip_len, grip_w, thickness]);
        translate([-grip_len / 2 - weps, -hw - weps, 0])
            cube([grip_len + 2 * weps, grip_w + 2 * weps, thickness + 2 * weps]);
    }
}

module transition(len, w1, w2) {
    // w1, w2 : end widths (Y); len : length along X
    hull() {
        for (t = [0, 1])
            translate([t * len - len / 2, -(w1 + (w2 - w1) * t) / 2, 0])
                cube([len, w1 + (w2 - w1) * t, thickness]);
    }
}

// ---- Assembly ----
union() {
    grip();
    for (s = [-1, 1]) {
        translate([s * x0, 0, 0])
            grip();
        // outer transition: grip_w -> gauge_w
        translate([s * (x0 + grip_len / 2), 0, 0])
            transition(trans_len, grip_w, gauge_w);
    }
    translate([-gauge_len / 2, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, thickness]);
}
