            cube([grip_len + trans_len, grip_w, thickness]);
        // right grip
        translate([trans_len, -grip_w/2, 0])
            cube([grip_len + trans_len, grip_w, thickness]);
        // gauge
        translate([-gauge_len/2, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);
