        rotate([90, 0, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, 0], [trans_len, 0],
                    for (t = [0:0.01:1]) [trans_len - t, a*t - gauge_w/2],
                    [trans_len - t, a*t + gauge_w/2]
