// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds upward in +Z

$fn = 64;

// ---- Dimensions (mm) ----
thickness = 4;     // plate thickness
total_len = 140;   // overall length along X
gauge_w   = 8;     // gauge section width (Y)
gauge_len = 50;    // gauge section length (X)
grip_w    = 19;    // grip section width (Y)
grip_len  = 35;    // grip section length (X)
trans_len = 10;    // transition section length (X)

// ---- Derived ----
x0 = -total_len/2;          // left end
x1 = -grip_len/2 - trans_len/2;   // grip/start of transition
x2 = -gauge_len/2;           // gauge start
x3 = gauge_len/2;            // gauge end
x4 = grip_len/2 + trans_len/2;   // right transition end
x5 = total_len/2;            // right end

// ---- Width profile ----
w = function(t) {
    if (t < x1 || t > x4) return grip_w;
    if (t <= x0 || t >= x5) return grip_w;
    if (t < x2) return grip_w - (t - x1) * (grip_w - gauge_w) / trans_len;
    if (t > x3) return grip_w - (x4 - t) * (grip_w - gauge_w) / trans_len;
    return gauge_w;
};

difference() {
    // Plate
    linear_extrude(thickness)
        polygon(points = [
            [x0, 0], [x5, 0],
            for (p = [x0 : 1 : x5]) [p, w(p)],
            [x5, 0], [x0, 0]
        ]);

    // Cut a strip along each 45-degree diagonal, centred on the part
    for (s = [-1, 1])
        rotate([90, 0, s * 45])
            translate([0, -trans_len, 0])
                linear_extrude(trans_len)
                    circle(d = thickness + 2, center = [0, 0]);
}
