// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, building up in +Z

// ---------- Dimensions (mm) ----------
specimen_length = 140;   // overall length along X
specimen_thick  = 4;     // thickness along Z
gauge_width     = 8;     // width of the narrow gauge section (Y)
gauge_length    = 50;    // length of the gauge section (X)
grip_width      = 19;    // width of each grip section (Y)
grip_length     = 35;    // length of each grip section (X)
transition_len  = 10;    // length of each grip-to-gauge transition (X)

eps = 0.5;               // overlap / cutter overshoot tolerance

$fn = 64;

// ---------- Derived ----------
head_len      = grip_length + transition_len;   // one end block length
head_start    = -(specimen_length / 2 - head_len);   // end block start X
gauge_start   = -gauge_length / 2;
gauge_end     = gauge_start + gauge_length;
end_block_end = specimen_length / 2 - head_len;

// ---------- Model ----------
module flat_dogbone() {
    difference() {
        // Outer solid: two grip end blocks with a central gauge section
        union() {
            // Left end block: grip -> transition -> gauge start
            translate([head_start, -grip_width / 2, 0])
                linear_extrude(thickness = specimen_thick)
                    polygon(points = [
                        [head_start, -grip_width / 2],
                        [end_block_end, -grip_width / 2],
                        [end_block_end, grip_width / 2],
                        [head_start, grip_width / 2]
                    ]);

            // Right end block: gauge end -> transition -> grip
            translate([end_block_end, -grip_width / 2, 0])
                linear_extrude(thickness = specimen_thick)
                    polygon(points = [
                        [end_block_end, -grip_width / 2],
                        [specimen_length / 2 - grip_len, -grip_width / 2],
                        [specimen_length / 2 - grip_len, grip_width / 2],
                        [end_block_end, grip_width / 2]
                    ]);
        }

        // Central gauge section, cut slightly below top and bottom faces
        translate([gauge_start, -gauge_width / 2, -eps])
            linear_extrude(thickness = specimen_thick + 2 * eps)
                polygon(points = [
                    [gauge_start, -gauge_width / 2],
                    [gauge_end, -gauge_width / 2],
                    [gauge_end, gauge_width / 2],
                    [gauge_start, gauge_width / 2]
                ]);
    }
}

