$fn = 64;

// ---- Dimensions ----
thickness    = 3;     // specimen thickness (Z)
total_length = 150;   // overall length along X
gauge_width  = 8;     // narrow gauge width (Y)
gauge_length = 50;    // gauge length (X)
grip_width   = 19;    // grip section width (Y)
grip_length  = 35;    // grip section length (X)
transition   = 15;    // transition segment length (X)

// ---- Derived ----
half_gauge   = gauge_length / 2;
grip_start_x = -total_length / 2 + grip_length;
x0           = grip_start_x - transition;  // start of left transition
area         = grip_width * grip_length + gauge_width * gauge_length + grip_width * transition;

// ---- Model ----
difference() {
    // Profile in XY, extruded to thickness
    linear_extrude(thickness)
        union() {
            // Grip sections
            translate([-total_length / 2, -grip_width / 2])
                square([grip_length, grip_width]);
            translate([total_length / 2 - grip_length, -grip_width / 2])
                square([grip_length, grip_width]);
            // Gauge section
            translate([-half_gauge, -gauge_width / 2])
                square([gauge_length, gauge_width]);
            // Transitions (overlapping into grips for a clean union)
            for (s = [-1, 1])
                translate([s * x0, -grip_width / 2])
                    linear_extrude(height = transition + 1)
                        circle(d = grip_width, $fn = 64);
        }

    // Overcut past top and bottom faces
    translate([0, 0, -1])
        cube([total_length, grip_width, 2]);
}
