```openscad
// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, builds upward in +Z
// Positioned using the user's coordinates: total length 150 mm along X,
// grip sections from x = 0 to 35 and x = 115 to 150, gauge in the middle.

// ---------------- Parameters ----------------
spec_thickness = 3;     // specimen thickness (Z)
total_length   = 150;   // overall length along X (mm)

grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length along X (mm)

gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length along X (mm)

transition_len = 15;    // transition section length along X (mm)

overlap        = 0.5;   // overlap of cutting shapes into faces (mm)

$fn = 64;

// ---------------- Derived ----------------
half_trans = transition_len / 2;   // 7.5 mm

// Width profile of the two transition blocks (outer grip -> inner gauge)
// Profile in (X, Y); extruded, then sliced at the overlap depth.
module transition_profile() {
    hull() {
        translate([-transition_len, -grip_width / 2])
            cube([transition_len, grip_width, overlap]);
        translate([0, -gauge_width / 2])
            cube([transition_len, gauge_width, overlap]);
    }
}

// ---------------- Model ----------------
difference() {
    union() {
        // Grip section at x = 0 .. 35
        translate([0, -grip_width / 2, 0])
            cube([grip_length, grip_width, spec_thickness]);

        // Grip section at x = 115 .. 150
        translate([total_length - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, spec_thickness]);

        // Gauge section in the middle (x = 50 .. 100)
        translate([total_length / 2 - gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, spec_thickness]);

        // Transition blocks between each grip and the gauge
        for (s = [-1, 1])
            translate([s > 0 ? gauge_length / 2 - half_trans :
                       total_length / 2 - gauge_length / 2 - half_trans,
                       0, 0])
                rotate([0, 90, 0])
                    linear_extrude(height = spec_thickness)
                        transition_profile();
    }

    // Optional clean-up cuts, extended past faces
    for (s = [-1, 1])
        translate([s > 0 ? gauge_length / 2 - half_trans :
                   total_length / 2 - gauge_length / 2 - half_trans,
                   -grip_width / 2 - overlap, 0])
            cube([transition_len, grip_width + 2 * overlap, spec_thickness + overlap]);
}
