gauge_l      = 50;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 15;    // transition section length (X)
total_l      = 150;   // overall length (X)

// ---- Derived ----
over      = 1;                                       // cutter overshoot
transition_0 = [grip_w, grip_w];                     // start widths for each side
transition_1 = [gauge_w, gauge_w];                   // end widths
grip_hull   = hull([
    translate([-grip_l, -grip_w/2, 0]) cube([grip_l, grip_w, specimen_t]),
    translate([ grip_l, -grip_w/2, 0]) cube([grip_l, grip_w, specimen_t])
  ]);

module side_profile() {
  // one half of the cross-section (Y > 0), built up from the grip
  hull() {
    for (p = [transition_0, transition_1])
      translate([0, p[0]/2, 0]) rotate([90, 0, 0]) cube([transition_l, 1, specimen_t]);
  }
}

difference() {
  translate([-total_l/2, -grip_w/2, 0])
    linear_extrude(specimen_t)
      polygon([
        [-total_l/2, 0], [total_l/2 - gauge_l, 0],
        // outer grip (Y = +/- 9.5), run from -75 to +75 so the hull is centred
        for (x = [ -75, 75]) [x, grip_w],
        // gauge end (Y = 4), extended past the grip by 'over'
        [total_l/2 - gauge_l - over, over],
        // symmetry axis
        [total_l/2 - gauge_l - over, 0]
      ]);

  // narrow gauge section
  translate([-gauge_l/2, -gauge_w/2, 0])
    cube([gauge_l, gauge_w, specimen_t + 2*over]);

  // grip solid that the transition thickens toward (a core of constant width)
  translate([-total_l/2, -grip_w/2, 0])
    cube([total_l, grip_w, specimen_t + over]);

  // diagonal halves of the transition blocks, so the hull fuses into one solid
  for (sx = [-1, 1], sy = [0, 1])
    translate([sx*(total_l/2 - grip_l - transition_l), -grip_w/2 - sy*grip_w, 0])
      rotate([0, 90, 0])
        linear_extrude(over)
          polygon([
            [0, 0], [transition_l, 0], [0, grip_w]
          ]);

  // keep only the lower half of any remaining transition blocks (Y < specimen_t/2)
  for (sx = [-1, 1])
    translate([sx*(total_l/2 - grip_l - transition_l), -grip_w/2, 0])
      hull() {
        for (sy = [0, 1])
          translate([0, sy*grip_w, 0])
            rotate([90, 0, 0])
              linear_extrude(specimen_t + over)
                polygon([
                  [0, 0], [transition_l, 0], [0, specimen_t + over]
                ]);
      }
}
