            [-total_l/2 + grip_l/2,  grip_w/2],
            // Left transition (grip -> gauge)
            [-total_l/2 + grip_l - transition_l/2, -grip_w/2],
            [-total_l/2 + grip_l - transition_l/2,  grip_w/2],
            // Gauge
            [-gauge_l/2, -gauge_w/2],
            [-gauge_l/2,  gauge_w/2],
            // Right transition (gauge -> grip)
            [gauge_l/2, -gauge_w/2],
            [gauge_l/2,  gauge_w/2],
            // Right grip
            [total_l/2 - grip_l/2, -grip_w/2],
            [total_l/2 - grip_l/2,  grip_w/2]
        ]);
    }
}

