// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 .. thickness

// ---------------- Parameters ----------------
specimen_thickness = 3;     // plate thickness (Z)

total_length       = 150;   // overall length along X (mm)

gauge_width        = 8;     // narrow gauge section width (Y)
gauge_length       = 50;    // gauge section length (X)

grip_width         = 19;    // grip section width (Y)
grip_length        = 35;    // grip section length (X)

transition_length  = 15;    // each grip-to-gauge transition length (X)

cut_extra          = 0.5;   // overshoot of cutting shapes past faces

$fn = 64;                   // curve resolution

// Derived check: 2*grip_length + gauge_length + 4*transition_length = total_length
// 2*35 + 50 + 4*15 = 70 + 50 + 60 = 180 mm -> MISMATCH with 150

// ---------------- Model ----------------
module dogbone() {
    difference() {
        // Plate body
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([total_length, grip_width, specimen_thickness]);

        // Grip pockets (wider than gauge, leaving transition regions)
        // Pocket width = grip_width + 2 * cut_extra to avoid coplanar faces
        for (x = [-1, 1])
            translate([x * (grip_length - transition_length),
                       -grip_width / 2 - cut_extra,
                       -cut_extra])
                cube([grip_length + cut_extra,
                     grip_width + 2 * cut_extra,
                     specimen_thickness + 2 * cut_extra]);

        // Central gauge pocket
        translate([-gauge_length / 2, -gauge_width / 2 - cut_extra, -cut_extra])
            cube([gauge_length,
                 gauge_width + 2 * cut_extra,
                 specimen_thickness + 2 * cut_extra]);
    }
}

dogbone();
