$fn = 64;

// ---- Dimensions (mm) ----
specimen_t = 3;     // thickness
gauge_w    = 8;     // gauge section width (Y)
gauge_l    = 50;    // gauge section length (X)
grip_w     = 19;    // grip section width (Y)
grip_l     = 35;    // grip section length (X)
trans_l    = 15;    // transition section length (X)
total_l    = 150;   // overall length (X)

// ---- Derived ----
grip_x0   = grip_l - trans_l;   // grip starts after transition
gauge_x0  = -gauge_l / 2;
overlap   = trans_l / 2;       // overlap grip/transition for a clean union

// ---- Model ----
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * grip_x0 - grip_l + overlap, -grip_w / 2, 0])
            cube([grip_l - overlap, grip_w, specimen_t]);

    // Gauge section
    translate([gauge_x0, -gauge_w / 2, 0])
        cube([gauge_l, gauge_w, specimen_t]);

    // Transitions (width changes linearly from grip to gauge)
    for (s = [-1, 1])
        translate([s * grip_x0 + overlap, -trans_l, 0])
            rotate([90, 0, 0])
                linear_extrude(specimen_t)
                    polygon([
                        [0, -grip_w / 2],
                        [trans_l, -grip_w / 2],
                        [trans_l,  grip_w / 2],
                        [0,  grip_w / 2]
                    ]);
}
