// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, builds upward in +Z

$fn = 64;

// ---- Dimensions (mm) ----
specimen_t   = 3;     // thickness
gauge_w      = 8;     // gauge section width (Y)
gauge_len    = 50;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_len     = 35;    // grip section length (X)
trans_len    = 15;    // transition section length (X)
total_len    = 150;   // total length (X)

// ---- Derived ----
n_grips      = 2;     // number of grip sections
overlap      = 0.01;  // small overlap to fuse sections cleanly

// Width at a given X position (relative to left grip start)
function width(x) =
    if (x < trans_len)
        grip_w;
    else if (x < trans_len + gauge_len)
        gauge_w;
    else
        grip_w;

module section(len, w) {
    translate([-len/2, -w/2, 0])
        cube([len, w, specimen_t]);
}

union() {
    // Grip sections
    for (i = [0 : n_grips - 1]) {
        x0 = (i % 2) * (total_len - n_grips*grip_len - gauge_len)/2;
        translate([x0, 0, 0])
            section(grip_len, grip_w);
    }
    // Gauge section
    x0 = -(total_len - n_grips*grip_len - gauge_len)/2;
    translate([x0, 0, 0])
        section(gauge_len, gauge_w);
    // Transitions
    for (i = [0 : n_grips - 1]) {
        x0 = (i % 2) * (total_len - n_grips*grip_len - gauge_len)/2 + grip_len;
        translate([x0, 0, 0])
            linear_extrude(height = specimen_t)
                polygon([
                    [0, 0], [trans_len, 0],
                    [trans_len, grip_w - gauge_w], [0, grip_w - gauge_w]
                ]);
    }
}
