    // Gauge section
    translate([-gauge_l / 2, -gauge_w / 2, 0])
        cube([gauge_l, gauge_w, specimen_t]);

    // Transitions: grip end -> gauge end (each side)
    for (s = [-1, 1]) {
        x0 = -total_l / 2 + grip_l - transition_l;   // outer grip end
        x1 = -gauge_l / 2 + overlap;                 // gauge end
        rotate([0, 0, s * 90])
            linear_extrude(height = specimen_t)
                polygon([
                    [x0, -grip_w / 2],
                    [x0 + transition_l, -grip_w / 2],
                    [x1, -gauge_w / 2],
                    [x1, gauge_w / 2],
                    [x0 + transition_l, gauge_w / 2],
                    [x0, gauge_w / 2]
                ]);
    }
}
