axle_d      = 5;     // axle hole diameter (mm)
spoke_count = 8;     // number of spokes
spoke_w     = 5;     // spoke width (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = rim_od, h = rim_w);

        // Hub
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = rim_w + 2 * eps);

        // Spokes, first along +X axis
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, -eps])
                    cube([spoke_w, spoke_w, rim_w + 2 * eps]);
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = rim_w + 2 * eps, $fn = 64);
}
