        // Outer rim (ring)
        cylinder(d = rim_outer_d, h = part_thickness);

        // Hub (underlies spokes, centred)
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = hub_t + 2 * eps);

        // Spokes: rectangle from angle 0 to spoke_width,
        // rotated so the rectangle runs radially outward.
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([0, 0, -eps])
                rotate([0, 0, a])
                    translate([hub_d / 2 - eps, -spoke_width / 2, 0])
                        cube([spoke_width + 2 * eps, spoke_width, part_thickness]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_hole_d, h = hub_t + 2 * eps, $fn = 64);
