// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
wheel_thickness   = 8;     // part thickness (Z)
outer_diameter    = 60;    // outer rim diameter
rim_width         = 6;     // rim width (radial)
hub_diameter      = 14;    // hub diameter
axle_hole_d       = 6;     // axle hole diameter
spoke_count       = 6;     // number of spokes
spoke_width       = 5;     // spoke width (radial)
spoke_start_angle = 0;     // first spoke along +X axis
cut_extra         = 0.5;   // cutter overshoot past faces
$fn               = 96;    // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
rim_r   = outer_r - rim_width;   // inner radius of rim
hub_r   = hub_diameter / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim ring
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub (overlaps rim slightly for a clean union)
        translate([0, 0, -rim_width])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * rim_width);

        // Spokes: rectangle from hub outer edge to rim outer edge
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_angle + i * 360 / spoke_count;
            translate([hub_r, 0, -rim_width])
                rotate([0, 0, a])
                    cube([rim_r - hub_r, spoke_width, wheel_thickness + 2 * rim_width]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra, $fn = 64);
}
```

