```openscad
// Spoked wheel for sample cart
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 96;

// ---- Dimensions (mm) ----
thickness    = 6;     // part thickness
outer_d      = 100;   // outer rim diameter
rim_w        = 6;     // rim width
hub_d        = 14;    // hub diameter
axle_d       = 6;     // axle hole diameter
spoke_count  = 6;     // number of spokes
spoke_w      = 5;     // spoke width
spoke_start  = 0;     // angle of first spoke (deg, +X axis)

eps          = 0.5;   // cutter overshoot

// ---- Derived ----
outer_r      = outer_d / 2;
rim_id       = outer_d - 2 * rim_w;   // rim inner diameter
hub_r        = hub_d / 2;

// ---- Model ----
difference() {
    union() {
        // Rim
        cylinder(d = outer_d, h = thickness);

        // Recess between rim and hub
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = thickness + 2 * eps);

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes: from hub outer edge to rim inner edge
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([hub_r, 0, -eps])
                rotate([0, 0, a])
                    cube([rim_id / 2 - hub_r, spoke_w, thickness + 2 * eps]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
```

