// Spoked wheel for a small sample cart
// Flat part lying on the bed, centred on the origin

// ---- Dimensions (mm) ----
wheel_od     = 100;   // outer diameter of rim
wheel_width  = 6;     // rim width (also hub height)
hub_d        = 14;    // hub diameter
axle_d       = 6;     // axle hole diameter
spoke_count  = 6;     // number of spokes
spoke_w      = 5;     // spoke width
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;            // smoothness of curved shapes

// ---- Model ----
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = wheel_od, h = wheel_width);

        // Hub with axle hole
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = wheel_width + 2 * eps, $fn = 96);

        // Radial spokes from hub to rim, first along +X axis
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - eps, -spoke_w / 2, -eps])
                    cube([spoke_w + 2 * eps, spoke_w, wheel_width + 2 * eps]);
    }

    // Axle hole through the centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_width + 2 * eps, $fn = 64);
}
