// Spoked wheel for a small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---------------- Parameters ----------------
part_thickness   = 6;     // overall part thickness (Z)
rim_outer_d      = 80;    // outer diameter of rim
rim_width        = 4;     // rim width (radial)
hub_d            = 16;    // hub outer diameter
axle_hole_d      = 8;     // axle hole diameter
spoke_count      = 4;     // number of spokes
spoke_width      = 5;     // spoke width (radial and tangential)
spoke_start_ang  = 0;     // first spoke along +X axis
cut_overlap      = 0.5;   // extra length of cutters past faces
$fn              = 128;   // facet count for curved shapes

// ---------------- Derived ----------------
rim_inner_d = rim_outer_d - 2 * rim_width;   // 72 mm
hub_r      = hub_d / 2;
spoke_len  = rim_inner_d / 2 + cut_overlap;  // runs from hub to rim

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        cylinder(d = rim_outer_d, h = part_thickness);

        // Hub (overlaps the rim so the union is one solid)
        translate([0, 0, -cut_overlap])
            cylinder(d = hub_d, h = part_thickness + 2 * cut_overlap);

        // Spokes: radial slots from hub outward, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_r - cut_overlap, 0, -cut_overlap])
                rotate([0, 0, a])
                    translate([-spoke_width / 2, -spoke_width / 2, 0])
                        cube([spoke_len, spoke_width, part_thickness + 2 * cut_overlap]);
        }
    }

    // Through axle hole in the hub
    translate([0, 0, -cut_overlap])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_overlap, $fn = 64);
}
