// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

$fn = 96;

// --- Dimensions (mm) ---
part_thickness   = 6;    // total thickness of the wheel
outer_diameter   = 80;   // outer diameter of the rim
rim_width        = 4;    // width of the rim (radial)
hub_diameter     = 16;   // diameter of the central hub
axle_hole        = 8;    // diameter of the axle hole through the hub
spoke_count      = 4;    // number of spokes
spoke_width      = 5;    // width of each spoke (radial)
spoke_start_ang  = 0;    // angle of the first spoke (deg, 0 = +X axis)
cut_overlap      = 0.5;  // extra length for cutting shapes to pass through faces

// Derived
rim_inner_d = outer_diameter - 2 * rim_width;

module wheel() {
    difference() {
        union() {
            // Outer rim (ring)
            cylinder(d = outer_diameter, h = part_thickness);

            // Central hub with axle hole
            translate([0, 0, -cut_overlap])
                difference() {
                    cylinder(d = hub_diameter, h = part_thickness + 2 * cut_overlap);
                    translate([0, 0, -cut_overlap])
                        cylinder(d = axle_hole, h = part_thickness + 2 * cut_overlap);
                }
        }

        // Spokes, running radially from the hub to the rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([0, 0, -cut_overlap])
                rotate([0, 0, a])
                    cube([spoke_width, hub_diameter / 2 + cut_overlap, part_thickness + 2 * cut_overlap]);
        }
    }
}

wheel();
