// Spoked wheel for a small sample cart
// Print orientation: flat on bed, builds up +Z, centred on origin in X/Y

$fn = 96;

// --- Dimensions (mm) ---
wheel_d        = 100;   // outer diameter
wheel_w        = 6;     // wheel thickness
rim_d          = 90;    // rim inner diameter (10 mm rim margin)
rim_t          = 5;     // rim width (radial)
hub_d          = 14;    // hub diameter
axle_hole_d    = 5;     // axle hole diameter
spoke_count    = 5;     // number of spokes
spoke_w        = 4;     // spoke width
spoke_start_a  = 0;     // first spoke along +X axis
cut_margin     = 0.5;   // overshoot for clean boolean cuts

// Derived
rim_od = rim_d + 2 * rim_t;

module wheel() {
    union() {
        // Rim
        translate([0, 0, -cut_margin])
            hull() {
                cylinder(d = wheel_d, h = cut_margin);
                cylinder(d = rim_od, h = wheel_w);
                cylinder(d = rim_d, h = cut_margin);
            }

        // Hub
        translate([0, 0, -cut_margin])
            cylinder(d = hub_d, h = wheel_w + 2 * cut_margin);

        // Axle hole
        translate([0, 0, -cut_margin])
            cylinder(d = axle_hole_d, h = wheel_w + 2 * cut_margin);

        // Spokes: from hub radius to rim inner radius
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_a + i * 360 / spoke_count;
            translate([0, 0, -cut_margin])
                rotate([0, 0, a])
                    translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                        cube([(hub_d / 2 - 1) + spoke_w, spoke_w, wheel_w + 2 * cut_margin]);
        }
    }
}

wheel();
