    difference() {
        cylinder(d = rim_od, h = wheel_t);
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = wheel_t + 2 * eps);
    }

    // Hub with axle hole
    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = wheel_t + eps);
            translate([0, 0, -eps])
                cylinder(d = axle_d, h = wheel_t + 2 * eps);
        }

    // Spokes: radial blocks from hub to rim
    for (i = [0 : spokes - 1]) {
        a = spoke_start + i * 360 / spokes;
        translate([hub_d / 2 - 1, -spoke_w / 2, -eps])
            rotate([0, 0, a])
                cube([spoke_w, spoke_w, wheel_t + eps]);
    }
}
