// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// Positioned per user coordinates: X -7.5 .. 7.5, Y -7 .. 7, Z 0 .. 7

$fn = 64;

// ---- Flange ----
flange_width = 14;   // Y extent of flange
flange_thick = 3;    // Z thickness of flange (z = 0..3)

// ---- Neck ----
neck_width   = 8;    // Y extent of neck
neck_top_z   = 7;    // top of neck (neck runs z = 3..7)

// ---- Screw hole ----
