// 2D (x, y) -> (Y, Z); rotate 90 deg so the extrusion runs along X
module profile_2d() {
    polygon(points = [
        [-flange_width/2, 0],
        [ flange_width/2, 0],
        [ flange_width/2, flange_t],
        [ neck_width/2,  flange_t],
        [ neck_width/2,  neck_top_z],
        [0,              neck_top_z],
        [0,              flange_t],
        [-neck_width/2,  flange_t],
        [-flange_width/2, flange_t]
    ]);
}

// ---------------- Part ----------------
difference() {
    // T-shaped body
    translate([-length_x/2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                profile_2d();

    // Screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
