flange_width = 10;    // Y extent of flange
flange_thick = 2.5;   // Z thickness of flange (z = 0 .. 2.5)

// ---- Neck ----
neck_width = 7;       // Y extent of neck (above flange)
neck_top_z = 6.5;     // Z height of neck top

// ---- Screw hole ----
screw_d = 4.5;        // diameter of vertical screw hole
hole_overcut = 0.5;   // extra length so cutter passes through top and bottom faces

