    union() {
        // Bottom flange: 2D rectangle 10 (X) x 2.5 (Z), centred (-5, 1.25)
        translate([-flange_width / 2, 0, 0])
            cube([flange_width, flange_thick, 1]);
        // Neck: 2D rectangle 7 (X) x 4 (Z), centred (-3.5, 4.25)
        translate([-neck_width / 2, flange_thick, 0])
            cube([neck_width, neck_top_z - flange_thick, 1]);
    }
}

module body() {
    // Extrude profile along Y from -10 to 0 (user's X range), centred on origin
    rotate([90, 0, 90])
        linear_extrude(height = 10, center = true)
            t_profile();
}

