flange_thick    = 2.5;   // flange thickness (z = 0 to 2.5)
neck_width      = 7;     // neck width along Y
neck_top_z      = 6.5;   // top of neck (neck runs z = 2.5 to 6.5)
screw_d         = 4.5;   // vertical screw hole diameter
