flange_z1       = flange_thick;
neck_z0         = flange_z1;
neck_z1         = neck_top_z;
overall_z1      = neck_z1;

// ---------------- Profile (X-Y) ----------------
// Bottom flange: x = -5 .. 5, y = 0 .. 10
// Neck: x = -3.5 .. 3.5, y = 0 .. 7, raised to the flange top
profile_pts = concat(
    [-5,   0], [5,   0],
    [5,   2.5], [-5,  2.5],   // flange inner edge (y = 2.5)
    [-3.5, 6.5], [3.5, 6.5],  // neck outer edge (y = 6.5)
    [3.5, 2.5], [-3.5, 2.5]  // neck inner edge (y = 2.5)
);

// ---------------- Model ----------------
difference() {
    union() {
        // Flat-bottomed flange
        translate([-5, 0, flange_z0])
            cube([10, flange_width, flange_z1 - flange_z0]);

        // Centred neck overlapping the flange
        translate([-3.5, 0, neck_z0 - cut_overlap])
            cube([7, neck_width, neck_z1 - (neck_z0 - cut_overlap)]);
    }

    // Vertical screw hole through the full height
    translate([0, 0, -cut_overlap])
        cylinder(d = screw_d, h = overall_z1 + 2 * cut_overlap);
}

