```openscad
// Anti-vibration foot - truncated cone with a rubber pad recess and a screw hole
// Units: mm. Print orientation: bottom face on the bed (z = 0), building up +Z.

// ---------- Dimensions ----------
foot_height      = 15;    // overall height of the frustum
foot_bottom_d    = 40;    // diameter at the bottom face (z = 0)
foot_top_d       = 32;    // diameter at the flat top face (z = 15)

recess_d         = 32;    // diameter of the round recess for the rubber pad
recess_depth     = 2;     // depth of the recess from the bottom face

screw_d          = 5.5;   // diameter of the through screw hole (on the axis)

overcut          = 0.5;   // extra length so cutters pass through faces

$fn = 96;                 // curve resolution

// ---------- Model ----------
difference() {
    // Truncated cone: hull between two coaxial cylinders
    union() {
        cylinder(d = foot_bottom_d, h = foot_height, $fn = 96);
        translate([0, 0, foot_height])
            cylinder(d = foot_top_d, h = 1, $fn = 96);
    }

    // Rubber pad recess, cut into the bottom face
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + overcut, $fn = 96);

    // Central screw hole, runs through the whole part
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = foot_height + 2 * overcut, $fn = 96);
}
