// Print orientation: flat on bed, recess facing down

// ---- Dimensions (mm) ----
bottom_d     = 30;   // frustum diameter at z = 0
top_d        = 22;   // frustum diameter at z = 12
height       = 12;   // frustum height
recess_d     = 22;   // rubber pad recess diameter
recess_depth = 2;    // rubber pad recess depth
screw_d      = 5.5;  // central screw hole diameter
eps          = 0.5;  // cutter overshoot past faces

$fn = 96;

difference() {
    // Truncated cone, centred on Z axis
    cylinder(d1 = bottom_d, d2 = top_d, h = height);

    // Round recess in bottom face for rubber pad
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through hole for screw along axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = height + 2 * eps);
}
```

