```openscad
// Stiffened cover panel - flat plate with 4 transverse ribs
// Print orientation: plate flat on bed (z = 0), ribs pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 120;  // length along X
plate_wid   = 60;   // width along Y
plate_thk   = 2;    // thickness (z = 0 to 2)

// ---- Ribs ----
rib_count   = 4;    // number of ribs
rib_thk     = 3;    // rib thickness along X
rib_h       = 6;    // rib height from top of plate (z = 2 to 8)
rib_pitch   = 24;   // centre-to-centre spacing along X
rib_margin  = 24;   // distance of outer rib centres from plate ends

// ---- Misc ----
overlap     = 0.01; // small overlap so ribs fuse with plate

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module ribs() {
    for (i = [0 : rib_count - 1]) {
        x = (i - (rib_count - 1)/2) * rib_pitch + rib_margin - rib_thk/2;
        translate([x, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}

union() {
    plate();
    ribs();
}
```

