```openscad
// Stiffened cover panel
// Print orientation: plate flat on the bed, ribs pointing up (+Z)

$fn = 64;

// ---- Panel ----
panel_len   = 120;  // panel length along X (mm)
panel_wid   = 50;   // panel width along Y (mm)
panel_thk   = 2;    // panel thickness (mm), z = 0..2

// ---- Ribs ----
rib_count   = 4;    // number of ribs
rib_thk     = 3;    // rib thickness along X (mm)
rib_h       = 5;    // rib height above panel (mm), z = 2..7
rib_pitch   = 24;   // centre-to-centre spacing of ribs along X (mm)
rib_start_x = 24;   // distance of outer rib centres from panel ends (mm)

// ---- Misc ----
overlap     = 0.5;  // extra length so ribs fuse into the panel

// X positions of the rib centres: 24, 48, 72, 96
function rib_centres() =
    [for (i = [0 : rib_count - 1])
     rib_start_x + i * rib_pitch];

module panel() {
    translate([-panel_len / 2, -panel_wid / 2, 0])
        cube([panel_len, panel_wid, panel_thk]);
}

module ribs() {
    for (cx = rib_centres())
        translate([cx - rib_thk / 2, -panel_wid / 2, panel_thk])
            cube([rib_thk, panel_wid, rib_h + overlap]);
}

union() {
    panel();
    ribs();
}
