module stiffened_panel() {
    union() {
        // Base plate, centred in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Ribs running full width along Y
        for (i = [0 : rib_count - 1]) {
            translate([rib_x0 + (i - (rib_count - 1)/2) * rib_pitch - rib_thk/2,
                       -plate_wid/2, 0])
                cube([rib_thk + eps, plate_wid, rib_h_total]);
        }
    }
}

stiffened_panel();
