// Stiffened cover panel - flat plate with 3 transverse ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

$fn = 64;

// ---------------- Plate ----------------
plate_len    = 120;   // plate length along X
plate_wid    = 80;    // plate width along Y
plate_thk    = 2;     // plate thickness (z = 0 to 2)

// ---------------- Ribs ----------------
rib_count    = 3;     // number of ribs
rib_thk      = 2;     // rib thickness along X
rib_h        = 6;     // rib total height (z = 0 to 6, sits on plate)
rib_pitch    = 30;    // centre-to-centre spacing along X
rib_end_off  = 30;    // distance of outer rib centres from plate ends

// ---------------- Misc ----------------
overlap      = 0.01;  // small overlap so ribs fuse with plate

// Derived
rib_span = (rib_count - 1) * rib_pitch;   // distance between outer rib centres

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module ribs() {
    for (i = [0 : rib_count - 1]) {
        x = (i == 0) ? -rib_end_off :
            (i == rib_count - 1) ? rib_end_off :
            (rib_span / 2 - rib_pitch);    // middle rib, centred on origin
        translate([x - rib_thk/2, -plate_wid/2, 0])
            cube([rib_thk, plate_wid, rib_h]);
    }
}

union() {
    plate();
    ribs();
}
