difference() {
    union() {
        // Lower half of hollow sphere
        translate([0, 0, outer_r])
            difference() {
                sphere(r = outer_r);
                translate([0, 0, -eps])
                    cylinder(r = outer_r + 2 * eps, h = outer_r + eps);
