    // Debloat overlapping regions
    translate([0, 0, outer_r - eps])
        difference() {
            cube([outer_r + eps, handle_y + 2 * eps, handle_t + eps]);
            translate([handle_x0, -handle_y / 2 - eps, 0])
                cube([handle_x1 - handle_x0, handle_y + 2 * eps, handle_t + eps]);
        }
