// Measuring scoop for powders
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle on top.

$fn = 96;

// ---- Bowl ----
outer_radius   = 10;    // outer radius of spherical bowl
wall_thickness = 2;     // wall thickness (hollow)
bowl_centre_z  = 10;    // z of sphere centre (lower half kept)

// ---- Handle ----
handle_length  = 62;    // X length of handle (x = 8 .. 70)
handle_width   = 12;    // Y width of handle
handle_thick   = 4;     // Z thickness of handle (top flush with rim)

// ---- Cutting overlap ----
eps = 0.5;              // extension past cut faces to avoid coplanar faces

module bowl() {
    difference() {
        translate([0, 0, bowl_centre_z])
            sphere(r = outer_radius);
        translate([0, 0, -eps])
            sphere(r = outer_radius - wall_thickness);
    }
}

module handle() {
    translate([8, -handle_width / 2, bowl_centre_z - handle_thick])
        cube([handle_length, handle_width, handle_thick]);
}

union() {
    bowl();
    handle();
}
