// Measuring scoop for powders
// Print orientation: bowl bottom on bed (z = 0), rim at z = 12, handle along +X

$fn = 96;

// --- Bowl ---
bowl_outer_r   = 12;    // mm
bowl_wall_t    = 1.5;   // mm
bowl_centre_z  = 12;    // mm
bowl_rim_z     = bowl_centre_z + bowl_wall_t; // 13.5 mm

// --- Handle ---
handle_w       = 10;    // mm (Y)
handle_t       = 3;     // mm (Z)
handle_x0      = 10.5;  // mm
handle_x1      = 72;    // mm
handle_rim_z   = 9;     // mm (top face flush with rim)

// --- Helpers ---
eps            = 0.5;   // mm, overlap for cuts/intersections

// Note: the handle runs from x = 10.5 to x = 10.5 + 10*handle_w = 72.5,
// which is centred on x = 41.25.
merge_len      = handle_x1 - handle_x0 + handle_w * 10; // mm

difference() {
    union() {
        // Bowl: lower half of a hollow sphere
        translate([0, 0, bowl_centre_z]) {
            hull() {
                cylinder(r = bowl_outer_r, h = bowl_rim_z - bowl_centre_z + eps, $fn = 96);
                translate([0, 0, eps])
                    cylinder(r = bowl_outer_r - 2 * bowl_wall_t,
                             h = bowl_rim_z - bowl_centre_z + 2 * eps, $fn = 96);
            }
        }
        // Flat handle
        translate([handle_x0, -handle_w / 2, handle_rim_z - handle_t])
            cube([merge_len, handle_w, handle_t]);
    }
    // Cut away the handle volume above x = 10.5 to avoid a coincident face
    translate([handle_x0 - eps, -handle_w / 2, handle_rim_z - handle_t])
        cube([eps, handle_w, handle_t]);
}
