// Powder measuring scoop
// Print orientation: handle on the bed (z = 0), bowl rising upward.
// The user specified absolute Z values for the bowl (z = 0..12), so the
// handle is placed at that base level and fused into the union.

$fn = 96;

// ---- Bowl ----
outer_r      = 12;   // outer radius of the spherical bowl
wall_t       = 1.5;  // wall thickness (hollowing radius)
bowl_h       = 12;   // height of the bowl bottom (z of rim and handle top)
bowl_start   = bowl_h;       // z where the sphere begins
bowl_end     = bowl_h + outer_r; // z of the sphere's south pole

// ---- Handle ----
handle_x0    = 10.5; // handle start (X)
handle_x1    = 72;   // handle end (X)
handle_w     = 10;   // handle width (Y)
handle_t     = 3;    // handle thickness (Z)

// ---- Cutting overlap ----
eps          = 0.5;  // extension of cutters past the faces they cut

difference() {
    union() {
        // Hollow sphere: only the lower half, so the bowl opens upward.
        translate([0, 0, bowl_start])
            difference() {
                cylinder(h = outer_r, r = outer_r);
                translate([0, 0, wall_t])
                    cylinder(h = outer_r - wall_t, r = outer_r - wall_t);
            }

        // Straight flat handle along +X, centred on y = 0
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Remove the upper half of the sphere so the rim sits at z = bowl_h.
    // The cutter runs from bowl_h down to bowl_end - eps, staying above the
    // southernmost point of the outer surface.
    translate([0, 0, bowl_h])
        rotate([0, 180, 0])
            cylinder(h = outer_r - eps, r = outer_r);
}
