        // Straight flat handle along +X
        translate([bowl_center_z - embed, -handle_w / 2,
                   bowl_center_z - handle_t])
            cube([handle_len, handle_w, handle_t]);
    }

    // Extension past the rim, keeping the same wall thickness
    translate([bowl_center_z - embed, -handle_w / 2 - eps,
               bowl_center_z - handle_t])
        cube([embed + eps, handle_w + 2 * eps, handle_t]);
