            cylinder(r = bowl_r, h = bowl_r);               // upper half (stability)
        translate([0, 0, -bowl_h])
            cylinder(r = bowl_r + 2*eps, h = 2*bowl_h + 2*eps); // full outer shape
        translate([0, 0, -eps])
            cube([2*bowl_r + 4*eps, 2*bowl_r + 4*eps, eps]); // flatten bottom at z = 0
    }
}

