// Powder measuring scoop
// Print orientation: handle flat on bed, bowl pointing up

$fn = 96;

// --- Bowl ---
bowl_od    = 12;   // outer diameter of bowl (mm)
bowl_r     = bowl_od / 2;      // outer radius (mm)
bowl_h     = bowl_r;       // bowl height from bottom (mm)
bowl_wall  = 2;             // wall thickness (mm)

// --- Handle ---
handle_w   = 12;   // handle width (mm)
handle_t   = 4;     // handle thickness (mm)
handle_x0  = 10;    // handle start X (mm)
handle_x1  = 72;    // handle end X (mm)

// --- Integration ---
eps        = 0.5;   // overlap for clean unions / cuts (mm)

difference() {
    union() {
        // Half-sphere bowl (lower half, opens upward)
        translate([0, 0, bowl_h])
            difference() {
                sphere(d = bowl_od);
                translate([0, 0, -eps])
                    cube([bowl_od * 2, bowl_od * 2, eps]);
            }

        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Lower the bowl bottom so it touches the bed at z = 0
    translate([0, 0, bowl_h - eps])
        difference() {
            sphere(d = bowl_od - 2 * bowl_wall);
            translate([0, 0, -eps])
                cube([bowl_od - 2 * bowl_wall,
                      bowl_od - 2 * bowl_wall,
                      eps]);
        }
    // (a solid ghost of the inner volume, kept at the same height,
    //  so the wall stays where it belongs)
}
