```openscad
// Powder measuring scoop
// Print orientation: handle along +X, its top face flush with the rim.

$fn = 96;

// ---- Bowls ----
outer_r      = 15;    // outer radius of the sphere
wall         = 1.5;   // wall thickness
bowl_bottom  = 0;     // z of the lower pole (touches the bed)

// ---- Handle ----
handle_w     = 8;     // handle width (Y)
handle_t     = 4;     // handle thickness (Z)
handle_x0    = 13.5;  // start of handle (X)
handle_x1    = 95;    // end of handle (X)
rim_z        = outer_r; // rim height (top face of the handle)

// ---- Cut clearance ----
eps          = 0.5;   // extension of cutting shapes past the faces they cut

// Derived
inner_r = outer_r - wall;

module sphere_bowl() {
    // lower half of a hollow sphere: z = bowl_bottom .. rim_z
    translate([0, 0, bowl_bottom])
        difference() {
            sphere(r = outer_r, h = outer_r + 1);
            translate([0, 0, bowl_bottom + eps])
                sphere(r = inner_r, h = inner_r + 1 + 2 * eps);
        }
}

module flat_handle() {
    translate([handle_x0, -handle_w / 2, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

union() {
    sphere_bowl();
    flat_handle();
}
