// Ring weight for a flask neck, used in a water bath
// Print orientation: flat on the bed, middle plane at z = 6

// ---------------- Parameters ----------------
torus_d          = 12;   // diameter of the torus cross-section (mm)
torus_r          = 28;   // radius of the torus (mm)
cutting_plane_z  = 6;    // z position of the cutting plane (mm)
cut_margin       = 1;    // extra length on the cutting shapes (mm)
$fn              = 128;  // facet count for curved surfaces

// ---------------- Model ----------------
intersection() {
    // Torus: a circle of diameter `torus_d` swept around the Z axis
    // on a circle of radius `torus_r`. Placed at the user-specified
    // middle plane `cutting_plane_z`.
    translate([0, 0, cutting_plane_z])
        rotate([90, 0, 0])
            cylinder(d = torus_d, r = torus_r, $fn = $fn);

    // A flat disc that cuts the torus in half, passing through its
    // lowest point (z = cutting_plane_z - torus_d/2), so the result
    // rests on z = 0. The disc extends `cut_margin` mm above the
    // top face of the torus to avoid coplanar faces.
    translate([0, 0, cutting_plane_z - torus_d / 2 - cut_margin])
        rotate([0, 90, 0])
            cylinder(d = torus_r * 2 + 2 * cut_margin, h = torus_d / 2 + cut_margin);
}
