// Ring weight - torus lying flat on the bed
// Print orientation: bottom surface on z = 0, builds upward (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
cross_section_d   = 12;    // diameter of the circular cross-section
ring_centre_r     = 35;    // radius of the Z-axis circle on which the cross-section centre lies
ring_width        = 82;    // overall ring diameter (across)
ring_middle_z     = 6;     // height of the cross-section's middle plane
cut_extra         = 0.5;   // overshoot for clean boolean cuts

// Derived
ring_centre_y     = cross_section_d / 2 + ring_middle_z;   // height of cross-section top
