ring_inward_r     = ring_centre_r - cross_section_d / 2;   // inner radius of torus

module cross_section() {
    difference() {
        // cylinder along Y, centred on its axis (at z = ring_middle_z)
        cylinder(d = cross_section_d, h = ring_width, $fn = 96);
        // cut away everything below z = 0 and above the top of the section
        translate([-(ring_outward_r + cut_extra), 0, -cut_extra])
            cube([2 * (ring_outward_r + cut_extra),
                  ring_centre_y + cut_extra,
                  2 * cut_extra]);
    }
}

difference() {
    // revolve the cross-section around the Z axis
    rotate([90, 0, 0])
        linear_extrude(height = ring_width)
            circle(d = cross_section_d);

    // remove a coaxial core that runs from z = 0 up to ring_middle_z,
    // with a small wall (cut_extra) so no faces are coplanar
    translate([0, 0, 0])
        cylinder(r = ring_inward_r + cut_extra,
                 h = ring_middle_z + cut_extra,
                 $fn = 96);
}
