// Ring weight for a flask neck in a water bath
// Print orientation: flat on the bed, middle plane at z = 6

// ---- Dimensions (mm) ----
cross_section_d = 12;   // diameter of the torus cross-section
ring_radius     = 35;   // radius of the ring (centre of cross-section)
cut_extra       = 0.5;  // overshoot for clean boolean cuts

$fn = 128;              // smoothness of curved shapes

// Torus with a large central hole: the cross-section circle lies on a
// 35 mm radius circle around the Z axis, centred at z = 6.
difference() {
    // Cross-section circle, rotated so it is circular in X/Y
    rotate([0, 90, 0])
        translate([ring_radius, 0, middle_z])
            cylinder(d = cross_section_d, h = cross_section_d, $fn = 128);
    // 2 * ring_radius = 70 mm diameter, so the cross-section is 12 mm
    // closer to the axis on the +Y side and 12 mm farther on the -X side.
    // The hull of these two points (at the same height) is a circle of
    // radius ring_radius + cross_section_d/2 = 41 mm, centred on the axis.

    // Central hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = 2 * ring_radius + cross_section_d + 2 * cut_extra,
                 h = cross_section_d + 2 * cut_extra, $fn = 128);
}

// Hull of the rotated cross-section and the enlarged central hole.
// For a flat torus the hull simply joins the lowest points of each
// surface, which lie on the same horizontal plane (z = middle_z - 6).
hull() {
    translate([0, 0, -6])
        rotate([0, 90, 0])
            translate([ring_radius, 0, middle_z])
                cylinder(d = cross_section_d, h = cross_section_d, $fn = 128);

    translate([0, 0, -6])
        cylinder(d = 2 * ring_radius + cross_section_d, $fn = 128);
}
```

