// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_h   = 6;     // knuckle height above plate (mm)
knuckle_p0  = -15;   // x position of first knuckle (mm)
knuckle_p   = 10;    // spacing between knuckles (mm)
knuckle_n   = 5;     // number of segments
knuckle_on  = [1,3,5]; // segments with knuckles

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
knuckle_count = len(knuckle_on);
plate_half_w  = plate_wid / 2;

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_half_w, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on specified segments
        for (i = [0 : knuckle_count - 1]) {
            x = knuckle_p0 + (knuckle_on[i] - 1) * knuckle_p;
            translate([x, plate_half_w, 0])
                cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin hole along X through all knuckles
    translate([knuckle_p0 - eps, plate_half_w, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
}
