// ---------------- Parameters ----------------
plate_len    = 60;    // plate length along X (mm)
plate_wid    = 30;    // plate width along Y (mm)
plate_thk    = 2.5;   // plate thickness along Z (mm)

segment_len  = 12;    // length of each X segment along +Y edge (mm)
segment_n    = 5;     // number of segments (1st, 3rd, 5th get knuckles)
knuckle_d    = 8;     // knuckle cylinder diameter (mm)
knuckle_z    = 4;     // height of knuckle axis above plate (mm)

pin_d        = 2.5;   // pin hole diameter (mm)
eps          = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;             // facet count for round features

// ---------------- Derived ----------------
half_plate = plate_len / 2;   // 30 mm
// Knuckle centres: 1st -> -18, 3rd -> 0, 5th -> 18 (3 x 24 mm span)
knuckle_span = (segment_n - 1) * segment_len * 2 / 2;  

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-half_plate, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along X at y = 15, z = 4
        for (i = [-segment_n / 2 : segment_n / 2]) {
            // Only 1st (i=-2), 3rd (i=0), 5th (i=2) segments
            if (abs(i) <= segment_n / 2 && (i < 0 || i > 0 || segment_n % 2 == 1)) {
                translate([i * segment_len - segment_len / 2,
                           plate_wid / 2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = 10, $fn = 96);
            }
        }
    }

    // Pin hole along the knuckle axis (y = 15, z = 4)
    translate([0, plate_wid / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_span + 2 * eps, $fn = 96);
