```openscad
// Leaf of a pin hinge
// Units: mm. Print orientation: plate flat on bed, knuckles pointing up.

$fn = 96;

// ---- Plate ----
plate_len    = 60;   // X length of base plate
plate_wid    = 30;   // Y width of base plate
plate_thk    = 2.5;  // Z thickness of base plate

// ---- Knuckles ----
knuckle_d    = 8;    // diameter of each cylindrical knuckle
knuckle_h    = 8;    // height of each knuckle above its pivot line
knuckle_juc  = 3;    // number of knuckles (1st, 3rd, 5th segments)
knuckle_w    = plate_len / knuckle_juc / 2; // half-segment width
knuckle_r    = plate_wid / 2;              // distance from origin to +Y edge

// ---- Pin ----
pin_d        = 2.5;  // diameter of pin hole through each knuckle

// ---- Misc ----
eps          = 0.5;  // cutter overshoot past faces

// Base plate
module base_plate() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

// Knuckles, mounted on the edge along X at y = knuckle_r
module knuckle_bank() {
    for (i = [0 : knuckle_juc - 1]) {
        x = (i % 2) * knuckle_w;   // 0: left end, 1: right end of segment
        translate([x, knuckle_r, 0])
            cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
    }
}

// Pin holes
module pin_holes() {
    for (i = [0 : knuckle_juc - 1]) {
        x = (i % 2) * knuckle_w;
        translate([x, knuckle_r, -eps])
            cylinder(d = pin_d, h = knuckle_h + 2 * eps, $fn = 96);
    }
}

difference() {
    union() {
        base_plate();
        knuckle_bank();
    }
    pin_holes();
}
```

