// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 50;   // X length of plate
plate_wid   = 20;   // Y width of plate
plate_thk   = 2.5;  // Z thickness of plate

// ---- Knuckles ----
knuckle_d     = 6;  // knuckle cylinder diameter
knuckle_y     = 10; // knuckle axis Y position (on +Y edge)
knuckle_z     = 3;  // knuckle axis height above plate
knuckle_count = 5;  // total number of segments
knuckle_step  = plate_len / knuckle_count; // segment length (10 mm)
knuckle_idxs  = [1, 3, 5]; // 1-based segment indices with knuckles

// ---- Pin hole ----
pin_d = 3; // hole diameter through every knuckle

// ---- Misc ----
eps = 0.5; // overshoot for clean boolean cuts

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_count - 1]) {
        if (!(i + 1) in knuckle_idxs)
            continue;
        x = -plate_len/2 + i * knuckle_step + knuckle_step/2;
        translate([x, knuckle_y, knuckle_z])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2*eps);
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2*eps);
            }
    }
}

union() {
    plate();
    knuckles();
}
