```openscad
// Pin hinge leaf
// Flat plate along X, knuckles on the +Y edge. Prints flat on the bed.

// ---------- Parameters ----------
plate_len   = 60;    // plate length (X)
plate_wid   = 30;    // plate width (Y)
plate_t     = 2.5;   // plate thickness (Z)

knuckle_d   = 6;     // knuckle diameter
knuckle_h   = 10;    // knuckle height above plate top
knuckle_z0  = 3;     // knuckle axis height (plate top + 0.5)

pin_d       = 2;     // pin hole diameter
pin_overlap = 1;     // how far the pin runs into each knuckle

segments    = 3;     // equal length segments along X
eps         = 0.5;   // cutter overshoot

$fn = 96;            // smoothness of curved surfaces

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_t]);

        // Knuckles on the 1st and 3rd segments
        for (i = [0, segments - 1]) {
            x = (i * plate_len/segments - plate_len/2 + plate_len/segments/2);
            translate([x, plate_wid/2, knuckle_z0])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
        }
    }

    // Pin axis hole through every knuckle
    for (i = [0, segments - 1]) {
        x = (i * plate_len/segments - plate_len/2 + plate_len/segments/2);
        translate([x, plate_wid/2, pin_overlap])
            cylinder(d = pin_d, h = knuckle_h - pin_overlap + eps, $fn = 96);
    }
}
