// 6-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

// ---- Dimensions (mm) ----
outer_r    = 35;    // distance of outer points from centre
inner_r    = 17.5;  // distance of inner points from centre
thickness  = 3;     // plate thickness
hole_d     = 6;     // central through-hole diameter
cut_extra  = 0.5;   // overshoot of cutters past faces
$fn        = 96;    // circle resolution

// ---- Model ----
difference() {
    // Star outline: alternating outer/inner points, first outer on +X
    hull() {
        for (i = [0 : 5])
            rotate([0, 0, i * 60])
                union() {
                    translate([outer_r, 0, 0])
                        cylinder(h = thickness, r = outer_r);
                    translate([-inner_r, 0, 0])
                        cylinder(h = thickness, r = inner_r);
                }
    }

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(h = thickness + 2 * cut_extra, d = hole_d);
}
