```openscad
// 6-pointed star (angle 0 on +X)
// Print flat on the bed, centred on the origin

// ---------------- Parameters ----------------
star_points     = 6;    // number of outer/inner points
outer_point_r   = 35;   // distance of outer points from centre (mm)
inner_point_r   = 17.5; // distance of inner points from centre (mm)
plate_thickness = 3;    // plate thickness (mm)
hole_d          = 6;    // central through-hole diameter (mm)
cut_extra       = 0.5;  // extra length on cutting shapes past faces (mm)
$fn             = 128;  // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline, extruded to plate thickness
    linear_extrude(height = plate_thickness) {
        polygon([
            // outer points
            // [r, 0], [r cos 60, r sin 60], ..., [r cos -60, r sin -60]
            concat(
                [[outer_point_r, 0]],
                [for (i = [1 : star_points - 1])
                    [outer_point_r * cos(i * 360 / star_points),
                     outer_point_r * sin(i * 360 / star_points)]]
            ),
            // inner points (shifted by 30 degrees)
            // [r cos 30, r sin 30], ..., [r cos -30, r sin -30]
            concat(
                [for (i = [0 : star_points - 1])
                    [inner_point_r * cos(30 + i * 360 / star_points),
                     inner_point_r * sin(30 + i * 360 / star_points)]]
            )
        ])
    }

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thickness + 2 * cut_extra);
}
