            translate([outer_r * cos(i * 360 / points),
                       outer_r * sin(i * 360 / points)])
                line(p1 = [outer_r * cos(i * 360 / points),
                          outer_r * sin(i * 360 / points)],
                     p2 = [inner_r * cos((i + 0.5) * 360 / points),
                          inner_r * sin((i + 0.5) * 360 / points)]);
            // inner point
            translate([inner_r * cos((i + 0.5) * 360 / points),
                       inner_r * sin((i + 0.5) * 360 / points)])
                line(p1 = [inner_r * cos((i + 0.5) * 360 / points),
                          inner_r * sin((i + 0.5) * 360 / points)],
                     p2 = [outer_r * cos((i + 1) * 360 / points),
                          outer_r * sin((i + 1) * 360 / points)]);
