                    // inner point
                    translate([-inner_r, 0, -eps])
                        cylinder(r = eps, h = thickness + 2 * eps);
                }
        }
    }

    // central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
