// 6-pointed star wheel
// Print orientation: flat on bed, builds upward in +Z

// ---------------- Parameters ----------------
star_points    = 6;    // number of points on the star
outer_radius   = 40;   // distance of outer points from centre
inner_radius   = 20;   // distance of inner points from centre
