// ---------------- Model ----------------
difference() {
    // Star outline, drawn in XY, extruded in Z
    // rotate([90,0,0]) maps polygon's 2D angle to world YZ,
    // then translate by -inner_radius so the vertex sits at the origin.
    translate([0, -inner_radius, 0])
        rotate([90, 0, 0])
            linear_extrude(height = plate_thick)
                polygon([for (i = [0 : star_points - 1])
                    let (r = (i % 2) ? outer_radius : inner_radius)
                        [r, i * 360 / star_points]]);

    // Central through hole
    translate([0, 0, -cut_extra])
        cylinder(d = centre_hole, h = plate_thick + 2 * cut_extra);
}
