inner_off  = point_step / 2;        // offset so inner points lie between outer ones

union() {
    // Outer rim
    for (i = [0 : points - 1])
        rotate([0, 0, i * point_step])
            translate([outer_r, 0, 0])
                cylinder(h = thickness);

    // Inner points (concave regions)
    for (i = [0 : points - 1])
        rotate([0, 0, (i + inner_off / 180) * 360])
            translate([inner_r, 0, 0])
                cylinder(h = thickness);
}

// Central through-hole
translate([0, 0, -1])
    cylinder(d = hole_d, h = thickness + 2);
