bottom_z   = 0;     // z of the bottom face (mm)
top_w      = 70;    // side of the top square face (mm)
top_z      = 25;    // z of the top face (mm)
pocket_w   = 60;    // side of the square pocket (mm)
pocket_d   = 5;     // depth of the pocket into the top face (mm)
eps        = 0.5;   // overshoot for the cutting shapes (mm)
$fn        = 64;    // curve resolution (set per the user's instruction)

// ---------------- Derived values ----------------
// Side length of the frustum at a given z (linearly tapered)
function frustum_side(z) = bottom_w + (top_w - bottom_w) * (z - bottom_z) / (top_z - bottom_z);

// ---------------- Model ----------------
difference() {
    // Tapered block: a solid defined by an outer surface and the bed plane
    // The surface is built with hull() from the bottom and top edges,
    // then rotated so the hull runs along +Z and is extruded 1 mm above top_z.
    translate([-bottom_w / 2, -bottom_w / 2, bottom_z])
        hull() {
            // Bottom edge (at z = 0)
            translate([0, -bottom_w / 2, 0])
                cube([bottom_w, 1, 1]);
            // Top edge (at z = 25)
            translate([0, -top_w / 2, top_z])
                cube([top_w, 1, 1]);
        }
    // A thin slab above the top face acts as the "outer surface";
    // cutting the pocket through it leaves an open-top pocket.
    translate([0, 0, top_z])
        cube([frustum_side(top_z + eps), top_w + 2 * eps, eps]);

    // Square pocket, centred on the X and Y axes
    translate([0, 0, top_z - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);

    // Rest the solid on the bed by cutting away anything below z = 0
    translate([0, 0, -eps])
        cube([bottom_w + 2 * eps, top_w + 2 * eps, eps]);
}
