        linear_extrude(height = base_size)
            polygon([
                [-base_size / 2, -overlap],
                [ base_size / 2, -overlap],
                [ top_size / 2,  height - overlap],
                [-top_size / 2,  height - overlap]
            ]);
}

// ---------------- Part ----------------
difference() {
    // Solid frustum, built from four sloped faces
    union() {
        for (a = [0, 90, 180, 270])
            rotate([0, 0, a])
                tapered_face();
    }

    // Square pocket cut into the top face
    translate([0, 0, height])
        cube([pocket_size, pocket_size, pocket_depth + overlap]);
