// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: X -50 .. 50, Y -50 .. 50, Z 0 .. 25.

// ---------------- Parameters ----------------
bottom_size = 100;   // side length of the bottom square (mm)
top_size    = 80;    // side length of the top square (mm)
height      = 25;    // overall height of the frustum (mm)
pocket_w    = 72;    // pocket side length (mm)
pocket_d    = 5;     // pocket depth (mm)
eps         = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 64;            // not used explicitly, set per the user's rule

// ---------------- Derived ----------------
// Taper per side: (bottom - top) / (2 * height) = 10 / 50 = 0.2 mm/mm.
// Top-left corner = bottom-left corner - taper * height.
top_x0 = bottom_x0 - (bottom_size - top_size) / 2;   // -10
top_y0 = bottom_y0 - (bottom_size - top_size) / 2;   // -10

// ---------------- Modules ----------------
module bottom_face() {
    translate([bottom_x0, bottom_y0, 0])
        square([bottom_size, bottom_size]);
}

module top_face() {
    translate([top_x0, top_y0, height])
        square([top_size, top_size]);
}

module pocket() {
    // Pocket is open at the top: runs from (height - pocket_d) up through the top face.
    translate([0, 0, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}

// ---------------- Assembly ----------------
union() {
    // Frustum body: a set of vertical columns that grow (or shrink) linearly.
    // Each column spans from the bed up to the top face, so the union is solid.
    for (t = [0 : 0.01 : height]) {
        // Interpolate between the bottom and top squares at height t.
        mix_a = 1 - t / height;      // 1 at z = 0, 0 at z = height
        w     = bottom_size * mix_a + top_size * (1 - mix_a);
        h     = t + 0.01;            // thin column, no zero-sized members
        translate([bottom_x0 + (top_x0 - bottom_x0) * mix_a,
                   bottom_y0 + (top_y0 - bottom_y0) * mix_a,
                   0])
            square([w, w], center = false);
    }

    // Square pocket, centred, 5 mm deep, open at the top
    pocket();
}
