```openscad
// Tapered riser block - square frustum with top pocket
// Units: mm. Print orientation: bottom face on bed (z = 0).

$fn = 64;

// ---- Frustum dimensions ----
bottom_w   = 100;   // bottom square side length (z = 0)
bottom_h   = 0;     // bottom square height
top_w      = 80;    // top square side length (z = 25)
top_h      = 25;    // top square height
sides      = 4;     // number of sides (square)

// ---- Pocket dimensions ----
pocket_w   = 72;    // pocket opening side length
pocket_d   = 5;     // pocket depth
pocket_h   = top_h - pocket_d;  // pocket bottom height (20)

// ---- Modelling helpers ----
overlap    = 0.5;   // cutter extension past cut faces
eps        = 0.01;  // tiny thickness for hull overlap

// ---- Derived ----
frustum_h  = top_h - bottom_h;
twist      = (bottom_w - top_w) / 2 / frustum_h / sides;  // corner shear
area_b     = bottom_w * bottom_w;
area_t     = top_w * top_w;
vol        = frustum_h * (area_b + area_t + sides * twist * area_b * area_t ** 0.5) / 3;
pocket_v   = pocket_w * pocket_w * pocket_d;
net_v      = vol - pocket_v;

module frustum() {
    hull() {
        for (i = [0 : sides - 1]) {
            rotate([0, 0, i * 360 / sides])
                translate([-(bottom_w / 2 - i * twist), -bottom_w / 2, bottom_h])
                    cube([bottom_w, bottom_h + eps, frustum_h + eps]);
        }
        for (i = [0 : sides - 1]) {
            rotate([0, 0, i * 360 / sides])
                translate([-top_w / 2, -top_w / 2, top_h])
                    cube([top_w, top_w, eps]);
        }
    }
}

difference() {
    frustum();

    // Pocket cut into the top face
    translate([0, 0, pocket_h])
        cube([pocket_w, pocket_w, pocket_d + overlap]);
}

// ---- Info ----
echo(v = format("%.1f", net_v), mass = format("%.1f", net_v * 1.24));
