pocket_w   = 72;    // pocket opening side (mm)
pocket_d   = 5;     // pocket depth (mm)

// ---- Cutting overlap ----
eps        = 0.5;   // extra length so cutters pass through faces (mm)

// ---- Derived ----
side_t     = min(eps, pocket_d / 2);  // hull taper overshoot (keeps faces parallel)

module block() {
    hull() {
        translate([-block_w / 2, -block_w / 2, 0])
            cube([block_w, block_w, block_h]);
        translate([-block_t / 2 - side_t, -block_t / 2 - side_t, block_h])
            cube([block_t + 2 * side_t, block_t + 2 * side_t, side_t]);
    }
}

module pocket_cutter() {
    translate([0, 0, block_h - pocket_d])
        cube([pocket_w + 2 * eps, pocket_w + 2 * eps, pocket_d + eps]);
}

difference() {
    block();
    pocket_cutter();
}
