```openscad
// Tapered riser block with a square pocket
// Units: mm. Print orientation: base on bed (z = 0), pocket facing up.

$fn = 64;

// ---- Frustum dimensions ----
base_size    = 60;   // bottom square side length (z = 0)
top_size     = 40;   // top square side length (z = 25)
frustum_h    = 25;   // height of the frustum

// ---- Pocket dimensions ----
pocket_size  = 30;   // pocket side length
pocket_depth = 5;    // pocket depth from the top face

// ---- Derived ----
pitch      = (base_size - top_size) / frustum_h;  // taper rate (size decrease per mm of height)
pocket_top = frustum_h - pocket_depth;            // z of the pocket's top opening
overlap    = 0.5;  // extra cutter length past the top face

module frustum() {
    // linear_extrude uses 2D (x, y) coordinates; rotate so the square
    // sides stay parallel to X and Y. The profile runs from z = 0 to z = 25.
    rotate([90, 0, 45])
        linear_extrude(height = frustum_h)
            polygon(points = [
                [-base_size/2, -base_size/2],
                [ base_size/2, -base_size/2],
                [ base_size/2,  base_size/2],
                [-base_size/2,  base_size/2],
                [ top_size/2,   top_size/2],
                [-top_size/2,  top_size/2],
                [-top_size/2,  -top_size/2],
                [ top_size/2,  -top_size/2]
            ]);
}

module pocket_cutter() {
    // Centre the pocket on the origin in x and y, extend it upward
    // past the top face along +z.
    translate([-pocket_size/2, -pocket_size/2, 0])
        cube([pocket_size, pocket_size, pocket_top + overlap]);
}

difference() {
    frustum();
    pocket_cutter();
}
