        polygon([
            [-frustum_side(height, bottom, top, height) / 2,
             -frustum_side(height, bottom, top, height) / 2],
            [ frustum_side(height, bottom, top, height) / 2,
             -frustum_side(height, bottom, top, height) / 2],
            [ frustum_side(height, bottom, top, height) / 2,
              frustum_side(height, bottom, top, height) / 2],
            [-frustum_side(height, bottom, top, height) / 2,
              frustum_side(height, bottom, top, height) / 2]
