// Tapered riser block with a square pocket
// Units: mm. Print orientation: bottom face on the bed (z = 0).

$fn = 64;

// ---- Frustum dimensions ----
bottom_w   = 60;   // bottom square side length (X and Y)
bottom_h   = 0;    // bottom face height (z = 0)
top_w      = 40;   // top square side length (X and Y)
top_h      = 25;   // top face height (z = 25)

// ---- Pocket dimensions ----
pocket_w   = 30;   // pocket square side length (X and Y)
pocket_d   = 5;    // pocket depth from the top face

// ---- Modelling helpers ----
eps        = 0.5;  // overshoot for clean boolean cuts

// Derived
total_h    = top_h - bottom_h;              // frustum height
pitch      = (bottom_w - top_w) / 2 / total_h; // taper per mm height (positive: widens downward)

// Clamp the pocket cut to the actual solid height, in case the depth
// would exceed the top face on a very short part.
pocket_d_clamped = min(pocket_d, eps + 0.01);

module square_frustum() {
    // Extrude a 2D hull between the bottom and top square profiles.
    // With bottom_h = 0 the profile runs from z = 0 to z = top_h.
    hull() {
        for (z = [bottom_h, top_h])
            translate([-top_w/2 + (bottom_w - top_w)/2 * (z - bottom_h) / total_h,
                       -top_w/2 + (bottom_w - top_w)/2 * (z - bottom_h) / total_h,
                       z])
                square([top_w + 2 * pitch * (z - bottom_h),
                        top_w + 2 * pitch * (z - bottom_h)]);
    }
}

