// Tapered riser block with a square pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: X -50 .. 50, Y -50 .. 50, Z 0 .. 20.

// ---------------- Parameters ----------------
block_x      = 100;   // block bottom length in X (mm)
block_y      = 100;   // block bottom length in Y (mm)
block_h      = 20;    // block height (mm)
block_top_x  = 80;    // block top length in X (mm)
block_top_y  = 80;    // block top length in Y (mm)

pocket_x     = 72;    // pocket length in X (mm)
pocket_y     = 72;    // pocket length in Y (mm)
pocket_d     = 8;     // pocket depth from top face (mm)

eps          = 0.5;   // overshoot for the pocket cutter past the top face (mm)

$fn = 64;

// ---------------- Derived values ----------------
// Fxmin, Fymin are the coordinates of the bottom face (z = 0).
Fxmin = -block_x / 2;
Fymin = -block_y / 2;

// Tlab, Try are the coordinates of the top face (z = block_h).
// The top face is centred on the origin in X and Y.
Tlab = -block_top_x / 2;
Try  = -block_top_y / 2;

// ---------------- Model ----------------
difference() {
    // Tapered block: a prism whose cross‑section is drawn in the XY plane
    // and is extruded from z = 0 to z = block_h.
    // rotate([90,0,0]) turns the 2D (lab, try) coordinates into X, Y,
    // and the extrusion direction becomes +Z.
    rotate([90, 0, 0])
        linear_extrude(height = block_h)
            polygon(points = [
                [Fxmin, Fymin],
                [Fxmax, Fymin],
                [Fxmax, Fymax],
                [Fxmin, Fymax]
            ]);

    // Square pocket cut into the top face, centred on the origin.
    // The cutter extends past the top face by eps so no faces are coplanar.
    translate([Tlab + pocket_x / 2, Try + pocket_y / 2, block_h - pocket_d])
        cube([pocket_x, pocket_y, eps]);
}
