    // Square frustum: hull of two centred, parallel square faces
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, bottom_z])
            cube([bottom_w, bottom_w, f(0)]);
        translate([-top_w / 2, -top_w / 2, top_z - f(0)])
            cube([top_w, top_w, f(0)]);
    }

    // Square pocket cut into the top face
    translate([0, 0, top_z - overlap])
        cube([pocket_w, pocket_w, overlap]);
}
