        for (sx = [-1, 1])
            translate([sx * post_x, 0, 0])
                cylinder(d = post_d, h = post_h);

        // Straight bar on top of the posts
        translate([-bar_l / 2, -bar_w / 2, post_h])
            cube([bar_l, bar_w, bar_t]);
    }

    // Screw holes, 12 mm deep from the bottom face of each post
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + 2 * eps);
}
