        // Posts
        for (x = post_x)
            translate([x, 0, 0])
                cylinder(d = post_d, h = post_h);

        // Bar with a little overlap into the posts
        translate([-bar_len/2, -bar_w/2, post_h - overlap])
            cube([bar_len, bar_w, bar_t]);
