// Flat dog-bone tensile specimen
// Print orientation: flat on the bed, z = 0 up to specimen thickness

// ---------- Parameters ----------
specimen_thickness = 3;     // Z thickness of the plate
total_length       = 110;   // overall length along X (mm)
gauge_width        = 8;     // narrow gauge section width (Y)
gauge_length       = 40;    // gauge section length (X)
grip_width         = 19;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)
transition_length  = 10;    // length of each grip-to-gauge transition (X)
overlap            = 1;     // overlap of adjacent sections for a clean union (mm)

$fn = 64;

// ---------- Derived ----------
centre      = 0;
gauge_start = -total_length / 2 + grip_length + transition_length;
gauge_end   = total_length / 2 - grip_length - transition_length;

// ---------- Model ----------
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * (total_length / 2 - grip_length - transition_length),
                   -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

    // Gauge section
    translate([gauge_start, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, specimen_thickness]);

    // Transitions (width changes linearly from grip width down to gauge width)
    for (s = [-1, 1])
        translate([s * (total_length / 2 - transition_length - gauge_start) / 2,
                   -transition_length / 2, 0])
            linear_extrude(height = specimen_thickness)
                polygon([
                    [-transition_length / 2, -gauge_width / 2],
                    [ transition_length / 2, -gauge_width / 2],
                    [ transition_length / 2,  gauge_width / 2],
                    [-transition_length / 2,  gauge_width / 2]
                ]);
}
