// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, builds up +Z

// ---------------- Parameters ----------------
thickness  = 3;     // plate thickness (Z)
total_len  = 110;   // overall length along X
gauge_w    = 8;     // gauge section width (Y)
gauge_len  = 40;    // gauge section length (X)
grip_w     = 19;    // grip section width (Y)
grip_len   = 25;    // grip section length (X)
trans_len  = 10;    // transition section length (X)
eps        = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Derived ----------------
a      = grip_w + 2 * eps;      // grip width + overshoot
L      = total_len;
w      = gauge_w;
g      = gauge_len;
t      = thickness;
s      = trans_len;             // transition length

// ---------------- Model ----------------
// Outer envelope: grip - transition - gauge - transition - grip
union() {
    // Left grip
    translate([-L / 2 - grip_len / 2, -a / 2, 0])
        cube([grip_len, a, t]);

    // Right grip
    translate([L / 2 - grip_len / 2, -a / 2, 0])
        cube([grip_len, a, t]);

    // Gauge section (overlaps transitions slightly for a clean union)
    translate([-L / 2 - grip_len / 2 - s - g / 2, -w / 2, 0])
        cube([g + 2 * s, w, t]);
}

// ---------------- Cutouts ----------------
difference() {
    // Plate
    translate([-L / 2, -a / 2, 0])
        cube([L, a, t]);

    // Groove along the gauge section
    translate([-L / 2 - grip_len / 2 - s - g / 2, -w / 2 - eps, -eps])
        rotate([90, 0, 0])
            linear_extrude(height = t + 2 * eps)
                polygon([
                    [-(g / 2 + eps), -w / 2 - eps],
                    [ g / 2 + eps, -w / 2 - eps],
                    [ 0, w / 2 + eps],
                    [ 0, -w / 2 - eps]
                ]);
}
