gauge_x1          = gauge_x0 + gauge_length;
right_grip_x1     = gauge_x1 + 2 * transition_length + grip_length;

// ---------- Model ----------
union() {
    // Left grip
    translate([left_grip_x0 - overlap, -grip_width / 2, 0])
        cube([grip_length + overlap, grip_width, specimen_thickness]);

    // Left transition (19 -> 8)
    translate([left_grip_x0, -grip_width / 2, 0])
        linear_extrude(height = specimen_thickness)
