                [left_grip_x0 + transition_length, -grip_width / 2],
                [left_grip_x0 + transition_length, -gauge_width / 2],
                [gauge_x0 + gauge_length, -gauge_width / 2],
                [gauge_x0 + gauge_length, gauge_width / 2],
                [left_grip_x0 + transition_length, gauge_width / 2],
                [left_grip_x0, gauge_width / 2]
            ]);

