// Dog-bone tensile specimen - flat bar with a central narrow section
// Print orientation: flat on the bed, building up in +Z

// ---------- Dimensions (mm) ----------
thickness      = 3;     // bar thickness (Z)
overall_length = 110;   // total length along X
gauge_width    = 8;     // width of the central gauge section (Y)
gauge_length   = 40;    // length of the gauge section (X)
grip_width     = 19;    // width of each grip section (Y)
grip_length    = 25;    // length of each grip section (X)
transition_len  = 10;   // length of each grip-gauge transition (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gage   = gauge_length / 2;
grip_x0     = -overall_length / 2 + grip_length;   // left grip start X
trans_x0    = grip_x0 + grip_length;               // transition start X
gage_x0     = trans_x0 + transition_len;           // gauge start X
trans_x2    = gage_x0 + transition_len;             // right transition end X
grip_x2     = trans_x2 + grip_length;              // right grip end X

// ---------- Model ----------
module dogbone() {
    difference() {
        // Outer block
        translate([-overall_length / 2, -thickness / 2, 0])
            cube([overall_length, thickness, 3 * thickness]);

        // Removed material: grips, transitions and gauge core
        union() {
            translate([grip_x0, -grip_width / 2, thickness * 0.25])
                cube([grip_length, grip_width, 2.5 * thickness]);

            translate([trans_x0, -transition_len / 2, thickness * 0.25])
                cube([transition_len, transition_len, 2.5 * thickness]);

            translate([gage_x0, -half_gage, thickness * 0.25])
                cube([gauge_length, half_gage + eps, 2.5 * thickness]);

            // right-side mirror image
            translate([trans_x2, -transition_len / 2, thickness * 0.25])
                cube([transition_len, transition_len, 2.5 * thickness]);

            translate([grip_x2 - grip_length, -grip_width / 2, thickness * 0.25])
                cube([grip_length, grip_width, 2.5 * thickness]);
        }
    }
}

dogbone();
