// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: lying flat on the bed, centred on the origin.
// Coordinates follow the user's specification (X along length, Y = width).

$fn = 64;

// ---- Dimensions (mm) ----
total_len   = 110;  // overall length along X
gauge_len   = 40;   // length of the narrow gauge section
gauge_w     = 8;    // width of the gauge section (Y)
grip_len    = 25;   // length of each grip section (X)
grip_w      = 19;   // width of each grip section (Y)
trans_len   = 10;   // length of each grip->gauge transition (X)
thickness   = 3;    // plate thickness (Z)

// ---- Derived ----
grip_x0 = -(grip_len/2 + trans_len);   // grip start, outer end
g1_x0   = -(trans_len/2 + gauge_len/2); // transition start (inner)
g2_x0   =  trans_len/2 + gauge_len/2;  // transition end (inner)
g3_x0   =  grip_len/2 + trans_len;     // second grip start, outer end

// ---- Model ----
module specimen() {
    hull() {
        // outer grip sections (full width, extends past the ends)
        translate([grip_x0 - 1, -grip_w/2, 0])
            cube([grip_len + 2, grip_w, thickness]);
        translate([g3_x0 - 1, -grip_w/2, 0])
            cube([grip_len + 2, grip_w, thickness]);

        // gauge section
        translate([g1_x0, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // transitions: width changes linearly from grip_w to gauge_w
        for (s = [-1, 1])
            translate([s * g2_x0, -grip_w/2, 0])
                rotate([0, 0, s * 90])
                    linear_extrude(height = thickness)
                        polygon([
                            [0, -grip_w/2],
                            [trans_len, -grip_w/2],
                            [trans_len, 0],
                            [0, 0]
                        ]);
    }
}

specimen();
