    // hull of two grip-end blocks, centred on origin
    hull() {
        translate([-trans_len, -grip_w/2, 0])
            cube([trans_len, grip_w, thickness]);
        translate([trans_len, -grip_w/2, 0])
            cube([trans_len, grip_w, thickness]);
    }
}

module gauge() {
    translate([-lx/2, -gauge_w/2, 0])
        cube([lx, gauge_w, thickness]);
}

// ---------- Assembly ----------
union() {
    grip();      // left grip
    transition(); // left transition
    gauge();     // gauge section
    transition(); // right transition
    grip();      // right grip
}
