// Print orientation: flat on bed, builds upward in +Z

$fn = 64;

// ---- Dimensions (mm) ----
total_len     = 110;  // overall length along X
gauge_w       = 8;    // gauge section width (Y)
gauge_len     = 40;   // gauge section length (X)
grip_w        = 19;   // grip section width (Y)
grip_len      = 25;   // grip section length (X)
trans_len     = 10;   // transition section length (X)
thickness     = 3;    // specimen thickness (Z)

eps           = 0.5;  // overshoot for clean cuts

// ---- Derived ----
half_grip   = grip_len / 2;
half_gauge  = gauge_len / 2;
start_x     = -total_len / 2;

// Width profile seen from above (piecewise linear)
function profile_w(x) =
    x < -half_gauge - trans_len ? grip_w :
    x < -half_gauge ? grip_w + (trans_len - (-x + half_gauge + trans_len)) * (gauge_w - grip_w) / trans_len :
    x <= -half_trans ? gauge_w :
    x <= half_gauge + trans_len ? gauge_w + (x - (half_gauge + trans_len)) * (gauge_w - grip_w) / trans_len :
    grip_w;

module specimen() {
    // Current SCAD hull only accepts 2D points (X, Y); extrude then rotate
    hull() {
        for (sx = [start_x, start_x + trans_len, start_x + trans_len + gauge_len,
                   start_x + total_len - trans_len - gauge_len, start_x + total_len - trans_len])
            translate([sx, 0, 0]) rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    circle(r = profile_w(sx) / 2, $fn = 64);
    }
}

specimen();
