// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness    = 3;     // specimen thickness (Z)
gauge_width  = 8;     // narrow gauge section width (Y)
gauge_length = 40;    // gauge section length (X)
grip_width   = 19;    // grip section width (Y)
grip_length  = 25;    // grip section length (X)
transition   = 10;    // transition section length (X)

total_length = 2 * grip_length + gauge_length + 2 * transition; // 110 mm

// ---- Model ----
difference() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * (grip_length - transition), -grip_width / 2, 0])
                cube([grip_length + transition, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition regions (trapezoidal profile in XY, extruded in Z)
        for (s = [-1, 1]) {
            x0 = s > 0 ? grip_length - transition : -grip_length + transition;
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [x0, -grip_width / 2],
                        [x0 + transition, -grip_width / 2],
                        [x0 + transition, grip_width / 2],
                        [x0, grip_width / 2]
                    ]);
        }
    }

    // Small hole in each grip to avoid coplanar faces
    for (s = [-1, 1])
        translate([s * (grip_length + transition / 2), 0, -1])
            cylinder(d = 2, h = thickness + 2);
}
