        // Grip sections
        for (s = [-1, 1])
            translate([s * (grip_l - trans_l), -grip_w / 2, 0])
                cube([grip_l + trans_l, grip_w, thickness]);
        // Gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, thickness]);
        // Transitions (linear width change)
        for (s = [-1, 1])
            translate([s * (grip_l - trans_l) / 2, 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(thickness)
                        polygon(points = [
                            [0, -grip_w / 2],
                            [trans_l, -grip_w / 2],
                            [trans_l, grip_w / 2],
                            [0, grip_w / 2]
                        ]);
    }
    // Cut overlapping regions so no faces are coplanar
    for (s = [-1, 1])
        translate([s * (grip_l - trans_l) / 2 - 1, -trans_w / 2, -1])
            cube([trans_l + 2, trans_w, thickness + 2]);
}

// Transition width (needs to be < grip_w so the cut is fully inside)
trans_w = grip_w - 4;
