// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, building up in +Z

// ---------- Dimensions (mm) ----------
specimen_thickness = 3;     // plate thickness (Z)
overall_length     = 130;   // total length along X
gauge_width        = 8;     // width of the narrow gauge section (Y)
gauge_length       = 50;    // length of the gauge section (X)
grip_width         = 15;    // width of each grip section (Y)
grip_length        = 25;    // length of each grip section (X)
transition_length  = 15;    // length of each grip -> gauge transition (X)

$fn = 64;

// ---------- Derived ----------
half_grip          = grip_length / 2;
half_gauge         = gauge_length / 2;
gauge_x_start      = -overall_length / 2 + grip_length + transition_length;
width_profile      = [ grip_width,                         // grip
                       gauge_width,                        // gauge
                       grip_width ];                        // grip

// ---------- Model ----------
module dogbone() {
    // rotate([90,0,0]) maps the 2D profile (X,Y) to (Y,Z), then extrude along X
    rotate([90, 0, 0])
        linear_extrude(height = specimen_thickness)
            hull() {
                for (wx = [gauge_x_start - transition_length,
                           gauge_x_start,
                           overall_length / 2 - grip_length - transition_length])
                    translate([wx, 0])
                        circle(d = width_profile[0], $fn = 64);
                for (wx = [gauge_x_start + transition_length,
                           gauge_x_start + gauge_length,
                           overall_length / 2 - half_grip])
                    translate([wx, 0])
                        circle(d = width_profile[1], $fn = 64);
            }
}

dogbone();
