// Dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow section width (Y)
gauge_length   = 50;    // narrow section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // grip-to-gauge transition length (X)

// ---- Derived ----
grip_x0    = -(total_length / 2) + grip_length + transition_len;  // left grip start X
w_trans    = [grip_width, gauge_width];                           // transition end widths
area_trans = [w_trans[0] * grip_width / 2, w_trans[1] * gauge_width / 2]; // use triangle area

module profile() {
    // Upper half (y > 0), mirrored across X axis
    union() {
        // grip sections
        translate([-grip_length / 2, 0])   cube([grip_length, grip_width, thickness / 2]);
        translate([ grip_length / 2, 0])   cube([grip_length, grip_width, thickness / 2]);
        // gauge section
        translate([0, -gauge_width / 2])   cube([gauge_length, gauge_width, thickness / 2]);
        // transitions (overlapping endpoints for a clean union)
        for (dx = [-transition_len, transition_len])
            translate([dx, 0])
                linear_extrude(height = thickness / 2)
                    polygon(points = [
                        [0, 0], [dx, 0], [dx + 15, 15],
                        [dx + 15, 15], [dx + 15, gauge_width]
                    ]);
    }
}

difference() {
    rotate([90, 0, 0])   // rotate profile so its 2D Y becomes Z
        linear_extrude(height = total_length)
            profile();
    // centre the part in X/Y
    translate([0, 0, 0])
        cube([total_length, 2 * grip_width, thickness]);
}
