// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, builds upward in +Z

$fn = 64;

// ---- Dimensions (mm) ----
thickness     = 3;     // specimen thickness (Z)
total_len     = 130;   // overall length along X
gauge_w       = 8;     // width of the narrow gauge section (Y)
gauge_len     = 50;    // length of the gauge section (X)
grip_w        = 15;    // width of each grip section (Y)
grip_len      = 25;    // length of each grip section (X)
trans_len     = 15;    // length of the transition between grip and gauge (X)
trans_start_w = 15;    // width at the grip end of the transition
trans_end_w   = 8;     // width at the gauge end of the transition

// ---- Derived ----
half_grip   = grip_len / 2;
half_gauge  = gauge_len / 2;
half_trans  = trans_len / 2;
x0          = -half_grip - half_trans - half_gauge;   // left end of model

// ---- Model ----
module specimen() {
    // Expand every section slightly (1 mm) so the hull has no coplanar faces
    extrusion_w = max(w + 1, thickness + 2) for w = [grip_w, trans_start_w, trans_end_w, gauge_w];

    hull() {
        for (s = [-1, 1]) {
            translate([x0, 0, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [-half_grip - half_trans, -trans_start_w / 2],
                        [ half_grip + half_trans, -trans_start_w / 2],
                        [ half_grip + half_trans,  trans_start_w / 2],
                        [ -half_grip - half_trans,  trans_start_w / 2],
                        [ -half_trans - half_gauge, -trans_end_w / 2],
                        [ -half_trans - half_gauge,  trans_end_w / 2],
                        [ half_trans - half_gauge, -trans_end_w / 2],
                        [ half_trans - half_gauge,  trans_end_w / 2],
                        [ half_grip, -gauge_w / 2],
                        [ -half_grip, -gauge_w / 2],
                        [ -half_grip,  gauge_w / 2],
                        [ half_grip,  gauge_w / 2]
                    ]);
        }
    }
}

specimen();
