```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_len      = 130;   // overall length along X (mm)
gauge_width    = 8;     // narrow section width (Y)
gauge_len      = 50;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_len       = 25;    // grip section length along X
transition_len = 15;    // length of each grip->gauge transition
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
a     = grip_width;     // grip width
b     = gauge_width;    // gauge width
L1    = grip_len;       // grip length
L2    = gauge_len;      // gauge length
L3    = transition_len; // transition length
n     = 2;              // symmetry (two grip ends)
x0    = -(total_len / 2 + L3); // transition start X

// ---------- Model ----------
module side_profile() {
    // drawn in X-Y plane, extruded along Z
    translate([0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                [x0, 0],
                [x0 + L3, 0],
                [x0 + L3 + L2 / 2, (a + b) / 2],
                [x0 + L3 + L2, 0],
                [x0 + 2 * L3 + L2, 0],
                [x0 + 2 * L3 + L2 - L2 / 2, (a + b) / 2],
                [x0 + L3 + L2 - L2 / 2, b],
                [x0 + L3 - L2 / 2, b],
                [x0 - L3 + L2 / 2, b],
