// ---------- Model ----------
module dog_bone_2d() {
    // Profile in XY (top face), built with hull and for loops
    hull() {
        // Grip sections at each end
        for (sx = [-1, 1])
            translate([sx * (grip_l + transition_l), -grip_w / 2])
                square([grip_l, grip_w]);

        // Gauge section in the middle
        translate([-gauge_l / 2, -gauge_w / 2])
            square([gauge_l, gauge_w]);

        // Transition sections: width changes linearly from grip (15) to gauge (8)
        for (sx = [-1, 1]) {
            x0 = sx > 0 ? grip_l - transition_l : -(grip_l + transition_l);
            x1 = sx > 0 ? grip_l : -(grip_l + transition_l);
            // Width at the two ends of the transition (y runs -w0/2 .. w0/2)
            p0 = [x0, -grip_w / 2];
            p1 = [x1, -gauge_w / 2];
            polygon(points = [p0, p1, [x1, gauge_w / 2], [x0, gauge_w / 2]]);
        }
    }
}

difference() {
    // Extrude the 2D profile to the full thickness
    linear_extrude(height = specimen_t)
        dog_bone_2d();

    // Small slit through each grip, centred on the origin in X
    // (extends eps past top and bottom faces)
    for (y = [-grip_w / 2, grip_w / 2])
        translate([0, y, -eps])
            cube([grip_l + 2 * eps, eps, specimen_t + 2 * eps]);
