// Flat tensile test specimen (dog bone) for FDM printing
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---------- Dimensions (mm) ----------
specimen_t   = 3;     // thickness (Z)
grip_w       = 15;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
transition_l = 15;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 130 mm

// ---------- Model ----------
module dogbone() {
    // Profile in XY, extruded in Z
    rotate([90, 0, 0])
        linear_extrude(height = specimen_t)
            polygon(points = [
                // Left grip
                [-total_l / 2 + grip_l, -grip_w / 2],
                [-total_l / 2 + grip_l,  grip_w / 2],
                // Left transition
                for (t = [0 : 1])
                    [
                        -total_l / 2 + grip_l + transition_l * (1 - t),
                        -grip_w / 2 + (gauge_w / 2 - grip_w / 2) * (1 - t)
                    ],
                // Gauge section
                [-total_l / 2 + grip_l + 2 * transition_l - gauge_l, -gauge_w / 2],
                [-total_l / 2 + grip_l + 2 * transition_l - gauge_l,  gauge_w / 2],
                // Right transition
                for (t = [0 : 1])
                    [
                        total_l / 2 - grip_l - transition_l * (1 - t),
                        -grip_w / 2 + (gauge_w / 2 - grip_w / 2) * (1 - t)
                    ],
                // Right grip
                [total_l / 2 - grip_l, -grip_w / 2],
                [total_l / 2 - grip_l,  grip_w / 2]
            ]);
}

// ---------- Cut / Clean ----------
module clean(solid) {
    difference() {
        solid;
        // Cutter that passes through top and bottom faces
        translate([-total_l - 2 * eps, -grip_w - 2 * eps, -eps])
            cube([total_l + 2 * eps, grip_w + 2 * eps, specimen_t + 2 * eps]);
    }
}

clean(dogbone());
