gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // each grip-to-gauge transition length (X)

// ---- Derived ----
left_grip_x0   = -(grip_length + transition_len);   // -40
right_grip_x0  = gauge_length + transition_len;     // 65
overall_len    = 2 * (grip_length + transition_len) + gauge_length; // 130

// ---- Model ----
union() {
    // Grip sections
    for (sx = [-1, 1])
        translate([sx * right_grip_x0 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transitions: width changes linearly from grip_w to gauge_w
    for (sx = [-1, 1]) {
        x0 = sx * right_grip_x0 - grip_length - transition_len; // start of transition
        // Hull over two line segments lying in the XY plane, then extruded.
        // rotate([90,0,0]) maps hull's z -> Y, so translate by -Y to set z = 0.
        translate([0, 0, -thickness])
            rotate([90, 0, 0])
                hull() {
                    for (tx = [0, transition_len])
                        translate([x0 + tx * gauge_width / transition_len,
                                   -thickness / 2])
                            cube([1, thickness, 1]); // thin slab along the line
                    for (tx = [0, transition_len])
                        translate([sx * right_grip_x0 - grip_length - tx,
                                   -thickness / 2])
                            cube([1, thickness, 1]); // thin slab along the line
                }
    }
}
