        grip_w
    else if (x <= -half_gauge)
        // linear drop from 15 to 6 over the left transition
        grip_w + (6 - grip_w) * (x + half_grip) / trans_len
    else if (x <= half_gauge)
        gauge_w
    else if (x <= half_grip)
        // linear rise from 6 to 15 over the right transition
        gauge_w + (grip_w - gauge_w) * (x - half_gauge) / trans_len
    else
