    translate([-overall_len/2 + gauge_length/2, -gauge_width/2, 0])
        linear_extrude(height = thickness)
            polygon([
                [0, -gauge_width/2],
                [transition_len, grip_width/2],
                [transition_len, gauge_width/2],
                [0, gauge_width/2]
            ]);

