// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on the bed, z = 0 upward. Symmetric about the origin.

// ---------------- Parameters ----------------
specimen_thickness = 3;     // plate thickness (Z) mm
gauge_width        = 6;     // narrow gauge section width (Y) mm
gauge_length       = 50;    // gauge section length (X) mm
grip_width         = 15;    // grip section width (Y) mm
grip_length        = 30;    // grip section length (X) mm
transition_length  = 10;    // each transition segment length (X) mm
eps                = 0.5;   // cutter overshoot past faces (Z) mm

$fn = 64;

// ---------------- Derived ----------------
total_length   = 2 * grip_length + gauge_length + 2 * transition_length;   // 130 mm
start_gauge_x  = -gauge_length / 2;                                        // -25 mm
end_gauge_x    = gauge_length / 2;                                          // 25 mm
start_grip_x   = end_gauge_x + transition_length;                           // 35 mm
end_grip_x     = total_length / 2;                                          // 65 mm
start_trans_x  = -end_grip_x;                                               // -35 mm

// ---------------- Model ----------------
module dog_bone_plate() {
    // Plate body
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, specimen_thickness]);

    // Central gauge section (slightly reduced width so cutters are not coplanar)
    translate([start_gauge_x, -gauge_width / 2 - 0.01, 0])
        cube([gauge_length, gauge_width + 0.02, specimen_thickness - eps]);

    // Grip and transition segments on the right side
    for (s = [-1, 1]) {
        x0 = s > 0 ? start_grip_x : start_trans_x;
        x1 = s > 0 ? end_grip_x     : end_gauge_x;
        // Width at the far end of the transition (gauge end or grip end)
        w_end = x1 == end_gauge_x ? gauge_width : grip_width;
        translate([x0, -w_end / 2, 0])
            cube([x1 - x0 + eps, w_end, specimen_thickness - eps]);
    }
}

dog_bone_plate();
