// Flat dog-bone tensile specimen for FDM printing
// Units: mm. Print orientation: flat on bed, z = 0 upward.

// ---------- Dimensions ----------
gauge_len   = 50;   // length of narrow gauge section (X)
gauge_w     = 6;    // width of gauge section (Y)
grip_len    = 30;   // length of each grip section (X)
grip_w      = 15;   // width of grip sections (Y)
trans_len   = 10;   // length of each transition zone (X)
thickness   = 3;    // plate thickness (Z)

eps         = 0.5;  // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
total_len = 2 * grip_len + gauge_len + 2 * trans_len;  // 130 mm

// ---------- Model ----------
module specimen() {
    union() {
        // Grip sections
        for (sx = [-1, 1])
            translate([sx > 0 ? grip_len : -total_len + grip_len, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);

        // Gauge section
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Transitions: width changes linearly from grip_w to gauge_w
        for (sx = [-1, 1]) {
            x0 = sx > 0 ? grip_len - trans_len : -gauge_len / 2 - trans_len;
            // Hull between a point in the grip and the adjacent gauge end
            hull() {
                translate([x0, -grip_w / 2, 0])
                    cube([trans_len, grip_w, thickness]);
                translate([sx > 0 ? gauge_len / 2 : -gauge_len / 2 - trans_len, -gauge_w / 2, 0])
                    cube([trans_len, gauge_w, thickness]);
            }
        }
    }
}

specimen();
