trans_len    = 10;    // transition section length (X), each side
cut_extra    = 0.5;   // overshoot of cutting shapes past faces

// ---------- Derived ----------
total_len    = 2 * grip_len + gauge_len + 2 * trans_len;   // 130 mm
grip_half    = grip_w / 2;
gauge_half   = gauge_w / 2;

// ---------- Model ----------
module specimen() {
    hull() {
        // End grips (full width through the part)
        for (sx = [-1, 1])
            translate([sx * (grip_len + trans_len), -grip_half, 0])
                cube([grip_len, grip_w, specimen_t]);

        // Central gauge section
        translate([-gauge_len / 2, gauge_half, 0])
            cube([gauge_len, gauge_w, specimen_t]);

        // Transitions: width changes linearly from grip (15) to gauge (6)
        for (sx = [-1, 1])
            translate([sx * trans_len, (grip_half + gauge_half) / 2, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = specimen_t)
                        polygon([
                            [0, grip_half],
                            [trans_len, gauge_half]
                        ]);
    }

    // Clean up any coincident faces by cutting slightly into both sides
    difference() {
        translate([-total_len / 2 - cut_extra, -grip_half - cut_extra, 0])
            cube([total_len + 2 * cut_extra, grip_w + 2 * cut_extra, specimen_t]);
    }
}

