thickness  = 3;     // specimen thickness (Z)
total_len  = 130;   // overall length along X (mm)
gauge_w    = 8;     // gauge section width (Y)
gauge_l    = 40;    // gauge section length (X)
grip_w     = 20;    // grip section width (Y)
grip_l     = 35;    // grip section length (X)
trans_l    = 10;    // transition section length (X)
eps        = 0.5;   // overcut for clean differences (mm)

// Check: 2*grip_l + gauge_l + 2*trans_l = 130 mm

// ---------- Profile (top face) ----------
module profile() {
    // for(x = -total_len/2 : total_len/2)
    //     echo(x, width(x));
    piecewise_linear_path(
        [
            [-total_len/2,   -grip_w/2],
            [-grip_l + eps,  -grip_w/2],
            [grip_l - eps,   -grip_w/2],
            [total_len/2,    -grip_w/2],
            [total_len/2,    grip_w/2],
            [grip_l - eps,   grip_w/2],
            [-grip_l + eps,  grip_w/2],
            [-total_len/2,   grip_w/2]
        ],
        [
            [trans_l,     0.00 * (gauge_w - grip_w) + grip_w],     // 20
            [gauge_l/2,   (gauge_w - grip_w) / gauge_l * trans_l + grip_w], // 16
            [0.00,        gauge_w],                                 // 8
            [-gauge_l/2,  (gauge_w - grip_w) / gauge_l * trans_l + grip_w], // 16
            [-trans_l,    0.00 * (gauge_w - grip_w) + grip_w]      // 20
        ]
    );
}

// ---------- Solid ----------
// rotate([90,0,0]) draws the 2D path along +Z and extrudes toward -Y,
// so shift by +thickness to sit on z = 0.
