    [ -transStart, -halfGrip ],
    [ -transStart,  halfGrip ],
    [  transStart,  halfGrip ],
    [  transStart, -halfGauge ],
    [  gaugeL - transStart, -halfGauge ],
    [ gaugeL - transStart, halfGauge ],
    [ totalLen/2 - gaugeL + transStart, halfGauge ],
    [ totalLen/2 - gaugeL + transStart, -halfGauge ],
    [ totalLen/2, -halfGauge ]
