trans_len   = 10;    // transition section length (X)

// ---- Derived ----
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
extent      = total_len / 2;

// ---- Model ----
module specimen() {
    // Outer plate
    difference() {
        translate([-extent, -thickness / 2, 0])
            cube([total_len, thickness, 4]);   // small overshoot in Z

        // Cutouts: grip -> transition -> gauge -> transition -> grip
        children(0);
    }
}

// One side of the central axis (Y >= 0); mirror to Y < 0
module cutouts() {
    grip_ext = grip_len / 2 + trans_len;   // distance from origin to grip end
    for (dx = [-(extent - grip_ext), grip_ext])
        translate([dx, 0, 0])
            linear_extrude(thickness + 1)
                polygon([
                    [0, half_grip],
                    [trans_len, half_gauge],
                    [-trans_len, half_gauge],
                    [0, -half_grip]
                ]);
}

module top_view() {
    clipper_round([
        translate([-extent, -half_grip - 1, 0])
            cube([total_len, grip_w + 2, 1]),   // grip bbox (overflowing)
        hull() {
            translate([-extent + grip_len / 2 + trans_len, 0, 0])
                cube([grip_len / 2 + trans_len, half_gauge, 0.01]);
            translate([extent - grip_len / 2 - trans_len, 0, 0])
                cube([grip_len / 2 + trans_len, half_gauge, 0.01]);
        },
        translate([-gauge_len / 2, -half_gauge, 0])
            cube([gauge_len, gauge_w, 0.01]),
        translate([gauge_len / 2, -half_gauge, 0])
            cube([gauge_len, gauge_w, 0.01])
    ]);
}

difference() {
    translate([-extent, -thickness / 2, 0])
        cube([total_len, thickness, 0]);

    mirror([1, 0, 0])
        cutouts();

    cutouts();

    union() {
        translate([0, 0, 0])
            top_view();
        mirror([0, 1, 0])
            top_view();
    }
}
