// ---- Derived ----
grip_start = total_len / 2 - grip_len;   // grip end / gauge start (X)
trans_start = grip_start - trans_len;    // transition end / gauge end (X)

// Width at a given X during a transition (linear between end_w and start_w)
function trans_w(x, end_w, start_w) =
    (x - trans_start) / trans_len * (end_w - start_w) + start_w;

module profile() {
    plot([total_len / 2, grip_start, trans_start],
         [grip_w / 2, gauge_w / 2, trans_w(trans_start - eps, gauge_w, grip_w)],
         join = true);
    // The curve comes back toward the origin, so the lower half is a mirror
    // (not a copy), which keeps the two sides meeting at a clean 0.0 overlap.
    mirror_y();
}

difference() {
    // Solid plate from the outer edges
    linear_extrude(thickness)
        translate([-total_len / 2, -thickness / 2, 0])
            polygon(points = [
                [total_len / 2, thickness / 2],
                [total_len / 2, -thickness / 2],
                [trans_start, trans_w(trans_start - eps, gauge_w, grip_w)],
                [grip_start, gauge_w / 2],
                [-grip_start, gauge_w / 2],
                [-trans_start, trans_w(trans_start - eps, gauge_w, grip_w)],
                [-total_len / 2, -thickness / 2],
                [-total_len / 2, thickness / 2]
            ]);

    // Central gauge section
    translate([-gauge_len / 2, -gauge_w / 2 - eps, 0])
        cube([gauge_len, gauge_w + 2 * eps, thickness + 2 * eps]);

    // Grip sections at both ends
    for (s = [-1, 1])
        translate([s * grip_start, -grip_w / 2 - eps, 0])
            cube([grip_len, grip_w + 2 * eps, thickness + 2 * eps]);
