// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, z = 0 upward. Symmetric about origin.

$fn = 64;

// ---------- Dimensions (mm) ----------
specimen_t   = 3;     // thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // transition length between grip and gauge (X)

// ---------- Derived ----------
total_l = 2 * grip_l + gauge_l + 2 * transition_l;  // 130 mm
overlap = 0.01;                                     // cutter overshoot past faces

// Width of the specimen at a given X (in the XY plane)
function specimen_w(x) =
    if (x < -grip_l)
        grip_w + (gauge_w - grip_w) * (x + grip_l) / transition_l
    else if (x <= -gauge_l / 2)
        grip_w
    else if (x < gauge_l / 2)
        gauge_w
    else if (x <= gauge_l + transition_l)
        grip_w + (gauge_w - grip_w) * (x - (gauge_l + transition_l)) / transition_l
    else
        grip_w;

// ---------- Model ----------
difference() {
    // Main body
    linear_extrude(height = specimen_t)
        polygon(points = [for (sx = [-1, 1])
            [sx * (total_l / 2), y for y in [0 : 0.001 : specimen_w(sx * (total_l / 2))]]]);

    // Grip sections (to create the dog-bone shape; leaves a 40 mm centre)
    for (s = [-1, 1])
        translate([s * (grip_l - overlap), -grip_w / 2, -overlap])
            cube([grip_l + 2 * overlap, grip_w, specimen_t + 2 * overlap]);
}
