// ---------------- Parameters ----------------
specimen_t   = 3;     // thickness (Z), mm
gauge_w      = 8;     // gauge section width (Y), mm
gauge_l      = 40;    // gauge section length (X), mm
grip_w       = 20;    // grip section width (Y), mm
grip_l       = 35;    // grip section length (X), mm
transition_l = 10;    // transition section length (X), mm
$fn          = 64;    // curve resolution (for consistency)

// Derived
total_len    = 2 * grip_l + gauge_l + 2 * transition_l;   // 130 mm
cut_extra    = 0.5;       // cutter overshoot past faces, mm

// ---------------- Profile ----------------
// Width of the specimen in Y for a given X position (2D, in the bed plane)
function profile_w(x) =
    if (x < -grip_l)
        // left grip -> transition: width falls from 20 to 8
        20 + (8 - 20) * (x + grip_l) / transition_l
    else if (x <= -gauge_l)
        grip_w
    else if (x < gauge_l)
        gauge_w
    else if (x <= gauge_l + transition_l)
        // gauge -> right grip: width rises from 8 to 20
        8 + (20 - 8) * (x - gauge_l) / transition_l
    else
        grip_w;

// ---------------- Model ----------------
difference() {
    // Flat plate, centred in X and Y, resting on z = 0
    translate([-total_len / 2, -specimen_t / 2, 0])
        linear_extrude(height = specimen_t)
            polygon(points = [for (sx = [-1, 1])
                for (t = [0 : 1])
                    [sx * (total_len / 2 - transition_l - gauge_l / 2)
                        + t * transition_l,
                     profile_w(-sx * (total_len / 2 - transition_l - gauge_l / 2)
                                + t * transition_l)]]);

    // Central gauge section, overcut past both end faces
    translate([-gauge_l / 2 - cut_extra, -gauge_w / 2, -cut_extra])
        cube([gauge_l + 2 * cut_extra, gauge_w, specimen_t + 2 * cut_extra]);
