// Flat dog-bone tensile specimen for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness     = 3;     // specimen thickness (Z)
gauge_width   = 8;     // central gauge width (Y)
gauge_length  = 40;    // central gauge length (X)
grip_width    = 20;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition    = 10;    // transition length between grip and gauge (X)
overlap       = 0.5;   // cutter overlap into faces (X, Y, Z)

// Derived
total_length  = 2 * grip_length + gauge_length + 2 * transition;

// Width profile in X (top face, z = thickness)
function profile_x(x) =
    if (x < -grip_length)       grip_width + (gauge_width - grip_width) * (x + grip_length) / transition
    else if (x <= -gauge_length) grip_width
    else if (x < gauge_length)   gauge_width
    else if (x <= gauge_length + transition) grip_width + (gauge_width - grip_width) * (x - (gauge_length + transition)) / transition
    else                         grip_width;

module dogbone() {
    hull() {
        for (sx = [-1, 1])
            translate([sx * (total_length / 2 - grip_length), -grip_width / 2, 0])
                cube([grip_length + overlap, grip_width, thickness]);
    }
    // Cut out gauge and one copy of each transition to avoid coplanar faces
    difference() {
        dogbone_inner()
        translate([-gauge_length / 2 - overlap, -gauge_width / 2, -overlap])
            cube([gauge_length + 2 * overlap, gauge_width, thickness + 2 * overlap]);
    }
}

module dogbone_inner() {
    // Outer envelope: grip outer edges and gauge end edges
    hull() {
        for (sx = [-1, 1])
            for (xl = [transition, gauge_length + transition])
                translate([sx * (total_length / 2 - grip_length - xl), -profile_x(-grip_length - xl) / 2, 0])
                    cube([grip_length + overlap, profile_x(-grip_length - xl), thickness]);
    }
}

dogbone();
