thickness = 4;     // plate thickness
gauge_w   = 6;     // gauge section width (Y)
gauge_l   = 30;    // gauge section length (X)
grip_w    = 20;    // grip section width (Y)
grip_l    = 30;    // grip section length (X)
trans_l   = 15;    // transition section length (X)
