    union() {
        // grip sections
        translate([-total_len / 2 + grip_l, -grip_w / 2, 0])
            cube([grip_l, grip_w, thickness]);
        translate([total_len / 2 - grip_l, -grip_w / 2, 0])
            cube([grip_l, grip_w, thickness]);
        // transition sections
        translate([-total_len / 2 + grip_l + 0.01, -half_trans_w, 0])
            cone(trans_l, grip_w, gauge_w);
        translate([total_len / 2 - grip_l - 0.01, -half_trans_w, 0])
            cone(trans_l, grip_w, gauge_w);
        // gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, thickness]);
    }
    // remove 2D profile plane (above top face)
    translate([0, 0, thickness + cut])
        linear_extrude(height = cut)
            polygon([0, w0 / 2, trans_l, w1 / 2, trans_l, -w1 / 2, 0, -w0 / 2]);
