// Flat tensile test specimen (dog bone)
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
thickness = 4;     // specimen thickness (Z)
length    = 120;   // overall length along X (mm)
gauge_w   = 6;     // gauge section width (Y)
gauge_l   = 30;    // gauge section length (X)
grip_w    = 20;    // grip section width (Y)
grip_l    = 30;    // grip section length (X)
trans_l   = 15;    // transition section length (X)

eps = 0.5;         // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_w / 2;
half_grip  = grip_w / 2;
center     = -length / 2;          // specimen is centred on origin in X

// ---------- Model ----------
module width(x) {
    if (x < -grip_l) return grip_w;              // left grip
    if (x < -trans_l) return gauge_w;            // gauge
    if (x > length - grip_l) return grip_w;      // right grip
    if (x > length - trans_l) return grip_w;     // right transition
    // linear transition: gauge -> grip or grip -> gauge
    return min(half_gauge + (x + trans_l) / trans_l * (half_grip - half_gauge),
               half_grip + (x - length + grip_l + trans_l) / trans_l * (half_gauge - half_grip));
}

difference() {
    // outer shape
    hull() {
        for (x = [-grip_l, -trans_l, length - trans_l, length - grip_l])
            translate([x, 0, 0])
                cube([1, width(x), thickness]);
    }

    // inner channel (gauge + transitions), extended past end faces
    translate([-length / 2 - eps, -eps, -eps])
        cube([length + 2 * eps, width(length / 2) + 2 * eps, thickness + 2 * eps]);
}
