// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness  = 4;     // specimen thickness (Z)
total_len  = 120;   // overall length along X
gauge_w    = 6;     // gauge section width (Y)
gauge_l    = 30;    // gauge section length (X)
grip_w     = 20;    // grip section width (Y)
grip_l     = 30;    // grip section length (X)
trans_l    = 15;    // transition section length (X)
overcut    = 0.5;   // extra length on cutting shapes past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_w / 2;
half_grip  = grip_w / 2;
a          = grip_w;   // start width of transition
b          = gauge_w;  // end width of transition

// ---------- Model ----------
module body() {
    hull() {
        // left grip
        translate([-total_len / 2 + grip_l, -half_grip, 0])
            cube([grip_l, grip_w, thickness]);
        // right grip
        translate([total_len / 2 - grip_l, -half_grip, 0])
            cube([grip_l, grip_w, thickness]);
        // gauge section
        translate([-gauge_l / 2, -half_gauge, 0])
            cube([gauge_l, gauge_w, thickness]);
    }
}

module transitions() {
    // linear width change from grip to gauge on each side
    translate([0, 0, 0])
        linear_extrude(height = thickness)
            polygon([
                [-(total_len / 2 - grip_l - trans_l), -a / 2],
                [-(total_len / 2 - grip_l - trans_l),  a / 2],
                [total_len / 2 - grip_l - trans_l,    -a / 2],
                [total_len / 2 - grip_l - trans_l,    a / 2],
                [gauge_l / 2,                         -b / 2],
                [gauge_l / 2,                          b / 2],
                [-gauge_l / 2,                         -b / 2],
                [-gauge_l / 2,                          b / 2]
            ]);
}

difference() {
    union() {
        body();
        transitions();
    }

    // cut the grip ends so the transitions are exposed
    translate([-(total_len / 2 - grip_l - trans_l - overcut), -a / 2 - overcut, -overcut])
        cube([trans_l + overcut, a + 2 * overcut, thickness + 2 * overcut]);
    translate([(total_len / 2 - grip_l - trans_l - overcut), -a / 2 - overcut, -overcut])
        cube([trans_l + overcut, a + 2 * overcut, thickness + 2 * overcut]);
}
