module dogbone() {
    hull() {
        // Left grip block
        translate([-total_len/2 + grip_len, -half_g2, 0])
            cube([grip_len, grip_w, thickness]);
        // Right grip block
        translate([total_len/2 - grip_len, -half_g2, 0])
            cube([grip_len, grip_w, thickness]);
        // Gauge block (overlaps the transitions to keep the hull solid)
        translate([-gauge_len/2, -half_g, 0])
            cube([gauge_len, gauge_w, thickness]);
    }

    // Remove the two transition volumes, leaving a V-shaped width change
    for (s = [-1, 1]) {
        x0 = -total_len/2 + grip_len;   // start of transition
        x1 = -gauge_len/2;              // end of transition
        // rotate([90,0,0]) maps our 2D (x, width) to (x, z), then
        // the cone runs along Y, from y = eps up to y = trans_len
        translate([s * x0, eps, 0])
            rotate([90, 0, 0])
                cone(h = trans_len, r1 = s * grip_w / 2, r2 = s * gauge_w / 2);
    }
}

