half_grip   = grip_w / 2;   // grip half-width
half_gauge  = gauge_w / 2;  // gauge half-width
reach       = grip_len + trans_len; // distance from origin to grip end

// ---------- Model ----------
difference() {
    // Hull of grip, gauge, and transition blocklets
    hull() {
        for (s = [-1, 1]) {
            translate([s * reach, -half_grip, 0])
                cube([grip_len, grip_w, thickness]);   // grip
            translate([s * (reach - trans_len), -half_gauge, 0])
                cube([gauge_len, gauge_w, thickness]); // gauge
            // transition: width changes linearly from 20 to 6
            for (t = [0 : trans_len / 2 : trans_len]) {
                w = half_grip - (t / trans_len) * (half_grip - half_gauge);
                translate([s * (reach - trans_len + t), -w, 0])
                    cube([dt(t), 2 * w, thickness]);
            }
        }
    }

    // Cut out the centre span between the two transitions,
    // leaving a 6 mm-wide gauge section exactly 30 mm long.
    translate([-1 * (reach - trans_len), -half_gauge, -eps])
        cube([2 * (reach - trans_len), gauge_w, thickness + 2 * eps]);
