$fn = 64;

// ---- Dimensions ----
thickness      = 4;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip->gauge transition
cut_overlap    = 0.5;   // extra length on cutters to avoid coplanar faces

// ---- Derived ----
