x0             = -total_length / 2;  // left end of part

// Width of the part at a given X position
function w(x) =
    if (x < grip_length - cut_overlap)
        grip_width;
    else if (x < gauge_length - cut_overlap + grip_length - cut_overlap)
        // left transition: grip_width -> gauge_width
        grip_width - (x - (grip_length - cut_overlap))
                      * (grip_width - gauge_width) / transition_len;
    else if (x < gauge_width + cut_overlap + grip_length - cut_overlap)
        // right transition: gauge_width -> grip_width
        gauge_width + (x - (gauge_width + cut_overlap)
                        + cut_overlap + grip_length - cut_overlap)
                      * (grip_width - gauge_width) / transition_len;
    else
        grip_width;

// ---- Model ----
linear_extrude(thickness)
    polygon(points = [for (i = [0 : 100]) [x0 + i * total_length / 99, w(x0 + i * total_length / 99)]]);
