// Flat tensile test specimen (dog-bone shape)
// Units: mm. Print flat on the bed (z = 0 up to thickness).

$fn = 64;

// ---- Dimensions ----
thickness      = 4;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 6;     // width of the narrow gauge section (Y)
gauge_length   = 30;    // length of the gauge section along X
grip_width     = 20;    // width of each grip section (Y)
grip_length    = 30;    // length of each grip section along X
transition_len = 15;    // length of the tapered transition between grip and gauge
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
mid_x      = 0;                              // centre of the part
grip_x0    = -mid_x - total_length/2 + grip_length;  // left grip start
grip_x1    = mid_x + total_length/2 - grip_length;   // right grip end
gauge_x0   = grip_x0 + grip_length;           // gauge start (transition end)
gauge_x1   = gauge_x0 + gauge_length;         // gauge end (transition start)

// ---- Model ----
difference() {
    // Outer plate
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon(points = [
                // Left grip
                [grip_x0, -grip_width/2], [grip_x0, grip_width/2],
                // Left transition
                for (t = [0 : 1]) [transition_x(t), w(t)],
                // Gauge section
                [gauge_x0 - gauge_length/2, -gauge_width/2],
                [gauge_x0 - gauge_length/2,  gauge_width/2],
                [gauge_x1,     gauge_width/2],
                [gauge_x1,     -gauge_width/2],
                // Right transition
                for (t = [0 : 1]) [transition_x(1 - t), w(1 - t)],
                // Right grip
                [grip_x1,     grip_width/2], [grip_x1, -grip_width/2]
            ]);

    // Cut out gauge section (extends into transitions to avoid coplanar faces)
    translate([gauge_x0 - gauge_length/2 - cut_extra,
               -gauge_width/2, 0])
        cube([gauge_length + 2*cut_extra, gauge_width, thickness + 2*cut_extra]);
}

// ---- Helpers ----
// Tapered transition: width changes linearly from grip_width to gauge_width
function transition_x(u) = grip_x0 + grip_length + u * transition_len;
function w(u) = grip_width - u * (grip_width - gauge_width);
