        gauge_width + (x - gauge_x0) * (grip_width - gauge_width) / transition_len;
    else
        grip_width;

difference() {
    // Main plate
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon(points = [for (sx = [-1, 1], sy = [-1, 1])
                [sx * (total_length/2 - grip_length + 0.01),
                 sy * (total_length/2 - grip_width + 0.01)]]);

    // Central gauge section (overlaps slightly into transitions for a clean cut)
    translate([-gauge_x0 - cut_extra, -gauge_width/2, 0])
        cube([gauge_length + 2*cut_extra, gauge_width, thickness]);
}
