// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
overlap        = 1;     // overlap of grip sections for a solid union

// ---- Derived ----
x0 = -total_length / 2;   // left end of specimen

// ---- Modules ----
module grip(length, width) {
    translate([x0 + length / 2, -width / 2, 0])
        cube([length, width, thickness]);
}

module transition(length, w1, w2) {
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = length)
            polygon([
                [-w1 / 2, 0], [w1 / 2, 0],
                [w2 / 2, length / 2], [-w2 / 2, length / 2]
            ]);
}

// ---- Assembly ----
union() {
    for (s = [-1, 1])
        grip(grip_length, grip_width);

    translate([0, 0, 0])
        union() {
            for (sx = [-1, 1])
                for (sy = [-1, 1])
                    translate([sx * (total_length / 2 - gauge_length / 2),
                               sy * (total_length / 2 - gauge_length / 2)])
                        translate([0, 0, 0])
                            union() {
                                for (t = [transition_len / 2, -transition_len / 2])
                                    translate([t * sy, 0, 0])
                                        transition(transition_len, grip_width, gauge_width);
                                translate([0, 0, 0])
                                    cube([gauge_length, gauge_width, thickness]);
                            }
        }
}
