// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, symmetric about the origin.
// Coordinates: X = length direction, Y = width direction, Z = thickness (0 .. t)

// ---------------- Parameters (mm) ----------------
specimen_length   = 130;   // total length along X
thickness         = 3;     // thickness along Z
gauge_width       = 10;    // width of the central gauge section
gauge_length      = 30;    // length of the central gauge section
grip_width        = 20;    // width of each grip section (end blocks)
grip_length       = 35;    // length of each grip section
transition_length = 15;    // length of each flank transition (grip -> gauge)
overcut           = 0.5;   // extra length so cutters pass through faces

$fn = 64;

// ---------------- Derived ----------------
half_gauge_w = gauge_width / 2;
half_grip_w  = grip_width  / 2;

// Centre of each feature (specimen centred on origin)
x_gauge      = 0;
x_grip       = -(specimen_length / 2 + transition_length + gauge_length / 2);
x_grip_pos   =  specimen_length / 2 + transition_length + gauge_length / 2;

// ---------------- Model ----------------
union() {
    // Central gauge section
    translate([x_gauge - gauge_length / 2, -half_gauge_w, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Grip sections (end blocks)
    for (sx = [-1, 1])
        translate([sx * x_grip, -half_grip_w, 0])
            cube([grip_length, grip_width, thickness]);

    // Flank transitions: width changes linearly from grip width -> gauge width
    for (sx = [-1, 1]) {
        w_start = sx < 0 ? grip_width : gauge_width;
        w_end   = sx < 0 ? gauge_width : grip_width;
        translate([sx * (specimen_length / 2 - gauge_length / 2 - transition_length),
                   -half_gauge_w, 0])
            linear_extrude(height = thickness)
                polygon([
                    [0, 0],
                    [transition_length, 0],
                    [transition_length, w_end / 2],
                    [0, w_start / 2]
                ]);
        mirror([0, 1, 0])
            translate([sx * (specimen_length / 2 - gauge_length / 2 - transition_length),
                       -half_gauge_w, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, 0],
                        [transition_length, 0],
                        [transition_length, -w_end / 2],
                        [0, -w_start / 2]
                    ]);
    }
}

// ---------------- Boolean cleanup ----------------
// Differences are extended by 'overcut' so no cut face is coplanar with a solid face.
difference() {
    // Full solid (slightly extended past the end faces to avoid coplanar faces)
    translate([-specimen_length / 2 - overcut, -grip_width / 2, -overcut])
        cube([specimen_length + 2 * overcut, grip_width, thickness + 2 * overcut]);

    // Remove the grip regions, leaving only gauge + transitions
    for (sx = [-1, 1])
        translate([sx * x_grip - overcut, -half_grip_w - overcut, -overcut])
            cube([grip_length + 2 * overcut, grip_width + 2 * overcut,
                  thickness + 2 * overcut]);
}
