                [end_x - transition_len, grip_width / 2],
                [end_x - transition_len, -grip_width / 2],
                // right grip
                [end_x, grip_width / 2],
                [end_x, -grip_width / 2],
                // left grip
                [grip_start_x, grip_width / 2],
                [grip_start_x, -grip_width / 2],
            ]);

    // ---- Cutouts ----
    difference() {
        // Central gauge cut (through the whole part)
        translate([-gauge_length / 2, -gauge_width / 2 - cut_extra, -cut_extra])
            cube([gauge_length, gauge_width + 2 * cut_extra, thickness + 2 * cut_extra]);

        // Rounded end pockets so the grip sections fuse into the transitions
        for (sx = [-1, 1])
            translate([sx * (end_x - transition_len), -cut_extra, -cut_extra])
                cylinder(r = grip_width / 2 - 0.5, h = cut_extra + 0.5);
    }
}

dog_bone();
