    if (x < gauge_start_x - transition_len)
        // left grip section
        grip_width;
    else if (x < gauge_start_x)
        // left transition: grip width -> gauge width
        grip_width - (grip_width - gauge_width) *
            (x - (gauge_start_x - transition_len)) / transition_len;
