// Flat dog-bone tensile specimen
// Units: mm. Print orientation: flat on bed, z = 0 up.

// ---------- Dimensions ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // grip-to-gauge transition length (X)

// ---------- Derived ----------
eps            = 0.5;   // overlap/extension for clean booleans and hulls

x0_grip        = -total_length/2 + grip_length;                  // grip start X
x0_gauge       = x0_grip + grip_length;                          // gauge start X
x0_trans       = [x0_gauge - transition_len, x0_gauge + transition_len]; // transition start X (both ends)

// ---------- Model ----------
hull() {
    // Grip blocks at each end
    for (s = [-1, 1])
        translate([s * x0_grip, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

    // Central gauge block
    translate([x0_gauge - gauge_length, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transition blocks: width changes linearly from grip (20) to gauge (10)
    for (s = [-1, 1])
        for (t = [0, 1])
            translate([x0_trans[s] + t * transition_len - transition_len,
                       -20/2, 0])
                cube([transition_len, 20, thickness]);
}

// Cut the gauge region so the grip/transition zones carry the load
difference() {
    // --- Solid (as built above) ---
    hull() {
        for (s = [-1, 1])
            translate([s * x0_grip, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);

        translate([x0_gauge - gauge_length, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        for (s = [-1, 1])
            for (t = [0, 1])
                translate([x0_trans[s] + t * transition_len - transition_len,
                           -20/2, 0])
                    cube([transition_len, 20, thickness]);
    }

    // --- Cutting shapes ---
    // 1) Gauge section, extended past its end faces
    translate([x0_gauge - gauge_length - eps, -gauge_width/2, -eps])
        cube([gauge_length + 2*eps, gauge_width, thickness + 2*eps]);

    // 2) Overlap between each grip and its transition: width 20 -> 15
    for (s = [-1, 1]) {
        overlap_x = grip_length - transition_len + eps;   // where the two widenings cross
        translate([s * x0_grip - transition_len + eps, -15/2, -eps])
            cube([overlap_x + eps, 15, thickness + 2*eps]);
    }
}
