// Flat dog-bone tensile specimen for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // each grip-to-gauge transition length (X)
overcut        = 0.5;   // extension of cutting shapes past faces

// ---- Derived ----
half_thick = thickness / 2;
// width at a given X, using the linear profile between the four zones
function w(x) =
    if (x < -grip_length - transition_len) grip_width + (gauge_width - grip_width) *
        (x + grip_length + transition_len) / transition_len
    else if (x <= -gauge_length / 2) grip_width
    else if (x <= gauge_length / 2) gauge_width
    else if (x < grip_length + transition_len) grip_width
    else grip_width + (gauge_width - grip_width) *
        (x - (grip_length + transition_len)) / transition_len;

difference() {
    // central hull of four corner blocks (sides and endoms)
    hull() {
        for (sx = [-1, 1])
            for (sy = [-1, 1])
                translate([
                    sx * (grip_length + transition_len),
                    sy * (w(grip_length + transition_len) / 2),
                    0
                ])
                    cube([transition_len, w(grip_length + transition_len), thickness]);
        for (sx = [-1, 1])
            for (sy = [-1, 1])
                translate([
                    sx * (-grip_length - transition_len),
                    sy * (w(-grip_length - transition_len) / 2),
                    0
                ])
                    cube([transition_len, w(-grip_length - transition_len), thickness]);
    }
    // grip sections, overcut on top and bottom
    for (sx = [-1, 1])
        translate([sx * (grip_length - transition_len), -grip_width / 2, -overcut])
            cube([grip_length + 2 * transition_len, grip_width, thickness + 2 * overcut]);
    // gauge section, overcut on top and bottom
    translate([-gauge_length / 2, -w(gauge_length / 2) / 2, -overcut])
        cube([gauge_length, w(gauge_length / 2), thickness + 2 * overcut]);
}
