// Spoked wheel for a small sample cart
// Flat part, printed lying on the bed, centred on the origin.

$fn = 96;

// ---- Dimensions (mm) ----
wheel_thickness  = 5;    // overall thickness of the part (Z)
outer_diameter   = 60;   // outer rim diameter
rim_width        = 4;    // rim width (radial extent of the ring)
hub_diameter     = 14;   // round hub diameter
axle_hole        = 6;    // axle hole diameter through the hub
spoke_count      = 5;    // number of spokes
spoke_width      = 4;    // spoke width (radial)
spoke_start_ang  = 0;    // first spoke along +X axis (degrees)
overlap          = 0.5;  // radial overlap of spokes into rim/hub for a clean union

// ---- Derived ----
outer_r = outer_diameter / 2;

// Rim: ring from (outer_d - width)/2 out to outer_d/2
module rim() {
    difference() {
        cylinder(d = outer_diameter, h = wheel_thickness);
        translate([0, 0, -1])
            cylinder(d = outer_diameter - 2 * rim_width, h = wheel_thickness + 2);
    }
}

// Hub: round hub with an axial hole, slightly extending past the rim to fuse the spokes
module hub() {
    translate([0, 0, -1])
        cylinder(d = hub_diameter + 2 * overlap, h = wheel_thickness + 2);
    translate([0, 0, -1])
        cylinder(d = axle_hole, h = wheel_thickness + 2 + overlap);
}

// Spokes: straight radial bars from the hub out to the rim
module spokes() {
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_ang + i * 360 / spoke_count;
        translate([0, 0, -1])
            rotate([0, 0, a])
                translate([-(hub_diameter / 2 - overlap), -spoke_width / 2, 0])
                    cube([(hub_diameter / 2 - overlap) + outer_r - hub_diameter / 2,
                          spoke_width,
                          wheel_thickness + 2]);
    }
}

union() {
    rim();
    hub();
    spokes();
}
