// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 upward

// ---------- Parameters ----------
wheel_d      = 60;    // outer diameter of rim (mm)
rim_w        = 4;     // rim width (mm)
hub_d        = 20;    // hub diameter (mm)
axle_hole_d  = 8;     // axle hole diameter (mm)
spoke_count  = 6;     // number of spokes
spoke_w      = 4;     // spoke width (mm)
spoke_start  = 0;     // angle of first spoke, deg (0 = +X axis)
eps          = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;             // smoothness of curved shapes

// ---------- Derived ----------
outer_r = wheel_d / 2;
hub_r   = hub_d / 2;
spoke_len = outer_r - hub_r;   // from hub edge to rim edge

// ---------- Model ----------
union() {
    // Outer rim
    cylinder(d = wheel_d, h = rim_w);

    // Hub with axle hole
    translate([0, 0, rim_w])
        difference() {
            cylinder(d = hub_d, h = rim_w + eps);
            translate([0, 0, -eps])
                cylinder(d = axle_hole_d, h = rim_w + 2 * eps);
        }

    // Spokes, radially from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([hub_r, 0, rim_w])
            rotate([0, 0, a])
                translate([0, -spoke_w / 2, 0])
                    cube([spoke_len + eps, spoke_w, rim_w + eps]);
    }
}
