// Spoked wheel for small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 96;

// --- Dimensions (mm) ---
total_d      = 60;   // outer rim diameter
rim_w        = 4;    // rim width
hub_d        = 20;   // hub diameter
axle_d       = 8;    // axle hole diameter
spoke_count  = 6;    // number of spokes
spoke_w      = 4;    // spoke width
spoke_l      = 48;   // spoke length (hub to rim)
thickness    = 6;    // part thickness

eps          = 0.5;  // cut overshoot

difference() {
    union() {
        // Rim
        cylinder(d = total_d, h = rim_w);
        // Hub
        translate([0, 0, rim_w])
            cylinder(d = hub_d, h = thickness - rim_w + 0.01);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, rim_w])
                    cube([spoke_l + 2, spoke_w, thickness - rim_w - 0.01]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
