// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

// ---------- Parameters ----------
wheel_d      = 60;    // outer rim diameter
wheel_t      = 6;     // wheel thickness (Z)
rim_w        = 4;     // rim width
hub_d        = 20;    // hub diameter
axle_d       = 8;     // axle hole diameter
spokes       = 6;     // number of spokes
spoke_w      = 4;     // spoke width
spoke_start  = 0;     // angle of first spoke (deg, +X axis)
eps          = 0.5;   // cutter overshoot

$fn = 128;

// ---------- Model ----------
difference() {
    // Rim + hub body
    union() {
        // Rim (ring)
        cylinder(d = wheel_d, h = wheel_t);
        // Hub (inner disc, overlaps rim for a clean union)
        translate([0, 0, -eps])
            cylinder(d = hub_d + 4, h = wheel_t + 2 * eps);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_t + 2 * eps);

    // Spokes: radial slots from hub to rim
    for (i = [0 : spokes - 1]) {
        a = spoke_start + i * 360 / spokes;
        translate([0, 0, -eps])
            rotate([0, 0, a])
                translate([0, -spoke_w / 2, 0])
                    cube([spoke_w, spoke_w, wheel_t + 2 * eps]);
    }
}
