// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 up to part thickness

$fn = 128;

// ---- Dimensions (mm) ----
wheel_thickness = 8;     // part thickness (Z)
outer_diameter  = 100;   // outer rim diameter
rim_width       = 6;     // rim width (radial)
hub_diameter    = 20;    // hub diameter
axle_hole       = 6;     // axle hole diameter
spoke_count     = 6;     // number of spokes
spoke_width     = 4;     // spoke width (radial)
spoke_start     = 0;     // first spoke along +X axis
cut_overlap     = 0.5;   // extra length for cutters to pass faces

// ---- Derived ----
outer_r      = outer_diameter / 2;
rim_inner_r  = outer_r - rim_width;
hub_r        = hub_diameter / 2;

// Spokes run from the hub to the rim, slightly over both ends
spoke_len = (outer_r - hub_r) + 2 * cut_overlap;

module wheel() {
    difference() {
        union() {
            // Outer rim (ring)
            hull() {
                for (a = [0, 180])
                    rotate([0, 0, a])
                        translate([outer_r - rim_width, 0, 0])
                            cylinder(r = rim_width, h = wheel_thickness);
            }

            // Hub
            cylinder(r = hub_r, h = wheel_thickness);

            // Spokes
            for (i = [0 : spoke_count - 1])
                rotate([0, 0, spoke_start + i * 360 / spoke_count])
                    translate([hub_r + cut_overlap, 0, 0])
                        cube([spoke_len, spoke_width, wheel_thickness]);
        }

        // Axle hole through the hub
        translate([0, 0, -cut_overlap])
            cylinder(d = axle_hole, h = wheel_thickness + 2 * cut_overlap);
    }
}

wheel();
