// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin, builds upward (+Z)

// ---------------- Parameters ----------------
wheel_d      = 60;    // outer diameter of wheel (mm)
width        = 5;     // wheel thickness (mm)
spokes       = 4;     // number of spokes
spoke_w      = 5;     // spoke width (mm)
hub_d        = 14;    // hub outer diameter (mm)
axle_d       = 6;     // axle hole diameter (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 128;   // facet count for round features

// Derived
rim_w = width - 2 * eps;   // rim height below cutter top plane

// ---------------- Model ----------------
difference() {
    // Wheel body: outer disc minus a counterbore that leaves the hub
    // 2 mm thicker above the bed (affects only the hole, per the spec)
    counterbore_d = hub_d + 2 * eps;
    counterbore_h = width + 2 * eps;
    union() {
        cylinder(d = wheel_d, h = width - eps);
        translate([0, 0, eps])
            cylinder(d = counterbore_d, h = counterbore_h - eps);
    }

    // Axle hole through the full height
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = width + 2 * eps);

    // Spokes: radial blocks from hub out to the rim, evenly spaced
    // (first along +X per the spec; overlaps the hub/rim, which is fine)
    for (i = [0 : spokes - 1])
        rotate([0, 0, i * 360 / spokes])
            translate([0, -spoke_w / 2, 0])
                cube([wheel_d / 2 + eps, spoke_w, width]);
}
