// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)
// Units: mm

// ---------------- Parameters ----------------
flange_width   = 10;   // flange width along Y
flange_thick   = 3;    // flange thickness (z = 0 to 3)
neck_width     = 7;    // neck width along Y
neck_top_z     = 6;    // top of neck (neck runs z = 3 to 6)
screw_d        = 4.5;  // central screw hole diameter
screw_overcut  = 0.5;  // extra length of hole past top and bottom faces
x_length       = 10;   // part length along X axis
x_center       = 0;    // X centre of part
y_center       = 0;    // Y centre of part

$fn = 64;              // circle resolution

// ---------------- Model ----------------
difference() {
    // T profile (flange + neck)
    union() {
        // Bottom flange: z = 0 to 3, Y = -5 to 5, X = -5 to 5
        translate([x_center, -flange_width / 2, 0])
            cube([x_length, flange_width, flange_thick]);

        // Neck: z = 3 to 6, Y = -3.5 to 3.5, X = -5 to 5
        translate([x_center, -neck_width / 2, flange_thick])
            cube([x_length, neck_width, neck_top_z - flange_thick]);
    }

    // Central vertical screw hole, extends past both faces
    translate([0, 0, -screw_overcut])
        cylinder(d = screw_d, h = neck_top_z + 2 * screw_overcut);
}
