// T-shaped nut for aluminium extrusion
// Print orientation: flange flat on bed, neck pointing up (+Z)

// ---------------- Parameters ----------------
flange_width = 14;    // flange size in Y (and X, symmetric)
flange_t     = 3;     // flange thickness (z = 0 to 3)

neck_width   = 7;     // neck size in Y (and X, symmetric)
neck_top_z   = 6;     // top of neck (neck runs z = 6 to 12)

screw_d      = 3.4;   // central screw hole diameter
screw_h      = 15;    // screw hole depth from top of neck

overlap      = 0.01;  // small overlap so flange and neck fuse cleanly

$fn = 64;

// ---------------- Model ----------------
difference() {
    union() {
        // Flange
        translate([0, 0, 0])
            cube([flange_width, flange_width, flange_t]);

        // Neck (slightly wider so it overlaps the flange)
        translate([0, 0, neck_top_z - overlap])
            cube([neck_width + 2 * overlap,
                  neck_width + 2 * overlap,
                  neck_h + overlap]);
    }

    // Screw hole from top of neck down into the flange
    translate([0, 0, neck_top_z - screw_h])
        cylinder(d = screw_d, h = screw_h + overlap);
}
