```openscad
// Stiffened cover panel - flat plate with 3 transverse ribs
// Units: mm. Print orientation: plate on bed (z = 0), ribs up (+Z).

$fn = 64;

// ---- Plate ----
plate_len   = 80;    // plate length along X
plate_wid   = 50;    // plate width along Y
plate_thk   = 2;     // plate thickness (z = 0 to 2)

// ---- Ribs ----
rib_count   = 3;     // number of ribs
rib_thk     = 2;     // rib thickness along X
rib_h       = 4;     // rib total height (z = 0 to 4)
rib_pitch   = 20;    // centre-to-centre spacing of ribs
rib_off     = 20;    // distance of outer rib centres from plate ends

// ---- Misc ----
overlap     = 0.01;  // small overlap so ribs fuse into plate

// Derived rib centres: 4 equal parts -> 3 ribs at 20, 40, 60
for (i = [0 : rib_count - 1])
    rib_c[i] = (i + 1) * rib_pitch;

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module ribs() {
    for (r = [0 : rib_count - 1]) {
        x = rib_c[r];
        // extend slightly into plate and upward for a solid union
        translate([x - rib_thk/2, -plate_wid/2, -overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}

union() {
    plate();
    ribs();
}
