// Stiffened cover panel - flat plate with 3 transverse ribs
// Print orientation: plate flat on bed (z = 0), ribs build upward (+Z)

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 50;    // plate width along Y (mm)
