rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate top (mm), z = 2..6
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 20;    // distance of outer rib centres from plate ends (mm)

overlap     = 0.01;  // small overlap so ribs fuse with plate (mm)

$fn = 64;

// ---------------- Derived ----------------
first_x = rib_offset;
last_x  = plate_len - rib_offset;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        x = (i < (rib_count - 1) / 2) ? first_x + i * rib_pitch
            : (i >= (rib_count - 1) / 2) ? last_x - i * rib_pitch
                                         : (first_x + last_x) / 2;
        translate([x - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
