overlap      = 0.01;  // small overlap so ribs fuse into the plate

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    // Their centres are 20 mm apart; the outer ones are 20 mm from the ends,
    // which places them at X = 20, 40, 60, 80 (5 equal 20-mm sections)
    for (i = [0 : rib_count - 1])
        translate([i * rib_centre_sp - (rib_count - 1) * rib_centre_sp / 2
                   - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
