// Stiffened cover panel - flat plate with 4 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 100;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

// ---- Ribs ----
rib_count   = 4;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 2..6
rib_pitch   = 20;    // centre-to-centre spacing along X (mm)
rib_offset  = 20;    // distance of outer rib centres from plate ends (mm)

// ---- Modelling ----
overlap     = 0.5;   // rib embedment into plate for clean union (mm)

// Rib centre X positions: outer ones 'rib_offset' from the ends,
// then evenly spaced across the middle.
function rib_x(i) =
    (i < rib_count / 2)
        ? -plate_len / 2 + rib_offset + i * rib_pitch
        : plate_len / 2 - rib_offset - (rib_count - 1 - i) * rib_pitch;

union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1])
        translate([rib_x(i) - rib_thk / 2, -plate_wid / 2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
}
