    union() {
        // Bowl: lower half of hollow sphere
        translate([0, 0, 0])
            difference() {
                cylinder(h = bowl_rim_z, r = bowl_outer_radius);
                translate([0, 0, eps])
                    cylinder(h = bowl_rim_z - eps, r = bowl_outer_radius - bowl_wall);
            }

        // Handle: flat plate along +X, top face flush with rim
        translate([13.5, -handle_width / 2, bowl_rim_z - handle_thickness])
            cube([handle_length, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere above the rim to avoid overlapping solid
    translate([0, 0, bowl_rim_z + eps])
        cylinder(h = bowl_outer_radius + eps, r = bowl_outer_radius + eps);
}
