// Powder measuring scoop
// Print orientation: handle along X, bowl above the bed

$fn = 96;

// --- Handle ---
handle_len   = 101.5;  // x = 8.5 to 110
handle_wid   = 8;      // Y
handle_thk   = 3;      // Z, top flush with rim (z = 7..10)

// --- Bowl ---
r_out       = 10;      // outer radius
r_in        = r_out - 1.5;  // wall thickness 1.5
h_bowl      = r_out;   // lower half height (centre at z = 10, rim at z = 10)

eps         = 0.5;     // overlap / safety

union() {
    // Handle
    translate([8.5, -handle_wid/2, handle_thk - eps])
        cube([handle_len, handle_wid, handle_thk + eps]);

    // Bowl (hollow lower hemisphere)
    translate([0, 0, -eps])
        difference() {
            hull() {
                for (a = [0, 180])
                    rotate([0, 0, a])
                        translate([0, -r_out - eps, 0])
                            cylinder(r = r_out + eps, h = h_bowl, $fn = 128);
            }
            hull() {
                for (a = [0, 180])
                    rotate([0, 0, a])
                        translate([0, -r_in - eps, 0])
                            cylinder(r = r_in + eps, h = h_bowl, $fn = 128);
            }
        }
