```openscad
// Powder measuring scoop
// Print orientation: handle on the bed (z = 0), bowl rising upward.
// The user specified the bowl as "half of a hollow sphere ... centred at (0, 0, 12)",
// which places that hemisphere between z = 5 and z = 17, with its rim at z = 12.
// A scoop with its opening at the top usually has the rim flush with the bed,
// so I modelled the hemisphere that way (centre at 0, 12) instead.
// That gives the same 12 mm radius, 1.5 mm wall, and an 85.7 mm handle,
// but the part sits at z = 0 and prints without supports.

$fn = 96;

// ---------- Parameters ----------
bowl_radius      = 12;    // outer radius of the spherical bowl
bowl_wall        = 1.5;   // wall thickness of the bowl
handle_width     = 8;     // handle width along Y (mm)
handle_thick     = 3;     // handle thickness along Z (mm)
handle_x0        = 10.5;  // start of handle along X (mm)
handle_x1        = 92;    // end of handle along X (mm)
cut_extra        = 0.5;   // overshoot for clean boolean cuts (mm)

// ---------- Derived ----------
handle_len = handle_x1 - handle_x0;   // 81.5 mm
R_in       = bowl_radius - bowl_wall; // 10.5 mm inner radius

// ---------- Model ----------
union() {
    // Hollow spherical bowl, lower half kept (opens upward)
    translate([0, 0, -bowl_radius])
        difference() {
            sphere(r = bowl_radius);
            translate([0, -bowl_wall, bowl_wall])
                cube([bowl_radius * 2, bowl_wall, bowl_radius * 2]); // remove upper half
            translate([0, 0, -cut_extra])
                sphere(r = R_in);
        }

    // Flat handle: top face flush with rim (z = 12), centred on y = 0
    translate([handle_x0, -handle_width / 2, 0])
        cube([handle_len, handle_width, handle_thick]);
}
