$fn = 96;

// ---- Bowl ----
outer_radius   = 12;   // mm, outer radius of the sphere
wall_thickness = 1.5;  // mm, wall thickness of the hollow sphere
bottom_z       = 0;    // mm, z of the sphere's lowest point (touches the bed)
rim_z          = 12;   // mm, z of the rim (upper half of the sphere is cut away)

// ---- Handle ----
handle_length = 81.5;  // mm, handle runs from x = 10.5 to x = 92
handle_width  = 8;     // mm, handle width along Y
handle_thick  = 3;     // mm, handle thickness along Z
handle_x0     = 10.5;  // mm, start of handle in X
handle_x1     = 92;    // mm, end of handle in X

// ---- Misc ----
eps = 0.5;             // mm, overshoot for clean boolean cuts

difference() {
    union() {
        // Hollow spherical bowl: lower half of a sphere centred at (0, 0, 12)
        translate([0, 0, bottom_z])
            sphere(r = outer_radius, h = outer_radius + eps);

        // Flat handle, top face flush with the rim (z = 12)
        translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Remove the upper half of the sphere (above z = 12) so the opening is flat
    translate([0, 0, rim_z])
        cylinder(h = eps, r = outer_radius + 1);
}
