        translate([handle_start_x - overlap, -handle_width / 2, outer_radius - handle_thick])
            cube([handle_end_x - handle_start_x + overlap, handle_width, handle_thick]);
    }

    // Small round foot at the bowl bottom so it sits firmly on the bed
    translate([0, 0, -cut_ext])
        cylinder(h = cut_ext + 0.01, r = 3);
