// Powder measuring scoop
// Units: mm. Print orientation: handle flat on bed, bowl pointing up.

$fn = 96;

// ---- Parameters ----
bowl_outer_r   = 12;    // outer radius of spherical bowl
bowl_wall      = 1.5;   // bowl wall thickness
bowl_bottom_z  = 3;     // height of bowl bottom above bed
handle_len     = 101.5; // handle length (x = 10.5 to 112)
handle_w       = 10;    // handle width (Y)
handle_t       = 4;     // handle thickness (Z), top flush with rim

eps            = 0.5;   // cutter overshoot

// ---- Derived ----
bowl_inner_r   = bowl_outer_r - bowl_wall;
rim_z          = bowl_bottom_z + bowl_outer_r;   // = 15
half_thick     = bowl_outer_r / 2;               // for sphere cut

// ---- Model ----
union() {
    // Bowl: lower half of a thick-walled sphere
    translate([0, 0, bowl_bottom_z])
        difference() {
            sphere(r = bowl_outer_r);
            translate([0, 0, -half_thick])
                sphere(r = half_thick + 0.01);   // remove upper half
        }

    // Handle: straight bar along +X, centred on y = 0
    translate([10.5, -handle_w / 2, 0])
        cube([handle_len, handle_w, handle_t]);
}

// ---- Clean coplanar faces ----
difference() {
    // re-use the same union as a temporary solid
    t = draw_id();
    for (f = get_faces(t))
        if (is_horizontal(f))
            cut_plane(z = f.z + eps);
    return t;
}
