// ---- Derived ----
bowl_inner_r   = bowl_outer_r - bowl_wall;
bowl_bottom_z  = bowl_rim_z - bowl_outer_r;   // sphere bottom (z = 0)
bowl_hull_r    = max(bowl_outer_r, handle_w / 2 + 1); // hull radius at rim

// ---- Model ----
union() {
    // Hollow spherical bowl (lower half kept, rim open upward)
    translate([0, 0, bowl_bottom_z])
        difference() {
            cylinder(r = bowl_outer_r, h = bowl_outer_r);
            translate([0, 0, -eps])
                cylinder(r = bowl_inner_r, h = bowl_outer_r + 2 * eps);
        }

    // Straight handle, centred on y = 0, x = 10.5 .. 112
    translate([10.5, -handle_w / 2, 0])
        cube([handle_len, handle_w, handle_t]);

    // Hull fuses bowl and handle into one solid
    hull() {
        translate([0, 0, bowl_bottom_z])
            cylinder(r = bowl_hull_r, h = eps);       // radius at z = 0
        translate([0, bowl_hull_r, 0])
            rotate([90, 0, 0])
                translate([0, -bowl_hull_r, 0])
                    cylinder(r = bowl_hull_r, h = eps); // radius at z = 24
    }
}
