        // Handle
        translate([10.5, -handle_w/2, 0])
            cube([handle_len, handle_w, handle_t]);

        // Spout: half-hollow sphere, centred at (0, 0, spout_h), lower half kept
        translate([-spout_r, 0, spout_h])
            hull() {
                for (a = [0 : 180])
                    rotate([0, 0, a])
                        translate([0, -spout_r, 0])
                            cylinder(r = spout_r, h = spout_h + overlap, $fn = 64);
