    translate([-spout_r, 0, spout_h - spout_wall])
        hull() {
            for (a = [0 : 180])
                rotate([0, 0, a])
                    translate([0, -spout_r, 0])
                        cylinder(r = spout_r, h = spout_wall + overlap, $fn = 64);
        }
}
