// Measuring scoop for powders
// Print orientation: bowl bottom touching the bed at z = 0, handle extending along +X

$fn = 96;

// ---- Bowl ----
outer_radius = 15;    // outer radius of the full sphere
wall         = 1.5;   // wall thickness
bowl_centre  = 15;    // sphere centre height (lower half kept: rim at z = 15)

// ---- Handle ----
handle_width   = 12;  // width along Y
handle_thick   = 4;   // thickness along Z
handle_x_start = 13.5;
handle_x_end   = 95;  // runs from x = 13.5 to x = 95
handle_top_z   = bowl_centre - handle_thick;  // top face flush with rim (z = 11 to 15)

// ---- Misc ----
eps = 0.5;            // overshoot for clean cuts

difference() {
    union() {
        // Hollow spherical bowl
        translate([0, 0, bowl_centre])
            difference() {
                cylinder(r = outer_radius, h = bowl_centre);
                translate([0, 0, -eps])
                    cylinder(r = outer_radius - wall, h = bowl_centre + 2 * eps);
            }

        // Flat handle along +X
        translate([handle_x_start, -handle_width / 2, handle_top_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
    }

    // Remove the lower half of the outer sphere (below z = bowl_centre - eps)
    translate([0, 0, bowl_centre - eps])
        cylinder(r = outer_radius + eps, h = eps);
}
