// Cable bridge - rectangular block with 3 semicircular tunnels along Y
// Print orientation: flat on bed, tunnels facing down

// ---- Block dimensions ----
block_len   = 80;   // X length (mm)
block_wid   = 40;   // Y width (mm)
block_h     = 15;   // Z height (mm)

// ---- Tunnel dimensions ----
tunnel_d    = 12;   // tunnel diameter (mm)
tunnel_pitch = 16;  // centre-to-centre spacing along X (mm)
tunnel_n    = 3;    // number of tunnels

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces (mm)
$fn         = 96;   // curve resolution

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels along Y at floor level
    for (i = [0 : tunnel_n - 1]) {
        x = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])
                cylinder(d = tunnel_d, h = block_wid/2 + eps, center = true);
    }
}
