difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels: cylinder axes along Y at z = 0, open downward
    for (i = [0 : tunnel_n - 1]) {
        translate([tunnel_x(i), 0, 0])
            translate([0, 0, eps])
                rotate([0, 90, 0])
                    cylinder(r = tunnel_r, h = block_wid / 2 + eps);
