// Cable bridge - rectangular block with semicircular tunnels along Y at floor level
// Print orientation: base on the bed (z = 0), tunnels open downward

// ---------------- Parameters ----------------
block_len    = 80;    // block length along X (mm)
block_wid    = 40;    // block width along Y (mm)
block_ht     = 15;    // block height along Z (mm)

tunnel_d     = 12;    // tunnel cylinder diameter (mm)
tunnel_pitch = 16;    // centre-to-centre spacing of tunnel axes along X (mm)
tunnel_n     = 3;     // number of tunnels

eps          = 0.5;   // overcut so cutters pass beyond the faces they cut (mm)

$fn = 96;             // curve resolution

// Derived: X position of first tunnel axis (tunnel axes centred on the origin)
tunnel_x0 = -(tunnel_n - 1) * tunnel_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axes along Y at z = 0, open downward
    for (i = [0 : tunnel_n - 1]) {
        translate([tunnel_x0 + i * tunnel_pitch, 0, 0])
            translate([0, 0, eps])
                rotate([0, 90, 0])
                    cylinder(d = tunnel_d, h = block_wid / 2 + eps);
    }
}
