```openscad
// Ring weight - torus lying flat on the bed
// Print orientation: rests on z = 0, middle plane at z = 8

// ---- Dimensions (mm) ----
cross_section_d  = 16;   // diameter of the round cross-section
ring_centre_r    = 28;   // radius of the circle the cross-section centre sweeps around Z
ring_width       = 72;   // ring size across (diameter of the torus)
cut_extra        = 0.5;  // extra length for cutting shapes past faces

$fn = 96;                // smoothness for curved shapes

// Derived values
cross_section_h = cross_section_d;  // height of cross-section (diameter = height for a circle)
ring_centre_z   = middle_z          // z of the cross-section centre (given as middle plane height)

// Main torus body
module ring_body() {
    // rotate([90,0,0]) maps the 2D ring (in XY) to XZ, then extrude along Y (0..ring_width)
    rotate([90, 0, 0])
        linear_extrude(height = ring_width)
            circle(d = cross_section_d, h = cross_section_h, $fn = 96);
}

// Central through-hole (radius reaches past the outer edge of the ring)
module ring_hole() {
    translate([0, 0, -cut_extra])
        cylinder(r = ring_centre_r + cross_section_d / 2 + cut_extra,
                 h = ring_width + 2 * cut_extra,
                 $fn = 96);
}

difference() {
    ring_body();
    ring_hole();
}
```

