```openscad
// Ring weight that sits around the neck of a flask in a water bath
// Print orientation: flat on the bed, middle plane at z = 4

// ---- Parameters ----
cross_section_d = 8;     // diameter of the round cross-section (mm)
ring_radius     = 30;    // radius of the ring (distance from Z axis to cross-section centre)
cut_extra       = 0.5;   // extra length on the cutting shapes to avoid coplanar faces (mm)
$fn             = 128;   // facet count for curved shapes

// ---- Derived ----
ring_widest     = ring_radius * 2 + cross_section_d;   // 68 mm across
ring_half_width = ring_widest / 2;

// ---- Model ----
// A torus is the set of points at distance ring_radius from the Z axis,
// with a circular cross-section of diameter cross_section_d swept around Z.
module ring_body() {
    // The user's coordinates place the cross-section centre at z = 4.
    // Shift it down by cross_section_d/2 so the bottom of the ring lies on z = 0.
    translate([0, 0, -cross_section_d / 2])
        linear_extrude(height = ring_radius * 2)
            circle(d = cross_section_d, $fn = 128);
}

// ---- Cutting shapes ----
// 1. Central hole: a cylinder on the Z axis, extended past top and bottom.
module central_hole() {
    translate([0, 0, -cut_extra])
        cylinder(h = ring_body().height + 2 * cut_extra, $fn = 128);
}

// 2. Two diagonal struts that run from the inner wall to the outer wall,
//    through the middle plane, to remove material that would otherwise be
//    inside the flask neck (a solid block from z = 0 to z = 8 would be a
//    valid solid, and the user did not rule it out, so the struts are used.)
module diagonal_struts() {
    for (a = [45, 135]) {
        rotate([0, 0, a])
            translate([ring_half_width - cut_extra, 0, -cut_extra])
                cube([cross_section_d + 2 * cut_extra,
                      ring_radius * 2 + 2 * cut_extra,
                      cross_section_d + 2 * cut_extra]);
    }
}

// ---- Part ----
difference() {
    ring_body();
    central_hole();
    diagonal_struts();
}
```

