// Ring weight - torus lying flat on the bed
// Print orientation: bottom face on z = 0, middle plane at z = 4

// ---- Dimensions (mm) ----
cross_section_d = 8;     // diameter of the round cross-section
ring_radius     = 30;    // radius of the Z-axis circle the cross-section sweeps around
total_width     = 68;    // overall across dimension (2 * ring_radius + cross_section_d)
middle_z        = 4;     // height of the torus middle plane

// ---- Derived ----
cross_section_r = cross_section_d / 2;   // cross-section radius
tube_h          = cross_section_d;       // tube height (same as diameter for a round cross-section)

// ---- Modelling ----
// A tube沿 the Z axis, centred on the circle of radius ring_radius,
// rests on z = 0 and has its middle plane at middle_z.
tube_center_z = middle_z - tube_h / 2;
rot_start_ang = -90;              // rotate so the tube top faces +Z

module ring_weight() {
    rotate([0, 0, rot_start_ang])
        linear_extrude(height = tube_h)
            translate([ring_radius, 0, 0])
                cylinder(r = cross_section_r, h = tube_h + tube_h / 2, center = true);
}

ring_weight();
