```openscad
// Pin hinge - one leaf
// Flat plate on the bed with two round knuckles along +Y and a pin hole through each.

// ---------------- Parameters ----------------
plate_len   = 45;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle diameter (mm)
knuckle_z   = 4;     // knuckle axis height above bed (mm)
knuckle_n   = 3;     // number of equal segments along X
knuckle_x0  = 0;     // first segment centre x (mm)
knuckle_x1  = 15;    // segment length = plate_len / knuckle_n (mm)

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X and Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments along +X
        for (i = [0, knuckle_n - 1]) {
            x = knuckle_x0 + i * knuckle_x1 - knuckle_x1/2;
            // cylinder centred at y = 15, z = 4, axis along X
            rotate([90, 0, 0])
                translate([x - knuckle_d/2, knuckle_x1, knuckle_z])
                    cylinder(d = knuckle_d, h = knuckle_x1 + eps);
        }
    }

    // Pin holes running along the knuckle axes
    for (i = [0, knuckle_n - 1]) {
        x = knuckle_x0 + i * knuckle_x1 - knuckle_x1/2;
        translate([x - knuckle_d/2 - eps, knuckle_x1, knuckle_z])
            rotate([90, 0, 0])
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2*eps);
    }
}
