                cylinder(d = knuckle_d, h = 10, $fn = 64);
        }
    }

    // Pin hole along X through every knuckle
    translate([-100, knuckle_y, knuckle_h])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = 200, $fn = 64);
}
