// Pin hinge leaf
// Print orientation: plate lying flat on the bed, z = 0 up to plate_thk

$fn = 96;

// ---- Plate ----
plate_len   = 40;   // X length of plate
plate_wid   = 30;   // Y width of plate
plate_thk   = 2.5;  // Z thickness of plate

