        // Base plate, centred in X/Y, sitting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments, axis along X
        for (i = [0 : 2 : knuckle_n - 1]) {
            x0 = -plate_len/2 + i * seg_w;
            x1 = x0 + seg_w;
            translate([x0, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin hole along the same axis through every knuckle
    translate([-plate_len/2, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = knuckle_n * seg_w + 2*eps);
}
