// Leaf of a pin hinge
// Print orientation: flat on the bed (z = 0), knuckles building up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 40;   // plate length along X (mm)
plate_wid   = 30;   // plate width along Y (mm)
plate_thk   = 2.5;  // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d      = 6;   // knuckle cylinder diameter (mm)
knuckle_count  = 3;   // number of knuckles per leaf
knuckle_pitch  = 8;   // centre-to-centre spacing along X (mm)
knuckle_y      = 15;  // knuckle axis Y position (mm)
knuckle_z      = 3;   // knuckle axis height above bed (mm)

// ---- Pin ----
pin_d          = 3;   // pin hole diameter (mm)

// ---- Derived ----
segments_per_len = plate_len / knuckle_pitch;  // 5 segments along X
first_knuckle_x  = (knuckle_count - 1) * knuckle_pitch / 2;  // centre the knuckles

// ---- Model ----
difference() {
    union() {
        // Base plate, centred in X and Y
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X
        for (i = [-knuckle_count / 2 : knuckle_count / 2 - 1 : knuckle_count / 2]) {
            translate([i * knuckle_pitch, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 1);
        }
    }

    // Pin hole running along X through every knuckle
    translate([-first_knuckle_x - knuckle_pitch / 2, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_pitch * knuckle_count + 2);
}
