```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len    = 40;    // plate length along X (mm)
plate_wid    = 30;    // plate width along Y (mm)
plate_thk    = 2.5;   // plate thickness along Z (mm)

knuckle_d    = 6;     // knuckle cylinder diameter (mm)
knuckle_y    = 15;    // knuckle axis Y position (mm)
knuckle_z    = 3;     // knuckle axis height above bed (mm)
knuckle_h    = 8;     // knuckle height above plate (mm)
knuckle_pcd  = 40;    // pitch circle diameter of the 5 knuckles (mm)
knuckle_count = 5;    // number of knuckles

pin_d        = 3;     // pin hole diameter (mm)

eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// ---------------- Derived ----------------
outer_r = knuckle_pcd / 2 + knuckle_d / 2;   // reach of knuckle centres + half thickness

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles: cylinder of radius (PCD/2 + thickness/2), axis along X
        for (i = [0 : knuckle_count - 1])
            rotate([0, 0, i * 360 / knuckle_count])
                translate([0, 0, plate_thk / 2])
                    cylinder(r = knuckle_pcd / 2 + plate_thk / 2, h = knuckle_h);
    }

    // Pin hole: axis along X, through every knuckle
    translate([0, 0, plate_thk / 2])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_h + 2 * eps);
