        // Base plate, centred in X/Y, sitting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (0-, 2-, 4- indexed)
        for (i = [0 : 2 : 4])
