// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 40;   // plate length along X (mm)
plate_wid   = 25;   // plate width along Y (mm)
plate_thk   = 3;    // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle cylinder diameter (mm)
knuckle_h   = 12.5; // knuckle axis height (y = plate_wid/2, z = knuckle_h)
knuckle_as  = 0.5;  // knuckle half-length along X (mm)

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter (mm)

// ---- Segments ----
n_segments  = 5;    // number of equal segments along plate length
segment_l   = plate_len / n_segments;  // segment length (8 mm)
overlap     = 0.5;  // overlap between adjacent cylinders for a clean union

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    // 1st, 3rd, 5th segments (0-based indices 0, 2, 4)
    for (i = [0 : 4 : n_segments - 1]) {
        x0 = -plate_len/2 + i * segment_l;
        translate([x0 - knuckle_as, plate_wid/2, 0])
            difference() {
                cylinder(d = knuckle_d, h = knuckle_as + overlap);
                translate([0, 0, -overlap])
                    cylinder(d = pin_d, h = knuckle_as + overlap + 1);
            }
    }
}

union() {
    plate();
    knuckles();
}
