knuckle_ids = [1, 3, 5]; // 1st, 3rd, 5th segments get a knuckle
knuckle_n   = len(knuckle_ids); // 3 knuckles

// ---- Pin ----
pin_d = 3;          // pin hole diameter

// ---- Misc ----
eps = 0.5;          // overshoot for clean cuts

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_n - 1]) {
        seg_x = (knuckle_ids[i] - 1) * knuckle_w; // centre of segment
        translate([seg_x, plate_wid/2, 0])
            difference() {
                // cylinder along X
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = plate_len/2 + 2*eps, center = true);
                // pin hole along axis
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_len/2 + 2*eps, center = true);
            }
    }
}

union() {
    plate();
    knuckles();
}
