// Pin hinge leaf
// Flat plate on the bed, centred on the origin in X and Y.
// Round knuckles run along the +Y edge on alternate segments, with a
// 3 mm pin hole through every knuckle along an X-directed axis.

$fn = 96;

// ---- Plate ----
plate_len   = 40;   // plate length along X (mm)
plate_wid   = 20;   // plate width along Y (mm)
plate_thk   = 3;    // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d      = 8;    // knuckle cylinder diameter (mm)
knuckle_count  = 5;    // number of knuckles (1st, 3rd, 5th segments)
knuckle_pitch  = plate_len / (knuckle_count - 1);  // 8 mm segment length
knuckle_r      = knuckle_d / 2;

// ---- Pin ----
pin_d       = 3;    // pin hole diameter (mm)

// ---- Modelling ----
eps         = 0.5;  // overshoot for clean boolean cuts (mm)

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0)
                translate([(i % 2 - 0.5) * knuckle_pitch, plate_wid / 2, 0])
                    rotate([0, 90, 0])
                        cylinder(d = knuckle_d, h = knuckle_pitch + eps, center = true);
        }
    }

    // Pin holes
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0)
            translate([(i % 2 - 0.5) * knuckle_pitch, plate_wid / 2, -eps])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = knuckle_pitch + 2 * eps, center = true);
    }
}
