// Pin hinge leaf
// Flat plate lying on the bed, centred on the origin, with three round knuckles
// along its +Y edge and a pin hole running through them along X.

// ---------------- Parameters ----------------
plate_length   = 40;   // plate length along X (mm)
plate_width    = 20;   // plate width along Y (mm)
plate_thick    = 3;    // plate thickness along Z (mm)

knuckle_count  = 5;    // number of edge segments
knuckle_pitch  = 8;    // segment length (mm)
knuckle_dia    = 8;    // knuckle diameter (mm)
knuckle_axis_y = 10;   // knuckle axis Y position (mm)
knuckle_axis_z = 4;    // knuckle axis height above bed (mm)

pin_dia        = 3;    // pin hole diameter (mm)

overlap        = 0.5;  // extra length on cutters to avoid coplanar faces (mm)
$fn            = 96;   // curve resolution

// ---------------- Derived ----------------
segment0_start = -plate_length/2 + 0.5*knuckle_pitch;  // -8 mm (between 1st/2nd)
segment0_end   = segment0_start + knuckle_pitch;       // 0 mm

// Check: 2nd knuckle centre at y = knuckle_axis_y - knuckle_pitch = 2 mm (on 3rd segment)
// 4th knuckle centre at y = knuckle_axis_y + knuckle_pitch = 18 mm (on 5th segment)

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckle cylinders
        for (i = [0 : knuckle_count - 1]) {
            y = knuckle_axis_y + (i - (knuckle_count - 1)/2) * knuckle_pitch;
            translate([0, y, knuckle_axis_z])
                cylinder(d = knuckle_dia, h = plate_thick + overlap);
        }
    }

    // Pin hole along X through every knuckle
    translate([0, knuckle_axis_y, knuckle_axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_dia, h = plate_length + 2*overlap);
}
