// ---------------- Parameters ----------------
plate_len     = 60;    // plate length along X (mm)
plate_wid     = 25;    // plate width along Y (mm)
plate_thk     = 3;     // plate thickness along Z (mm)

knuckle_d     = 7;     // knuckle cylinder diameter (mm)
knuckle_h     = 10;    // knuckle cylinder height above plate (mm)
knuckle_count = 5;     // number of equal segments along +Y edge
knuckle_pitch = plate_wid / (knuckle_count - 1);  // segment pitch (12.5 mm)

pin_d         = 3;     // pin hole diameter (mm)

eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 96;    // smoothness for curved shapes

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge: 1st, 3rd, and 5th segments
        for (i = [0 : 2 : knuckle_count - 1]) {
            seg_x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
            translate([seg_x - knuckle_d/2,
                       plate_wid/2 - knuckle_d/2,
                       plate_thk])
                cube([knuckle_d, knuckle_d, knuckle_h]);
        }
    }

    // Pin hole running along X at y = 12.5, z = 3.5
    translate([-pin_d/2 - eps,
               knuckle_pitch/2,
               plate_thk + eps])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
