```openscad
// Star-shaped indexing wheel: 5-pointed flat plate with central hole
// Print orientation: flat on bed (z = 0), builds upward in +Z

// ---------- Parameters ----------
outer_r    = 30;    // distance of outer points from centre (mm)
inner_r    = 15;    // distance of inner points from centre (mm)
points     = 5;     // number of points in the star
plate_t    = 3;     // plate thickness (mm)
hole_d     = 8;     // diameter of central through-hole (mm)
overcut    = 0.5;   // extra length of cutters past faces (mm)
$fn        = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // 5-pointed star outline, first outer point on +X axis
    linear_extrude(height = plate_t) {
        polygon(points = points * 2, // 5 outer + 5 inner points
               function = function(t) {
                   t = t % 1; // repeat every 2*PI
                   if (t < 0.5) // outer points
                       return outer_r * [cos(2 * PI * t), sin(2 * PI * t)];
                   else         // inner points
                       return inner_r * [cos(2 * PI * t - PI / points),
                                        sin(2 * PI * t - PI / points)];
               });
    }

    // Central through-hole
    translate([0, 0, -overcut])
        cylinder(d = hole_d, h = plate_t + 2 * overcut);
}
