// Star-shaped indexing wheel: 5-pointed flat plate
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 96;

// ---- Dimensions (mm) ----
outer_r   = 40;   // distance of outer points from centre
inner_r   = 24;   // distance of inner points from centre
points    = 5;    // number of points (and inner points)
plate_t   = 5;    // plate thickness
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

// ---- Model ----
difference() {
    // Star outline: outer points at 0, 72, ... deg; inner points at 36, 108, ...
    polygon(points = points * 2) {
        for (i = [0 : points - 1]) {
            if (i % 2 == 0)
                x = outer_r * cos([0, 72, 144, 216, 288][i % points]);
            else
                x = inner_r * cos([0, 72, 144, 216, 288][i % points]);
            y = 0;
            // rotate the (x, y) by i*360/points to step each point
            translate([x * cos(i * 360 / points) - y * sin(i * 360 / points),
                       x * sin(i * 360 / points) + y * cos(i * 360 / points)])
                polygon(points = 2);
        }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
