        [outer_r * [cos(360 * i / points), sin(360 * i / points)] for i in [0 : points - 1]],
        [inner_r * [cos(360 * (i + 0.5) / points), sin(360 * (i + 0.5) / points))] for i in [0 : points - 1]]
    );

difference() {
    // Plate body
    linear_extrude(height = thickness)
        polygon(points = points * 2, points = star_2d());

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra);
}
