```openscad
// 5-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

$fn = 96;                  // smoothness of curved shapes

// ---- Star dimensions ----
outer_r = 30;              // distance of outer points from centre
inner_r = 18;              // distance of inner points from centre
points  = 5;               // number of points (and inner points)
pitch   = 360 / points;    // angular spacing between points

// ---- Plate dimensions ----
plate_t = 5;               // plate thickness
hole_d  = 6;               // central through-hole diameter

// ---- Cutting overshoot ----
eps = 0.5;                 // extension of cutters past faces

// First outer point lies on the +X axis; inner points are
// offset by half the pitch so the two point sets are interleaved.
start_angle = 0;
inner_start = start_angle + pitch / 2;

module star_2d() {
    // Outline of the star in the XY plane
    union() {
        for (i = [0 : points - 1]) {
            a = start_angle + i * pitch;
            // outer point
            translate([outer_r * cos(a), outer_r * sin(a)])
                circle(d = outer_r);
            // inner point
            translate([inner_r * cos(a + pitch / 2),
                       inner_r * sin(a + pitch / 2)])
                circle(d = inner_r);
        }
    }
}

difference() {
    // Star plate, resting on z = 0
    linear_extrude(height = plate_t)
        star_2d();

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 64);
}
```

