// 5-pointed star wheel
// Print orientation: flat on bed, z = 0 up to plate_t
// Units: mm

$fn = 96;

// ---- Parameters ----
star_points   = 5;    // number of points (and inner crevices)
outer_radius  = 30;   // distance of outer points from centre
inner_radius  = 18;   // distance of inner points from centre
plate_t       = 5;    // plate thickness
hole_d        = 6;    // central through-hole diameter
cut_extra     = 0.5;  // extra length on cutting shapes past faces

// ---- Derived ----
angle_step    = 360 / star_points;   // 72 deg between outer points

// One outer point on +X axis (t = 0), inner points rotated by half a step
// Hull may slightly round the inner corners, but the shape stays within
// outer_radius x outer_radius x plate_t.
module star_2d() {
    hull() {
        for (t = [0 : star_points - 1]) {
            translate([outer_radius * cos(t * angle_step),
                       outer_radius * sin(t * angle_step)])
                circle(d = outer_radius);
            translate([inner_radius * cos(t * angle_step + angle_step / 2),
                       inner_radius * sin(t * angle_step + angle_step / 2)])
                circle(d = inner_radius);
        }
    }
}

difference() {
    linear_extrude(height = plate_t)
        star_2d();

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2 * cut_extra);
}
