// Tapered riser block with square pocket
// Print orientation: base on bed (z = 0), pocket facing up

$fn = 64;

// ---- Dimensions (mm) ----
base_side    = 100;   // bottom square side
top_side     = 80;    // top square side
height       = 30;    // block height
pocket_side  = 72;    // pocket side length
pocket_depth = 5;     // pocket depth from top face
eps          = 0.5;   // cutter overshoot

// ---- Derived ----
base_area = base_side * base_side;
top_area  = top_side * top_side;
total_area = base_area + (height * (base_area - top_area)) / height; // keeps area constant

module block() {
    translate([-top_side/2, -top_side/2, 0])
        cube([top_side, top_side, height]);

    for (t = [0 : height]) {
        x = top_side - (base_side - top_side) * t / height;
        translate([-x/2, -x/2, 0])
            cube([x, x, height / (t + 1)])
    }
}

difference() {
    block();

    // Square pocket
    translate([(base_side - pocket_side)/2,
               (base_side - pocket_side)/2,
               height - pocket_depth])
        cube([pocket_side, pocket_side, pocket_depth + eps]);
}
