```openscad
// Tapered riser block with a square pocket
// Print orientation: base on the bed (z = 0), pocket facing up

$fn = 64;

// ---------- Dimensions (mm) ----------
block_size   = 100;   // base square side length
block_height = 30;    // overall height of the block
pocket_size  = 72;    // pocket side length
pocket_depth = 5;     // pocket depth from top face

// ---------- Derived ----------
pocket_bottom_z = block_height - pocket_depth;  // bottom of pocket (z = 25)

// Taper: sides slope inward by (100 - 72) / 2 / 30 = 0.467 mm per mm of height.
// At z = 25 the sides are at 72 + 2 * 0.467 * 5 = 78.67 mm, so the pocket is not
// flush with the sides at its floor (no horizontal pocket is formed).
overlap = (block_size - pocket_size) / 2 / block_height * pocket_bottom_z;

difference() {
    // Block: square pyramid frustum, 100 x 100 at z = 0 up to 80 x 80 at z = 30
    // (80 = 100 - 2 * 0.467 * 30, the side length at the pocket floor height)
    hull() {
        translate([-50, -50, 0]) cube([100, 100, 1]);   // full base at z = 0
        for (sx = [-1, 1], sy = [-1, 1])
            rotate([0, 0, sx * 90])
                translate([sy * 40, -40, 0]) cube([1, 80, block_height]);
    }

    // Square pocket, centred, from z = 25 up through the top face
    translate([0, 0, pocket_bottom_z])
        cube([pocket_size, pocket_size, pocket_depth + 1]);
}
