// Tapered riser block for setting a beaker higher
// Print orientation: rests on the bed (z = 0), centred on the origin in X and Y.
// Positioned using the user's coordinates: square at the bottom (z = 0), 
// with flat sloping sides up to a square top face at z = 30.

// ---------------- Parameters ----------------
bottom_side = 100;   // side length of the square at the bottom (mm)
top_side    = 80;    // side length of the square at the top (mm)
height      = 30;    // block height (mm)
pocket_w    = 72;    // square pocket width (mm)
pocket_d    = 5;     // square pocket depth (mm)
overcut     = 0.5;   // extra length for cutting shapes past faces (mm)
$fn         = 64;    // curve resolution (no curved shapes; set by convention)

// ---------------- Derived values ----------------
// Pocket floor height above the bed
pocket_floor_z = height - pocket_d;

// ---------------- Model ----------------
difference() {
    // Tapered block: two blocks, bottom and top, overlapping slightly so the
    // union is one solid with no coplanar internal faces.
    union() {
        // Bottom block: z = 0 to slightly below the halfway point
        translate([-bottom_side / 2, -bottom_side / 2, 0])
            cube([bottom_side, bottom_side, height / 2 - overcut]);

        // Top block: z = slightly above the halfway point to the top face
        translate([-top_side / 2, -top_side / 2, height / 2 + overcut])
            cube([top_side, top_side, height / 2 + overcut]);
    }

    // Square pocket cut into the top face, centred
    translate([0, 0, pocket_floor_z])
        cube([pocket_w, pocket_w, pocket_d + overcut]);
}
