module square_frustusm() {
    // hull() of two coaxial squares; sides are flat and slope inward
    hull() {
        translate([-bottom_w/2, -bottom_w/2, bottom_h])
            cube([bottom_w, bottom_w, 1]);   // thin slab at bottom face
        translate([-top_w/2, -top_w/2, top_h - 1])
            cube([top_w, top_w, 1]);         // thin slab at top face
    }
}

// Square pocket cut into the top face
module square_pocket() {
    translate([0, 0, top_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + overlap]);
}

