    translate([-base_side/2, -base_side/2, 0])
        cube(base_side, base_side, height);

    // Tapered sides: from 80 x 80 at z = 0 down to 50 x 50 at z = 30
    translate([-top_side/2, -top_side/2, height])
        cube(top_side, top_side, overlap);

    // Square pocket in the top face, centred
    translate([-pocket_w/2, -pocket_w/2, height - pocket_d])
        cube(pocket_w, pocket_w, pocket_d + overlap);

    // Clear the topmost overlapping corner to avoid a zero-volume region
    translate([-top_side/2 - overlap, -top_side/2 - overlap, height])
        cube(overlap, overlap, overlap);
