module block() {
    // Linearly tapered square prism: width = block_w + (block_t - block_w) * z / block_h
    rotate([90, 0, 0])
        linear_extrude(height = block_h)
            polygon(points = [
                [-block_w / 2, -block_w / 2],
                [ block_w / 2, -block_w / 2],
                [ block_t / 2,  block_w / 2],
                [-block_t / 2,  block_w / 2]
            ]);
}

difference() {
    block();

    if (pocket_d > 0) {
        translate([-pocket_w / 2, -pocket_w / 2, pocket_z0])
            cube([pocket_w, pocket_w, pocket_d + eps]);
    }
}
