```openscad
// Tapered riser block with a square pocket
// Print orientation: flat on bed, bottom face at z = 0

$fn = 64;

// ---- Dimensions (mm) ----
block_bottom = 60;   // bottom square side
block_top    = 40;   // top square side
block_h      = 25;   // block height
pocket_size  = 30;   // square pocket side
pocket_depth = 8;    // pocket depth from top face
eps          = 0.5;  // overshoot for clean cuts

// ---- Derived ----
pocket_floor_z = block_h - pocket_depth;
pocket_floor_y = -pocket_size / 2;
pocket_floor_x = -pocket_size / 2;

// Taper rate per mm height (difference in half-width per mm)
// Using full side difference to avoid half-mm rounding errors
taper = (block_bottom - block_top) / 2 / block_h;

module bottom_face() {
    translate([-block_bottom / 2, -block_bottom / 2, 0])
        square([block_bottom, block_bottom]);
}

module top_face() {
    translate([-block_top / 2, -block_top / 2, block_h])
        square([block_top, block_top]);
}

module sides() {
    // hull builds a convex hull of the two faces plus the corner
    // tracks at height z = block_h - 0.01, so the hull ends at exactly
    // z = block_h with a face parallel to the top face
    hull() {
        translate([-block_bottom / 2 - taper * 0.01,
                   -block_bottom / 2 - taper * 0.01,
                   0])
            cube([block_bottom + 2 * taper * 0.01,
                  block_bottom + 2 * taper * 0.01,
                  block_h - 0.01]);
        translate([-block_top / 2 - taper * 0.01,
                   -block_top / 2 - taper * 0.01,
                   block_h - 0.01])
            cube([block_top + 2 * taper * 0.01,
                  block_top + 2 * taper * 0.01,
                  0.01]);
    }
}

module pocket() {
    translate([pocket_floor_x, pocket_floor_y, pocket_floor_z])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

difference() {
    union() {
        bottom_face();
        top_face();
        sides();
    }
    pocket();
}
