```openscad
// Tapered riser block with square pocket
// Print orientation: bottom face on bed (z = 0), centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
block_h     = 20;    // block height (z = 0 to 20)
bottom_w    = 60;    // bottom square side
top_w       = 30;    // top square side
pocket_w    = 20;    // pocket side length
pocket_d    = 5;     // pocket depth from top face

eps         = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
pocket_z0   = block_h - pocket_d;   // bottom of pocket (z = 15)

module bottom_face() {
    difference() {
        translate([-bottom_w/2, -bottom_w/2, 0])
            cube([bottom_w, bottom_w, 1]);
        // small matching pocket at bottom, same overshoot, for exact volume
        translate([-pocket_w/2, -pocket_w/2, -eps])
            cube([pocket_w, pocket_w, 1 + 2*eps]);
    }
}

module top_face() {
    difference() {
        translate([-top_w/2, -top_w/2, block_h])
            cube([top_w, top_w, 1]);
        // pocket cut through the top face
        translate([-pocket_w/2, -pocket_w/2, pocket_z0])
            cube([pocket_w, pocket_w, pocket_d + eps]);
    }
}

// ---- Body: two hull vertices plus the pocket cavity ----
difference() {
    hull([
        [bottom_w/2, bottom_w/2, 0],
        [-bottom_w/2, -bottom_w/2, 0],
        [top_w/2, top_w/2, block_h],
        [-top_w/2, -top_w/2, block_h]
    ]) {
        // straight-walled pocket (slopes differ from the flanks)
        translate([-pocket_w/2, -pocket_w/2, -eps])
            cube([pocket_w, pocket_w, block_h + 2*eps]);
    }
}

union() {
    bottom_face();
    top_face();
}
