        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 1]);

        // Top face, centred on the origin, at z = height
        // The hull curve ends at z = hull_height, so this face is buried inside,
        // which avoids any coplanar faces with the curve
        translate([-top_size / 2, -top_size / 2, height - overlap])
            cube([top_size, top_size, overlap]);
    }

