difference() {
    // Tapered block: hull between the bottom face and the top face at z = 25.5
    hull() {
        translate([-half_base, -half_base, 0])
            cube([base_size, base_size, height]);
        translate([-half_top_ext, -half_top_ext, height + overcut])
            cube([width_at_25_5, width_at_25_5, overcut]);
    }

    // Square pocket: open at the top, floor at z = 20, centred on the origin
    translate([0, 0, pocket_floor_z])
        cube([pocket_size, pocket_size, pocket_depth + overcut]);
