// Pull handle for a cabinet door
// Print orientation: posts stand on the bed (z = 0), bar on top.

$fn = 64;

// ---- Posts ----
post_d     = 12;   // post diameter
post_h     = 20;   // post height (z = 0 to 20)
post_x     = 48;   // post centre offset from origin (+/-)
post_y     = 0;    // post centre Y position
screw_d    = 4.5;  // screw hole diameter
screw_len  = 10;   // screw hole depth from bottom face

// ---- Bar ----
bar_len    = 108;  // bar length along X
bar_w      = 12;   // bar width along Y
bar_t      = 6;    // bar thickness (z = 20 to 26)
bar_x      = 0;    // bar centre X position
bar_y      = 0;    // bar centre Y position

// ---- Misc ----
eps        = 0.5;  // overlap / cutter overshoot

module post() {
    difference() {
        cylinder(d = post_d, h = post_h);
        translate([0, 0, -eps])
            cylinder(d = screw_d, h = post_h + screw_len + eps);
    }
}

module bar() {
    translate([bar_x - bar_len / 2, bar_y - bar_w / 2,
               post_h - eps])
        cube([bar_len, bar_w, bar_t + eps]);
}

union() {
    for (sx = [-1, 1])
        translate([sx * post_x, post_y, 0])
            post();
    bar();
}
```

