    translate([-half_specimen, -thickness / 2, 0])
        cube([specimen_len, thickness, 3]);

    // Cutout (below mid thickness so no coplanar faces)
    translate([-half_specimen, -y(half_specimen) / 2 - eps, eps])
        cube([specimen_len, y(half_specimen) + 2 * eps, thickness - eps]);
