// Print orientation: flat on bed, builds up in +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // each transition (gauge -> grip) length (X)
eps            = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
n_trans      = 2;       // number of transitions
tall_half    = grip_width/2 + transition_len*0.5 + eps;           // half-width at far end of a transition
fit_half     = min(gauge_width/2, grip_width/2 - eps);            // half-width deep into gauge/grip

// width profile seen from above, walking along X
function w(x) =
    if (x < 0)
        if (x < -total_length/2) grip_width
        else if (abs(x) < transition_len)   // into the left transition
            fit_half + (gauge_width/2 - fit_half) * (abs(x) + eps) / transition_len
        else if (abs(x) < transition_len + gauge_length) gauge_width
        else if (abs(x) < total_length/2)
            gauge_width/2 + (grip_width/2 - gauge_width/2) * (abs(x) - transition_len - gauge_length + eps) / transition_len
        else grip_width
    else
        if (x < transition_len + gauge_length) gauge_width
        else if (x < total_length/2)
            gauge_width/2 + (grip_width/2 - gauge_width/2) * (x - transition_len - gauge_length + eps) / transition_len
        else if (x < total_length - transition_len) grip_width
        else fit_half + (gauge_width/2 - fit_half) * (total_length/2 - x + eps) / transition_len;

module grip_len_mod(v) = min(v, grip_length); // keep end grips at the specified length

difference() {
    hull() {
        for (sx = [-1, 1])
            translate([sx * (total_length/2 - transition_len), 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(thickness)
                        polygon([for (y = [0 : 0.01 : w(sx * (total_length/2 - transition_len)))
                                 [sx * (total_length/2 - transition_len), y]]]);
    }
    // remove the middle, so each grip runs exactly grip_len_mod from its edge inward
    for (sx = [-1, 1])
        translate([sx * (total_length/2 - transition_len - grip_len_mod(total_length - 2*transition_len - gauge_length)),
                   -w(sx * (total_length/2 - transition_len - grip_len_mod(total_length - 2*transition_len - gauge_length))), 0])
            cube([grip_len_mod(total_length - 2*transition_len - gauge_length) + eps,
                  w(sx * (total_length/2 - transition_len - grip_len_mod(total_length - 2*transition_len - gauge_length))),
                  thickness + 2*eps]);
}
