x0 = -total_length / 2;              // left end of specimen
w  = [grip_width, gauge_width];       // widths of gauge and grip
l  = [gauge_length, grip_length];     // lengths of gauge and grip

module flat_plate(len, wid, thk)     // rectangle aligned to origin
    translate([-len / 2, -wid / 2, 0]) cube([len, wid, thk]);

module grip()                        // one grip section, uses x0 each time
    flat_plate(grip_length, grip_width, thickness);

module transition(w1, w2)            // linear width change w1 -> w2
    hw = (w1 + w2) / 2;
    r  = (w2 - w1) / 2 / transition_len;   // width change per mm
    translate([-transition_len / 2, -hw, 0])
        linear_extrude(thickness)
            polygon([[-transition_len / 2, -hw], [transition_len / 2, -hw],
                     [transition_len / 2, hw], [-transition_len / 2, hw]]);

difference() {
    union() {
        grip();                                                   // left grip
        for (i = [0 : 1])
            translate([-x0 + l[i] - transition_len, 0, 0])
                transition(w[i], w[i + 1]);                       // transitions
        translate([-x0 + gauge_length / 2, 0, 0])
            flat_plate(gauge_length, gauge_width, thickness);   // gauge
        for (i = [0 : 1])
            translate([x0 - l[i] + transition_len, 0, 0])
                transition(w[i + 1], w[i]);                       // transitions
        grip();                                                   // right grip
    }
    // remove a thin outer skin so the cut passes clearly through faces
    translate([-total_length / 2 - cut_extra, -thickness / 2 - cut_extra, 0])
        cube([total_length + 2 * cut_extra, thickness + 2 * cut_extra, thickness]);
