```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

// ---------- Dimensions ----------
specimen_thickness = 4;     // Y (specimen is 4 mm wide)
specimen_length    = 130;   // X total length
gauge_width        = 10;    // X width of gauge section
gauge_length       = 40;    // Y length of gauge section
grip_width         = 15;    // X width of grip sections
grip_length        = 30;    // Y length of grip sections
transition_length  = 15;    // Y length of each transition zone

// ---------- Derived ----------
n_grips   = 2;
n_trans   = 2;
n_section = n_grips + n_trans + 1;  // 5 sections along X
section_overlap = 0.01;             // small overlap so adjacent rects fuse

// ---------- Model ----------
union() {
    for (i = [0 : n_section - 1]) {
        if (i < n_grips) {
            // grip sections at each end, centred on +/- specimen_length/2
            x_c = (i < n_grips / 2) ? -specimen_length / 2 : specimen_length / 2;
            translate([x_c - grip_width / 2, -grip_length / 2, 0])
                cube([grip_width, grip_length, specimen_thickness]);
        }
        else if (i == n_grips) {
            // left transition: grip width -> gauge width
            w0 = grip_width;  w1 = gauge_width;
            x_c = -specimen_length / 2 + grip_length / 2;
            translate([x_c - w0 / 2, -transition_length / 2, 0])
                cube([w0 + w1, transition_length, specimen_thickness]);
        }
        else if (i == n_grips + 1) {
            // gauge section
            translate([-gauge_width / 2, -gauge_length / 2, 0])
                cube([gauge_width, gauge_length, specimen_thickness]);
        }
        else if (i == n_grips + 2) {
            // right transition: gauge width -> grip width
            w0 = gauge_width;  w1 = grip_width;
            x_c = specimen_length / 2 - grip_length / 2;
            translate([x_c - w1 / 2, -transition_length / 2, 0])
                cube([transition_length, w0 + w1, specimen_thickness]);
        }
    }
}
