// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on the bed, symmetric about the origin

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
eps            = 0.5;   // overshoot for clean boolean cuts
plate_height   = 10;    // internal height for slice logic (z = 0..thickness)

// X positions of internal features (gauge centre, grip centres)
feature_x = [
    -(total_length / 2 + grip_length / 2),   // left grip centre
    -(total_length / 2 - grip_length / 2),   // left grip outer edge
    -half_gauge,                             // gauge centre
      half_gauge,                             // gauge outer edge
      total_length / 2 - grip_length / 2,    // right grip outer edge
      total_length / 2 + grip_length / 2     // right grip centre
];

// ---- Model ----
module dogbone() {
    difference() {
        // Main plate
        translate([-total_length / 2, -thickness / 2, 0])
            cube([total_length, thickness, plate_height]);

        // Cut out grip blocks, transitions, and gauge section
        for (i = [0 : 5]) {
            translate([feature_x[i], 0, -eps])
                cube([1, grip_width, plate_height + 2 * eps]);
        }

        // Gauge section (extends into transitions; width drops to gauge_width at x = 0)
        translate([-half_gauge - eps, -(gauge_width + 2) / 2, 0])
            cube([gauge_length + 2 * eps, gauge_width + 2, plate_height + eps]);
    }
}

dogbone();
