// Dog-bone tensile specimen
// Units: mm. Print orientation: flat on bed, z = 0 upward.

$fn = 64;

// ---------- Dimensions ----------
total_len    = 120;   // overall length (X)
thickness    = 3;     // specimen thickness (Z)

gauge_w      = 6;     // gauge section width (Y)
gauge_len    = 30;    // gauge section length (X)

grip_w       = 15;    // grip section width (Y)
grip_len     = 30;    // grip section length (X)

trans_len    = 15;    // transition section length (X)

eps          = 0.5;   // overshoot for clean cuts

// ---------- Derived ----------
half_grip    = grip_w / 2;
half_gauge   = gauge_w / 2;
grip_reach   = grip_len + trans_len;  // outer edge of transition

// ---------- Modules ----------
module gauge_section() {
    translate([-gauge_len / 2, -half_gauge, 0])
        cube([gauge_len, gauge_w, thickness]);
}

module grip_section(side) {
    // side = -1 (left) or +1 (right); x0 is the far end of the grip
    x0 = (side < 0) ? -grip_len : grip_len;
    translate([side * x0, -half_grip, 0])
        cube([grip_len, grip_w, thickness]);
}

// Linear width change between two end sections
module transition_section(side) {
    // side = -1 (left): from grip_w down to gauge_w
    // side = +1 (right): from gauge_w up to grip_w
    w0 = (side < 0) ? grip_w : gauge_w;   // left end width
    w1 = (side > 0) ? grip_w : gauge_w;   // right end width
    translate([side * (trans_len / 2), -w0 / 2, 0])
        linear_extrude(thickness)
            polygon([
                [0, 0],
                [trans_len, 0],
                [0, (w1 - w0) / trans_len * trans_len + w0]
            ]);
}

// ---------- Assembly ----------
union() {
    for (s = [-1, 1]) grip_section(s);
    gauge_section();
    for (s = [-1, 1]) transition_section(s);
}
