// overlap between adjacent blocks so hull merges cleanly
ov = trans_len / 2;

// ---------- Model ----------
hull() {
    // left grip
    translate([-total_len/2, -grip_w/2, 0])
        cube([grip_len, grip_w, thickness]);
    // right grip
    translate([total_len/2 - grip_len, -grip_w/2, 0])
        cube([grip_len, grip_w, thickness]);
    // gauge
    translate([-gauge_len/2, -gauge_w/2, 0])
        cube([gauge_len, gauge_w, thickness]);
    // left transition (grip -> gauge)
    translate([left_grip_x0 - ov, -grip_w/2, 0])
        cube([ov + trans_len/2, grip_w, thickness]);
    // right transition (gauge -> grip)
    translate([gauge_len/2 + ov, -grip_w/2, 0])
        cube([ov + trans_len/2, grip_w, thickness]);
