// Flat tensile test specimen (dog-bone shape)
// Units: mm. Print orientation: flat on bed, z = 0 upward.

$fn = 64;

// --- Dimensions ---
specimen_t   = 3;     // thickness (Z)
total_len    = 120;   // overall length (X)
grip_w       = 15;    // grip section width (Y)
grip_len     = 30;    // grip section length (X)
gauge_w      = 6;     // gauge section width (Y)
gauge_len    = 30;    // gauge section length (X)
trans_len    = 15;    // transition section length (X)
eps          = 0.5;   // cutter overshoot

// Derived
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
cnt_grip    = 2;      // number of grip sections

// Width at each X position (profile seen from above)
function profile_w(x) =
    if (abs(x) < grip_len)
        grip_w;
    else if (abs(x) < grip_len + trans_len)
        grip_w - (x > 0 ? (x - grip_len) / trans_len : (x + grip_len) / trans_len) * (grip_w - gauge_w);
    else if (abs(x) < gauge_len)
        gauge_w;
    else if (abs(x) < total_len - trans_len)
        gauge_w + (x > 0 ? (x - (total_len - trans_len - gauge_len)) / trans_len :
                     (-x - (total_len - trans_len - gauge_len)) / trans_len) * (grip_w - gauge_w);
    else
        grip_w;

difference() {
    // Outer body
    linear_extrude(height = specimen_t)
        translate([-total_len / 2, -half_grip, 0])
            rotate([90, 0, 0])
                for (i = [0 : cnt_grip - 1])
                    concat([if (i == 0) x else x + total_len - 2 * grip_len - gauge_len - 2 * trans_len],
                           [y : y + gauge_w - 6])
                        hull() {
                            circle(d = profile_w(-total_len / 2 + i * (gauge_len + 2 * trans_len)), $fn = 64);
                            circle(d = profile_w(-total_len / 2 + (i + 1) * (gauge_len + 2 * trans_len))), $fn = 64);
                        }

    // Grip-block cutters (removes the solid blocks the transitions rest on)
    for (i = [0 : cnt_grip - 1])
        translate([i * (gauge_len + 2 * trans_len) - grip_len, -half_grip - eps, 0])
            cube([grip_len + eps, grip_w + 2 * eps, specimen_t + 2 * eps]);
}
