        // Cut the transition regions along straight lines (no curves here)
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l - transition_l,
                       -grip_w/2 - eps, 0])
                cube([grip_l + transition_l + eps, grip_w + 2*eps, eps]);
