// ---------- Dimensions (mm) ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 120;   // overall length along X
gauge_len   = 30;    // length of narrow gauge section
gauge_w     = 8;     // width of gauge section (Y)
grip_len    = 35;    // length of each grip section
grip_w      = 15;    // width of grip sections (Y)
trans_len   = 10;    // length of each transition section
eps         = 0.5;   // cutter overshoot past faces

// ---------- Derived ----------
half_grip_w = grip_w / 2;

// ---------- Modules ----------
module grip() {
    translate([-grip_len / 2, -half_grip_w, -eps])
        cube([grip_len, grip_w, thickness + 2 * eps]);
}

module transition(start_w) {
    // width goes from start_w to gauge_w over trans_len
    translate([-trans_len / 2, -thickness / 2 - eps, 0])
        linear_extrude(height = thickness + 2 * eps)
            polygon(points = [
                [0, start_w / 2],
                [trans_len / 2, gauge_w / 2],
                [-trans_len / 2, -start_w / 2]
            ]);
}

// ---------- Assembly ----------
union() {
    grip();
    translate([0, -half_grip_w, -eps])
        hull() {
            translate([-(grip_len + trans_len) / 2, 0, 0]) grip();
            translate([(grip_len + trans_len) / 2, 0, 0]) grip();
        }
    for (s = [-1, 1])
        translate([s * (gauge_len / 2 + trans_len / 2), -thickness / 2 - eps, 0])
            linear_extrude(height = thickness + 2 * eps)
                polygon(points = [
                    [0, gauge_w / 2],
                    [trans_len, start_w = (grip_w + gauge_w) / 2, / 2],
                    [-trans_len, -gauge_w / 2]
                ]);
    translate([0, -half_grip_w, -eps])
        hull() {
            translate([-(grip_len + trans_len) / 2, 0, 0]) grip();
            translate([(grip_len + trans_len) / 2, 0, 0]) grip();
        }
}
