gauge_x0    = trans_x0 + trans_len;               // gauge start X

// Width envelope: grip (15) -> transition (8..15) -> gauge (8) -> transition (15..8) -> grip (15)
function width(x) =
    if (x < trans_x0)
        grip_w
    else if (x < gauge_x0)
        8 + (15 - 8) * (x - trans_x0) / trans_len
    else if (x < total_len / 2 - trans_len)
        15
    else if (x < total_len / 2)
        8 + (15 - 8) * (total_len / 2 - x) / trans_len
    else
        width(total_len - x);

difference() {
    // Main plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, 100]);

    // Strichenzug: along the X axis, from x = -55 to x = 55 (covers both grip regions and the gauge)
    // cut 1.5 mm above the top face so no faces are coplanar
    translate([-55, -10, thickness - 1.5])
        rotate([90, 0, 0])
            linear_extrude(height = 2 * grip_w + gauge_w + 2 * trans_len + 3)
                polygon(points = [
