                    [total_len / 2 - grip_len, -15], [-total_len / 2 + grip_len, -15],
                    [-total_len / 2 + grip_len, 15], [-gauge_len + trans_len, 8],
                    [-gauge_len + trans_len, -8], [-trans_len, 15], [-trans_len, -15]
