// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 120;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
left_grip_start   = grip_len;
right_grip_start  = total_len - grip_len;
transition_start  = left_grip_start - trans_len;
transition_end    = right_grip_start - trans_len;

// ---------- Model ----------
module profile() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * left_grip_start, -grip_w / 2, 0])
            cube([grip_len, grip_w, thickness]);

    // Gauge section
    translate([-gauge_len / 2, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, thickness]);

    // Transitions: width changes linearly from grip_w to gauge_w
    for (s = [-1, 1]) {
        x0 = s * transition_start;
        x1 = s * transition_end;
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [x0, -grip_w / 2],
                    [x1, -grip_w / 2],
                    [x1, gauge_w / 2],
                    [x0, gauge_w / 2]
                ]);
    }
}

difference() {
    linear_extrude(height = thickness)
        profile();

    // Small cut to remove any coplanar faces at z = 0
    translate([-total_len / 2 - eps, -eps, -eps])
        cube([total_len + 2 * eps, 2 * eps, thickness + 2 * eps]);
}
