module transition() {
    // width profile along X: grip_width -> gauge_width -> grip_width
    // (z = 0 to thickness, y = -gauge_width/2 to gauge_width/2)
    translate([0, -gauge_width / 2, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                [0, grip_width / 2],
                [transition_length, grip_width / 2],
                [transition_length + gauge_length / 2, gauge_width / 2],
                [transition_length + gauge_length / 2, -gauge_width / 2],
                [transition_length, -gauge_width / 2],
                [0, -gauge_width / 2]
            ]);
}

module gauge() {
    translate([0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
}

difference() {
    union() {
        for (s = [-1, 1])
            translate([s * midpoint_x, 0, 0])
                grip();
        for (s = [-1, 1])
            translate([s * (midpoint_x + grip_length + transition_length), 0, 0])
                grip();
        for (s = [-1, 1])
            translate([s * (midpoint_x + grip_length + transition_length + gauge_length / 2), 0, 0])
                gauge();
        for (s = [-1, 1])
            translate([s * (midpoint_x + grip_length / 2), 0, 0])
                transition();
    }
}
