        for (s = [-1, 1])
            translate([s * (total_len / 2 - grip_len / 2), -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);

        // Gauge section in the middle
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Transition sections between grip and gauge
        for (s = [-1, 1])
            translate([s * (gauge_len / 2 + trans_len / 2),
                       (s * (gauge_w - grip_w) / 2) + grip_w / 2,
                       0])
                cube([trans_len, grip_w - s * (gauge_w - grip_w) / 2,
                      thickness]);
    }
}

