        grip(grip_len, grip_w);      // left grip
        for (s = [-1, 1])
            translate([s * (gauge_len/2 + trans_len), 0, 0])
                transition(trans_len, grip_w, s * gauge_w); // transitions
        translate([-gauge_len/2, 0, 0])
            // gauge: length along X, width along Y
            linear_extrude(thickness)
                polygon([[0, gauge_w], [gauge_len, gauge_w], [gauge_len, 0], [0, 0]]);
