    // extend the outer grip blocks into the transitions to avoid coplanar faces
    for (s = [-1, 1])
        translate([s * (gauge_len/2 + trans_len), -grip_w/2, 0])
            cube([trans_len + 1, grip_w, thickness + 2]);
