// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

$fn = 64;

// ---- Dimensions (mm) ----
total_len    = 110;  // overall length along X
thickness    = 3;    // specimen thickness (Z)
gauge_len    = 40;   // gauge section length (X)
gauge_w      = 6;    // gauge section width (Y)
grip_len     = 25;   // grip section length (X)
grip_w       = 19;   // grip section width (Y)
trans_len    = 10;   // transition section length (X)
cut_ext      = 0.5;  // cutter overshoot past faces

// ---- Derived ----
half_grip = grip_len / 2;
half_gauge = gauge_len / 2;

module grip() {
    translate([-half_grip, -grip_w / 2, 0])
        cube([grip_len, grip_w, thickness]);
}

module transition(len, w1, w2) {
    // rotate([90,0,0]) maps 2D x -> Y, 2D y -> Z; hull cross-section lies in YZ
    rotate([90, 0, 0])
        hull() {
            translate([-len / 2, 0, w1])
                square([len, w1]);
            translate([len / 2, 0, w2])
                square([len, w2]);
        }
}

difference() {
    union() {
        grip();
        translate([half_grip - trans_len, 0, 0])
            transition(trans_len, gauge_w, grip_w);
        translate([-half_grip + trans_len, 0, 0])
            transition(trans_len, gauge_w, grip_w);
        translate([-half_gauge, 0, 0])
            cube([gauge_len, gauge_w, thickness]);
        translate([half_gauge, 0, 0])
            cube([gauge_len, gauge_w, thickness]);
        translate([half_grip, 0, 0])
            grip();
    }
    // remove the core volume to leave a solid outline
    translate([-total_len / 2, -thickness - cut_ext, 0])
        cube([total_len, thickness + 2 * cut_ext, 1]);
}
