// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward. Symmetric about origin.

// ---------------- Parameters ----------------
specimen_t   = 3;     // plate thickness (Z) mm
gauge_w      = 6;     // gauge section width (Y) mm
gauge_len    = 40;    // gauge section length (X) mm
grip_w       = 19;    // grip section width (Y) mm
grip_len     = 25;    // grip section length (X) mm
transition_l = 10;    // transition section length (X) mm
cut_extra    = 0.5;   // extra length on cutting shapes past faces (mm)

$fn = 64;

// ---------------- Derived ----------------
grip_x0      = -(grip_len + transition_l);   // left grip start X
grip_x1      = grip_len + transition_l;      // right grip end X
pitch        = grip_x1 - grip_x0;            // centre-to-centre grip spacing (80)
total_len    = pitch + gauge_len;            // 110 mm overall length

// ---------------- Model ----------------
module dog_bone_plate() {
    difference() {
        // Outer plate
        translate([-total_len / 2, -grip_w / 2, 0])
            cube([total_len, grip_w, specimen_t]);

        // Central gauge section (narrower, 40 mm long)
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, specimen_t]);

        // Two grip sections at the ends, 19 mm wide.
        // Width grows linearly over 10 mm from 6 mm (gauge end) to 19 mm (grip end).
        for (s = [-1, 1]) {
            translate([s > 0 ? transition_l - cut_extra : -(transition_l - cut_extra),
                       -grip_w / 2, 0])
                linear_extrude(height = specimen_t)
                    polygon(points = [
                        [0, -grip_w / 2],
                        [transition_l, -grip_w / 2],
                        [transition_l, grip_w / 2],
                        [0, grip_w / 2]
                    ]);
        }
    }
}

dog_bone_plate();
