$fn = 64;

// ---------------- Model ----------------
module flat_dog_bone() {
    // Outer plate: grip - transition - gauge - transition - grip
    plate_length = 2 * grip_length + gauge_length + 2 * transition_length;

    hull() {
        // End grip blocks
        translate([-plate_length / 2 + grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);
        translate([ plate_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Centre gauge block
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);
    }

    // Grooves that carve the linear transitions between the hull blocks
    for (s = [-1, 1]) {
        x0 = (s > 0) ? plate_length / 2 - grip_length : -plate_length / 2 + grip_length;
        // groove spans from the outer edge of the grip into the transition
        translate([x0 - eps, 0, 0])
            cube([transition_length + eps,
                  gauge_width + transition_delta_y * eps / transition_length,
                  specimen_thickness]);
    }
}

