grip_x0 = -total_len/2 + grip_len;        // grip start X (left)
gauge_x0 = grip_x0 + grip_len;            // gauge start X
trans_x0 = gauge_x0 + gauge_len - trans_len; // transition start X

module profile() {
    // Left grip
    translate([grip_x0, -grip_w/2, 0])
        cube([grip_len, grip_w, thickness + 2*eps]);
    // Left transition: width changes from grip_w down to gauge_w
    translate([trans_x0, -grip_w/2, 0])
        cube([trans_len, grip_w, thickness + 2*eps]);
    // Gauge section
    translate([gauge_x0, -gauge_w/2, 0])
        cube([gauge_len, gauge_w, thickness + 2*eps]);
    // Right transition: width changes from gauge_w up to grip_w
    translate([-trans_x0 - trans_len, -grip_w/2, 0])
        cube([trans_len, grip_w, thickness + 2*eps]);
    // Right grip (mirrored about origin in X)
    rotate([0, 0, 180])
        translate([grip_x0, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness + 2*eps]);
}

module dogbone() {
    hull() {
        profile();
        // Opposite faces so hull is solid through the length
        translate([0, 0, thickness])
            mirror([0, 0, -1])
                profile();
    }
}

