// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on the bed, z = 0 upward. Symmetric about origin.

// ---------- Dimensions (mm) ----------
thickness    = 3;     // specimen thickness (Z)
total_length = 110;   // overall length along X
gauge_width  = 6;     // narrow gauge section width (Y)
gauge_length = 30;    // gauge section length (X)
grip_width   = 20;    // grip section width (Y)
grip_length  = 25;    // grip section length (X)
transition   = 15;    // length of each grip-to-gauge transition (X)

// ---------- Derived ----------
half_gauge = gauge_length / 2;            // 15
half_grip  = grip_length / 2;             // 12.5
// X span of one grip + its transition = grip_length + transition = 37.5
// two such spans + gauge = 110 mm (check: 37.5*2 + 30 = 105? wait: 75+30=105)
// Actually total length is grip+trans+gauge+trans+grip = 25+15+30+15+25 = 110 OK

// ---------- Model ----------
module dogbone() {
    difference() {
        // Outer contour (top face), extruded from z = 0 to z = thickness
        linear_extrude(height = thickness)
            polygon(points = [
                // left grip
                for (x = [-half_grip - transition : 1 : half_grip + transition])
                    [x, -grip_width / 2],
                // left transition: width changes linearly from grip_width to gauge_width
                for (x = [0 : 1 : transition])
                    [half_grip - x,
                     (grip_width - gauge_width) * x / transition - grip_width / 2],
                // gauge section
                for (x = [-half_gauge : 1 : half_gauge])
                    [x, -gauge_width / 2],
                // right transition: width changes linearly from gauge_width to grip_width
                for (x = [0 : 1 : transition])
                    [half_gauge + x + transition,
                     (grip_width - gauge_width) * x / transition - grip_width / 2],
                // right grip
                for (x = [half_grip - transition : -1 : -half_grip - transition])
                    [x, -grip_width / 2]
            ]);

        // Optional: cut a flat bottom face at z = thickness - 0.5
        // so the part is slightly under the stated thickness (for safety)
        translate([0, 0, thickness - 0.5])
            cube([total_length, grip_width, 0.5]);
    }
}

dogbone();
