// Flat dog-bone tensile specimen, printed lying flat on the bed
// Units: mm

$fn = 64;

// ---- Dimensions ----
total_len   = 110;  // overall length (X)
thickness   = 3;    // thickness (Z)
gauge_len   = 30;   // gauge section length (X)
gauge_w     = 6;    // gauge section width (Y)
grip_len    = 25;   // grip section length (X)
grip_w      = 20;   // grip section width (Y)
trans_len   = 15;   // transition section length (X)
eps         = 0.5;  // cutter overshoot past faces (Z)

// ---- Derived ----
x0 = -total_len / 2;  // left end of left grip
w0 = grip_w;          // grip width
w1 = gauge_w;         // gauge width
l1 = trans_len;       // transition length
l2 = gauge_len;       // gauge length
l3 = trans_len;       // right transition length
l4 = grip_len;        // right grip length
w2 = grip_w;          // right grip width

module profile() {
    // Upper surface outline (y from -w/2 to +w/2), closed counter-clockwise
    concat(
        [x0 - eps, -w0 / 2], [x0 - eps, w0 / 2],
        // left grip
        for (i = [0 : grip_len / 10 : l4])
            [x0 + i - eps, -w0 / 2], [x0 + i - eps, w0 / 2],
        // right grip
        for (i = [l4 - grip_len / 10 : -grip_len / 10 : -eps])
            [x0 + l4 + i - eps, -w0 / 2], [x0 + l4 + i - eps, w0 / 2],
        // return along upper faces (clipper needs something there)
        for (s = [l4 - grip_len / 10 : -grip_len / 10 : -eps])
            [x0 + l4 + s - eps, w0 / 2],
        for (i = [l3 - grip_len / 10 : -grip_len / 10 : -eps])
            [x0 + l3 + i - eps, w2 / 2], [x0 + l3 + i - eps, -w2 / 2],
        // right transition
        for (t = [0 : trans_len / 20 : l3])
            [x0 + l3 + t - eps, -w2 / 2], [x0 + l3 + t - eps, w2 / 2],
        // gauge
        for (t = [l3 - gauge_len / 20 : -gauge_len / 20 : -eps])
            [x0 + t - eps, -w1 / 2], [x0 + t - eps, w1 / 2],
        // left transition
        for (t = [gauge_len / 20 : -gauge_len / 20 : -eps])
            [x0 + l1 + t - eps, -w1 / 2], [x0 + l1 + t - eps, w1 / 2],
        // back to start
        [x0 - eps, -w0 / 2]
    );
}

module tensile_specimen() {
    // Extrude profile; rotate so profile lies in XY and thickness is +Z
    translate([0, 0, -eps])
        rotate([90, 0, 0])
            linear_extrude(height = thickness + 2 * eps)
                profile();
}

tensile_specimen();
