// Flat dog-bone tensile specimen
// Units: mm. Print orientation: flat on bed, z = 0 upward.

// ---------- Parameters ----------
specimen_thickness = 3;     // overall Z thickness
total_length       = 110;   // overall length along X

// Grip sections (at each end)
grip_width         = 20;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)

// Gauge section (in the middle)
gauge_width        = 6;     // gauge section width (Y)
gauge_length       = 30;    // gauge section length (X)

// Transition regions (between grip and gauge)
transition_length  = 15;    // transition length along X
transition_start_y = (grip_width + gauge_width) / 2;  // where the flank meets at 45 deg

// Cutting overlap
eps                = 0.5;   // extension past faces for difference cuts

// ---------- Derived ----------
left_grip_x0 = -total_length / 2 + grip_length;
right_grip_x0 = total_length / 2 - grip_length;

// ---------- Model ----------
module flat_dogbone() {
    union() {
        // Grip blocks
        for (s = [-1, 1])
            translate([s * left_grip_x0, -grip_width / 2, 0])
                cube([grip_length, grip_width, specimen_thickness]);

        // Gauge block
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // 45-degree transition flanks
        for (s = [-1, 1])
            for (t = [-1, 1])
                translate([s * left_grip_x0 + grip_length - transition_start_y,
                           t * (transition_start_y - gauge_width / 2),
                           0])
                    cube([transition_length,
                           transition_start_y - gauge_width / 2,
                           specimen_thickness]);
    }

    // Cut the middle third of each grip to keep only the outer third (true grip)
    for (s = [-1, 1]) {
        translate([s * left_grip_x0, -grip_width / 2 - eps, 0])
            cube([grip_length / 3 + eps,
                  grip_width + 2 * eps,
                  specimen_thickness + 2 * eps]);
    }
}

