// ---------- Dimensions ----------
specimen_thickness = 3;     // plate thickness (Z)
gauge_width        = 6;     // narrow section width (Y)
gauge_length       = 30;    // narrow section length (X)
grip_width         = 20;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)
transition_length  = 15;    // length of each grip->gauge transition (X)

// ---------- Derived ----------
total_length   = grip_length + transition_length + gauge_length + transition_length + grip_length;
gauge_start_x  = -transition_length - gauge_length / 2;   // outer corner of gauge
fillet_radius  = 3;                                        // blended corner radius

// ---------- Model ----------
module flat_dogbone() {
    hull() {
        // Grip sections
        for (sx = [-1, 1])
            translate([sx * (transition_length + gauge_length / 2), 0, 0])
                cube([grip_length, grip_width, specimen_thickness]);

        // Gauge section
        translate([-gauge_length / 2, 0, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Transition spines (outer edge of grip to outer edge of gauge)
        for (sx = [-1, 1]) {
            a = [0, specimen_thickness];                       // grip spine
            b = [sx * (transition_length + gauge_length / 2), 0]; // gauge spine
            hull() {
                for (t = [0, 1])
                    translate([mix(b[0], a[0], t), mix(b[1], a[1], t), mix(b[2], a[2], t)])
                        cube([fillet_radius, fillet_radius, fillet_radius]);
            }
        }
    }
}

