grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is transition_len away from gauge outer edge
grip_x0 = -half_gauge - transition_len;   // left grip start
grip_x1 =  half_gauge + transition_len;   // right grip end

// ---- Model ----
difference() {
    union() {
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_x0, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
    }

    // Rounded fillets between grip and gauge (radius = 3)
    for (s = [-1, 1])
        translate([s * (half_gauge + transition_len / 2), 0, 0])
            rotate([0, 90, 0])
                cylinder(r = 3, h = thickness + 2 * r, center = true);
}
