// ---------------- Model ----------------
difference() {
    union() {
        // Rim
        cylinder(r = rim_r, h = part_thickness);

        // Hub (laid on bed, extends past top face)
        translate([0, 0, -cut_extra])
            cylinder(r = hub_r, h = part_thickness + 2 * cut_extra);

        // Spokes: radial blocks from hub to rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            rotate([0, 0, a])
                translate([hub_r - cut_extra, -spoke_n2, 0])
                    cube([spoke_n2 + cut_extra, 2 * spoke_n2, part_thickness]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(r = axle_hole_d / 2, h = part_thickness + 2 * cut_extra, $fn = 64);
