    translate([0, 0, -cut_extra])
        cylinder(d = hub_d, h = thickness + 2 * cut_extra, $fn = 96);
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = thickness + 2 * cut_extra, $fn = 64);

    // Spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = start_a + i * 360 / spoke_count;
        translate([hub_d / 2 - 1, 0, -cut_extra])
            rotate([0, 0, a])
