// Spoked wheel for a small sample cart
// Flat part, prints on the bed (z = 0 upward)

// ---------- Parameters ----------
rim_d      = 100;   // outer diameter of rim (mm)
rim_w      = 4;     // rim width (mm)
hub_d      = 16;    // hub outer diameter (mm)
axle_d     = 8;     // axle hole diameter (mm)
spokes     = 6;     // number of spokes
spoke_w    = 4;     // spoke width (mm)
eps        = 0.5;   // cutter overshoot past faces (mm)
$fn        = 128;   // curve resolution

// ---------- Derived ----------
rim_iw = rim_d - rim_w;   // inner diameter of rim (outer - width)

// ---------- Model ----------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = rim_d, h = rim_w);

        // Hub, slightly overlapping the rim for a clean union
        translate([0, 0, rim_w - 0.01])
            cylinder(d = hub_d, h = hub_d + 0.01);

        // Spokes: from hub to rim, first along +X axis
        for (i = [0 : spokes - 1])
            rotate([0, 0, i * 360 / spokes])
                translate([hub_d / 2, -spoke_w / 2, rim_w])
                    cube([spoke_w, spoke_w, hub_d + 0.01]);
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = rim_w + 2 * eps);
}
