// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------- Parameters ----------
wheel_d      = 80;    // outer diameter of the wheel (mm)
wheel_t      = 5;     // wheel thickness (mm)
hub_d        = 14;    // outer diameter of the hub (mm)
axle_d       = 8;     // diameter of the central axle hole (mm)
spoke_count  = 8;     // number of spokes
spoke_w      = 4;     // width of each spoke (mm)
spoke_r      = 30;    // length of each spoke from hub to rim (mm)
eps          = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;             // smoothness of curved shapes

// ---------- Model ----------
difference() {
    // 1. Outer rim (ring)
    cylinder(d = wheel_d, h = wheel_t);

    // 2. Hub (on top of the rim, slightly overlapping)
    translate([0, 0, wheel_t - eps])
        cylinder(d = hub_d, h = eps + 0.01);

    // 3. Axle hole through the hub
