// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 96;

// ---- Dimensions (mm) ----
wheel_thickness = 5;     // part thickness (Z)
outer_diameter  = 80;    // rim outer diameter
rim_width       = 6;     // rim width (radial)
hub_diameter    = 20;    // hub diameter
axle_hole       = 8;     // axle hole diameter
spoke_count     = 4;     // number of spokes
spoke_width     = 5;     // spoke width (radial and tangential)
first_spoke     = 0;     // angle of first spoke (deg, +X axis)
cut_overlap     = 1;     // extra length on cutters to avoid coplanar faces

// ---- Derived ----
outer_radius = outer_diameter / 2;
hub_radius  = hub_diameter / 2;
rim_inner_r = outer_radius - rim_width;

module wheel() {
    difference() {
        union() {
            // Outer rim
            cylinder(h = wheel_thickness,
                     r = outer_radius,
                     $fn = 96);

            // Hub (slightly overlapping rim for a clean union)
            translate([0, 0, -rim_width])
                cylinder(h = wheel_thickness + 2 * rim_width,
                         r = hub_radius,
                         $fn = 96);

            // Spokes: from hub out to the outer rim
            for (i = [0 : spoke_count - 1]) {
                a = first_spoke + i * 360 / spoke_count;
                translate([hub_radius - cut_overlap, 0, 0])
                    rotate([0, 0, a])
                        cube([spoke_width,
                              hub_radius + rim_width + cut_overlap,
                              wheel_thickness]);
            }
        }

        // Axle hole through the centre
        translate([0, 0, -cut_overlap])
            cylinder(h = wheel_thickness + 2 * cut_overlap,
                     d = axle_hole,
                     $fn = 64);
    }
}

wheel();
