// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// See-through for the screw - the hole runs from the top of the neck
// down through the flange and past the bottom face.

// ---------- Parameters ----------
flange_width = 12;    // flange width along Y (mm)
flange_thick = 2;     // flange thickness along Z (mm), z = 0..2
neck_width   = 6;     // neck width along Y (mm)
neck_top_z   = 6;     // top of neck along Z (mm)
screw_d      = 3.4;   // screw hole diameter (mm)
length_x     = 20;    // part length along X (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 64;    // curve resolution

// ---------- Model ----------
difference() {
    // T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);
        // Neck (overlaps flange slightly for a clean union)
        translate([-neck_width / 2, -neck_width / 2, flange_thick - 0.01])
            cube([neck_width, neck_width, neck_top_z - flange_thick + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + eps);
}
