flange_t      = 2;    // flange thickness (Z)
neck_w        = 8;    // neck width (Y)
neck_h        = 4;    // neck height (Z)
screw_d       = 5.5;  // screw hole diameter
x_len         = 15;   // part length along X
cut_ext       = 0.5;  // cutter overshoot past faces

// ---- Derived ----
flange_a = (x_len * flange_w) / 2;          // flange area (half about X axis)
neck_a  = (neck_w * neck_h) / 2;            // neck area (half about X axis)
total_a = flange_a + neck_a;                // combined area about X axis
gy      = (flange_w * flange_a + neck_w * neck_a) / total_a; // centroid Y

// ---- Model ----
translate([0, gy, 0])
    difference() {
        union() {
            // Flange: rectangle in XY, extruded to z = 2
            translate([-x_len/2, -flange_w/2, 0])
                cube([x_len, flange_w, flange_t]);
            // Neck: rectangle in XZ, extruded to y = +/-4, centred on flange
            translate([0, -neck_h/2, flange_t - cut_ext])
                cube([x_len, neck_h, neck_h]);
        }
        // Screw hole through the full height
        translate([0, 0, -cut_ext])
            cylinder(d = screw_d, h = flange_t + neck_h + 2*cut_ext);
    }
