```openscad
// Anti-vibration foot - truncated cone with a rubber pad recess and a screw hole
// Units: mm. Print orientation: bottom face (larger diameter) on the bed,
// building upward along +Z.

$fn = 128;                 // facet count for round features

// ---- Part dimensions ----
foot_h       = 15;         // overall height of the foot (z = 0 to z = 15)
foot_d0      = 50;         // cone diameter at the bottom face (z = 0)
foot_d1      = 36;         // cone diameter at the top face (z = 15)

// ---- Recess dimensions ----
recess_d     = 44;         // recess diameter for the rubber pad
recess_depth = 3;          // recess depth from the bottom face

// ---- Screw hole dimensions ----
screw_d      = 4.5;        // diameter of the central through-hole

// ---- Modelling helpers ----
eps          = 0.5;        // overshoot so cutters pass through faces
poly_h       = foot_h + 1;  // height for the outer cone extended past the top face

difference() {
    // Outer body: a truncated cone, centred on the Z axis
    translate([0, 0, 0])
        linear_extrude(height = poly_h)
            polygon([for (d = [foot_d0, foot_d1]) circle(d = d, $fn = 128)]);

    // Round recess cut into the bottom face for the rubber pad
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps, $fn = 128);

    // Through hole for the screw, running along the Z axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_h + 2 * eps, $fn = 128);
}
```

