foot_diam_top  = 40;       // diameter at flat top face
recess_dia     = 44;       // recess diameter for rubber pad
recess_depth   = 2;        // recess depth from bottom face
screw_dia      = 5.5;      // through-hole screw diameter

// ---- Derived ----
recess_ovr     = 0.5;      // extension of recess cutter past bottom face
screw_ovr      = 0.5;      // extension of screw hole past top/bottom faces

// ---- Model ----
difference() {
    // Truncated cone: hull between two coaxial cylinders
    hull() {
        cylinder(d = foot_diam_bot, h = recess_ovr);   // bottom portion
        cylinder(d = foot_diam_bot);                   // full bottom face
        cylinder(d = foot_diam_top, h = foot_height - recess_ovr); // upper part
    }

    // Rubber pad recess cut into bottom face
    translate([0, 0, -recess_depth])
        cylinder(d = recess_dia, h = recess_depth + 2 * recess_ovr);

    // Central screw through-hole along the axis
    translate([0, 0, -screw_ovr])
        cylinder(d = screw_dia, h = foot_height + 2 * screw_ovr);
