```openscad
// Anti-vibration foot - truncated cone with a rubber pad recess and a screw hole
// Print orientation: flat base on the bed (z = 0), building upward in +Z

// ---------- Dimensions (mm) ----------
foot_d_bottom   = 50;    // cone diameter at the bottom face (z = 0)
foot_d_top      = 42;    // cone diameter at the top face (z = 12)
foot_height     = 12;    // overall height of the foot

recess_d        = 42;    // diameter of the round recess for the rubber pad
recess_depth    = 3;     // depth of the rubber pad recess from the bottom face

screw_d         = 4.5;   // diameter of the central screw hole

overcut         = 0.5;   // extra length so cutters pass through faces

$fn = 128;               // smoothness of curved surfaces

// ---------- Model ----------
difference() {
    // Truncated cone (frustum), centred on Z, standing on the bed
    translate([0, 0, foot_height])
        cylinder(d1 = foot_d_top, d2 = foot_d_bottom, h = foot_height);

    // Rubber pad recess, cut into the bottom face
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + overcut);

    // Central screw hole, through the entire part along the axis
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = foot_height + 2 * overcut);
}
```

