```openscad
// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 6;     // rib height above plate (mm), z = 2..8
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 20;    // distance of outer ribs from plate ends (mm)

eps         = 0.5;   // overlap for clean booleans (mm)
$fn         = 64;    // curve resolution

// ---------- Derived ----------
rib_x = [for (i = [0 : rib_count - 1]) rib_offset + i * rib_pitch];

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, run full width along Y
    for (x = rib_x)
        translate([x - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
}
```

