// Stiffened cover panel: flat plate with 3 transverse ribs
// Print orientation: plate flat on bed (z = 0), ribs building up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 60;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

// ---- Ribs ----
rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 5;     // rib total height (mm), z = 0..5 (overlaps plate)
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs along X (mm)
rib_end_off = 20;    // distance of outer rib centres from plate ends (mm)

// ---- Misc ----
eps         = 0.01;  // tiny overlap for clean unions

// Derived
span  = plate_len / (rib_count + 1);         // = 20 mm, checks rib_end_off
rib_x = [for (i = [0 : rib_count - 1]) rib_end_off + i * rib_pitch];

module plate() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module ribs() {
    for (x = rib_x)
        translate([x - rib_thk / 2, -plate_wid / 2, 0])
            cube([rib_thk, plate_wid, rib_h]);
}

union() {
    plate();
    ribs();
}
```

