// Stiffened cover panel
// Flat plate with 3 straight ribs running along Y, dividing the length into 4 equal parts

// ---- Parameters ----
plate_len      = 100;  // plate length along X (mm)
plate_wid      = 50;   // plate width along Y (mm)
plate_thk      = 3;    // plate thickness (mm), z = 0..3

rib_thk        = 3;    // rib thickness along X (mm)
rib_h          = 6;    // rib height from top of plate (mm), z = 3..9
rib_count      = 3;    // number of ribs
rib_end_offset = 25;   // distance of outer rib centres from plate ends (mm)

overlap        = 0.01; // small overlap so ribs fuse into the plate

$fn = 64;

// ---- Model ----
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs: centre them so the length is split into 4 equal parts.
    // For n ribs the step is (L - 2*offset) / (n - 1); with n = 4 that gives 25 mm.
    for (i = [0 : rib_count - 1]) {
        x = (i + 1) * (plate_len - 2*rib_end_offset) / (rib_count - 1);
        translate([x - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
