// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
outer_radius   = 15;    // outer radius of spherical bowl (mm)
wall_thickness = 1.5;   // bowl wall thickness (mm)
handle_width   = 10;    // handle width in Y (mm)
handle_thick    = 4;     // handle thickness in Z (mm)
handle_x0       = 13.5;  // handle start position in X (mm)
handle_x1       = 75;    // handle end position in X (mm)
cut_extra       = 0.5;   // extra length for cutting shapes past faces (mm)

$fn = 96;               // curve resolution

// Derived values
rim_z      = outer_radius;               // rim height (lower half: z = 0..15)
inner_r    = outer_radius - wall_thickness;
handle_y0  = -handle_width / 2;
handle_y1  =  handle_width / 2;
handle_z0  = rim_z - handle_thick;       // top face flush with rim

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        cylinder(r = outer_radius, h = outer_radius);
        translate([0, 0, wall_thickness])
            cylinder(r = inner_r, h = outer_radius + cut_extra);
    }

    // Flat handle along +X
    translate([handle_x0, handle_y0, handle_z0])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}
