bowl_wall         = 1.5;   // bowl wall thickness (mm)
handle_width      = 10;    // handle width in Y (mm)
handle_thick      = 4;     // handle thickness in Z (mm)
handle_x0         = 13.5;  // handle start in X (mm)
handle_x1         = 75;    // handle end in X (mm)
