handle_z0     = bowl_rim_z - handle_thick + overlap;     // handle bottom height
handle_z1     = bowl_rim_z + overlap;                    // handle top height (flush with rim)

// ---------------- Model ----------------
union() {
    // Bowl: lower half of a hollow sphere
    difference() {
        translate([0, 0, 0])
            cylinder(r = bowl_outer_radius, h = bowl_outer_radius);
        translate([0, 0, bowl_wall])
            cylinder(r = bowl_outer_radius - bowl_wall,
                     h = bowl_outer_radius + overlap);
