// Powder measuring scoop
// Print orientation: handle on the bed, bowl pointing up

$fn = 96;

// --- Scoop bowl ---
bowl_od    = 15;   // outer diameter of the sphere (mm)
bowl_r     = bowl_od / 2;
bowl_wall  = 1.5;  // wall thickness (mm)
bowl_z0    = 15;   // sphere centre height (mm)

// --- Handle ---
handle_w   = 10;   // handle width along Y (mm)
handle_t   = 4;    // handle thickness along Z (mm)
handle_x0  = 13.5; // handle start position along X (mm)
handle_x1  = 75;   // handle end position along X (mm)

// --- Fusion ---
eps        = 0.5;  // overlap for a clean union (mm)

module handle() {
    translate([handle_x0, -handle_w / 2, 0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

module bowl() {
    translate([0, 0, bowl_z0])
        difference() {
            sphere(r = bowl_r);
            translate([0, 0, -eps])
                sphere(r = bowl_r + 2 * bowl_wall);
        }
}

union() {
    bowl();
    handle();
}
