// Measuring scoop for powders
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

$fn = 96;

// --- Bowl ---
outer_radius = 15;      // outer radius of spherical bowl
wall         = 1.5;     // wall thickness
cut_extra    = 0.5;     // overlap for clean boolean cuts

// --- Handle ---
handle_width   = 10;    // handle width (Y)
handle_thick   = 4;     // handle thickness (Z)
handle_x_start = 13.5;  // where handle meets the bowl (X)
handle_x_end   = 75;    // handle tip (X)

// Derived
inner_r = outer_radius - wall;
rim_z   = outer_radius;   // top of bowl / handle top face

module bowl() {
    difference() {
        // outer hemisphere (lower half)
        translate([0, 0, rim_z])
            sphere(r = outer_radius);
        // inner cavity, extends past the bottom face
        translate([0, 0, cut_extra])
            sphere(r = inner_r);
    }
}

module handle() {
    translate([handle_x_start, -handle_width / 2, rim_z - handle_thick])
        cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
}

union() {
    bowl();
    handle();
}
