// Powder measuring scoop - hollow spherical bowl with a flat handle along +X
// Print orientation: bowl bottom on the bed (z = 0), handle on top, opening upward.

$fn = 96;

// ---- Bowl ----
outer_radius   = 12;   // outer radius of the sphere
wall_thickness = 2;    // wall thickness of the hollow bowl
bottom_z       = 0;    // z of the bowl bottom (touches the bed)
rim_z          = 12;   // z of the rim (lower hemisphere: bottom_z + outer_radius)

// ---- Handle ----
handle_length = 62;    // length along +X, from x = 10 to x = 72
handle_width  = 10;    // width along Y
handle_thick  = 4;     // thickness along Z, flush with the rim (z = 8 to 12)

// ---- Misc ----
eps = 0.5;             // cutter overshoot past faces

difference() {
    union() {
        // Hollow spherical bowl: lower half of a sphere centred at (0, 0, 12)
        translate([0, 0, bottom_z])
            cylinder(h = outer_radius, r = outer_radius + wall_thickness);

        // Straight flat handle running along +X
        translate([10, -handle_width / 2, rim_z - handle_thick])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Remove the upper half of the outer sphere, leaving the lower half solid
    translate([0, 0, bottom_z + eps])
        cylinder(h = outer_radius - eps, r = outer_radius + wall_thickness);

    // Blind pocket from the open side to thicken the rim and fuse the handle
    translate([10, -handle_width / 2 - eps, bottom_z])
        cube([handle_length + 2 * eps, handle_width + 2 * eps, rim_z - eps]);
}
