// Measuring scoop for powders: half-sphere bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle on top.

$fn = 96;

// ---- Dimensions (mm) ----
bowl_outer_radius = 12;    // outer radius of spherical bowl
bowl_wall         = 2;     // wall thickness of bowl
handle_length     = 62;    // handle runs from x = 10 to x = 72
handle_width      = 10;    // handle width along Y
handle_thickness  = 4;     // handle thickness along Z
overlap           = 0.5;   // overlap between bowl and handle for a clean union

// Derived values
bowl_center_z = bowl_outer_radius;   // bowl centre at (0, 0, 12)
handle_z      = bowl_center_z - handle_thickness;  // handle spans z = 8 to 12

difference() {
    union() {
        // Half-sphere bowl (lower half only)
        translate([0, 0, bowl_center_z])
            difference() {
                sphere(r = bowl_outer_radius);
                translate([0, 0, -overlap])
                    cylinder(h = overlap + 0.01, r = bowl_outer_radius + 1);
            }

        // Straight handle along +X
        translate([10, -handle_width / 2, handle_z])
            cube([handle_length, handle_width, handle_thickness]);
    }

    // Empty the bowl: remove the upper half of the volume (above z = 6),
    // leaving a solid bottom and a thin wall that keeps the shape.
    translate([0, 0, bowl_outer_radius / 2 - 0.01])
        difference() {
            hull() {
                translate([0, 0, 0])
                    sphere(r = bowl_outer_radius - 2 * bowl_wall);
                translate([0, 0, bowl_center_z + 0.01])
                    sphere(r = bowl_outer_radius);
            }
            // extend the cavity slightly past the rim
            translate([0, 0, bowl_center_z + 0.01])
                sphere(r = bowl_outer_radius + 0.5);
        }
}
