// Powder measuring scoop
// Print orientation: handle on bed, bowl pointing up

$fn = 96;

// ---- Bowl ----
outer_r = 12;      // outer radius of sphere
wall    = 2;       // wall thickness
half_h  = outer_r; // height of lower half (0 to -12)

// ---- Handle ----
handle_w = 10;     // width (Y)
handle_t = 4;      // thickness (Z)
handle_x0 = 10;    // start (X)
handle_x1 = 72;    // end (X)

// ---- Cut clearance ----
eps = 0.5;

difference() {
    union() {
        // Bowl
        translate([0, 0, -half_h])
            cylinder(h = half_h + eps, r = outer_r);

        // Handle
        translate([handle_x0, -handle_w/2, 0])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Remove upper half of sphere (z > 0) and thin wall
    translate([0, 0, -eps])
        intersection() {
            translate([0, 0, -half_h - eps])
                cylinder(h = half_h + 2*eps + wall);
            translate([0, 0, -half_h])
                cylinder(h = half_h + wall + eps);
        }
}
