    translate([10, -handle_width / 2, 0])
        cube([handle_length, handle_width, handle_thick]);

    // Bowl: half of a hollow sphere, centred at (0, 0, bowl_rim_z)
    translate([0, 0, bowl_rim_z])
        difference() {
            sphere(r = bowl_radius);

            // Remove the upper half, keeping only the lower half
            // whose points satisfy z <= bowl_rim_z
            translate([0, 0, bowl_rim_z + overlap])
                cube([bowl_radius * 2, bowl_radius * 2, overlap]);
        }
}
