// Powder measuring scoop - half-sphere bowl with a straight handle
// Units: mm. Print orientation: bowl bottom on the bed (z = 0).

$fn = 96;

// ---- Bowl ----
bowl_outer_r   = 12;    // outer radius of the spherical bowl
bowl_wall      = 2;     // wall thickness (2 mm, stated explicitly)
bowl_center_y  = 0;     // bowl centre Y (on the X axis)

// ---- Handle ----
handle_len     = 102;   // handle runs from x = 10 to x = 112
handle_w       = 12;    // handle width along Y
handle_t       = 3;     // handle thickness along Z
handle_x0      = 10;    // handle start X
handle_x1      = 112;   // handle end X

// ---- Misc ----
eps            = 0.5;   // small overlap for clean booleans / unions
debug          = 0;     // set to 1 to see intermediate parts

// Derived
bowl_inner_r = bowl_outer_r - bowl_wall;   // 10 mm clear space
rim_z        = bowl_center_y + bowl_outer_r;  // 12 mm rim height

module bowl() {
    // Hollow lower half of the sphere, centred at z = 12
    translate([0, 0, bowl_center_y])
        difference() {
            sphere(r = bowl_outer_r);
            translate([0, 0, -eps])
                sphere(r = bowl_inner_r);
            // discard the upper half (z > rim), keep the bottom at z = 0
            translate([0, 0, rim_z - eps])
                cube([bowl_outer_r * 2 + 2, bowl_outer_r * 2 + 2, eps]);
        }
}

module handle() {
    translate([handle_x0, -handle_w / 2, 0])
        cube([handle_len, handle_w, handle_t]);
}

union() {
    bowl();
    handle();
}
