        // Hollow lower-half bowl
        translate([0, 0, center_z])
            difference() {
                sphere(r = outer_radius);
                translate([0, 0, eps])
                    sphere(r = outer_radius - wall);
            }

        // Flat handle along +X
        translate([handle_start_x, -handle_width / 2, center_z - handle_thick])
            cube([handle_end_x - handle_start_x, handle_width, handle_thick]);
    }

    // Keep only the part below z = 13 (rim area), so the bowl bottom touches z = 0
    translate([0, 0, 13])
        cube([100, handle_width + 2, eps]);
}
