// Measuring scoop for powders
// Units: mm

$fn = 128;

// --- Bowl ---
outer_radius = 10;
wall         = 2;
// lower half of sphere, centred at (0,0,10), opens upward

// --- Handle ---
handle_width   = 8;   // Y
handle_thick   = 3;   // Z
handle_start_x = 8;   // X
handle_end_x   = 70;  // X
// top face flush with rim (z = 7 to 10)

// --- Cut clearance ---
eps = 0.5;

difference() {
    union() {
        // Bowl
        translate([0, 0, 10])
            cylinder(h = outer_radius, r = outer_radius + wall);
        translate([0, 0, 5])
            cylinder(h = outer_radius + eps, r = wall);

        // Handle
        translate([handle_start_x, -handle_width / 2, 7])
            cube([handle_end_x - handle_start_x, handle_width, handle_thick]);
    }

    // Remove upper half of bowl (keep rim at z = 10)
    translate([0, 0, 10])
        cylinder(h = outer_radius + eps, r = outer_radius + 1);
}
