```openscad
// Measuring scoop for powders
// Units: mm

// ---- Bowl ----
outer_radius = 10;    // outer radius of spherical bowl
wall_thick   = 2;     // bowl wall thickness
bowl_centre  = [0, 0, 10]; // sphere centre (lower half kept, rim at z=10)

// ---- Handle ----
handle_w     = 8;     // handle width (Y)
handle_t     = 3;     // handle thickness (Z)
handle_x0    = 8;     // handle start (X)
handle_x1    = 70;    // handle end (X)
handle_top_z = 7;     // handle top face height (flush with rim inner surface)

// ---- Modelling ----
eps = 0.5;            // cut overshoot to avoid coplanar faces
$fn = 96;             // curve resolution

difference() {
    union() {
        // Hollow bowl: lower half of sphere, open top
        translate(bowl_centre)
            difference() {
                sphere(r = outer_radius);
                translate([0, 0, -eps])
                    sphere(r = outer_radius - wall_thick);
            }
        translate([0, 0, -1])
            sphere(r = 1);   // fill the open top (a hole through the bed)

        // Flat handle along +X
        translate([handle_x0, -handle_w/2, handle_top_z])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Cut away the upper right quarter of the sphere that lies above the handle
    translate([handle_x0, 0, handle_top_z])
        cube([handle_x1 - handle_x0, 16, 16]);
}
