outer_radius   = 10;    // outer radius of spherical bowl (mm)
wall_thickness = 2;     // wall thickness of bowl (mm)
handle_width  = 8;     // handle width along Y (mm)
handle_thick  = 3;     // handle thickness along Z (mm)
handle_x0     = 8;     // handle start position along X (mm)
handle_x1     = 70;    // handle end position along X (mm)
cut_extra     = 0.5;   // extra length on cutting shapes to avoid coplanar faces (mm)

$fn = 96;              // facet count for curved surfaces

// Derived values
rim_z      = outer_radius;             // rim height of the full sphere (z = 10)
bowl_inner = outer_radius - wall_thickness;  // inner radius of the hollow sphere
// handle top face is flush with the rim, so handle_z spans z = 7 to z = 10

// ---------------- Model ----------------
union() {
    // Lower half of hollow sphere: bowl opens upward, bottom touches the bed
    difference() {
        cylinder(h = outer_radius, r = outer_radius);
        translate([0, 0, wall_thickness])
            cylinder(h = outer_radius + cut_extra, r = bowl_inner);
    }

    // Flat handle running along +X from x = 8 to x = 70
    translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}

// ---------------- Helper ----------------
// Handle runs from z = 7 to z = 10 (flush with rim)
function handle_z0() = rim_z - handle_thick;
