```openscad
// Measuring scoop for powders
// Print orientation: handle along +X, bowl at origin

$fn = 96;

// --- Handle ---
handle_len    = 101.5;  // x = 8.5 to 110
handle_w      = 12;     // Y width
handle_t      = 3;      // thickness, top flush with rim (z 7..10)

// --- Bowl ---
r_out         = 10;     // outer radius
t_wall        = 1.5;    // wall thickness
bowl_z0       = 0;      // bottom touches bed
bowl_rim_z    = r_out;  // rim at z = R (lower half kept)

// --- Misc ---
eps           = 0.5;    // cutter overshoot

difference() {
    union() {
        // Handle
        translate([8.5, -handle_w/2, bowl_z0 + r_out - t_wall])
            cube([handle_len, handle_w, t_wall]);

        // Bowl
        translate([0, 0, bowl_z0])
            difference() {
                hull() { for (a = [0 : 30 : 180])
                    rotate([0, 0, a])
                        translate([-r_out, 0, 0])
                            cylinder(r = r_out, h = r_out + eps, $fn = 96);
                }
                translate([0, 0, eps])
                    hull() { for (a = [0 : 30 : 180])
                        rotate([0, 0, a])
                            translate([-r_out + t_wall, 0, 0])
                                cylinder(r = r_out - t_wall, h = r_out + 2*eps, $fn = 96);
                    }
            }
    }
}
