// Powder measuring scoop
// Print orientation: handle on bed, bowl pointing up

$fn = 96;

// ---- Dimensions (mm) ----
bowl_outer_r    = 10;    // bowl outer radius
bowl_wall_t     = 1.5;   // bowl wall thickness
bowl_rim_z      = 7;     // rim height (top of bowl)
handle_len      = 101.5; // handle length (x = 8.5 to 110)
handle_w        = 12;    // handle width (Y)
handle_t        = 3;     // handle thickness (Z)
