difference() {
    union() {
        // Lower half of a sphere: z = 0 to 10, centred at origin
        sphere(r = bowl_outer_r, h = bowl_outer_r * 2, $fn = 128);
        // Flat handle along +X, top face flush with rim height
        translate([bowl_outer_r + overlap, -handle_w / 2, 0])
            cube([handle_len, handle_w, handle_t]);
    }
