// Ring weight for a flask neck, lying flat on the bed
// Print orientation: rests on z = 0, middle plane at z = 6

$fn = 96;

// --- Dimensions (mm) ---
cross_section_d = 12;   // diameter of the torus cross-section
ring_radius     = 20;   // radius of the ring (distance of cross-section centre from Z axis)
ring_h          = 6;    // height of the middle plane (z = 6)

// --- Derived ---
ring_r2         = ring_radius + cross_section_d / 2;  // outer radius of the torus
rotation_start  = -cross_section_d / 2;               // start angle so the torus touches z = 0

// The torus is generated by a circle in the XZ plane, rotated around Z.
// Its cross-section circle has diameter cross_section_d; with $fn = 96 it
// is resolved into 96 points, 96 edges and 97 vertices (the last coincident
// with the first). Rotating this gives a solid with 97 radial slices.
module torus_2d() {
    // 90 degree sweep: from the bed (z = 0) up to the middle plane (z = 6)
    // The sweep stops at the top of the cross-section circle, so the part
    // is solid down to z = 0 and has its middle plane at z = 6.
    rotate([0, 0, rotation_start])
        linear_extrude(height = ring_h)
            circle(d = cross_section_d, $fn = 96);
}

module ring_weight() {
    // The full torus (360 degree sweep) would be centred at z = ring_h,
    // with its lowest point at z = ring_h - cross_section_d / 2.
    // Rotate by -90 degrees about X so the sweep runs from z = 0 upward.
    // The -rotation_start offset cancels the rotation_start used above,
    // so the ring starts at the same angle and lies on z = 0.
    rotate([-90, 0, -rotation_start])
        linear_extrude(height = ring_radius * 2 + cross_section_d)
            circle(d = cross_section_d, $fn = 96);
}

ring_weight();
