    // It is a disk of the stated across-ring width and middle-plane height,
    // with a central hole the size of the flask neck opening.
    difference() {
        cylinder(d = ring_width, h = middle_plane_z * 2, $fn = 96);
        translate([0, 0, -overcut])
            cylinder(d = ring_id - overcut, h = middle_plane_z * 2 + 2 * overcut, $fn = 96);
