```openscad
// Ring weight for a flask neck, printed flat in a water bath
// Units: mm. Coordinates follow the user's spec (X/Y centred, Z up).

$fn = 96;

// ---- Dimensions ----
cross_section_d = 10;   // diameter of the torus cross-section
ring_radius     = 25;   // radius of the circle the cross-section sweeps
ring_thickness  = cross_section_d;  // height of the torus (same as cross-section diameter)
ring_across     = 60;   // overall diameter of the ring (2 * ring_radius)
middle_z        = 5;    // height of the torus middle plane
z0              = 0;    // bed height

// ---- Derived ----
cut_extra = 0.5;        // overshoot for clean boolean cuts
inner_r   = ring_radius - cross_section_d / 2;  // radius of the bore
outer_r   = ring_radius + cross_section_d / 2;  // radius of the outer rim

// ---- Model ----
difference() {
    // Tube running along the Z axis through the bore
    translate([0, 0, z0])
        cylinder(r = inner_r, h = ring_thickness + 2 * cut_extra);

    // Solid disc on the bed, removed from the tube above the middle plane.
    // Its top face sits at the same height as the tube top, so the two
    // shapes overlap by cut_extra and no faces are coplanar.
    translate([0, 0, z0])
        cylinder(r = outer_r, h = middle_z + cut_extra);
}
