```openscad
// Ring weight - torus lying flat on the bed
// Units: mm

$fn = 96;

// --- Dimensions ---
tube_d      = 10;   // tube diameter (cross-section circle diameter)
major_r     = 25;   // major radius (distance of tube centre from Z axis)
tube_h      = tube_d; // tube height / length along the spiral
result_d    = major_r * 2 + tube_d; // overall diameter (~60 mm)
middle_z    = 5;    // z of the tube's middle plane

// --- Model ---
// Cylinder(s) along Z, centred on a circle of radius major_r.
// Placed on z = 0 and building upward; their axis lies at z = tube_h / 2,
// so the middle plane is at z = tube_h / 2 = 5.
module ring_weight() {
    hull() {
        for (a = [i * 360 / 8 : i < 8 : a])
            translate([major_r * cos(a), major_r * sin(a), 0])
                cylinder(d = tube_d, h = tube_h);
    }
}

ring_weight();
```

```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles
knuckle_w   = 15;   // length of each segment (plate_len / knuckle_n)
knuckle_z   = 3.5;  // knuckle axis height above bed
knuckle_y   = 10;   // knuckle axis Y position (on +Y edge)

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments, axis along X
        for (i = [0, 2]) {
            x0 = -plate_len/2 + i * knuckle_w;
            translate([x0, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len);
        }
    }

    // Pin hole through every knuckle (along X axis)
    translate([0, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps, center = true);
}
```

