// Pin hinge leaf
// Print orientation: plate flat on bed, knuckle axes at z = 3.5

// ---------------- Parameters ----------------
plate_length   = 45;   // plate length along X
plate_width    = 20;   // plate width along Y
plate_thick    = 3;    // plate thickness (Z)

knuckle_d      = 7;    // knuckle cylinder diameter
knuckle_count  = 3;    // number of knuckles
segment_len    = 15;   // length of each segment (plate_length / count)
knuckle_y      = 10;   // common knuckle axis Y position

pin_d          = 3;    // pin hole diameter

eps            = 0.5;  // cutter overshoot

$fn = 64;

// ---------------- Model ----------------
difference() {
    union() {
        // Plate
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles: cylinders along X, centred on 1st and 3rd segments
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0)
                translate([-segment_len/2 + i*segment_len, knuckle_y, 0])
                    rotate([0, 90, 0])
                        cylinder(d = knuckle_d, h = segment_len);
        }
    }

    // Pin hole through all knuckles
    translate([-segment_len/2 - eps, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_length + 2*eps);
}
