// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles
knuckle_w   = 15;   // length of each segment (plate_len / knuckle_n)
knuckle_y   = 10;   // knuckle axis Y position (on +Y edge)
knuckle_z   = 3.5;  // knuckle axis height above bed

// ---- Pin ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, centred on their X axis
        for (i = [0 : knuckle_n - 1]) {
            x = (i < knuckle_n / 2) ? -knuckle_w/2 : knuckle_w/2;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_w);
        }
    }

    // Pin hole along the knuckle axis through every knuckle
    translate([-knuckle_w/2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
