```openscad
// Pin hinge leaf
// Print orientation: flat plate on bed, knuckles pointing up

$fn = 64;

// --- Dimensions ---
plate_len   = 45;   // plate length (X)
plate_wid   = 30;   // plate width (Y)
plate_thk   = 3;    // plate thickness (Z)
knuckle_d   = 6;    // knuckle diameter
knuckle_h   = 10;   // knuckle height above plate
pin_d       = 2.5;  // pin hole diameter
segment_n   = 3;    // number of knuckle segments
eps         = 0.5;  // cut overlap

// --- Model ---
difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = [0 : segment_n - 1]) {
            x = (i - (segment_n - 1)/2) * plate_len/segment_n;
            if (i == 0 || i == segment_n - 1)
                translate([x, plate_wid/2, plate_thk])
                    cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin holes
    for (i = [0 : segment_n - 1]) {
        x = (i - (segment_n - 1)/2) * plate_len/segment_n;
        translate([x, plate_wid/2, plate_thk - eps])
            cylinder(d = pin_d, h = knuckle_h + 2*eps);
    }
}
