// Pin hinge leaf
// Print orientation: flat plate on the bed, knuckle axes at z = plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_l     = 45;    // plate length along X
plate_w     = 30;    // plate width along Y
plate_t     = 3;     // plate thickness along Z
knuckle_d   = 6;     // knuckle diameter
knuckle_h   = 5;     // knuckle height above plate top
pin_d       = 2.5;   // pin hole diameter
knuckle_n   = 3;     // number of knuckles (1st, 3rd segments)
eps         = 0.5;   // cutter overshoot

// ---- Derived ----
seg = plate_l / knuckle_n;   // 15 mm segment
x0  = -seg * (knuckle_n - 1) / 2;  // first knuckle X

difference() {
    union() {
        // Plate
        translate([-plate_l / 2, -plate_w / 2, 0])
            cube([plate_l, plate_w, plate_t]);
        // Knuckles
        for (i = [0 : knuckle_n - 1])
            translate([x0 + i * seg, plate_w / 2, plate_t])
                cylinder(d = knuckle_d, h = knuckle_h);
    }
    // Pin holes
    for (i = [0 : knuckle_n - 1])
        translate([x0 + i * seg, plate_w / 2, -eps])
            cylinder(d = pin_d, h = knuckle_h + 2 * eps);
}
