```openscad
// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
plate_length   = 45;   // X length of plate
plate_width    = 30;   // Y width of plate
plate_thick    = 3;    // Z thickness of plate

knuckle_count  = 3;    // number of knuckle segments
knuckle_dia    = 6;    // knuckle cylinder diameter
knuckle_pitch  = plate_length / knuckle_count; // 15 mm segment length

pin_dia        = 2.5;  // pin hole diameter
pin_y          = 15;   // knuckle axis Y position
pin_z          = 3;    // knuckle axis Z position

eps            = 0.5;  // overshoot for clean cuts

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on 1st and 3rd segments
        for (i = [0 : knuckle_count - 1]) {
            x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
            if (abs(i - (knuckle_count - 1)/2)) // skip centre segment
                translate([x, pin_y, pin_z])
                    cylinder(d = knuckle_dia, h = 10, $fn = 96);
        }
    }

    // Pin holes through knuckles
    for (i = [0 : knuckle_count - 1]) {
        x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
        if (abs(x) < eps) continue;
        translate([x, pin_y, pin_z])
            rotate([0, 90, 0])
                cylinder(d = pin_dia, h = 11, $fn = 96);
    }
}
