// Pin hinge leaf
// Print orientation: flat plate on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_length   = 45;   // plate length along X
plate_width    = 30;   // plate width along Y
plate_thick    = 3;    // plate thickness along Z
knuckle_dia    = 6;    // knuckle diameter
knuckle_count  = 3;    // number of knuckles
knuckle_pitch  = 15;   // centre-to-centre spacing along X
knuckle_offset = 15;   // Y position of knuckle axis (edge)
pin_dia        = 2.5;  // pin hole diameter
overlap        = 0.5;  // knuckle overlap into plate for a clean union

// ---- Derived ----
knuckle_z      = plate_thick; // axis height of knuckles

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles along +Y edge, alternating phase
        for (i = [0 : knuckle_count - 1]) {
            x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
            // cylinder from z = 0, overlapped into plate by 'overlap'
            translate([x, knuckle_offset, 0])
                cylinder(d = knuckle_dia, h = plate_thick + overlap);
        }
    }

    // Pin hole running along X through every knuckle
    translate([-knuckle_pitch/2 - 1, knuckle_offset, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_dia, h = knuckle_pitch + 2);
}
