            rotate([0, 90 - inv, 0])
                cylinder(d = knuckle_d, h = plate_len / 2 + knuckle_r, center = true);
    }

    // Pin hole along the common knuckle axis (y = 15, z = 4)
    translate([0, 15, -1])
        cylinder(d = pin_d, h = plate_thk + 2);
