knuckle_d      = 8;     // knuckle cylinder diameter (mm)
knuckle_axis_y = 15;    // knuckle axis Y position (mm)
knuckle_axis_z = 4;     // knuckle axis height above bed (mm)

pin_d          = 3;     // pin hole diameter (mm)
overlap        = 0.5;   // knuckle overlap onto plate for a clean union (mm)

$fn = 96;               // resolution for round features

// ---------- Derived ----------
seg_len = plate_length / knuckle_count;   // 10 mm segment length
// X positions of segment centres (−20 .. 20), and keep only the odd ones (1st, 3rd, 5th)
segment_xs = [x for x in [-(knuckle_count - 1) * seg_len / 2 + i * seg_len
                          for i in [0 : knuckle_count - 1]] if x % (2 * seg_len)];

// ---------- Model ----------
union() {
    // Flat plate, centred in X and Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Round knuckles whose axes run along X
    for (x : segment_xs)
        translate([x, knuckle_axis_y, knuckle_axis_z])
            difference() {
                cylinder(d = knuckle_d, h = seg_len + 2 * overlap, center = true);
                // Through-hole for the pin
                translate([0, 0, -overlap])
                    cylinder(d = pin_d, h = seg_len + 2 * overlap + 2, center = true);
            }
}
