knuckle_z      = 4;   // knuckle axis height (Z)
knuckle_y      = 15;  // knuckle row position (Y)
knuckle_span   = 50;  // span along X (1st to 5th segment centre-to-centre)
knuckle_pitch  = 10;  // segment length / centre spacing
