for (i = [0 : knuckle_holes - 1]) {
    x = (i % 2) * knuckle_pitch - (knuckle_span / 2);
    translate([x, 0, 0]) {
        union() {
            // Plate
            translate([-plate_len / 2, -plate_wid / 2, 0])
                cube([plate_len, plate_wid, plate_thk]);

            // Knuckle (cylinder along X, overlapping into the plate)
            translate([0, knuckle_y, 0])
                rotate([90, 0, 0])
                    cylinder(d = knuckle_d, h = plate_thk + overlap);
        }

        // Pin hole through the knuckle
        translate([0, knuckle_y, 0])
            rotate([90, 0, 0])
                cylinder(d = pin_d, h = plate_thk + overlap + 2);
    }
}
