// Pin hinge leaf
// Flat plate on the bed, knuckles along the +Y edge

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // knuckle axis height above bed (mm)
knuckle_ps   = 10;   // centre-to-centre knuckle spacing along X (mm)
knuckle_n    = 5;    // number of segments (knuckles on 1st, 3rd, 5th)

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
half_h = (knuckle_d)/2;                          // knuckle radius
first_x = -(knuckle_n - 1) * knuckle_ps / 2;     // x of 1st segment (centre -10mm)

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge, axis along X
        for (i = [0 : knuckle_n - 1]) {
            if ((i + 1) % 2 == 0) continue;       // even segments empty
            translate([first_x + i * knuckle_ps, plate_wid/2 - half_h, 0])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps, center = true);
        }
    }

    // Pin holes through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if ((i + 1) % 2 == 0) continue;
        translate([first_x + i * knuckle_ps, plate_wid/2 - half_h, -eps])
            cylinder(d = pin_d, h = plate_thk + 2*eps, center = true);
    }
}
