eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
seg_len = plate_len / knuckle_n;   // 10 mm segment length
first_x = (knuckle_sel[0] - 1) * seg_len; // X of first knuckle

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckle cylinders along X, through the plate
    for (i = [0 : len(knuckle_sel) - 1]) {
        seg = knuckle_sel[i];
        translate([first_x + (seg - 1) * seg_len, knuckle_y, 0])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2*eps, center = true);
                // Pin hole along X axis
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2*eps, center = true);
            }
    }
