            cube([plate_len, plate_wid, plate_thk]);

        // Round knuckles along +Y edge, axis running along X
        for (i = [0 : knuckle_n - 1])
            translate([(i - (knuckle_n - 1) / 2) * knuckle_h,
                       knuckle_y,
                       plate_thk / 2 + knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Through-hole for the pin along the knuckle axis
    translate([0, knuckle_y, plate_thk / 2 + knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_n * knuckle_h + 2 * eps);
