            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on +Y edge
        for (i = [knuckle_start : knuckle_end]) {
            x = -plate_len/2 + (i + 1) * plate_len / knuckle_n;
            translate([x, knuckle_y, plate_thk])
                cylinder(d = knuckle_d, h = knuckle_h);
