        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge, axis parallel to X
        for (i = [0 : knuckle_count - 1]) {
            seg = (i + 1) * 2 - 1; // 1, 3, 5
            x = (seg - 1) * knuckle_pitch / 2;
            translate([x, plate_wid/2, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps, $fn = 96);
        }
