$fn = 96;

// ---- Plate ----
plate_len   = 40;    // X length of base plate
plate_wid   = 25;    // Y width of base plate
plate_thk   = 3;     // Z thickness of base plate

// ---- Knuckles ----
knuckle_d   = 6;     // cylinder diameter
knuckle_h   = 10;    // cylinder height (overlaps plate for a solid union)
knuckle_n   = 5;     // number of equal segments along X
knuckle_y   = plate_wid / 2; // common axis Y (on the +Y edge)
knuckle_z   = plate_thk; // common axis Z

// ---- Pin ----
pin_d       = 2;     // through-hole diameter

// ---- Layout ----
seg_len     = plate_len / (knuckle_n - 1); // centre-to-centre spacing
offset      = -seg_len * (knuckle_n - 1) / 2; // first knuckle X

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders
        for (i = [0 : knuckle_n - 1])
            translate([offset + i * seg_len, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin through each knuckle
    for (i = [0 : knuckle_n - 1])
        translate([offset + i * seg_len, knuckle_y, 0])
            cylinder(d = pin_d, h = plate_thk + knuckle_h);
}
