        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the pitch circle
        for (i = [0 : 2]) {
            a = knuckle_start + i * 120;
            x = knuckle_pcd / 2 * cos(a);
            y = knuckle_pcd / 2 * sin(a);
            translate([x, y, plate_thk])
                cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin holes through every knuckle along the axis (at top height)
    for (i = [0 : 2]) {
        a = knuckle_start + i * 120;
        x = knuckle_pcd / 2 * cos(a);
        y = knuckle_pcd / 2 * sin(a);
        translate([x, y, plate_thk + 0.01])
            rotate([0, 90, a + 180])
                cylinder(d = pin_d, h = knuckle_h + 0.01);
    }
}
