hub_h        = 5;     // shaft hub height above disc
shaft_d      = 6;     // shaft through-hole diameter
eps          = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------------- Model ----------------
difference() {
    union() {
        // Cam disc
        translate([cam_x, 0, 0])
            cylinder(d = cam_d, h = cam_t);

        // Shaft hub (overlaps disc slightly for a clean union)
        translate([0, 0, cam_t - hub_h])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }

    // Shaft through-hole, runs through hub and disc
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = cam_t + 2 * eps);
}
