        [for (i = [0 : 7]) [outer_r * cos(i * 45), outer_r * sin(i * 45)]],   // outer
        [for (i = [0 : 7]) [inner_r * cos((i + 0.5) * 45), inner_r * sin((i + 0.5) * 45)]]  // inner
    ));

    // Through-hole in the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);

    // Thin discs at top and bottom to keep the solid thick near the cutters
    translate([0, 0, -eps])
        cylinder(d = outer_r - inner_r + 0.01, h = eps, $fn = 96);
    translate([0, 0, plate_t - eps])
        cylinder(d = outer_r - inner_r + 0.01, h = eps, $fn = 96);
