// Units: mm. Print orientation: flat on bed (z = 0), building upward.

$fn = 96;               // facet count for round features (no curves used)

// ---- Star outline ----
outer_r = 35;           // distance of outer points from centre
inner_r = 21;           // distance of inner points from centre
points  = 8;            // number of outer/inner points (evenly spaced)
pitch   = 360 / points; // angular spacing between outer points
// ---- Plate ----
thickness = 4;          // plate thickness (z = 0 to z = 4)
// ---- Hole ----
hole_d = 8;             // diameter of central through-hole
// ---- Cut clearance ----
eps = 0.5;              // overshoot of cutting shapes past faces

difference() {
    // Star outline: outer points on +X axis, alternating with inner points
    polygon(points = [
        for (i = [0 : points - 1])
            [
                (i % 2 == 0) ? outer_r : inner_r,
                (i % 2 == 0) ? 0 : -inner_r * sqrt(3) / 2
            ]
    ]);

    // Central through-hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
```

