inner_r  = 21;   // distance of inner points from centre
thickness = 4;   // plate thickness
hole_d   = 8;    // central through-hole diameter

point_count = 8; // number of outer/inner points
angle_step  = 360 / point_count; // 45 degrees

// ---- Model ----
difference() {
    linear_extrude(height = thickness) {
        polygon() = concat(
            // Outer points, first on +X axis
            [for (i = [0 : point_count - 1]) 
                [outer_r * cos(i * angle_step), outer_r * sin(i * angle_step)]],
            // Inner points, 22.5 degrees rotated
            [for (i = [0 : point_count - 1]) 
                [inner_r * cos(i * angle_step + angle_step / 2), 
                 inner_r * sin(i * angle_step + angle_step / 2)]]
        );
    }
    // Central hole, extends past top and bottom faces
    translate([0, 0, -1]) cylinder(d = hole_d, h = thickness + 2);
}
