// Star-shaped indexing wheel - 5-pointed flat plate
// Units: mm. Print orientation: flat on bed, z = 0 upward.

$fn = 96;                 // facet count for curves/polygons

// ---- Star dimensions ----
outer_r = 35;             // distance of outer points from centre
inner_r = 17.5;           // distance of inner points from centre
points  = 5;              // number of points (and inner vertices)
angle0  = 0;              // angle of first outer point (deg, +X axis)

// ---- Plate ----
plate_t = 5;              // plate thickness (Z)

// ---- Hole ----
hole_d = 8;               // diameter of central through-hole

// ---- Misc ----
eps = 0.5;                // overshoot for clean boolean cuts

// Derived
alt   = [outer_r, inner_r];   // radii sequence (outer, inner, outer, ...)
step  = 360 / points;         // angular spacing between features

difference() {
    // Star outline: join outer/inner points alternately
    linear_extrude(height = plate_t)
        polygon(points = points * 2,
                r     = alt,
                a     = [for (i = [0 : points - 1])
                         angle0 + i * step + (i % 2) * step]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}
```

```openscad
// Star-shaped indexing wheel - 5-pointed star flat plate
// Print orientation: lying flat on the bed, z = 0 upward

// ---------------- Parameters ----------------
star_points   = 5;    // number of points on the star
outer_radius  = 35;   // distance of outer points from centre (mm)
inner_radius  = 17.5; // distance of inner points from centre (mm)
plate_t       = 5;    // plate thickness (mm)
hole_d        = 8;    // central through-hole diameter (mm)
cut_extra     = 0.5;  // extra length for cutting shapes past faces (mm)
$fn           = 128;  // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline: outer points at 0°, 72°, 144°, ... ; inner points in between
    hull() {
        for (i = [0 : star_points - 1]) {
            rotate([0, 0, i * 360 / star_points])
                translate([outer_radius, 0, 0])
                    cylinder(h = plate_t, $fn = 64);
        }
    }
    // Remove the inner areas between the points (inner radius, not quite centre)
    translate([0, 0])
        linear_extrude(height = plate_t + 2 * cut_extra)
            circle(r = inner_radius - 1, $fn = 96);
    // Central through-hole
    translate([0, 0])
        linear_extrude(height = plate_t + 2 * cut_extra)
            circle(d = hole_d);
}
