// Star-shaped indexing wheel: 5-pointed star, flat plate with central hole
// Print orientation: lying flat on the bed, z = 0 upward

// ---------------- Parameters ----------------
star_points   = 5;    // number of points on the star
outer_radius  = 35;   // distance of outer points from centre (mm)
inner_radius  = 17.5; // distance of inner points from centre (mm)
plate_thick   = 5;    // plate thickness (mm)
hole_d        = 8;    // central hole diameter (mm)
cut_extra     = 0.5;  // extra length on cutting shapes past faces (mm)
fn_curve      = 96;   // facet count for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline: outer points at 0, 72, ... degrees, inner points in between
    hull() {
        for (i = [0 : star_points - 1]) {
            rotate([0, 0, i * 360 / star_points])
                translate([0, 0, -cut_extra])
                    if (i % 2 == 0)
                        cylinder(r = outer_radius, h = plate_thick + 2 * cut_extra, $fn = fn_curve);
                    else
                        cylinder(r = inner_radius, h = plate_thick + 2 * cut_extra, $fn = fn_curve);
        }
    }

    // Central through hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thick + 2 * cut_extra, $fn = fn_curve);
}
