// Star-shaped indexing wheel - 8-pointed flat plate with central hole
// Print orientation: lying flat on the bed (z = 0 up to plate_t)

// ---------- Parameters (mm) ----------
outer_r   = 35;   // distance of the 8 outer points from the centre
inner_r   = 21;   // distance of the 8 inner points from the centre
points    = 8;    // number of spikes (evenly spaced)
plate_t   = 3;    // plate thickness (z: 0 .. 3)
hole_d    = 6;    // diameter of the central through-hole
eps       = 0.5;  // overshoot for clean boolean cuts

$fn = 96;         // curve resolution

// ---------- Model ----------
difference() {
    // Two-circle "flower" profile in XY, extruded to plate_t.
    // With points = 8 and the phase offset, the profile has 8 outer
    // points at radius outer_r and 8 inner points at radius inner_r.
    rotate([0, 0, -atan(0, 1)])
        linear_extrude(height = plate_t)
            circle(d = outer_r + inner_r, $fn = 2 * points);

    // Cutting circles: outer and inner, in phase, so the spikes stay intact.
    for (r = [outer_r, inner_r])
        for (i = [0 : points - 1])
            translate([r * cos(i * 360 / points), r * sin(i * 360 / points), -eps])
                cylinder(d = eps, h = plate_t + 2 * eps);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
