// 5-pointed star indexing wheel
// Outer points 35 mm from centre, inner points 21 mm from centre
// Flat plate 5 mm thick with a 6 mm central hole

// ---- Parameters ----
outer_r   = 35;    // distance to outer points (mm)
inner_r   = 21;    // distance to inner points (mm)
points    = 5;     // number of points
thick     = 5;     // plate thickness (mm)
hole_d    = 6;     // centre hole diameter (mm)
overcut   = 0.5;   // extra length for clean booleans (mm)
$fn       = 96;    // curve resolution

// ---- Model ----
difference() {
    // Star outline, first outer point on +X axis
    polygon(points = points * 2,
            hull_points = [for (i = [0 : points - 1])
                            each [rotate([0, 0, i * 360 / points]) [outer_r, 0],
                                 rotate([0, 0, (i + 0.5) * 360 / points]) [inner_r, 0]]]);

    // Centre hole
    translate([0, 0, -overcut])
        cylinder(d = hole_d, h = thick + 2 * overcut);

    // File rests on the bed at z = 0
    translate([0, 0, -thick])
        linear_extrude(height = thick + overcut)
            polygon(points = points * 2,
                    hull_points = [for (i = [0 : points - 1])
                                    each [rotate([0, 0, i * 360 / points]) [outer_r, 0],
                                         rotate([0, 0, (i + 0.5) * 360 / points]) [inner_r, 0]]]);
}
