                    translate([outer_r, 0, 0]) cube([1, plate_t, 2 * outer_r]);
                    translate([inner_r, 0, 0]) cube([1, plate_t, 2 * inner_r]);
                }
    }
    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
