                union() {
                    translate([outer_r, 0, 0])
                        cylinder(h = plate_t, $fn = 96);
                    translate([inner_r, 0, 0])
                        rotate([0, 0, i * pitch + 180 / points])
                            cylinder(h = plate_t, $fn = 96);
                }
        }
    }
}

difference() {
    // Print the star plate
    star_outline();

    // Cut the central hole, which runs through the full thickness
    translate([0, 0, -eps])
        cylinder(h = plate_t + 2 * eps, d = hole_d, $fn = 96);
}
