// Star-shaped indexing wheel: 5-pointed flat plate
// Print orientation: flat on bed, builds upward in +Z

$fn = 96;

// --- Dimensions (mm) ---
points      = 5;    // number of corners (outer and inner)
outer_r     = 35;   // distance of outer points from centre
inner_r     = 21;   // distance of inner points from centre
thickness   = 5;    // plate thickness
hole_d      = 6;    // central through-hole diameter
cut_extra   = 0.5;  // overshoot for cutting shapes

first_angle = 0;    // first outer point on +X axis

difference() {
    // Star outline: alternate outer/inner points, convex hull
    hull() {
        for (i = [0 : points - 1]) {
            a = first_angle + i * 360 / points;
            // even i -> outer point, odd i -> inner point
            r = (i % 2 == 0) ? outer_r : inner_r;
            translate([r * cos(a), r * sin(a), 0]);
        }
    }

    // Central hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra);
}
