// 8-pointed star: outer points at 0, 45, ... deg; inner points offset by 22.5 deg
module star_outline() {
    clip_radius = outer_r - 2;  // keep vertices inside the bounding box
    polygon(points = concat(
        [for (i = [0 : points - 1])
            [outer_r * cos(start_a + i * 360 / points),
             outer_r * sin(start_a + i * 360 / points))],
        [for (i = [0 : points - 1])
            [inner_r * cos(start_a + (i + 0.5) * 360 / points),
             inner_r * sin(start_a + (i + 0.5) * 360 / points))],
