    // Hull of two coaxial squares gives flat sides at 45 deg and no coplanar faces
    hull() {
        translate([-block_w / 2, -block_w / 2, 0])
            cube([block_w, block_w, 0.01]);
        translate([-block_top_w / 2, -block_top_w / 2, block_h - overcut])
            cube([block_top_w, block_top_w, overcut + 0.01]);
    }

    // Square pocket 70 x 70 and 8 mm deep, centred, cut into the top face
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + overcut]);
