    // Lower tapered section: base 100 -> 109.4, thickness 17.01
    // (the user's 100 mm pocket has a 9.4 mm wall on each side at this height)
    translate([-base_size / 2, -base_size / 2, 0])
        linear_extrude(height = lower_h)
            polygon([
