                [-(base_size / 2 + 9.4), base_size / 2 + 9.4],
                [-(base_size / 2 + 9.4), -(base_size / 2 + 9.4)],
                [ base_size / 2 + 9.4, -(base_size / 2 + 9.4)],
                [ base_size / 2, -base_size / 2]
            ]);

    // Upper tapered section: 109.4 -> 80, thickness 7.99
    translate([-mid_size / 2 - 9.4, -mid_size / 2 - 9.4, height - pocket_d])
        linear_extrude(height = pocket_d + eps)
            polygon([
                [-mid_size / 2 - 9.4, -mid_size / 2 - 9.4],
                [ mid_size / 2 + 9.4, -mid_size / 2 - 9.4],
                [ mid_size / 2 + 9.4,  mid_size / 2 + 9.4],
                [-mid_size / 2 - 9.4,  mid_size / 2 + 9.4]
            ]);
}

// ---------------- Pocket ----------------
