        rotate([0, 0, i * 360 / n])
            translate([0, -hatch_width / 2, t])
                cube([height, hatch_width, 1]);   // extrude along +Z only
    }
}

module pocket() {
    translate([0, 0, pocket_top_z])
        cube([pocket_side, pocket_side, pocket_depth + eps]);
}

difference() {
    frustum();
    pocket();
}
