// Units: mm. Print orientation: bottom face on bed (z = 0).

$fn = 64;

// --- Frustum dimensions ---
bottom_w = 60;   // bottom square side (X and Y)
bottom_h = 0;    // bottom face height (z = 0)
top_w    = 20;   // top square side (X and Y)
top_h    = 20;   // top face height (z = 20)

// --- Pocket dimensions ---
pocket_w   = 12; // pocket square side (X and Y)
pocket_h   = 8;  // pocket depth from top face
pocket_x0  = 4;  // pocket start offset in X (centre: 10 - 12/2)
pocket_y0  = 4;  // pocket start offset in Y (centre: 10 - 12/2)

// --- Overlap for clean booleans ---
eps = 1;         // extension past cut faces

module frustum() {
    // hull of two coaxial squares; sides are flat and angled
    hull() {
        translate([-bottom_w/2, -bottom_w/2, bottom_h])
            cube([bottom_w, bottom_w, bottom_h + 1]);
        translate([-top_w/2, -top_w/2, top_h])
            cube([top_w, top_w, top_h + 1]);
    }
}

module pocket() {
    translate([pocket_x0, pocket_y0, top_h - pocket_h])
        cube([pocket_w, pocket_h, pocket_h + eps]);
}

difference() {
    frustum();
    pocket();
}
```

