// Tapered riser block for setting a beaker higher
// Print orientation: resting on the bed (z = 0), building upward (+Z)
// Positioned: centred on the origin in X and Y

// ---------------- Parameters ----------------
bottom_w    = 60;    // bottom square side (X and Y) at z = 0
bottom_h    = 60;    // bottom square side (Z depth) at z = 0
top_w       = 20;    // top square side (X and Y) at z = 20
top_h       = 20;    // top square side (Z depth) at z = 20
height      = 20;    // block height (z = 0 to z = 20)
pocket_w    = 12;    // square pocket side (X and Y)
pocket_d    = 8;     // square pocket depth from top face
eps         = 0.5;   // overshoot for clean boolean cuts

$fn = 64;            // curve resolution (for consistency)

// ---------------- Model ----------------
difference() {
    // Square frustum: solid square at the bottom, flat sloping sides up to a
    // smaller square top face. The hull of two centred, axis-aligned squares
    // produces faces parallel to X and Y.
    hull() {
        translate([-bottom_w / 2, -bottom_h / 2, 0])
            cube([bottom_w, bottom_h, 0]);
        translate([-top_w / 2, -top_h / 2, height])
            cube([top_w, top_h, height]);
    }

    // Square pocket cut into the top face, centred.
    // The cut extends past the top face so no faces are coplanar.
    translate([-pocket_w / 2, -pocket_d / 2, height - pocket_d])
        cube([pocket_w, pocket_d, pocket_d + eps]);
}
