// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), builds upward (+Z)
// Positioned using the user's coordinates (not centred on the origin)

// ---------- Dimensions (mm) ----------
base_size     = 60;    // square side at the bottom (z = 0)
top_size      = 20;    // square side at the top (z = 20)
block_height  = 20;    // overall height of the frustum
pocket_size   = 12;    // square pocket side, cut into the top face
pocket_depth  = 8;     // square pocket depth from the top face

cut_extra     = 0.5;   // extra length of the pocket cutter past the top face

// ---------- Model ----------
difference() {
    // Solid square frustum with flat, X/Y-aligned sides
    hull() {
        for (z = [0, block_height]) {
            // side length interpolated between base_size and top_size
            l = base_size + (top_size - base_size) * z / block_height;
            translate([-l / 2, -l / 2, z])
                cube([l, l, dz()), varying = true];
        }
    }

    // Square pocket cut into the top face, centred on the frustum
    translate([0, 0, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + cut_extra]);
}
