```openscad
// Tapered riser block with a square pocket
// Print orientation: bottom face (z = 0) on the bed, building upward.
// Positioned per the user's coordinates: x -30..30, y -30..30, z 0..25.

$fn = 64;

// ---- Dimensions (mm) ----
block_h     = 25;    // block height
bottom_w    = 60;    // bottom square side length
top_w       = 30;    // top square side length
pocket_w    = 20;    // pocket side length
pocket_d    = 5;     // pocket depth from top face
eps         = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
pocket_z0   = block_h - pocket_d;                   // pocket floor z
half_ext    = max(eps, (bottom_w - top_w) / 2 / block_h); // side extension per mm height

module risky_hull() {
    // Hull of a fat bottom square and a thinner top square: a square frustum.
    // NOTE: hull() can produce coplanar or self-touching faces for frusta.
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, 0])
            cube([bottom_w, bottom_w, 1]);
        translate([-top_w / 2, -top_w / 2, block_h - 1])
            cube([top_w, top_w, 1]);
    }
}

module frustum() {
    // Extrude a 2D linear taper (2D hull) between the two square profiles.
    // This avoids the coplanar-face issues of hull() in Z.
    translate([0, 0, block_h])
        rotate([90, 0, 0])
            linear_extrude(height = block_h)
                polygon(points = [
                    [-bottom_w / 2 - (half_ext - 1), -bottom_w / 2 - (half_ext - 1)],
                    [-bottom_w / 2 - (half_ext - 1),  bottom_w / 2 + (half_ext - 1)],
                    [ bottom_w / 2 + (half_ext - 1),  bottom_w / 2 + (half_ext - 1)],
                    [ bottom_w / 2 + (half_ext - 1), -(bottom_w / 2 + (half_ext - 1))],
                    [ top_w / 2, -top_w / 2],
                    [-top_w / 2, -top_w / 2],
                    [-top_w / 2, top_w / 2],
                    [ top_w / 2, top_w / 2]
                ]);
}

difference() {
    frustum();

    // Square pocket open at the top face (z = 25)
    translate([0, 0, pocket_z0])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
```

