// Tapered riser block with a square pocket
// Units: mm. Print orientation: base on bed (z = 0), building up +Z.

$fn = 64;               // facet count for round features

// ---- Frustum dimensions ----
base_side    = 60;      // bottom square side length at z = 0
top_side     = 30;      // top square side length at z = 25
height       = 25;      // total height of the frustum
eps          = 0.5;     // small overshoot for clean boolean cuts

// ---- Pocket dimensions ----
pocket_side  = 20;      // square pocket side length
pocket_depth = 5;       // pocket depth from top face

// ---- Derived ----
// Half-width of the block at a given z (linear taper)
function half_w(z) = base_side/2 - (base_side - top_side)/2 * z / height;
// Pocket floor height (pocket bottom is above the lowest third)
pocket_floor_z = height * 1/3;

module square_frustum(s_bottom, s_top, h) {
    // Hull of two square prisms gives a frustum with flat sloping sides,
    // edges parallel to X and Y. The extra height on each prism avoids
    // coplanar faces in the hull.
    hull() {
        translate([-s_bottom/2, -s_bottom/2, 0])
            cube([s_bottom, s_bottom, h + 2*eps]);
        translate([-s_top/2, -s_top/2, h])
            cube([s_top, s_top, h + 2*eps]);
    }
}

difference() {
    square_frustum(base_side, top_side, height);

    // Square pocket centred on the top face, open at the top.
    // Extended above the top face so no faces are coplanar.
    translate([-pocket_side/2, -pocket_side/2, pocket_floor_z])
        cube([pocket_side, pocket_side, pocket_depth + eps]);
}
