extent(z) = half_side(z) + overshoot;

// ---------------- Model ----------------
difference() {
    // Solid square frustum: 80 x 80 at the bottom, 40 x 40 at the top,
    // with flat sloping sides and edges parallel to X and Y.
    translate([0, 0, height])
        rotate([90, 0, 0])
            linear_extrude(height = height)
                polygon([
                    [-extent(0), extent(0)],
                    [ extent(0), extent(0)],
                    [ extent(0), -extent(0)],
                    [-extent(0), -extent(0)]
                ]);

    // Square pocket, centred, cut into the top face
    translate([0, 0, -pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overshoot]);
