// Print orientation: flat on the bed, bottom face at z = 0

// ---------------- Parameters ----------------
base_size   = 80;   // bottom square side length (mm)
top_size    = 40;   // top square side length (mm)
height      = 20;   // block height (mm)
pocket_w    = 32;   // pocket side length (mm)
pocket_d    = 5;    // pocket depth (mm)
eps         = 0.5;  // overshoot for clean boolean cuts (mm)
$fn         = 64;   // curve resolution (not strictly needed for squares)

// ---------------- Model ----------------
difference() {
    // Square frustum: bottom face at z = 0, top face at z = height
    // Sides slope linearly, edges parallel to X and Y
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0]);
        translate([-top_size/2, -top_size/2, height])
            cube([top_size, top_size, height]);
    }

    // Square pocket cut into the top face, centred
    translate([-pocket_w/2, -pocket_w/2, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
```

```openscad
// Tapered riser block for setting a beaker higher
// Print orientation: resting on the bed (z = 0), building upward (+Z)
// Positioned: centred on the origin in X and Y, per user instruction

// ---------------- Parameters ----------------
base_size   = 80;    // bottom square side length (mm)
base_z      = 0;     // bottom face height (mm)
top_size    = 40;    // top square side length (mm)
top_z       = 20;    // top face height (mm)
pocket_w    = 32;    // square pocket side length (mm)
pocket_d    = 5;     // square pocket depth (mm)
overcut     = 0.5;   // extra length for cutting shapes past faces (mm)
$fn         = 64;    // curve resolution (for consistency)

// ---------------- Derived ----------------
// Frustum side length at an arbitrary height h between base_z and top_z
alpha = (top_size - base_size) / 2 / (top_z - base_z);   // taper rate per mm
function side(h) = base_size - 2 * alpha * (h - base_z);

// ---------------- Model ----------------
difference() {
    // Solid square frustum: bottom face at z = 0, top face at z = 20
    // rotate([90,0,0]) maps the 2D profile (x, y) to (y, x, z),
    // so the for loop runs along +Z and every slice is a horizontal square
    rotate([90, 0, 0])
        linear_extrude(height = top_z - base_z)
            for (h = [base_z : 1 : top_z])
                polygon([[-side(h) / 2, -side(h) / 2],
                         [side(h) / 2, -side(h) / 2],
                         [side(h) / 2, side(h) / 2],
                         [-side(h) / 2, side(h) / 2]]);

    // Square pocket cut into the top face, centred
    // Top face is at z = 20; the pocket runs from z = 15 up to z = 20.5 (overcut)
    translate([0, 0, top_z - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + overcut]);
}
```

```openscad
// Tapered riser block - square frustum with top pocket
// Units: mm

$fn = 64;

// --- Block dimensions ---
bottom_w = 80;    // base square side
bottom_h = 20;    // block height (z = 0 to 20)
top_w    = 40;    // top square side

// --- Pocket dimensions ---
pocket_w = 32;    // pocket square side
pocket_d = 5;     // pocket depth from top face

// --- Derived ---
twist = bottom_w - top_w;   // total taper per side
gove  = max(0, bottom_h - pocket_d - 1);  // thickness below pocket

module frustum() {
    hull() {
        translate([-bottom_w/2, -bottom_w/2, 0])
            cube([bottom_w, bottom_w, 0]);
        translate([-top_w/2, -top_w/2, bottom_h])
            cube([top_w, top_w, bottom_h]);
    }
}

difference() {
    union() {
        frustum();
        // through-pocket if the frustum is thick enough
        if (gove > 1)
            translate([0, 0, 1])
                cube([pocket_w, pocket_w, bottom_h + 2 - 1]);
    }
    // tapered pocket cavity
    translate([0, 0, bottom_h - pocket_d - 1])
        linear_extrude(height = pocket_d + 1)
            polygon([
                [-pocket_w/2 - twist/2, -pocket_w/2 - twist/2],
                [ pocket_w/2 + twist/2, -pocket_w/2 - twist/2],
                [ pocket_w/2 + twist/2,  pocket_w/2 + twist/2],
                [-pocket_w/2 - twist/2,  pocket_w/2 + twist/2]
            ]);
}
