```openscad
// Tapered riser block for setting a beaker higher
// Print orientation: resting on the bed (z = 0), building upward (+Z)
// Positioned: centred on the origin in X and Y, per the user's instruction

// ---------- Dimensions (mm) ----------
base_size      = 80;    // bottom square side length (z = 0)
base_area      = base_size * base_size;                        // 6400 mm2
top_size       = 40;    // top square side length (z = 20)
top_area       = top_size * top_size;                          // 1600 mm2
height         = 20;    // block height (z = 0 to z = 20)
pocket_size    = 32;    // square pocket side length on top face
pocket_depth   = 5;     // square pocket depth from top face
overcut        = 0.5;   // extra cut length past faces (avoids coplanar faces)

// ---------- Model ----------
difference() {
    // Square frustum: bottom face at z = 0, top face at z = height
    // Hull of two rectangles drawn in XY, extruded along Z.
    // rotate([90,0,0]) maps the 2D (u,v) hull to (x,y), and the
    // extrusion axis to +Z, so the extrusion runs from z = 0 to z = 20.
    rotate([90, 0, 0])
        linear_extrude(height = height)
            hull() {
                translate([-base_size / 2, -base_size / 2])
                    square(base_area);
                translate([-top_size / 2, -top_size / 2])
                    square(top_area);
            }

    // Square pocket, centred on the top face, cut downward.
    // Extends past the face by 'overcut' so no faces are exactly coplanar.
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overcut]);
}
```

