```openscad
// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), centred on the origin in X and Y

// ---------------- Parameters ----------------
block_height = 20;    // total height of the frustum (mm)
bottom_w     = 80;    // side length of the square at the bottom (mm)
top_w        = 40;    // side length of the square at the top (mm)

pocket_size  = 32;    // side length of the square pocket (mm)
pocket_depth = 5;     // depth of the pocket cut into the top face (mm)

eps          = 0.5;   // overshoot for the cutting shape (mm)
$fn          = 64;    // curve resolution (not strictly needed for squares)

// ---------------- Model ----------------
difference() {
    // Square frustum with flat, sloping sides
    // The sides run from the bottom corners up to the top corners,
    // so the profile is extruded along Z and the corners stay sharp.
    linear_extrude(height = block_height)
        polygon(points = [
            [-bottom_w / 2, -bottom_w / 2],
            [ bottom_w / 2, -bottom_w / 2],
            [ bottom_w / 2,  bottom_w / 2],
            [-bottom_w / 2,  bottom_w / 2]
        ]);

    // Square pocket in the top face, centred, open to the top
    translate([
        -pocket_size / 2,
        -pocket_size / 2,
        block_height - pocket_depth
    ])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
