// Pull handle for a cabinet door
// Print orientation: posts stand on the bed (z = 0), bar on top.

$fn = 64;

// ---- Dimensions (mm) ----
post_d      = 14;    // round post diameter
post_h      = 25;    // post height (z = 0 to 25)
post_x      = [-48, 48]; // post axes at x = -48 and x = 48 (y = 0)
bar_len     = 110;   // bar length along X
bar_w       = 14;    // bar width along Y
bar_t       = 8;     // bar thickness (z = 25 to 33)
screw_d     = 4.5;   // screw hole diameter
screw_depth = 12;    // screw hole depth from bottom face of posts
eps         = 0.5;   // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    union() {
        // Posts
        for (x = post_x)
            translate([x, 0, 0])
                cylinder(d = post_d, h = post_h);
        // Bar
        translate([-bar_len/2, -bar_w/2, post_h])
            cube([bar_len, bar_w, bar_t]);
    }
    // Screw holes, extend past bottom face
    for (x = post_x)
        translate([x, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + eps);
}
