```openscad
// Pull handle for a cabinet door
// Print orientation: posts stand on the bed (z = 0), bar on top (z = 25..33)

$fn = 64;

// ---- Dimensions (mm) ----
post_d      = 14;    // post diameter
post_h      = 25;    // post height (z = 0 to 25)
post_x      = [-48, 48]; // post axes in X, y = 0
bar_len     = 110;   // bar length along X
bar_w       = 14;    // bar width along Y
bar_t       = 8;     // bar thickness (z = 25 to 33)
screw_d     = 4.5;   // screw hole diameter
screw_depth = 12;    // screw hole depth from bottom face
overlap     = 0.01;  // small overlap to fuse bar into posts

// ---- Model ----
union() {
    // Posts with screw holes
    for (x = post_x)
        translate([x, 0, 0])
            difference() {
                cylinder(d = post_d, h = post_h);
                translate([0, 0, -overlap])
                    cylinder(d = screw_d, h = screw_depth + 2 * overlap);
            }

    // Straight bar, slightly sunk into the posts
    translate([-bar_len / 2, -bar_w / 2, post_h - overlap])
        cube([bar_len, bar_w, bar_t + overlap]);
}
