```openscad
// Pull handle for a cabinet door
// Print orientation: posts stand on the bed (z = 0), bar on top.

$fn = 64;

// ---- Posts ----
post_d     = 14;    // post diameter
post_h     = 25;    // post height (z = 0 to 25)
post_x     = 48;    // post centre offset from origin (+/-)
post_y     = 0;     // post centre Y position
post_fn    = 64;    // facets for posts

// ---- Bar ----
bar_len    = 110;   // bar length along X
bar_w      = 14;    // bar width along Y
bar_t      = 8;     // bar thickness (z = 25 to 33)
bar_fn     = 64;    // facets for bar (if curved)

// ---- Screw holes ----
screw_d    = 4.5;   // screw hole diameter
screw_h    = 12;    // screw hole depth from bottom face
eps        = 0.5;   // overshoot for clean boolean cuts

// Derived
overlap    = 0.01;  // small overlap so bar fuses with posts

module post() {
    cylinder(d = post_d, h = post_h, $fn = post_fn);
}

module bar() {
    translate([-bar_len/2, -bar_w/2, post_h - overlap])
        cube([bar_len, bar_w, bar_t + overlap]);
}

difference() {
    union() {
        // Two posts
        for (sx = [-1, 1])
            translate([sx * post_x, post_y, 0])
                post();
        // Bar on top
        bar();
    }
    // Screw holes, extend past top face in case the overlap shifts
    for (sx = [-1, 1])
        translate([sx * post_x, post_y, -eps])
            cylinder(d = screw_d, h = post_h + 2 * eps);
}
```

