screw_d     = 4.5;   // screw hole diameter
screw_depth = 10;    // screw hole depth from bottom face
overlap     = 0.5;   // bar overlap into posts for a clean union

$fn = 64;

// ---- Model ----
union() {
    // Posts
    for (s = [-1, 1])
        translate([s * post_x, 0, 0])
            cylinder(d = post_d, h = post_h);

    // Bar (extends into posts by 'overlap' so no faces are coplanar)
    translate([-bar_len / 2 - overlap, -bar_w / 2, post_h - overlap])
        cube([bar_len + 2 * overlap, bar_w, bar_t + overlap]);

    // Screw holes
    for (s = [-1, 1])
        translate([s * post_x, 0, 0])
            difference() {
                cylinder(h = post_h + 1);   // slightly taller than the post
                translate([0, 0, -1])
                    cylinder(d = screw_d, h = screw_depth + 2);
            }
}
