```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness = 4;     // specimen thickness (Z)
total_len = 140;   // overall length along X
gauge_w   = 6;     // gauge section width (Y)
gauge_len = 50;    // gauge section length (X)
grip_w    = 19;    // grip section width (Y)
grip_len  = 35;    // grip section length (X)
trans_len = 10;    // transition section length (X)
$fn = 64;

// ---------- Derived ----------
left_grip_x0 = -(total_len / 2) + grip_len / 2;      // grip start X
right_grip_x0 = total_len / 2 - grip_len / 2;        // grip end X

// ---------- Model ----------
module width(x) {
    if (x < left_grip_x0) {
        // left grip
        return grip_w;
    } else if (x <= left_grip_x0 + trans_len) {
        // left transition: linear change grip_w -> gauge_w
        return grip_w + (gauge_w - grip_w) * (x - left_grip_x0) / trans_len;
    } else if (x <= left_grip_x0 + trans_len + gauge_len) {
        // gauge section
        return gauge_w;
    } else if (x < right_grip_x0) {
        // right transition: linear change gauge_w -> grip_w
        return gauge_w + (grip_w - gauge_w) * (x - (left_grip_x0 + trans_len + gauge_len)) / trans_len;
    } else {
        // right grip
        return grip_w;
    }
}

difference() {
    hull() {
        for (sx = [-1, 1])
            translate([sx * (total_len / 2 - grip_len / 2 - trans_len), -grip_w / 2, 0])
                cube([grip_len + trans_len, grip_w, thickness]);
    }
    // extend cutter past end faces
    translate([-total_len / 2 - 1, -grip_w / 2 - 1, -1])
        cube([total_len + 2, grip_w + 2, thickness + 2]);
}
```

```openscad
// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, centred on the origin

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 140;   // overall length along X (mm)
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
overlap     = 1;     // overlap between adjacent blocks for a clean union (mm)

$fn = 64;

// ---------- Derived ----------
centre_x    = 0;
right_end_x = total_len / 2;
left_end_x  = -right_end_x;

// ---------- Model ----------
union() {
    // Left grip
    translate([left_end_x, -grip_w / 2, 0])
        cube([grip_len, grip_w, thickness]);

    // Left transition (tapering from grip width to gauge width)
    translate([left_end_x + grip_len - trans_len, -grip_w / 2, 0])
        linear_extrude(height = thickness)
            polygon([
                [0, -grip_w / 2],
                [trans_len, -gauge_w / 2],
                [trans_len, gauge_w / 2],
                [0, gauge_w / 2]
            ]);

    // Gauge section
    translate([-gauge_len / 2, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, thickness]);

    // Right transition (tapering from gauge width to grip width)
    translate([right_end_x - grip_len + trans_len, -gauge_w / 2, 0])
        linear_extrude(height = thickness)
            polygon([
                [0, -gauge_w / 2],
                [trans_len, -grip_w / 2],
                [trans_len, grip_w / 2],
                [0, grip_w / 2]
            ]);

    // Right grip
    translate([right_end_x - grip_len, -grip_w / 2, 0])
        cube([grip_len, grip_w, thickness]);
}
