// Dog-bone tensile specimen, printed flat on the bed
// Units: mm. Print orientation: bottom face on z = 0, building up +Z.

// ---- Dimensions ----
spec_length    = 140;   // overall length along X
spec_thickness = 4;     // flat thickness (Z)

// Grip end blocks
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length along X

// Gauge (narrow) section
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length along X

// Transitions between grip and gauge
transition_length = 10; // transition length along X (each side)

// ---- Model ----
difference() {
    // Outer envelope: grip -> transition -> gauge -> transition -> grip
    hull() {
        for (s = [-1, 1]) {
            translate([s * (grip_length + transition_length), -grip_width / 2, 0])
                cube([grip_length, grip_width, spec_thickness]);
        }
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, spec_thickness]);
    }

    // Straight core running through the centre (removes the solid diagonals,
    // leaving a flat ring with a narrow gauge strip in the middle).
    translate([-spec_length / 2, -gauge_width / 2, -1])
        cube([spec_length, gauge_width, spec_thickness + 2]);
}
