        for (s = [-1, 1])
            translate([s * (total_len / 2 - grip_len), -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
        // gauge section
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);
        // transition sections
        for (s = [-1, 1])
            translate([s * (total_len / 2 - grip_len - trans_len), -a / 2, 0])
                cube([trans_len, a, thickness]);
