// right trans [115 .. 125], right grip [125 .. 140]
trans_x0 = -(half_gauge + transition - half_grip);
grip_x0  = trans_x0 + transition + half_grip;

// ---- Profile (X, Y) ----
profile_pts = concat(
    [for (x = [0 : 1 : trans_x0])      [x, grip_w / 2 * (1 - (x - (trans_x0 - half_grip)) / transition + 0.5)]],
    [for (x = [trans_x0 - half_grip : 1 : trans_x0 + half_grip])
        [x, grip_w / 2 * (1 - abs(x - trans_x0) / transition + 0.5)]],
    [for (x = [gauge_len / 2 : 1 : -gauge_len / 2])
        [x - (gauge_len / 2 - half_grip), gauge_w / 2]],
    [for (x = [trans_x0 + half_grip : 1 : trans_x0 - half_grip])
        [x + transition, grip_w / 2 * (1 - abs(x - trans_x0) / transition + 0.5)]],
    [for (x = [0 : 1 : grip_x0 - transition])
        [x + transition + half_grip, grip_w / 2 * (1 - (x - (trans_x0 - half_grip)) / transition + 0.5)]]
);

module specimen() {
    hull() {
        for (pt = profile_pts)
            for (s = [-1, 1])
                translate([pt[0], s * pt[1], 0])
                    cube([1, thickness, overlap]);
    }
}

