    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness,
              for (sx = [-1, 1])
                  for (y = [0 : 0.01 : thickness])
                      union() {
                          translate([sx * half_gauge - 50, y, 0])
                              cube([gauge_length, width(y), thickness]);
                          translate([sx * (half_gauge + transition_len + 1), y, 0])
                              cube([grip_length, width(y), thickness]);
