// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: lying flat on the bed, centred on the origin.
// Builds upward in +Z.

// ---------- Dimensions (mm) ----------
specimen_length = 140;   // overall length along X
thickness       = 4;     // specimen thickness (Z)

grip_length     = 35;    // length of each grip section (X)
grip_width      = 19;    // width of each grip section (Y)

gauge_length    = 50;    // length of the narrow gauge section (X)
gauge_width     = 6;     // width of the narrow gauge section (Y)

transition_len  = 10;    // length of each grip-to-gauge transition (X)
// transition width changes linearly from grip_width (at the grip)
// to gauge_width (at the gauge); the curve is drawn over grip_len
// so the ends sit exactly at the grip boundaries.

// ---------- Derived ----------
half_gauge = gauge_length / 2;              // gauge end points: +/- half_gauge
grip_start = half_gauge + transition_len;   // outer edge of the gauge / start of grips

// ---------- Model ----------
module dog_bone() {
    // Profile in the XY plane, extruded along Z.
    profile() {
        hull() {
            // Left grip section
            translate([-grip_length, -grip_width / 2]) square([grip_length, grip_width]);
            // Right grip section
            translate([grip_start, -grip_width / 2]) square([grip_length, grip_width]);
            // Gauge section with straight-sided transition (45 degree walls)
            linear_extrude(height = transition_len)
                polygon([
                    [0, gauge_width],
                    [transition_len, gauge_width + transition_len],
                    [half_gauge + transition_len, gauge_width + transition_len],
                    [half_gauge + transition_len, 0],
                    [-(half_gauge + transition_len), 0],
                    [-(half_gauge + transition_len), gauge_width + transition_len],
                    [-(transition_len), gauge_width + transition_len]
                ]);
        }
    }
    // Centre the part in X and Y before extruding it 4 mm high
    translate([0, 0, -thickness]) cube([specimen_length, 0, thickness]);
}

dog_bone();
