grip_x0   = -(total_length / 2 + grip_length / 2);   // grip left edge X
grip_x1   =  total_length / 2 - grip_length / 2;     // grip right edge X
x0        = grip_x1 + transition_len;                 // gauge start X
x1        = x0 + gauge_length;                        // gauge end X
x2        = x1 + transition_len;                      // right grip start X

// ---------- Model ----------
module width(y) {
    // width at a given Y, constant along X within each region
    if (y < 0 || y >= thickness) return 0;
    if (x0 <= X && X < x1)       return gauge_width;
    return grip_width;
}

module side_profile() {
    // X-Y profile (through thickness), drawn in 2D then extruded in Z
    polygon(points = [
        [grip_x0, 0], [grip_x0, grip_width],
        [x2,      grip_width], [x2, 0],
        [total_length / 2, 0], [-total_length / 2, 0]
    ]);
}

// Linearize the dog-bone shape and thicken it
linear_extrude(height = thickness) {
    hull() {
        for (s = [-1, 1])
            rotate([0, 0, s * 90])
                translate([0, grip_length / 2, 0])
                    cylinder(h = total_length, d = grip_width);
    }
}

difference() {
    module() {
        hull() {
            for (s = [-1, 1])
                rotate([0, 0, s * 90])
                    translate([0, grip_length / 2, 0])
                        cylinder(h = total_length, d = grip_width);
        }
    }

    // Central gauge pocket: extends past top and bottom faces
    translate([x0 - 1, -gauge_width / 2 - 1, -1])
        cube([gauge_length + 2, gauge_width + 2, thickness + 2]);
