        for (sx = [-1, 1])
            translate([sx * (overall / 2 - A / 2), -A / 2, 0])
                cube([trans_l, A, h + eps]);
        // gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, h + eps]);
    }
