// ---- Model ----
difference() {
    // Solid plate
    linear_extrude(thickness)
        polygon([
            // left grip
            [-(total_len / 2 + grip_len), -grip_w / 2],
            [-(total_len / 2 + grip_len),  grip_w / 2],
            // left transition
            for (t = [0 : trans_len / 2])
                [-(total_len / 2 + grip_len - t), -gauge_w / 2 * (1 - t / (trans_len / 2)) - (grip_w - gauge_w) / 2 * t / (trans_len / 2)],
                [-(total_len / 2 + grip_len - t),  gauge_w / 2 * (1 - t / (trans_len / 2)) + (grip_w - gauge_w) / 2 * t / (trans_len / 2)],
            // gauge
            [-(total_len / 2 - gauge_len / 2), -gauge_w / 2],
            [ total_len / 2 - gauge_len / 2,  gauge_w / 2],
            // right transition
            for (t = [0 : trans_len / 2])
                [ total_len / 2 - grip_len + t, -gauge_w / 2 * (1 - t / (trans_len / 2)) - (grip_w - gauge_w) / 2 * t / (trans_len / 2)],
                [ total_len / 2 - grip_len + t,  gauge_w / 2 * (1 - t / (trans_len / 2)) + (grip_w - gauge_w) / 2 * t / (trans_len / 2)],
            // right grip
            [ total_len / 2 - grip_start, -grip_w / 2],
            [ total_len / 2 - grip_start,  grip_w / 2]
        ]);

    // Gauge section cut
    translate([-gauge_len / 2, -gauge_w / 2 - eps, 0])
        cube([gauge_len, gauge_w + 2 * eps, thickness + 2 * eps]);

    // Grip sections cut
    for (x = [-1, 1])
        translate([x * (total_len / 2 - grip_len), -grip_w / 2 - eps, 0])
            cube([grip_len, grip_w + 2 * eps, thickness + 2 * eps]);
}
