hull_pts_x1   = [0, 0, 0, 0];          // hull layer at z = thickness
transition(w0, w1, x0) =
    concat([[x0 - trans_len / 2, -w0 / 2],
            [x0 - trans_len / 2,  w0 / 2],
            [x0 + trans_len / 2,  w1 / 2],
            [x0 + trans_len / 2, -w1 / 2]]);

// ---------- Model ----------
difference() {
