// ---------------- Parameters ----------------
specimen_length = 120;   // overall length in X
thickness       = 4;     // specimen thickness in Z
$fn             = 64;    // curve resolution (no curves here; kept per convention)

// Grip end sections
grip_width      = 19;    // grip width in Y
grip_length     = 35;    // grip length in X (each end)

// Gauge section (narrow middle)
gauge_width     = 8;     // gauge width in Y
gauge_length    = 30;    // gauge length in X

// Transition regions between grip and gauge
