// Check: 2*grip_length + gauge_length + 2*transition_length = 120

// ---------------- Model ----------------
module dogbone() {
    // Profile drawn in 2D (X, Y), then extruded along Z
    linear_extrude(height = thickness) {
        hull() {
            // Left grip block
            translate([-half_length, -grip_width / 2])
                square([grip_length, grip_width]);

            // Right grip block
            translate([half_length - grip_length, -grip_width / 2])
                square([grip_length, grip_width]);

            // Gauge section (removed from the grip blocks, leaving only the transitions)
            translate([-half_length + grip_length + transition_length, -gauge_width / 2])
                cube([gauge_length, gauge_width]);
        }
    }
}

