// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z, centred on origin in X/Y

// ---- Dimensions (mm) ----
thickness = 3;     // plate thickness (Z)
total_len = 120;   // overall length along X
gauge_w   = 8;     // gauge section width (Y)
gauge_l   = 30;    // gauge section length (X)
grip_w    = 15;    // grip section width (Y)
grip_l    = 35;    // grip section length (X)
trans_l   = 10;    // transition section length (X)
eps       = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---- Derived ----
a      = grip_w / 2;   // half-width of grip (15 -> 8 over 10 mm: slope 7/20)
end_x  = grip_l + trans_l;   // grip end at x = 45
area   = gauge_w * thickness;

// Width profile of the outer hull at a given X
function hull_w(x) =
    if (x < 0)
        a - (x + end_x) * (a - gauge_w / 2) / trans_l;   // left transition
    else if (x < trans_l)
        gauge_w / 2;                                      // gauge
    else
        a - (x - trans_l) * (a - gauge_w / 2) / trans_l;  // right transition

difference() {
    // Outer plate
    linear_extrude(height = thickness)
        translate([-end_x, -a, 0])
            hull() {
                for (dx = [trans_l, 2 * trans_l])
                    translate([dx - end_x, 0])
                        rotate([0, 90, 0])
                            linear_extrude(height = trans_l)
                                polygon(points = [
                                    [-trans_l / 2, -hull_w(0)],
                                    [ trans_l / 2, -hull_w(0)],
                                    [ trans_l / 2,  hull_w(0)],
                                    [-trans_l / 2,  hull_w(0)]
                                ]);
            }

    // Central groove (overcuts into grips for a clean break)
    translate([-gauge_l / 2 - eps, -a - eps, -eps])
        cube([gauge_l + 2 * eps, gauge_w + 2 * eps, thickness + 2 * eps]);
}
