// Dog-bone tensile specimen - flat bar with a central narrow section
// Print orientation: lying flat on the bed, builds up in +Z

// ---------- Dimensions (mm) ----------
total_len     = 120;   // overall length along X
thickness     = 3;     // bar thickness (Z)
gauge_len     = 30;    // central gauge section length (X)
gauge_width   = 8;     // gauge section width (Y)
grip_len      = 35;    // end grip section length (X)
grip_width    = 15;    // grip section width (Y)
transition_len = 10;   // length of each grip-to-gauge transition
eps           = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
a      = grip_width;     // major width (grip)
b      = gauge_width;    // minor width (gauge)
L      = total_len;      // total length
L_t    = grip_len + gauge_len + grip_len;   // visible length (100)
R      = (a - b) / 2;    // half-width difference
k      = transition_len / R; // radius of curvature for the ends

// ---------- Model ----------
difference() {
    // Visible body: grip sections and central gauge section
    union() {
        // left grip
        translate([-L_t / 2, -a / 2, 0]) cube([grip_len, a, thickness]);
        // gauge section
        translate([-gauge_len / 2, -b / 2, 0]) cube([gauge_len, b, thickness]);
        // right grip
        translate([gauge_len / 2, -a / 2, 0]) cube([grip_len, a, thickness]);
    }

    // blind cutter, stops inside the grip ends
    translate([-L / 2 - eps, -R - eps, -eps])
        cylinder(h = transition_len + eps, r = k, $fn = 64);   // left transition
    translate([L / 2 - eps, -R - eps, -eps])
        cylinder(h = transition_len + eps, r = k, $fn = 64);   // right transition
}
