function w(x) =
    abs(x) < reach       ? (half_grip + half_gauge) / 2 + (half_gauge / 2) * (1 - abs(x - (total_len / 2 - trans_len)) / trans_len) :
    abs(x) < grip_len    ? half_grip :
    1 / 0;

