        for (s = [-1, 1])
            translate([s * reach, -w(reach), 0])
                cube([trans_len + grip_len, 2 * w(reach), thickness]);
    }

    // Gauge cutter
    translate([-gauge_len / 2, -half_gauge - eps, -eps])
        cube([gauge_len, 2 * (half_gauge + eps), thickness + 2 * eps]);
