// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
end_x = -total_length / 2;

module grip(x0) {
    translate([x0, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);
}

module transition(x0, x1, w0, w1) {
    // w0 at x0, w1 at x1, linear change in width
    translate([x0, -w0 / 2, 0])
        linear_extrude(thickness)
            polygon([
                [0, 0], [transition_len, 0],
                [0, 0], [transition_len, w0],
                [0, w0], [transition_len, w1],
                [transition_len, w1], [0, w1]
            ]);
}

difference() {
    union() {
        grip(end_x);
        translate([end_x + grip_length + transition_len, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        translate([end_x + grip_length + 2 * transition_len, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    }
    // Cut out the two transition volumes to leave the grip and gauge sections only
    translate([end_x + grip_length, -grip_width / 2, -1])
        cube([transition_len, grip_width, thickness + 2]);
    translate([end_x + 2 * (grip_length + transition_len), -grip_width / 2, -1])
        cube([transition_len, grip_width, thickness + 2]);
}
