                translate([-55, -grip_width / 2]) square([grip_length, grip_width]);
                // right grip
                translate([x_end, -grip_width / 2]) square([grip_length, grip_width]);

                // transitions down to gauge
                translate([x_start - half_trans, -gauge_width / 2])
                    square([transition_length, gauge_width]);

                // gauge section (middle)
                translate([-overall_length / 2 + 2 * half_trans, -gauge_width / 2])
                    square([gauge_length, gauge_width]);

                // transitions back up to gauge
                translate([x_end + half_trans, -gauge_width / 2])
                    square([transition_length, gauge_width]);
            }
