// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Dimensions ----------
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

eps            = 0.5;   // overlap for clean booleans / union

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([-total_length/2 + grip_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions: grip width -> gauge width
        for (sx = [-1, 1])
            translate([sx > 0 ? -gauge_length/2 : -transition_len,
                       -grip_width/2, 0])
                rotate([0, 0, sx > 0 ? 180 : 0])
                    translate([-transition_len/2, -gauge_width/2, 0])
                        cube([transition_len, grip_width, thickness]);
    }

    // Cut down grip end blocks by eps so they are not coplanar with the
    // far ends of the part (avoid zero-volume faces at the extremes).
    for (sx = [-1, 1])
        translate([sx > 0 ? total_length/2 - grip_length/2 : -total_length/2 + grip_length/2,
                   -grip_width/2, 0])
            cube([grip_length - eps, grip_width, thickness]);
}
