$fn = 64;

// ---- Dimensions (mm) ----
thickness     = 4;     // specimen thickness
totalLength   = 150;   // overall length along X
gaugeWidth    = 8;     // gauge section width (Y)
gaugeLength   = 50;    // gauge section length (X)
gripWidth     = 20;    // grip section width (Y)
gripLength    = 35;    // grip section length (X)
transitionLen = 15;    // length of each grip-gauge transition
cutExtra      = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
gripX0        = -totalLength/2 + gripLength;   // grip start X
midX          = totalLength/2 - gripLength;    // gauge start X (if no transition)

// ---- Model ----
difference() {
    // Contour seen from above, extruded through thickness
    linear_extrude(height = thickness)
        hull() {
            for (s = [-1, 1]) {
                translate([0, s * gripWidth/2])
                    polygon([
                        [gripX0, 0],
                        [gripX0 + gripLength, 0],
                        [midX + (1 - s*2)*transitionLen, gripWidth/2],
                        [midX + (1 - s*2)*transitionLen, -gaugeWidth/2],
                        [midX + s*2*transitionLen, -gaugeWidth/2],
                        [midX + s*2*transitionLen, gaugeWidth/2],
                        [totalLength/2 - (1 - s*2)*transitionLen, gripWidth/2],
                        [totalLength/2 - (1 - s*2)*transitionLen, -gripWidth/2]
                    ]);
            }
        }

    // Straight grip-to-gauge cutter (ignores transition regions)
    translate([-cutExtra, 0, 0])
        cube([totalLength + 2*cutExtra, gripWidth/2 + cutExtra, thickness + 2*cutExtra]);
}
