        for (s = [-1, 1])
            translate([s * (gaugeLen / 2 + transLen) - gripLen / 2, -a / 2, 0])
                cube([gripLen, a, thickness]);
        // tapered middle
        translate([-L / 2, -b / 2, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0,      (a - b) * 0.5],
                        [L / 2,  (a - b) * 0.5],
                        [L / 2,  -(a - b) * 0.5],
                        [-L / 2, -(a - b) * 0.5]
                    ]);
    }
