```openscad
// Dog-bone tensile specimen
// Print orientation: flat on bed, centred on origin in X/Y

// ---------------- Parameters ----------------
thickness   = 4;     // specimen thickness (Z)
total_len   = 150;   // overall length along X (mm)
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Derived ----------------
a     = grip_w;      // end width (grip)
d     = gauge_w;     // middle width (gauge)
L     = gauge_len;   // middle length
n     = trans_len;   // transition length
l0    = grip_len;    // grip length
l     = total_len;   // specimen length

// ---------------- Model ----------------
difference() {
    // Outer envelope: grip --> transition --> gauge --> transition --> grip
    hull() {
        translate([-l/2 + l0, -a/2, 0])
            linear_extrude(height = thickness)
                rectangle([l0, a]);
        for (s = [-1, 1])
            translate([s * (l/2 - n), -a/2, 0])
                linear_extrude(height = thickness)
                    rectangle([n, a]);
        translate([-l/2 + n, -d/2, 0])
            linear_extrude(height = thickness)
                rectangle([L, d]);
        for (s = [-1, 1])
            translate([s * (l/2 - n), -d/2, 0])
                linear_extrude(height = thickness)
                    rectangle([n, d]);
        translate([l/2 - l0, -a/2, 0])
            linear_extrude(height = thickness)
                rectangle([l0, a]);
    }

    // Centroidal through-cut along X
    translate([-l/2 - eps, 0, -eps])
        cube([l + 2 * eps, thickness + 2 * eps, 2 * eps]);
}
