// Flat dog-bone tensile specimen
// Units: mm. Print orientation: flat on bed, z = 0 upward.

$fn = 64;

// ---- Dimensions ----
thickness   = 4;     // specimen thickness (Z)
total_len   = 150;   // overall length along X
gauge_len   = 50;    // gauge section length (X)
gauge_w     = 8;     // gauge section width (Y)
grip_len    = 35;    // grip section length (X)
grip_w      = 20;    // grip section width (Y)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

// Check: 2*grip_len + gauge_len + 4*trans_len = 150
assert(abs(2*35 + 50 + 4*15 - 150) < 0.01, "length mismatch");

// ---- Model ----
difference() {
    // Outer outline
    hull() {
        // Left grip
        translate([-total_len/2, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);
        // Left transition (20 -> 8)
        translate([-total_len/2 + grip_len, -grip_w/2, 0])
            cube([trans_len, grip_w, thickness]);
        // Gauge section
        translate([-total_len/2 + grip_len + trans_len, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);
        // Right transition (8 -> 20)
        translate([-total_len/2 + grip_len + trans_len + gauge_len, -gauge_w/2, 0])
            cube([trans_len, grip_w, thickness]);
        // Right grip
        translate([-total_len/2 + grip_len + trans_len + gauge_len + trans_len, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);
    }

    // Central through-hole, overshoot past top/bottom faces
    translate([-gauge_len/2, -eps, -eps])
        cube([gauge_len, gauge_w + 2*eps, thickness + 2*eps]);
}
