// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 150;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
overcut     = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
a = grip_w;       // grip width
b = gauge_w;      // gauge width
L = total_len;    // total length
l = gauge_len;    // gauge length

// ---------- Model ----------
difference() {
    // Union of grip, gauge and transition blocks
    union() {
        // grip
        translate([-L/2 + grip_len/2, -a/2, 0])
            cube([grip_len, a, thickness]);
        // gauge
        translate([-L/2 + grip_len + trans_len + l/2, -b/2, 0])
            cube([l, b, thickness]);
        // transition
        translate([-L/2 + grip_len/2, -a/2, 0])
            cube([trans_len, a, thickness]);
        translate([-L/2 + grip_len + trans_len + l/2, -b/2, 0])
            cube([trans_len, b, thickness]);
    }

    // Remove the overlapping volume between grip and transition (duplicated)
    translate([-L/2 + grip_len/2 - overcut, -a/2, 0])
        cube([trans_len + 2*overcut, a, thickness]);
}
