// ---------- Profile (top face) ----------
module profile() {
    // Grip section at left end
    translate([-outer_x, -grip_width / 2])
        cube([grip_length, grip_width, 0]);
    // Grip section at right end
    translate([outer_x, -grip_width / 2])
        cube([grip_length, grip_width, 0]);
    // Central gauge section
    translate([-half_gauge, -gauge_width / 2])
        cube([gauge_length, gauge_width, 0]);
    // Transitions (width changes linearly from grip width to gauge width)
    for (s = [-1, 1]) {
        x0 = s > 0 ? outer_x - transition_len : -outer_x + transition_len;
        w0 = grip_width;
        w1 = gauge_width;
        for (t = [0 : 0.01 : 1]) {
            w = w0 + (w1 - w0) * t;
            translate([x0 + s * t * transition_len, -w / 2])
                cube([transition_len, w, 0]);
        }
    }
}

// ---------- Part ----------
difference() {
    // Main body
    linear_extrude(height = thickness)
        profile();

    // Remove a small overlap so no faces are coplanar
    translate([-total_length / 2 - 1, -100, -1])
        cube([2, 200, 2]);
}
