```openscad
// Flat dog-bone tensile specimen
// Units: mm. Print orientation: flat on bed, z = 0 upward.

$fn = 64;

// ---- Dimensions ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
x0   = -total_length / 2;                    // left end
w0   = grip_width;                           // grip width (strong end)
w1   = gauge_width;                          // gauge width (weak end)
T    = thickness;
eps  = 0.01;                                 // small overlap for clean unions

// Width along the X axis: start in the grip, through the gauge, back into the grip
function width(x) =
    let (t = (x - x0 - grip_length) / transition_len)   // normalized transition (0..1)
    if (x < x0 + grip_length)
        w0
    else if (x < x0 + grip_length + transition_len)
        w0 + (w1 - w0) * t
    else if (x < x0 + grip_length + transition_len + gauge_length)
        w1
    else if (x < x0 + grip_length + 2 * transition_len + gauge_length)
        w0 + (w0 - w1) * (t - 1)
    else
        w0;

// ---- Model ----
union() {
    // Main plate
    hull() {
        for (s = [-1, 1])
            translate([x0 + grip_length + transition_len + gauge_length +
                       s * transition_len, 0, 0])
                linear_extrude(height = T)
                    circle(d = width(x0 + grip_length + transition_len + gauge_length +
                                      s * transition_len) / 2, $fn = 64);
        translate([x0, 0, 0])
            linear_extrude(height = T)
                circle(d = width(x0) / 2, $fn = 64);
    }

    // Grip pads extend past the hull to avoid coplanar faces
    for (s = [-1, 1])
        translate([x0 + grip_length + transition_len + gauge_length +
                   s * transition_len + eps, -grip_width / 2, 0])
            cube([grip_length - eps, grip_width, T]);
    translate([x0 - eps, -grip_width / 2, 0])
        cube([grip_length + eps, grip_width, T]);
}
