            cube([gauge_length, gauge_width, thickness]);

        // Grip sections at each end
        for (s = [-1, 1])
            translate([s * (half_gauge + transition_len), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
    }

    // Cut the transition regions to thin the part from grip to gauge widths
    for (s = [-1, 1])
        translate([s * (half_gauge - transition_len), 0, 0])
            linear_extrude(height = thickness)
                polygon([
                    [0, 0],
                    [transition_len, 0],
                    [transition_len, grip_width],
                    [0, gauge_width]
                ]);
}
