        // Grip sections
        for (s = [-1, 1])
            translate([grip_start + s * grip_length, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_start, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1])
            for (t = [0, 1])
                translate([gauge_start + s * transition_len + t * transition_len,
                           -grip_width / 2 + t * (gauge_width - grip_width) / 2,
                           0])
                    cube([transition_len, grip_width - t * (gauge_width - grip_width), thickness]);
    }
