    // Hub with axle hole
    difference() {
        cylinder(d = hub_diameter, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = axle_hole_d, h = wheel_thickness + 2 * eps);
    }

    // Spokes: from hub to rim, radially straight
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
            translate([hub_radius, -spoke_width / 2, 0])
                cube([(rim_inner_r - hub_radius) + fuse, spoke_width, wheel_thickness]);
