        // Spokes: from rim inward to near hub (overlap into hub for a solid union)
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([0, -spoke_width / 2, 0])
                    cube([hub_radius + rim_width, spoke_width, wheel_thickness]);
        }

        // Central hub
        cylinder(d = hub_diameter, h = wheel_thickness);
    }

    // Axle through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * cut_extra);
