// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
rim_od      = 80;   // outer diameter of rim
rim_w       = 5;    // rim width
hub_d       = 16;   // hub diameter
axle_d      = 6;    // axle hole diameter
spokes      = 4;    // number of spokes
spoke_w     = 5;    // spoke width
eps         = 0.5;  // cutter overshoot

$fn = 128;

// ---- Model ----
difference() {
    // Rim
    cylinder(d = rim_od, h = rim_w);
    // Hub
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = rim_w + 2 * eps);
    // Spokes
    for (i = [0 : spokes - 1])
        rotate([0, 0, i * 360 / spokes])
            translate([hub_d / 2 - eps, -spoke_w / 2, -eps])
                cube([spoke_w, spoke_w, rim_w + 2 * eps]);
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = rim_w + 2 * eps);
}
```

