```openscad
// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 96;

// ---- Dimensions (mm) ----
wheel_thickness = 6;    // overall Z thickness
outer_d         = 80;   // outer rim diameter
rim_width       = 5;    // rim width (radial)
hub_d           = 16;   // hub outer diameter
axle_d          = 6;    // axle hole diameter
spoke_count     = 4;    // number of spokes
spoke_w         = 5;    // spoke width (radial)
spoke_thickness = 3;    // spoke height overlap into rim/hub

// ---- Derived ----
od     = outer_d + 2 * rim_width;   // outer envelope diameter
cutov  = rim_width + 1;             // cutter overshoot for rim/spokes
cutaxle = 1;                        // axle hole cutter overshoot

union() {
    // Outer rim (ring)
    translate([0, 0, wheel_thickness / 2])
        hollow(cylinder(d = od, h = rim_width));

    // Hub with axle hole
    translate([0, 0, -wheel_thickness / 2])
        difference() {
            cylinder(d = hub_d, h = wheel_thickness);
            translate([0, 0, -cutaxle])
                cylinder(d = axle_d, h = wheel_thickness + 2 * cutaxle);
        }

    // Radial spokes, first along +X, evenly spaced
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([hub_d / 2 - spoke_thickness, -spoke_w / 2,
                       -spoke_thickness])
                cube([spoke_thickness, spoke_w, wheel_thickness + 2 * spoke_thickness]);
}
```

