            cylinder(d = rim_od - 2 * rim_width, h = part_thickness + 2 * cut_extra);
    }
}

module hub() {
    difference() {
        cylinder(d = hub_d, h = part_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = axle_hole, h = part_thickness + 2 * cut_extra);
    }
}

module spokes() {
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        rotate([0, 0, a])
            translate([hub_d / 2 - 1, -spoke_width / 2, 0])
                cube([spoke_width, spoke_width, part_thickness]);
    }
}

union() {
    rim();
    hub();
    spokes();
}
