// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, builds upward in +Z

$fn = 128;

// --- Wheel dimensions (mm) ---
wheel_d        = 100;   // outer diameter of rim
wheel_thick    = 5;     // part thickness (Z)
rim_width      = 6;     // radial width of the rim
hub_d          = 14;    // hub diameter
axle_hole_d    = 8;     // through-hole diameter for the axle
spoke_count    = 8;     // number of spokes
spoke_width    = 5;     // radial width of each spoke
cut_overlap    = 0.5;   // extra length on cutters / overlap for clean unions

// --- Model ---
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = wheel_d, h = wheel_thick);

        // Hub, slightly sunk into the rim so the union fuses cleanly
        translate([0, 0, -cut_overlap])
            cylinder(d = hub_d, h = wheel_thick + 2 * cut_overlap);

        // Spokes: start along +X, evenly spaced around the hub
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - cut_overlap, -spoke_width / 2,
                           -cut_overlap])
                    cube([(wheel_d - hub_d) / 2 + 2 * cut_overlap,
                          spoke_width,
                          wheel_thick + 2 * cut_overlap]);
    }

    // Axle through-hole through the hub (and a little past each face)
    translate([0, 0, -cut_overlap])
        cylinder(d = axle_hole_d, h = wheel_thick + 2 * cut_overlap);
}
