// T-shaped nut for aluminium extrusion
// Print orientation: flange on the XY plane (z = 0), neck builds upward (+Z)
// The slot runs along X, so the profile is centred on the origin in X and Y

// ---------- Dimensions (mm) ----------
flange_width   = 10;   // flange size along Y
flange_thick   = 2;    // flange thickness (z = 0 to z = 2)
neck_width     = 6;    // neck size along Y
neck_height    = 3;    // neck rises from z = 2 to z = 5 (delta Z)
screw_d        = 3.4;  // through-hole diameter for the screw
length_x       = 12;   // part length along X

overcut        = 0.5;  // extra length on cutting shapes past faces

$fn = 64;              // resolution for curved shapes

// ---------- Model ----------
difference() {
    // Upside-down T profile
    union() {
        // Bottom flange: full width, from z = 0 to z = flange_thick
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);

        // Neck: centred, from z = flange_thick up to z = flange_thick + neck_height
        translate([-neck_width / 2, -neck_width / 2, flange_thick])
            cube([neck_width, neck_width, neck_height]);
    }

    // Vertical through-hole along Z, centred on the origin
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = flange_thick + neck_height + 2 * overcut);
}
