// T-shaped nut that slides in an aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck rising toward the top

// ---------------- Dimensions (mm) ----------------
slot_width      = 14;    // extrusion slot width (Y), flange matches it
flange_thickness = 2;     // flange thickness (z = 0 to 2)
slot_length     = 15;    // slot length along X, part is centred on it
neck_top_z      = 5;     // height where the neck ends (z = 5)
screw_d         = 3.4;   // central screw hole diameter

overcut         = 0.5;   // extension of cutting shapes past faces

// Derived
neck_width      = 6;     // neck width (given in the profile)
flange_z0       = 0;     // flange bottom
flange_z1       = flange_thickness;   // flange top (z = 2)
neck_z0         = flange_z1;          // neck bottom, fused into flange
neck_z1         = neck_top_z;         // neck top (z = 5)

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: full slot width, centred on X origin
        translate([-slot_length / 2, -slot_width / 2, flange_z0])
