// T-shaped nut that slides in an aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck rising in +Z

// ---------------- Parameters ----------------
flange_w     = 10;    // flange width along Y
flange_t     = 3;     // flange thickness (z = 0 to 3)
neck_w       = 6;     // neck width along Y
neck_top_z   = 7;     // top of neck (neck runs z = 3 to 7)
screw_d      = 3.4;   // vertical screw hole diameter
overcut      = 0.5;   // hole extension past faces
$fn          = 64;    // curve resolution

// ---------------- Profile ----------------
// Printed along X, centred on the origin in X and Y:
// an upside-down T: bottom flange 10 mm wide and 3 mm thick,
// with a centred neck 6 mm wide rising from the flange to z = 7.
profile_h = neck_top_z;
profile_pts = concat(
    [[0, 0], [0, -flange_w / 2], [flange_w / 2, -flange_w / 2],
     [flange_w / 2, 0], [flange_w / 2, flange_t],
     [flange_w, flange_t], [flange_w, 0], [neck_w, 0],
     [neck_w, flange_t], [2 * flange_w - neck_w, flange_t],
     [2 * flange_w - neck_w, 0], [2 * flange_w, 0], [2 * flange_w, flange_t],
     [2 * flange_w - neck_w / 2, flange_t], [flange_w - neck_w / 2, flange_t],
     [flange_w - neck_w / 2, 0], [neck_w / 2, 0], [0, flange_t],
     [-neck_w / 2, flange_t], [0, 0]]
);

// ---------------- Part ----------------
difference() {
    // Extrude profile along X over its own length (10 mm)
    rotate([90, 0, 0])
        linear_extrude(height = flange_w)
            polygon(points = profile_pts);

    // Central vertical screw hole, extended past top and bottom faces
    translate([flange_w / 2 - overcut, 0, -overcut])
        cylinder(d = screw_d, h = flange_w + 2 * overcut);
}
