        // Bottom flange: z = 0 to 3, Y = -5 to 5, X = -5 to 5
        translate([x_center - x_length / 2,
                   y_center - flange_width / 2,
                   0])
            cube([x_length, flange_width, flange_thick]);

        // Neck: z = 3 to 7, Y = -3 to 3, X = -5 to 5
        translate([x_center - x_length / 2,
                   y_center - neck_width / 2,
                   flange_thick - cut_overlap])
            cube([x_length, neck_width, neck_top_z - flange_thick + cut_overlap]);
    }

    // Vertical screw hole through the full height
    translate([x_center, y_center, -cut_overlap])
        cylinder(d = screw_d, h = neck_top_z + cut_overlap);
}
