// Anti-vibration foot for benchtop instrument
// Print orientation: recess facing down (shallowly buried), screw hole through,
// frustum building upward (+Z) from the bed. Not centred on the origin in Z.

$fn = 128;

// ---- Dimensions (mm) ----
recess_depth = 2;     // rubber pad recess depth
screw_d      = 4.5;   // screw hole diameter
foot_d0      = 40;    // frustum diameter at z = 0
foot_d1      = 32;    // frustum diameter at z = 15
foot_h       = 15;    // frustum height

eps          = 0.5;   // cutter overshoot past faces

// ---- Model ----
union() {
    // Recess (cylindrical pocket, open at the top)
    translate([0, 0, -recess_depth])
        cylinder(d = foot_d0, h = recess_depth + eps);

    // Frustum: truncated cone from diameter foot_d0 at z = 0 up to foot_h
    // (check: d(z) = foot_d0 + (foot_d1 - foot_d0) * z / foot_h, so d(foot_h) = foot_d1)
    translate([0, 0, 0])
        cylinder(d1 = foot_d0, d2 = foot_d1, h = foot_h);
}

// ---- Screw hole ----
