    translate([0, 0, overlap - recess_depth])
        cylinder(h = recess_depth + 2 * overlap, d = recess_d);

    // Through screw hole along the axis
    translate([0, 0, -overlap])
        cylinder(h = frustum_h + 2 * overlap, d = screw_d);
}
