// Stiffened cover panel - flat plate with 3 longitudinal ribs
// Print orientation: plate flat on bed (z = 0), ribs build upward (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_t     = 2;     // plate thickness (mm), z = 0..2

rib_count   = 3;     // number of ribs
rib_t       = 3;     // rib thickness along X (mm)
rib_h       = 4;     // rib top height (mm), z = 2..6
rib_overlap = 1;     // how far each rib extends into the plate for a solid union (mm)

pitch = 30;          // centre-to-centre spacing of ribs along X (mm)
first_x = 30;        // distance of outer rib centres from plate ends (mm)

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, sitting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs, running the full width along Y
    for (i = [0 : rib_count - 1]) {
        // Rib i is at x = -plate_len/2 + first_x + i*pitch
        translate([-plate_len/2 + first_x + i*pitch - rib_t/2,
                   -plate_wid/2, 0])
            cube([rib_t, plate_wid, rib_h - plate_t + rib_overlap]);
    }
}
