total_rib_len  = rib_count * rib_thk;            // 12 mm
end_gap        = plate_len - total_rib_len;      // 108 mm
gap_per_cell   = end_gap / (rib_count + 1);      // 24 mm

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, evenly spaced along X
    for (i = [0 : rib_count - 1]) {
        x = -gap_per_cell/2 + i * (rib_thk + gap_per_cell);
        translate([x - rib_thk/2, -plate_wid/2, plate_thk - rib_overlap])
            cube([rib_thk, plate_wid, rib_h + rib_overlap]);
