// Powder measuring scoop
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
sphere_r      = 10;    // outer radius of spherical bowl
wall          = 2;     // bowl wall thickness
handle_w      = 10;    // handle width (Y)
handle_t      = 4;     // handle thickness (Z)
handle_x0     = 8;     // handle start (X)
handle_x1     = 90;    // handle end (X)
cut_extra     = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // curve resolution

// ---------- Derived ----------
rim_z = sphere_r;      // rim height (lower hemisphere: centre at z = r, rim at z = 2r)
// handle top face flush with rim -> handle spans z = rim_z - handle_t to rim_z

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half only)
    translate([0, 0, rim_z])
        difference() {
            sphere(r = sphere_r);
            translate([0, 0, -cut_extra])
                sphere(r = sphere_r - wall);   // inner cavity, open at top
        }

    // Flat handle along +X
    translate([handle_x0, -handle_w / 2, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
```

