// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---- Parameters ----
outer_radius   = 10;    // outer radius of spherical bowl (mm)
wall_thickness = 2;     // bowl wall thickness (mm)
handle_width   = 10;    // handle width along Y (mm)
handle_thick    = 4;    // handle thickness along Z (mm)
handle_x0      = 8;     // handle start position along X (mm)
handle_x1      = 90;    // handle end position along X (mm)
cut_extra      = 0.5;   // extra length for cutting shapes past faces (mm)

$fn = 96;

// ---- Derived ----
rim_z = outer_radius;   // rim height (lower half of sphere)
// inner radius of bowl (through the wall)
inner_radius = outer_radius - wall_thickness;

// ---- Model ----
union() {
    // Hollow spherical bowl: lower half kept, opens upward
    difference() {
        cylinder(h = rim_z, r = outer_radius);
        translate([0, 0, wall_thickness])
            cylinder(h = rim_z - wall_thickness + cut_extra, r = inner_radius);
    }

    // Flat handle, top face flush with rim (z = 6 to 10)
    translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}
