```openscad
// Measuring scoop for powders
// Print orientation: bowl bottom on bed (z = 0), rim at z = 10, handle along +X

// ---------------- Parameters ----------------
outer_radius   = 10;    // outer radius of the hemispherical bowl (mm)
wall_thickness = 2;     // wall thickness of the bowl (mm)
bowl_height    = outer_radius;  // height of lower half bowl (mm)

handle_width   = 10;    // handle width along Y (mm)
handle_thick   = 4;     // handle thickness along Z (mm)
handle_x0      = 8;     // handle start along X (mm)
handle_x1      = 90;    // handle end along X (mm)
handle_y0      = -wall_thickness;  // handle bottom Y, flush with rim (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;               // curve resolution

// ---------------- Modules ----------------
module bowl() {
    // Hollow lower half of a sphere, open top at z = outer_radius
    difference() {
        translate([0, 0, bowl_height])
            sphere(r = outer_radius);
        translate([0, 0, wall_thickness])
            sphere(r = outer_radius - wall_thickness + eps);
    }
}

module handle() {
    translate([handle_x0, handle_y0, bowl_height - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}

// ---------------- Part ----------------
union() {
    bowl();
    handle();
}
