```openscad
// Measuring scoop for powders
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

$fn = 96;

// ---- Bowl ----
bowl_outer_radius = 15;    // mm
bowl_wall         = 1.5;   // mm
bowl_center       = 15;    // z of sphere centre (lower half, opens upward)

// ---- Handle ----
handle_width   = 12;   // Y
handle_thick   = 3;    // Z
handle_x0      = 13.5; // start of handle (X)
handle_x1      = 115;  // end of handle (X)
handle_top_z   = 15;   // flush with rim

// ---- Cut clearance ----
eps = 0.5;

difference() {
    union() {
        // Hollow bowl
        translate([0, 0, bowl_center])
            difference() {
                sphere(radius = bowl_outer_radius);
                translate([0, 0, -eps])
                    sphere(radius = bowl_outer_radius - bowl_wall);
            }
        // Handle plate
        translate([handle_x0, -handle_width / 2, handle_top_z - handle_thick])
            cube([handle_x1 - handle_x0, handle_width, handle_thick]);
    }
    // Remove upper half of sphere above rim to avoid overlap with handle
    translate([0, 0, handle_top_z])
