cut_extension   = 0.5;  // mm, extension of cutting shapes past faces

// Derived
outer_bottom_z  = rim_z - outer_radius;   // -15 (below bed)
inner_radius    = outer_radius - wall_thickness;
handle_bottom_z = handle_top_z - handle_thick;

module bowl() {
    // Lower half of hollow sphere, kept from z = 0 upward
    translate([0, 0, bottom_z])
        hull() {
            cylinder(h = rim_z - bottom_z, r = outer_radius);
            translate([0, 0, rim_z - wall_thickness])
                cylinder(h = wall_thickness + cut_extension, r = outer_radius);
        }
}

module handle() {
    translate([handle_start_x, -handle_width / 2, handle_bottom_z])
        cube([handle_end_x - handle_start_x, handle_width, handle_thick]);
}

union() {
    bowl();
    handle();
}
