```openscad
// Powder measuring scoop
// Units: mm

$fn = 96;

// --- Dimensions ---
bowl_outer_radius = 12;    // outer radius of spherical bowl
bowl_wall         = 2;     // wall thickness
handle_length     = 62;    // handle runs from x = 10 to x = 72 (62 mm)
handle_width      = 12;    // handle width (Y)
handle_thickness  = 3;     // handle thickness (Z)
overlap           = 0.5;   // overlap between bowl and handle for a clean union

// Derived
handle_x0 = 10;
handle_x1 = handle_x0 + handle_length;
rim_z     = bowl_outer_radius;   // rim lies on the plane z = 12

module bowl() {
    // Lower half of a hollow sphere: from the bed (z = 0) up to the rim.
    difference() {
        translate([0, 0, 0])
            cylinder(h = bowl_outer_radius, r = bowl_outer_radius);
        translate([0, 0, bowl_outer_radius - bowl_wall])
            cylinder(h = bowl_wall + 1, r = bowl_outer_radius);
    }
}

module handle() {
    translate([handle_x0 - overlap, -handle_width / 2, 0])
        cube([handle_length + overlap, handle_width, handle_thickness]);
}

union() {
    bowl();
    handle();
}
