        // Bowl: lower half of a hollow sphere, touching the bed
        translate([0, 0, bowl_center_z])
            difference() {
                sphere(r = bowl_outer_r);
                translate([0, 0, bowl_wall])
                    sphere(r = bowl_outer_r - bowl_wall);
            }

        // Flat handle: top face flush with the rim (z = 15)
        translate([handle_x0 - overlap, -handle_w / 2, bowl_center_z - handle_t])
            cube([handle_x1 - handle_x0 + overlap, handle_w, handle_t]);
