        difference() {
            // outer sphere (upper half only)
            translate([0, 0, -bowl_r])
                cylinder(r = bowl_r, h = bowl_r + eps);
            // hollow
            translate([0, 0, -bowl_r + bowl_wall])
                cylinder(r = bowl_r - bowl_wall, h = bowl_r + eps + bowl_wall);
        }
}

union() {
    handle();
    bowl();
