// Cable bridge - rectangular block with 3 semicircular tunnels along Y at floor level
// Print orientation: base on the bed (z = 0), tunnels open downward

// ---------------- Parameters ----------------
block_len    = 60;    // block length along X (mm)
block_wid    = 40;    // block width along Y (mm)
block_h      = 12;    // block height along Z (mm)

tunnel_d     = 12;    // tunnel diameter (mm); radius = 6 mm
tunnel_count = 3;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing of tunnels along X (mm)

eps          = 0.5;   // overcut so cutters pass beyond the faces they cut

$fn = 96;             // curve resolution

// ---------------- Derived ----------------
tunnel_r = tunnel_d / 2;
// first tunnel axis X position, with the row centred on the origin
tunnel_x0 = -(tunnel_count - 1) * tunnel_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels: cylinder axes along Y at z = 0,
    // running from the negative to the positive X face
    for (i = [0 : tunnel_count - 1])
        translate([tunnel_x0 + i * tunnel_pitch, 0, 0])
            translate([0, 0, 0])
                cylinder(r = tunnel_r, h = block_len + 2 * eps, $fn = 96);
}
