```openscad
// Ring weight - torus lying flat on the bed
// Print orientation: bottom surface on z = 0, builds upward (+Z)

// ---------------- Parameters ----------------
cross_section_d   = 10;   // diameter of the torus cross-section (mm)
ring_radius       = 20;   // radius of the ring (distance from Z axis to cross-section centre) (mm)
total_width       = 50;   // overall width of the ring along X/Y (mm)
middle_plane_z    = 5;    // height of the torus middle plane (mm)
cut_extra         = 0.5;  // extra length for cutting shapes to avoid coplanar faces (mm)

// ---------------- Derived ----------------
cross_section_r = cross_section_d / 2;              // cross-section radius
bottom_z        = middle_plane_z - cross_section_r; // z of the lower cross-section arc (2.5 mm)
slice_r         = ring_radius + cross_section_r;    // outer radius used for slicing

// ---------------- Model ----------------
// The torus is generated by sweeping the cross-section circle around the Z axis.
// Each slice is rotated so its centre lies on the +X axis, so every slice
// rests on z = bottom_z. The union is shifted down so the absolute lowest
// point sits on z = 0.
module ring_weight() {
    union() {
        for (a = [0 : 10 : 360]) {
            translate([ring_radius * cos(a), ring_radius * sin(a), 0])
                rotate([0, 90, a])
                    cylinder(h = total_width, r = cross_section_r);
        }
    }
    translate([0, 0, -bottom_z])      // shift the whole union down to z = 0
        hull() {                       // hull of the cross-section disc and its outline at z = bottom_z
            for (r = [cross_section_r : 1 : slice_r])
                translate([r * cos(45), r * sin(45), 0])
                    circle(d = 2 * cross_section_r, $fn = 96);
        }
}

ring_weight();
