// Ring weight for a flask neck in a water bath
// Print orientation: lying flat on the bed (Z axis is the torus axis)

// ---------------- Parameters ----------------
torus_d      = 12;    // diameter of the round cross-section (mm)
torus_r      = 22;    // radius of the circle the cross-section centre sweeps (mm)
cut_extra    = 0.5;   // extra length on cutting shapes to avoid coplanar faces (mm)
$fn          = 96;    // number of facets for curved shapes

// Derived
torus_h      = torus_d;               // cross-section diameter = cylinder height
outer_r      = torus_r + torus_d / 2; // outer radius of the torus
inner_r      = torus_r - torus_d / 2; // inner radius of the torus
ring_width   = outer_r - inner_r;    // should equal torus_d

// ---------------- Model ----------------
difference() {
    // The torus itself: a cylinder whose axis runs along the Z axis,
    // centred on a circle of radius torus_r in the XY plane.
    // rotate([90, 0, 0]) maps the cylinder's local Z to world X,
    // so the cylinder now runs along world Z from z = 0 to z = torus_h.
    translate([0, 0, 0])
        rotate([90, 0, 0])
            cylinder(d = torus_d, h = torus_r * 2);

    // A cylindrical cutter centred on the origin, running through the part.
    // Its radius lies between inner_r and outer_r, so it removes the interior
    // without touching the outer face (no two faces are coplanar).
    translate([0, 0, -cut_extra])
        cylinder(r = (inner_r + outer_r) / 2, h = torus_r * 2 + 2 * cut_extra);
}
