// Pin hinge - one leaf
// Print orientation: plate flat on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
plate_length   = 60;   // plate runs along X
plate_width    = 25;   // plate runs along Y
plate_thick    = 3;    // plate thickness along Z

knuckle_count  = 3;    // 3 segments along the plate
knuckle_dia    = 8;    // knuckle (cylinder) diameter
knuckle_pitch  = plate_length / knuckle_count; // 20 mm between segment centres

pin_dia        = 3;    // pin hole diameter
eps            = 0.5;  // overshoot so cutters pass through faces

// ---- Derived ----
knuckle_start_x = -(knuckle_count - 1) * knuckle_pitch / 2; // -20, 0, 20

// ---- Model ----
union() {
    // Plate, centred in X and Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Knuckles on the 1st and 3rd segments only
    for (i = [0 : knuckle_count - 1])
        if ([0, knuckle_count - 1] & [i])
            translate([knuckle_start_x + i * knuckle_pitch,
                       plate_width / 2, 0])
                cylinder(d = knuckle_dia, h = plate_thick + eps);
}

// ---- Pin hole ----
// The axis runs along X at y = 12.5, z = 4, through every knuckle.
// The hole is extended past both end faces by 'eps'.
translate([knuckle_start_x - eps, plate_width / 2, 0])
    rotate([0, 90, 0])
        cylinder(d = pin_dia, h = plate_length + 2 * eps);
