// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len    = 60;   // plate length along X
plate_wid    = 25;   // plate width along Y
plate_thk    = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d    = 8;    // knuckle diameter
knuckle_h    = 8;    // knuckle height above plate (centre at z = plate_thk + 4)
knuckle_azim = 0;    // first knuckle at angle 0 (along +X)
knuckle_count= 3;    // 3 equal segments around the plate
knuckle_gap  = 0.5;  // small gap between knuckles to avoid overwriting plate

// ---- Pin ----
pin_d        = 3;    // pin hole diameter

// ---- Helpers ----
eps          = 0.5;  // cutter overshoot past faces
start_angle  = -knuckle_azim - (knuckle_count - 1) * 360 / 2 / knuckle_count;

difference() {
    union() {
        // Plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles (doughnut shape so they fuse into the plate)
        for (i = [0 : knuckle_count - 1]) {
            a = start_angle + i * 360 / knuckle_count;
            translate([plate_len / 2 * cos(a), plate_wid / 2 * sin(a), 0])
                linear_extrude(height = knuckle_h + plate_thk)
                    difference() {
                        circle(d = knuckle_d);
                        translate([0, 0, -eps])
                            cylinder(d = pin_d, h = knuckle_h + plate_thk + 2 * eps);
                    }
        }
    }

    // Pin hole along the common axis (y = 12.5, z = 4), through the whole plate
    translate([0, plate_wid / 2, 4])
        rotate([0, 90, 0])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = plate_len + 2 * eps);
}
