// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 60;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

knuckle_d   = 6;     // knuckle (cylinder) diameter
knuckle_n   = 3;     // number of knuckles
knuckle_y   = 15;    // knuckle axis Y position (on +Y edge)
knuckle_z   = 3;     // knuckle axis height above bed

pin_d       = 2;     // pin hole diameter
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd 20 mm segments
        for (i = [0, 2]) {
            x0 = -plate_len/2 + i * plate_len/knuckle_n;
            translate([x0, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk);
        }
    }

    // Pin holes through every knuckle
    for (i = [0, 2]) {
        x0 = -plate_len/2 + i * plate_len/knuckle_n;
        translate([x0, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2*eps);
    }
}
```

