```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 3;     // number of knuckles
knuckle_w   = plate_len / knuckle_n; // 20 mm segment width
knuckle_y   = plate_wid / 2; // 15 mm (on +Y edge)
knuckle_z   = plate_thk;    // 3 mm (axis at top of plate)

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments only
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)
                translate([-knuckle_w/2 + i * knuckle_w, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10, $fn = 64);
    }

    // Pin hole along X through every knuckle
    translate([-knuckle_w/2, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_w * knuckle_n + 2*eps, $fn = 64);
}
```

