```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle diameter
knuckle_z   = 3.5;   // knuckle axis height above bed
knuckle_n   = 3;     // number of knuckles
knuckle_w   = 20;    // length of each knuckle segment along X

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

// Derived
knuckle_r   = knuckle_d / 2;
first_x     = -(knuckle_n - 1) * knuckle_w / 2;  // centre the segments

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at y = 12.5, z = 3.5
        for (i = [0 : knuckle_n - 1]) {
            x = first_x + i * knuckle_w;
            translate([x - knuckle_w / 2, 12.5, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_w);
        }
    }

    // Pin hole through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x = first_x + i * knuckle_w;
        translate([x - knuckle_w / 2 - eps, 12.5, knuckle_z - eps])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_w + 2 * eps);
    }
}
```

