            cube([plate_length, plate_width, plate_thick]);

        // Knuckle cylinders along X axis
        for (s = [segment_start : knuckle_size : segment_start + (knuckle_count - 1) * knuckle_size])
            translate([s, knuckle_axis_y, 0])
                cylinder(r = knuckle_r, h = plate_thick + 2 * knuckle_r);
