```openscad
// Pin hinge leaf
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len    = 60;    // plate length along X
plate_wid    = 30;    // plate width along Y
plate_thk    = 2.5;   // plate thickness along Z

knuckle_d    = 6;     // knuckle cylinder diameter
knuckle_h    = 4;     // knuckle height above plate (z = 3 to top of plate)
knuckle_n    = 5;     // number of knuckle segments
knuckle_pitch = 12;   // centre-to-centre spacing along X (60/5 segments, 3 used)

pin_d        = 2.5;   // pin hole diameter
eps          = 0.5;   // overshoot for clean boolean cuts

// Derived
knuckle_r      = knuckle_d / 2;
first_knuckle_x = -knuckle_n * knuckle_pitch / 2 + knuckle_pitch / 2; // -12

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along +Y edge (x, y = 15, z = 3)
    for (i = [0 : knuckle_n - 1]) {
        translate([first_knuckle_x + i * knuckle_pitch,
                   knuckle_r,
                   knuckle_r])
            cylinder(d = knuckle_d, h = knuckle_h);
    }
}

// ---------------- Pin holes ----------------
difference() {
    // Current part
    module part() {
        union() {
            translate([-plate_len / 2, -plate_wid / 2, 0])
                cube([plate_len, plate_wid, plate_thk]);
            for (i = [0 : knuckle_n - 1]) {
                translate([first_knuckle_x + i * knuckle_pitch,
                           knuckle_r,
                           knuckle_r])
                    cylinder(d = knuckle_d, h = knuckle_h);
            }
        }
    }

    // Horizontal pin holes through every knuckle (along X axis at y = 15, z = 3)
    for (i = [0 : knuckle_n - 1]) {
        translate([first_knuckle_x + i * knuckle_pitch - eps,
                   knuckle_r,
                   knuckle_r])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_pitch + 2 * eps);
    }
}
