plate_len   = 45;   // plate length along X (mm)
plate_wid   = 25;   // plate width along Y (mm)
plate_thk   = 2.5;  // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d     = 7;   // knuckle diameter (mm)
knuckle_z     = 3.5; // knuckle axis height above bed (mm)
knuckle_count = 3;   // number of knuckles
knuckle_pitch = 15;  // centre-to-centre spacing along X (mm)
knuckle_start = 0;   // index of first knuckle (0 = 1st segment)

// ---- Pin hole ----
pin_d = 3;          // pin hole diameter (mm)

// ---- Derived ----
half_plate_wid = plate_wid / 2;   // 12.5 mm offset of knuckles in Y
overcut        = 0.5;             // extension of cutters past faces (mm)

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -half_plate_wid, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st and 3rd segments only
    for (i = [knuckle_start : 1 : knuckle_count - 1]) {
        x = (i - knuckle_start) * knuckle_pitch - knuckle_pitch / 2;
        translate([x, half_plate_wid, 0])
            cylinder(d = knuckle_d, h = plate_thk, $fn = 64);
    }

    // Pin hole along X through every knuckle
    translate([-knuckle_pitch * (knuckle_count - 1) / 2, half_plate_wid, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_pitch * (knuckle_count - 1) + 2 * overcut, $fn = 64);
}
