// Pin hinge leaf
// Print orientation: flat plate on bed (z = 0), building upward

// ---------- Parameters ----------
plate_length   = 45;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 3;     // number of knuckle segments along X
knuckle_dia    = 7;     // knuckle diameter (mm)
knuckle_z      = 3.5;   // knuckle axis height above bed (mm)
knuckle_y      = plate_width / 2; // knuckle axis Y position (mm)

pin_dia        = 3;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;               // curve resolution

// ---------- Derived ----------
segment_len = plate_length / knuckle_count;   // 15 mm per segment

// ---------- Model ----------
