    union() {
        // Base plate, centred in X/Y, sitting on z = 0
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on 1st and 3rd segments, axis along X
        for (i = [0 : knuckle_count - 1]) {
            x_c = (i - (knuckle_count - 1) / 2) * segment_len;
            if (i % 2 == 0) // 1st and 3rd segments
                translate([x_c, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_dia, h = segment_len);
        }
