// Pin hinge leaf
// Print orientation: plate lying flat on the bed, centred on the origin.
// The knuckles stand on the +Y edge of the plate.

// ---------------- Parameters ----------------
plate_len    = 45;    // plate length along X (mm)
plate_wid    = 25;    // plate width along Y (mm)
plate_t      = 2.5;   // plate thickness along Z (mm)

knuckle_d    = 7;     // knuckle diameter (mm)
knuckle_h    = 15;    // knuckle height above the plate (mm)
knuckle_z0   = 3.5;   // height of the knuckle axis above the bed (mm)
knuckle_pitch = 15;   // centre-to-centre spacing of the knuckles along X (mm)
knuckle_count = 3;    // number of knuckles

pin_d        = 3;     // pin hole diameter (mm)

overlap      = 0.5;   // extra length so cylinders cut into the plate (mm)

$fn = 64;             // resolution for curved surfaces

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_t]);

        // Knuckles: 3 cylinders whose axes run along X at y = 12.5, z = 3.5
        for (i = [0 : 2]) {
            x = (i - 1) * knuckle_pitch;   // -15, 0, +15
            translate([x, 12.5, 0])
                cylinder(d = knuckle_d, h = knuckle_h + plate_t, $fn = 64);
        }
    }

    // Pin hole along the common axis of the knuckles
    translate([0, 12.5, -overlap])
        cylinder(d = pin_d, h = knuckle_z0 + overlap + plate_t + overlap, $fn = 64);
}
