// Pin hinge - one leaf
// Print orientation: flat plate on the bed (z = 0), centred on the origin in X and Y.
// The plate lies along X, with its width along Y.

// ---------------- Parameters ----------------
plate_len    = 45;    // plate length along X (mm)
plate_wid    = 25;    // plate width along Y (mm)
plate_thk    = 2.5;   // plate thickness along Z (mm)

knuckle_d    = 7;     // knuckle cylinder diameter (mm)
knuckle_z    = 3.5;   // knuckle axis height above bed (mm)
knuckle_ns   = 3;     // number of segments along the plate length
knuckle_w    = plate_len / knuckle_ns; // width of each segment (15 mm)

pin_d        = 3;     // pin hole diameter (mm)
eps          = 0.5;   // overshoot for clean boolean cuts (mm)

$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments only
        for (i = [0 : knuckle_ns - 1]) {
            if (i % 2 == 0)
                translate([-(knuckle_ns - 1) * knuckle_w / 2 + i * knuckle_w,
                           plate_wid / 2,
                           0])
                    rotate([0, 90, 0])
                        cylinder(d = knuckle_d, h = knuckle_w, center = true);
        }
    }

    // Pin hole along Y = 12.5, through every knuckle
    translate([0, plate_wid / 2, -eps])
        rotate([90, 0, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
}
