```openscad
// 5-pointed star plate with central through-hole
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
star_points    = 5;     // number of points on the star
outer_radius   = 40;    // distance of outer points from centre (mm)
inner_radius   = 20;    // distance of inner points from centre (mm)
plate_thick    = 4;     // plate thickness (mm)
hole_diameter  = 8;     // central hole diameter (mm)
cut_extra      = 0.5;   // extra length for cutting shapes past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Star outline: alternate outer/inner points, start with outer on +X
    hull() {
        for (i = [0 : star_points - 1]) {
            // even i -> outer point, odd i -> inner point
            r = (i % 2 == 0) ? outer_radius : inner_radius;
            a = i * 360 / star_points;
            translate([r * cos(a), r * sin(a), 0])
                cylinder(h = plate_thick, $fn = 96);
        }
    }

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(h = plate_thick + 2 * cut_extra, d = hole_diameter, $fn = 96);
}
