plate_t       = 5;    // plate thickness
hole_d        = 8;    // central through-hole diameter
cut_extra     = 0.5;  // extra length on cutting shapes past faces

// ---- Derived ----
angle_step    = 360 / star_points;   // 72 deg between points
star_area     = 0.5 * star_points * (outer_radius + inner_radius) * outer_radius * sin(360 / star_points);

// ---- Model ----
difference() {
    // Outer star shape (hull of points on a circle)
    hull() {
        for (i = [0 : star_points - 1]) {
            rotate([0, 0, i * angle_step])
                translate([outer_radius, 0, 0])
                    cylinder(h = plate_t, r = outer_radius);
        }
    }

    // Inner material between the crevices (hull of inner points)
    hull() {
        for (i = [0 : star_points - 1]) {
            rotate([0, 0, (i + 0.5) * angle_step])
                translate([inner_radius, 0, 0])
                    cylinder(h = plate_t, r = inner_radius);
        }
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(h = plate_t + 2 * cut_extra, d = hole_d);
}
