plate_t   = 3;    // plate thickness (z: 0 .. 3)
hole_d    = 8;    // diameter of the central through-hole
eps       = 0.5;  // overshoot for clean boolean cuts

$fn = 96;         // curve resolution

// First outer point on +X axis (angle 0); inner points offset by 180/points = 22.5 deg

// ---------- Model ----------
difference() {
    // Star outline: two concentric 8-gons, one rotated 22.5 deg relative to the other
    union() {
        circle(r = outer_r, $fn = points);
        rotate([0, 0, 22.5 / 180 * pi])
            circle(r = inner_r, $fn = points);
    }

    // Central through-hole (extends past top and bottom faces)
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = points);
}
