// Star-shaped indexing wheel: flat plate with a 6-pointed star outline and a central hole.

$fn = 96;

// ---- Star dimensions ----
outer_r = 35;    // distance of outer points from the centre
inner_r = 17.5;  // distance of inner points from the centre
points  = 6;     // number of points on the star

// ---- Plate dimensions ----
plate_t = 5;     // plate thickness (Z)
hole_d  = 8;     // diameter of the through-hole at the centre

// ---- Clearances ----
cut_extra = 0.5; // extension of the cutting shapes beyond the faces they cut
fuse     = 0.5;  // overlap between neighbouring shapes to avoid coplanar faces

// First outer point lies on the +X axis (angle 0).
// Each step in the loop adds 60 degrees (360/points).
for (i = [0 : points - 1]) {
    rotate([0, 0, i * 60]) {
        // One "arm" of the star, from the inner circle out to the outer tip
        difference() {
            linear_extrude(height = plate_t)
                circle(r = outer_r, $fn = 96);
            translate([0, 0, -cut_extra])
                circle(r = inner_r + fuse, $fn = 96);
        }
    }
