// The arms leave a hexagonal core where the inner circles overlap.
// Difference() cannot remove that core from the union of the arms, so
// cut it out explicitly with a shape that stops at the top face.
translate([0, 0, plate_t - cut_extra])
    linear_extrude(height = cut_extra)
        circle(r = inner_r + fuse, $fn = 96);

// Central through-hole
