half_top    = top_w / 2;
pocket_y0   = -pocket_w / 2;   // pocket centre Y (user coordinates)

// ---------- Model ----------
difference() {
    // Square frustum: hull between the full bottom square and the
    // reduced top square, giving flat sloping sides parallel to X and Y.
    hull() {
        translate([-half_base, -half_base, 0])
            cube([base_w, base_w, base_h]);
        translate([-half_top, -half_top, base_h])
            cube([top_w, top_w, eps]);   // tiny top slab at z = 25
    }

    // Square pocket cut into the top face
    translate([0, pocket_y0, base_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
