    // Each corner is traced from bed level up to the top face and the hull
    // joins them with flat, 45-degree faces. Edges stay parallel to X and Y.
    hull() {
        for (s = [base_size, top_size])
            translate([-s / 2, -s / 2, 0])
                cube([s, s, height]);
    }

    // Square pocket cut into the top face, centred.
    // The cutter extends past the top face to avoid coplanar faces.
    translate([-pocket_w / 2, -pocket_w / 2, pocket_floor_z])
        cube([pocket_w, pocket_w, pocket_d + overcut]);
