total_h    = height + eps;  // extended top for pocket

// Slope per side (half-width difference over height)
slope      = (bottom_w - top_w) / 2 / height;

module frustum() {
    // Hull of two equally sized bottom faces and one smaller top face
    hull() {
        translate([-bottom_w/2, -bottom_w/2, 0])
            cube([bottom_w, bottom_w, height], center=false);
        translate([0, 0, total_h - eps])
            cube([pocket_w, pocket_w, eps], center=false);
    }
}

// Slightly larger base and top faces keep the pocket centred in X/Y
module base() {
    translate([-bottom_w/2 - 0.01, -bottom_w/2 - 0.01, 0])
        cube([bottom_w + 0.02, bottom_w + 0.02, 0.02]);
}

module top_face() {
    translate([-top_w/2, -top_w/2, height])
        cube([top_w, top_w, 0.02]);
}

union() {
    frustum();
    base();
    top_face();
}
