// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: flat on the bed, bottom face at z = 0

// ---------------- Parameters ----------------
base_size   = 80;   // bottom square side length (mm)
top_size    = 40;   // top square side length (mm)
height      = 20;   // block height (mm)
pocket_w    = 32;   // pocket side length (mm)
pocket_d    = 8;    // pocket depth from top face (mm)
eps         = 0.5;  // cutter overshoot past faces (mm)
$fn         = 64;   // curve resolution (for consistency)

