```openscad
// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face (z = 0) on the bed, pocket open upward.

$fn = 64;

// ---- Dimensions (mm) ----
base_side     = 60;   // bottom square side
top_side      = 30;   // top square side
block_height  = 30;   // block height (z = 0 .. 30)
pocket_size   = 20;   // pocket square side
pocket_depth  = 8;    // pocket depth from top face
eps           = 0.5;  // overshoot for clean booleans

// ---- Derived ----
pocket_top_z  = block_height - pocket_depth;
sides         = 4;

// Check: the edge-thickness profile along one X/Y axis (no diagonal corners)
// goes from base_side at z = 0 up to top_side at z = block_height,
// with the same slope on the way down from the top face.
profile_pts   = concat(
    [[z, (base_side + (top_side - base_side) * z / block_height) / 2] | z = [0 : block_height / sides : block_height - block_height / sides]],
    [[block_height - block_height / sides, (base_side + (top_side - base_side) * (block_height - block_height / sides) / block_height) / 2]],
    [[block_height, top_side / 2]]
);

module side_profile() {
    // 2D (x, z) outline, drawn counter-clockwise
    polygon(points = [
        [0, 0],
        [base_side, 0],
        map(p -> [p[0] + (p[1] - block_height + block_height / sides) * 2 / sides, p[1]], profile_pts),
        [block_height, top_side]
    ]);
}

difference() {
    // Block body
    hull() {
        for (i = [0 : sides - 1])
            rotate([0, 0, i * 360 / sides])
                translate([0, -block_height, 0])
                    linear_extrude(height = block_height)
                        side_profile();
    }

    // Top pocket
    translate([0, 0, pocket_top_z])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
