```openscad
// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face on the bed (z = 0), building upward.

$fn = 64;

// ---- Frustum dimensions ----
bottom_w   = 60;   // bottom square side (mm)
bottom_h   = 0;    // bottom face height (mm)
top_w      = 30;   // top square side (mm)
top_h      = 30;   // top face height (mm)
flip       = false; // set true if the model is upside down

// ---- Pocket ----
pocket_w   = 20;   // pocket side (mm)
pocket_d   = 8;    // pocket depth from top face (mm)

// ---- Misc ----
eps        = 0.5;  // overshoot for cutting shapes (mm)

// Convert a square side and height into hull end points, then hull()
// between them.  The loop runs twice so each face (X and Y) is
// extruded along its own axis, which gives a solid with flat sides.
module square_frustum(w1, h1, w2, h2) {
    pts = [
        [0, 0, h1], [w1 / 2, 0, h1], [w1 / 2, w1 / 2, h1],
        [0, w1 / 2, h1], [-w1 / 2, w1 / 2, h1], [-w1 / 2, 0, h1],
        [0, 0, h2], [w2 / 2, 0, h2], [w2 / 2, w2 / 2, h2],
        [0, w2 / 2, h2], [-w2 / 2, w2 / 2, h2], [-w2 / 2, 0, h2]
    ];
    for (i = [0 : 1])
        hull(pts = concat([for (p = [pts[i * 12 : i * 12 + 3]] p),
                           for (p = [pts[(i + 1) * 12 : (i + 1) * 12 + 3]] p)]);
}

difference() {
    square_frustum(bottom_w, bottom_h, top_w, top_h);

    // Pocket cut into the top face.  In the (possibly flipped) model
    // the top face is at z = top_h (or 0 if flipped), so the cut starts
    // there and runs downward.
    translate([0, 0, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}

// Rotate the part down onto the bed if the model is upside down.
// The pocket is then on the underside, but the block rests on the bed.
if (flip)
    rotate([90, 0, 0])
        current_part();
else
    current_part();
