// Tapered riser block (square frustum) with a recessed square pocket
// Print orientation: bottom face on the bed (z = 0), pocket is blind and closed

$fn = 64;

// ---------------- Dimensions (mm) ----------------
base_size    = 60;    // frustum bottom side length
top_size     = 20;    // frustum top side length
frustum_h    = 30;    // frustum height (z = 0 .. 30)
pocket_size  = 12;    // square pocket side length
pocket_depth = 5;     // pocket depth from top face (blind)

overlap      = 0.01;  // small overlap so cuts stay inside faces

// ---------------- Derived ----------------
// Pocket floor height above bed
pocket_floor_z = frustum_h - pocket_depth;
// Recess volume (floor * area), extended slightly into the floor
recess_vol     = pocket_size * pocket_size * (pocket_depth + overlap);

// ---------------- Model ----------------
difference() {
    // Square frustum built as a hull between two full cubes
    hull() {
        cube([base_size, base_size, overlap]);      // bottom slice at z = 0
        translate([0, 0, frustum_h - overlap])
            cube([top_size, top_size, overlap]);    // top slice at z = 30
    }

    // Blind square pocket cut from the top face
    translate([0, 0, pocket_floor_z])
        cube([pocket_size, pocket_size, pocket_depth + overlap]);
}

// ---------------- Notes ----------------
// - The frustum sides are flat and sloped (60 -> 20 over 30 mm);
//   no vertical walls above z = 30, so the part is stable as printed.
// - The pocket is centred and open to the top surface (a recess),
//   not a through-hole.
// - With base_size = 60 the part is solid down to the bed;
//   a 12 x 12 pocket only near the top avoids any support clashes.
