module riser() {
    difference() {
        hull() {
            for (i = [0 : sides - 1]) {
                // corners of a square aligned with X/Y, expanding upward
                rotate([0, 0, i * 360 / sides])
                    translate([0, 0, bottom_h])
                        linear_extrude(height = top_h - bottom_h)
                            square([bottom_w, bottom_w], center = true);
            }
        }
        // square pocket centred on the top face
        translate([0, 0, top_h - pocket_d])
            cube([pocket_w, pocket_w, pocket_d + eps]);
    }
}

riser();
