// ---------------- Parameters ----------------
post_d      = 12;     // post diameter (X and Y)
post_h      = 25;     // post height, z = 0 to 25
bar_len     = 108;    // bar length along X
bar_w       = 12;     // bar width along Y
bar_t       = 6;      // bar thickness, z = 25 to 31
screw_d     = 3.4;    // screw hole diameter
screw_depth = 10;     // screw hole depth from bottom face
eps         = 0.5;    // cutter overshoot past faces

$fn = 64;

// ---------------- Model ----------------
union() {
    // Two round posts, centred on y = 0, spaced 96 mm apart
    for (sx = [-1, 1])
        translate([sx * 48, 0, 0])
            cylinder(d = post_d, h = post_h);

    // Straight bar, centred on the origin
    translate([-bar_len / 2, -bar_w / 2, post_h])
        cube([bar_len, bar_w, bar_t]);

    // Screw holes in each post, from bottom face up the axis
    for (sx = [-1, 1])
        translate([sx * 48, 0, -eps])
            cylinder(d = screw_d, h = post_h + eps + screw_depth);
}
```

