// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // plate thickness
gauge_width    = 6;     // narrow section width (Y)
gauge_length   = 40;    // narrow section length (X)
grip_width     = 15;    // end grip width (Y)
grip_length    = 35;    // end grip length (X)
transition_len = 15;    // each grip-to-gauge transition length (X)

total_len = grip_length + transition_len + gauge_length + transition_len + grip_length;

// ---- Model ----
difference() {
    // Body: grip - transition - gauge - transition - grip
    module body() {
        grip(len = grip_length, w = grip_width);
        translate([transition_len, 0, 0])
            grip(len = grip_length, w = grip_width);
        translate([grip_length + transition_len, 0, 0])
            gauge();
        translate([grip_length + transition_len + gauge_length, 0, 0])
            grip(len = grip_length, w = grip_width);
        translate([2 * grip_length + 2 * transition_len + gauge_length, 0, 0])
            grip(len = grip_length, w = grip_width);
    }

    // End grip cutouts
    for (s = [-1, 1])
        translate([s * (grip_length + transition_len), -grip_width / 2 - 1, -1])
            rotate([90, 0, 0])
                linear_extrude(thickness + 2)
                    rectangle(h = grip_width + 2, d = grip_length);
}

module grip(len, w) {
    translate([-len / 2, -w / 2, 0])
        cube([len, w, thickness]);
}

module gauge() {
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
}
