```openscad
// Dog-bone flat tensile test specimen
// Print orientation: lying flat on the bed, centred on the origin

// ---------- Dimensions ----------
total_length = 140;   // overall length along X
thickness    = 4;     // thickness along Z
gauge_width  = 6;     // width of the narrow (gauge) section
gauge_length = 40;    // length of the gauge section
grip_width   = 15;    // width of each grip section
grip_length  = 35;    // length of each grip section
transition   = 15;    // length of each grip-to-gauge transition
eps          = 0.5;   // overshoot for clean boolean cuts

// Derived
half_grip     = grip_width  / 2;
half_gauge    = gauge_width / 2;
grip_start_x  = (total_length / 2) - grip_length;   // outer edge of grips
overlapping   = grip_length + transition + gauge_length + transition + grip_length; // 100 mm central overlap

// ---------- Profile (seen from above) ----------
module dogbone_profile() {
    union() {
        // Grip sections
        translate([-total_length / 2, -half_grip, 0])
            cube([grip_length, grip_width, thickness]);
        translate([ grip_start_x, -half_grip, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -half_gauge, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition regions: width changes linearly from grip_width to gauge_width
        for (s = [-1, 1])
            translate([s * (gauge_length / 2 + transition + eps), -transition, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [0, -half_grip],
                        [transition, -half_grip],
                        [transition, half_grip],
                        [0, half_grip]
                    ]);
    }
}

// ---------- Part ----------
difference() {
    linear_extrude(height = thickness)
        dogbone_profile();

    // Deburr: cut a little into every face to remove 3D-print overhangs / supports
    translate([0, 0, -eps])
        intersection() {
            translate([0, 0, 0])
                linear_extrude(height = thickness + 2 * eps)
                    dogbone_profile();
            translate([0, 0, -eps])
                cube([total_length, grip_width + 2 * eps, thickness + 2 * eps]);
        }
}
