// ---------- Model ----------
difference() {
    hull() {
        // Grip sections
        translate([-total_len/2 + grip_len, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);
        translate([ total_len/2 - grip_len, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);

        // Gauge section
        translate([-gauge_len/2, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);
    }

    // Cut away the gap between grip and transition (overlaps into both)
    translate([-total_len/2 - eps, -trans_w/2, 0])
        cube([trans_len + 2*eps, trans_w, thickness]);
    translate([ total_len/2 + eps, -trans_w/2, 0])
        cube([trans_len + 2*eps, trans_w, thickness]);
