// Flat dog-bone tensile specimen
// Units: mm. Print flat on the bed (z = 0 upward).

$fn = 64;

// ---- Dimensions ----
thickness   = 4;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
overlap     = 1;     // overlap between adjacent sections for a clean hull

// ---- Derived ----
half_gauge = gauge_w / 2;
half_grip  = grip_w / 2;

// Width at each X position (centered on origin)
function width(x) =
    if (x < -grip_len - overlap)          grip_w;
    else if (x <= -gauge_len - overlap)   grip_w;
    else if (x <= -gauge_len / 2 - overlap)
        half_gauge + (half_grip - half_gauge) * (x + gauge_len / 2 + overlap) / trans_len;
    else if (x <= gauge_len / 2 + overlap)
        half_gauge + (half_grip - half_gauge) * (gauge_len / 2 + overlap - x) / trans_len;
    else if (x <= gauge_len + overlap)    gauge_w;
    else if (x < grip_len + overlap)      grip_w;
    else                                  grip_w;

difference() {
    // Main plate
    translate([-total_len / 2, -half_grip, 0])
        cube([total_len, grip_w, thickness]);

    // Central gauge section (underlaps into grips by 'overlap')
    translate([-gauge_len / 2 - overlap, -half_gauge, 0])
        cube([gauge_len + 2 * overlap, gauge_w, thickness]);

    // Weakness holes in the grip areas (breaks the grip into two blocks)
    for (s = [-1, 1])
        translate([s * (total_len / 2 - grip_len - overlap), 0, -overlap])
            cylinder(d = overlap + 1, h = thickness + 2 * overlap);
}
