grip_len       = 35;    // grip section length (X)
transition_len = 15;    // length of each grip->gauge transition (X)

eps            = 0.5;   // cutter overshoot past faces

// ---------- Derived ----------
half_t = transition_len + gauge_len / 2;   // tip of triangle (from centre)
// area under one side curve, extended eps beyond the grip end:
// trapezoid (grip_w -> gauge_w over transition) + triangle (gauge_w at eps)
curve_a = (grip_w + gauge_w) / 2 * transition_len + gauge_w * eps / 2;

// ---------- Model ----------
difference() {
    // Profile in XY, extruded to thickness
    translate([-total_len / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            rotate([90, 0, 0])
                linear_extrude(height = total_len)
                    polygon(points = [
                        [0, grip_w], [half_t, curve_a / half_t * eps],
                        [half_t + gauge_len / 2, grip_w],
                        [half_t + gauge_len / 2, -grip_w],
                        [half_t, -curve_a / half_t * eps],
                        [-half_t, -grip_w], [-half_t, grip_w],
                        [-half_t - gauge_len / 2, -grip_w],
                        [-half_t - gauge_len / 2, grip_w],
                        [-half_t, curve_a / half_t * eps]
                    ]);

    // Central gauge cutter (overshoots top/bottom faces)
    translate([-gauge_len / 2, -gauge_w / 2 - eps, -eps])
        cube([gauge_len, gauge_w + 2 * eps, thickness + 2 * eps]);
