// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness
total_length   = 140;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // grip-to-gauge transition length (X)

// ---- Model ----
difference() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * (total_length / 2 - grip_length), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            w0 = grip_width + (s - 1) * (gauge_width - grip_width);   // grip end width
            w1 = gauge_width + (s - 1) * (gauge_width - grip_width);   // gauge end width
            translate([s * (total_length / 2 - grip_length - transition_len), -w0 / 2, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, w0 / 2],
                        [transition_len, w1 / 2],
                        [transition_len, -w1 / 2],
                        [0, -w0 / 2]
                    ]);
        }
    }

    // Deburr cutter
    for (s = [-1, 1]) {
        translate([s * (total_length / 2 - grip_length - 0.5), -gauge_width / 2 - 0.5, 0])
            cube([gauge_length + 1, gauge_width + 1, thickness + 2]);
    }
}
