```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness = 3;     // specimen thickness (Z)
total_len = 130;   // overall length along X
gauge_w   = 8;     // gauge section width (Y)
gauge_len = 40;    // gauge section length (X)
grip_w    = 15;    // grip section width (Y)
grip_len  = 35;    // grip section length (X)
trans_len = 10;    // transition section length (X)

// ---- Derived ----
mid      = -total_len / 2;          // left end of grip
grip_l   = mid + grip_len;          // end of left grip
trans_l  = grip_l + trans_len;      // end of left transition (gauge start)
gauge_h  = mid + gauge_len;         // end of gauge (overlaps left grip for clean math)

// ---- Width profile (upper surface, x vs y) ----
profile = concat(
    // left grip
    [for (i = [0 : grip_len / 2]) [mid - grip_len + i, grip_w / 2]],
    // left transition
    [for (i = [0 : trans_len]) [trans_l - i, (grip_w - (gauge_w - 1) * i / trans_len) / 2]],
    // gauge
    [for (i = [gauge_len / 2 : -1 : 0]) [mid + i, gauge_w / 2]],
    // right transition
    [for (i = [0 : trans_len]) [mid + gauge_len + trans_len + i, (grip_w - (gauge_w - 1) * i / trans_len) / 2]],
    // right grip
    [for (i = [0 : grip_len / 2]) [mid + gauge_len + trans_len + grip_len / 2 - i, grip_w / 2]]
);

module dogbone() {
    hull() {
        for (p = profile)
            translate([p[0], -p[1], 0])
                cube([thickness, 2 * p[1], thickness]);
    }
}

dogbone();
