            cube([grip_len + eps, grip_w, thickness]);
        translate([gauge_x0, -gauge_w / 2, 0])
            cube([gauge_len + eps, gauge_w, thickness]);
    }
    // Left side grip
    translate([-grip_x1, -grip_w / 2, 0])
        cube([grip_len + eps, grip_w, thickness]);
