// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

$fn = 64;

// ---- Dimensions (mm) ----
specimen_t   = 3;     // thickness
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // each transition length (X)
eps          = 0.5;   // cutter overshoot

total_l = 2 * grip_l + gauge_l + 2 * transition_l; // 130 mm

// Width profile from the 2D (X, Y) plane
function profile_w(x) =
    if (x < transition_l)
        // left grip -> transition: 15 -> 8
        15 - (x / transition_l) * (15 - 8)
    else if (x < transition_l + gauge_l)
        // gauge section
        8
    else
        // right transition -> grip: 8 -> 15
        8 + ((x - (transition_l + gauge_l)) / transition_l) * (15 - 8);

module dogbone() {
    // 2D shape, centred on origin in X, Y
    module shape_2d() {
        hull() {
            for (s = [-1, 1]) {
                translate([s * grip_l, -grip_w / 2]) cube([grip_l, grip_w, 1]);
                translate([s * (grip_l + transition_l + gauge_l / 2), -gauge_w / 2])
                    cube([gauge_l, gauge_w, 1]);
            }
        }
    }

    // Transform to real coordinates: extrude in Y, then rotate so
    // the extrusion becomes +Z and the part lies flat on the bed.
    translate([-total_l / 2, -profile_w(0) / 2, 0])
        rotate([90, 0, 0])
            linear_extrude(height = specimen_t)
                shape_2d();
}

dogbone();
