// Flat tensile test specimen (dog-bone shape) printed lying flat on the bed
// Units: mm. Print orientation: bottom face on the bed (z = 0), builds +Z.

// ---------- Dimensions ----------
specimen_thick = 3;     // overall thickness (Z)
gauge_width    = 8;     // width of the narrow gauge section (Y)
gauge_length   = 40;    // length of the gauge section along X
grip_width     = 15;    // width of each end grip section (Y)
grip_length    = 35;    // length of each grip section along X
transition_len  = 10;    // length of each grip->gauge transition along X
eps            = 0.5;   // cutter overshoot past faces

// Derived
total_len = 2 * grip_length + gauge_length + 2 * transition_len;   // 130 mm

// ---------- Model ----------
module dog_bone_2d() {
    // Outline seen from above: draw left to right (X -65 .. +65)
    linear_extrude(height = specimen_thick) {
        hull() {
            // Left grip
            translate([-grip_length, -grip_width / 2]) square([grip_length, grip_width]);
            // Right grip
            translate([grip_length, -grip_width / 2]) square([grip_length, grip_width]);
            // Gauge section, centred on the origin
            translate([-gauge_length / 2, -gauge_width / 2])
                square([gauge_length, gauge_width]);
        }
    }
}

difference() {
    dog_bone_2d();

    // Cut the two transition regions so the above hull is exact.
    // Each cutter runs past the faces it cuts by eps.
    for (s = [-1, 1]) {
        x0 = (s < 0) ? -grip_length : gauge_length;   // grip end (x = -65 or +65)
        // y runs from 4 to 7.5, which follows the straight 15->8 width change
        translate([x0 - eps, 4])
            cube([eps + transition_len, 3.5, specimen_thick + 2 * eps]);
        translate([x0 - eps, -7.5])
            cube([eps + transition_len, 3.5, specimen_thick + 2 * eps]);
    }
}
