    if (x < -transition_l)
        grip_w
    else if (x < -gauge_l / 2)
        grip_w + (8 - grip_w) * (x + transition_l) / transition_l
    else if (x > gauge_l / 2)
        grip_w + (8 - grip_w) * (x - transition_l) / transition_l
    else
        8;

module dogbone() {
