        for (s = [-1, 1])
            translate([s * (total_l / 2 - transition_l - gauge_l / 2),
                       -profile_w(total_l / 2 - transition_l - gauge_l / 2) / 2,
                       0])
                cube([transition_l + gauge_l / 2 + eps,
                      profile_w(total_l / 2 - transition_l - gauge_l / 2),
                      specimen_t]);
    }
}

