        // grip sections at each end
        for (s = [-1, 1])
            translate([s * tap_start, 0])
                rotate([0, 0, s > 0 ? 90 : -90])
                    cube([grip_width, grip_length, 0]);
        // central gauge section
        translate([-half_gauge, 0])
            rotate([0, 0, 90])
                cube([gauge_width, gauge_length, 0]);
    }
