    // main plate
    linear_extrude(thickness) profile();

    // straighten transitions: cut wedges so the hull becomes linear
    for (s = [-1, 1]) {
        x0 = s * tap_start;
        // wedge from full grip width down to gauge width over transition_len
        translate([x0 - transition_len / 2, 0])
            rotate([0, 90, 0])
                linear_extrude(height = transition_len)
                    polygon(points = [
                        [0, grip_width],
                        [transition_len / 2, gauge_width],
                        [transition_len / 2, -gauge_width],
                        [0, -grip_width]
                    ]);
