grip_x0 = -(total_length / 2 + grip_length / 2);   // left grip start
gauge_x0 = -total_length / 2 + grip_length + transition_len; // gauge start

// ---------- Modules ----------
module grip_section() {
    // width runs from grip_width at x = 0 out to total_length at x = grip_length
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                [0, -grip_width / 2],
                [grip_length, -grip_width / 2],
                [grip_length, grip_width / 2],
                [0, grip_width / 2]
            ]);
}

module transition_section() {
    // width runs from gauge_width at x = 0 out to grip_width at x = transition_len
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                [0, -gauge_width / 2],
                [transition_len, -grip_width / 2],
                [transition_len, grip_width / 2],
                [0, gauge_width / 2]
            ]);
}

