union() {
    for (s = [-1, 1])
        translate([s * grip_x0, 0, 0])
            grip_section();

    translate([gauge_x0, 0, 0])
        transition_section();

    translate([-gauge_x0, 0, 0])
        mirror([1, 0, 0])
            transition_section();
