// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // grip-to-gauge transition length (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
n_grips   = 2;          // grip sections at each end
n_trans   = n_grips - 1;// number of transition regions
pitch     = gauge_len + transition_len;  // repeat pitch (gauge + transition)

// ---- Model ----
difference() {
    // Full plate
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);

    // Grip sections and transitions, built left to right
    for (i = [0 : n_grips - 1]) {
        x0 = -total_length / 2 + i * pitch;  // start of grip
        // Grip block, extended into the following transition to avoid coplanar faces
        translate([x0, -grip_width / 2, -cut_extra])
            cube([grip_length + transition_len, grip_width, thickness + 2 * cut_extra]);
    }

    // Central gauge section
    translate([-gauge_length / 2, -gauge_width / 2, -cut_extra])
        cube([gauge_length, gauge_width, thickness + 2 * cut_extra]);

    // Transition regions: width changes linearly from grip to gauge
    for (j = [0 : n_trans - 1]) {
        x0 = -total_length / 2 + (j + 1) * transition_len;  // gauge-end of transition
        w0 = (j % 2 == 0) ? gauge_width : grip_width;        // left-side width
        w1 = (j % 2 == 1) ? gauge_width : grip_width;        // right-side width
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [x0 - transition_len, w0 / 2],
                    [x0 + transition_len, w1 / 2],
                    [x0 + transition_len, -w1 / 2],
                    [x0 - transition_len, -w0 / 2]
                ]);
    }
}
