// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters (mm) ----------
thickness     = 4;     // specimen thickness (Z)
total_length  = 110;   // overall length along X
gauge_width   = 8;     // narrow gauge section width (Y)
gauge_length  = 30;    // gauge section length (X)
grip_width    = 19;    // grip section width (Y)
grip_length   = 25;    // grip section length (X)
transition    = 15;    // transition section length (X)
cut_extra     = 0.5;   // overshoot of cutting shapes past faces

$fn = 64;              // curve resolution

// ---------- Derived ----------
half_gauge    = gauge_width  / 2;
half_grip     = grip_width   / 2;
grip_end_x    = (total_length - gauge_length) / 2 - transition;  // grip start (from centre)

// ---------- 2D profile (top half, y >= 0) ----------
module profile_points() {
    for (sx = [-1, 1]) {
        if (sx < 0) {
            // left grip
            for (t = [0 : grip_length / 3 : grip_length])
                translate([sx * (grip_end_x - grip_length / 2) + t, half_grip]) yield point();
            // left transition
            for (t = [0 : transition / 3 : transition])
                translate([sx * (grip_end_x - transition / 2) - t,
                           half_grip - (sx < 0 ? 0.5 : 0) * (half_grip - half_gauge) * t / transition]) yield point();
        } else {
            // right grip
            for (t = [0 : grip_length / 3 : grip_length])
                translate([sx * (grip_end_x - grip_length / 2) + t + transition + gauge_length, half_grip]) yield point();
            // right transition
            for (t = [0 : transition / 3 : transition])
                translate([sx * (grip_end_x - transition / 2) - t + transition + gauge_length,
                           half_grip - (sx < 0 ? 0.5 : 0) * (half_grip - half_gauge) * t / transition]) yield point();
        }
    }
    // centre gauge section
    for (x = [-gauge_length / 2 : gauge_length / 2])
        translate([x, 0]) yield point();
}

// ---------- Model ----------
difference() {
    // solid body from profile
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [p() | for (p = profile_points())]);

    // grip pockets (cut into top face)
    for (sx = [-1, 1]) {
        translate([sx * (grip_end_x + grip_length / 2), -half_grip - cut_extra, 0])
            cube([grip_length, grip_width + 2 * cut_extra, thickness + cut_extra]);
    }
}
