module specimen() {
    w(x) =
        if (x < -grip_length - transition_length)
            grip_width;
        else if (x <= -transition_length)
            width_via_cord(x, grip_width, gauge_width, transition_length);
        else if (x < 0)
            gauge_width;
        else if (x <= transition_length)
            gauge_width;
        else if (x <= grip_length + transition_length)
            width_via_cord(x, gauge_width, grip_width, transition_length);
        else
            grip_width;

    difference() {
        // Plate, centred in X/Y, sitting on z = 0
        translate([-total_length / 2, -specimen_thickness / 2, 0])
            cube([total_length, specimen_thickness, 10]);

        // Grip-end cutters (extend past both side faces)
        for (s = [-1, 1])
            translate([s * (grip_length + transition_length / 2), -cut_overlap, -cut_overlap])
                cube([grip_length + transition_length, specimen_thickness + 2 * cut_overlap,
                      10]);
    }
}

// Linear width change between two end sections (cordage style)
function width_via_cord(x, w_start, w_end, len) =
    w_start + (w_end - w_start) * (x + len / 2) / len;
```

```openscad
// Flat dog-bone tensile specimen, printed lying flat on the bed
// Units: mm. Oriented with the plate in the XY plane, z = 0 upward.

// ---------------- Parameters ----------------
plate_t       = 3;     // plate thickness (Z)
total_len     = 110;   // overall length along X
gauge_w       = 10;    // width of the central gauge section (Y)
gauge_len     = 30;    // length of the gauge section (X)
grip_w        = 15;    // width of each grip section (Y)
grip_len      = 25;    // length of each grip section (X)
transition_w  = 15;    // width of grip sections used as transition
eps           = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Derived ----------------
// X positions of section boundaries (centreed on origin)
x_g_start = -(grip_len + transition_w) / 2;   // gauge start
x_g_end   =  (grip_len + transition_w) / 2;   // gauge end
x_r_start =  (total_len - gauge_len) / 2;     // right grip start
x_r_end   = total_len / 2;                    // right grip end

// ---------------- Modules ----------------
module width_at(x) {
    // Piecewise width: grip -> transition -> gauge -> transition -> grip
    if (x <= x_g_start)
        draw_rect(x, grip_w, grip_len);
    else if (x < x_g_end)
        draw_transition(x, transition_w, gauge_w);
    else if (x < x_r_start)
        draw_transition(x, gauge_w, transition_w);
    else if (x <= x_r_end)
        draw_rect(x, grip_w, grip_len);
    else
        error("x = " + x + " lies outside the specimen");
}

module draw_rect(cx, wy, lx) {
    // Width constant over [cx - lx/2, cx + lx/2]
    translate([cx - lx / 2 - eps, -wy / 2, 0])
        cube([lx + 2 * eps, wy, plate_t]);
}

// Linear width change over a segment of length seg_len
module draw_transition(x, w_start, w_end) {
    seg_len = x - x_g_start + (x < x_r_start ? gauge_len : 0);
    ratio   = (x - (x_g_start + seg_len / 2)) / seg_len;
    w(x) = mix(w_start, w_end, ratio);
    // Extend cutter past both end faces by eps
    translate([x_g_start - eps, -w(x_g_start - eps) / 2, 0])
        rotate([90, 0, 0])
            linear_extrude(height = plate_t + 2 * eps)
                polygon([
                    for (s = [0 : 100])
                        [x_g_start - eps + s * (x - x_g_start + (x < x_r_start ? gauge_len : 0)) / 100,
                         -w(x_g_start - eps + s * (x - x_g_start + (x < x_r_start ? gauge_len : 0)) / 100) / 2]
                ]);
}

// ---------------- Part ----------------
difference() {
    union() {
        // Central gauge section
        translate([-gauge_len / 2, -w / 2, 0])
            cube([gauge_len, w, plate_t]);
        // Grip sections
        for (s = [-1, 1])
            translate([s * (total_len / 2 - grip_len / 2), -w / 2, 0])
                cube([grip_len, w, plate_t]);
    }
    // Transition regions (overlap into grip and gauge by eps)
    for (t = [transition_w, -transition_w])
        translate([t - eps, -w / 2, 0])
            rotate([90, 0, 0])
                linear_extrude(height = plate_t + 2 * eps)
                    polygon(points = [for (x = [t - eps, t + eps]) [x, width_at(x)]]);
}
