grip_x0 = -(total_length / 2 - grip_length / 2);   // left grip start X
gauge_x0 = grip_x0 + grip_length;                  // gauge start X
right_x = total_length / 2 - grip_length / 2;      // right grip end X

// ---------- Model ----------
module dogbone() {
    w = linear_extrude(thickness);

    // profile in XY: grip -> transition -> gauge -> transition -> grip
    profile = concat(
        [for (s = [0 : 1]) [grip_x0 + s * grip_length, grip_width * s + grip_width * (1 - s) / 2]],
        [for (s = [0 : 1]) [gauge_x0 + s * transition_len, grip_width - (grip_width - gauge_width) * s]],
        [for (s = [0 : 1]) [total_length / 2 - transition_len - s * gauge_length, gauge_width * s + gauge_width * (1 - s)]],
        [for (s = [0 : 1]) [right_x - grip_length + s * transition_len, grip_width - (grip_width - gauge_width) * s]],
        [right_x, grip_width / 2]
    );

    // close the loop
    union() {
        w(polygon = profile);
        translate([profile[0][0], profile[0][1], 0])
            cube([total_length - grip_x0 - profile[0][0], grip_width, thickness + 2 * eps]);
    }
}

