```openscad
// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, centred on the origin.
// The profile is drawn in XY and extruded along +Z.

// ---------------- Parameters ----------------
specimen_thickness = 3;     // overall thickness (Z) mm
total_length       = 110;   // overall length along X mm
width_gauge        = 10;    // narrow gauge width (Y) mm
length_gauge       = 30;    // gauge length (X) mm
width_grip         = 15;    // grip width (Y) mm
length_grip        = 25;    // grip length (X) mm
length_transition  = 15;    // transition length between grip and gauge (X) mm
overcut            = 0.5;   // extra length so cutters pass beyond faces mm

$fn = 64;                   // no curved features here; set for consistency

// ---------------- Derived ----------------
x_center_gauge     = 0;                                           // gauge centred on origin
x_start_gauge      = x_center_gauge - length_gauge / 2;           // -15
x_end_gauge        = x_center_gauge + length_gauge / 2;           // 15
x_start_transition  = x_end_gauge + length_transition;            // 30
x_end_transition   = x_start_transition + length_transition;     // 45
x_start_grip      = x_end_transition + length_grip;              // 70
x_end_grip       = x_start_grip + length_grip;                   // 95
x_start_stub     = -x_end_grip;                                   // -95
x_end_stub       = -x_start_transition - length_grip;           // -70

// ---------------- Profile (top face) ----------------
module top_profile() {
    // Scan along X from the far left to the far right and step up
    // at each feature boundary.  The width is constant between the
    // grip and gauge end points, which creates two flat spurs
    // (the stubs) that keep the area above the cutter.
    current_y = 0;
    for (x = [x_start_stub, x_end_stub, x_start_transition,
              x_end_transition, x_start_gauge, x_end_gauge,
              x_end_grip, x_start_grip]) {
        translate([x, 0, 0])
            linear_extrude(height = thickness)
                circle(r = current_y);
    }
}

// ---------------- Parts ----------------
module grip_section() {
    // grip + one transition + half of the constant‑width region
    translate([x_start_transition - length_grip, -width_grip / 2, 0])
        cube([length_grip + length_transition, width_grip, thickness]);
}

module gauge_section() {
    // gauge + one transition + half of the constant‑width region
    translate([x_start_gauge - length_transition, -width_grip / 2, 0])
        cube([length_transition + length_gauge, width_grip, thickness]);
}

// ---------------- Assembly ----------------
difference() {
    union() {
        for (s = [-1, 1])
            translate([s * x_start_stub, 0, 0])
                mirror([1, 0, 0])
                    top_profile();
        for (s = [-1, 1])
            translate([s * x_end_transition - length_grip, 0, 0])
                mirror([1, 0, 0])
                    grip_section();
        for (s = [-1, 1])
            translate([s * x_end_transition, 0, 0])
                mirror([1, 0, 0])
                    gauge_section();
    }
    // Central spine that runs through every cut, no matter how the
    // model is reoriented.  Its half‑thickness is reduced by the
    // overcut, so the cutter always penetrates past all faces.
    translate([-total_length / 2 - overcut, 0, 0])
        cube([total_length + 2 * overcut, thickness - 2 * overcut,
              thickness + 2 * overcut]);
}
