// ---------- Dimensions (mm) ----------
specimen_thickness = 3;     // plate thickness (Z)
overall_length     = 110;   // total length along X
gauge_width        = 10;    // width of the narrow gauge section (Y)
gauge_length       = 30;    // length of the gauge section (X)
grip_width         = 15;    // width of each grip section (Y)
grip_length        = 25;    // length of each grip section (X)
transition_length  = 15;    // length of the flank transition (X)

// Derived
half_gauge_len = gauge_length / 2;                 // 15
grip_start_x   = half_gauge_len + transition_length; // 30
// X runs from -55 to +55 (overall_length / 2)

// ---------- Model ----------
module flat_dogbone() {
    // Width profile seen from above (Y), defined piecewise along X
    function width_at(x) =
        if (x <  -grip_start_x)
            grip_width
        else if (x <= -half_gauge_len)
            // flank: linear change from grip width (15) to gauge width (10)
            grip_width - (x + grip_start_x) * (grip_width - gauge_width) / transition_length
        else if (x <= half_gauge_len)
            gauge_width
        else if (x <= grip_start_x)
            // flank: linear change from gauge width (10) to grip width (15)
            gauge_width + (x - half_gauge_len) * (grip_width - gauge_width) / transition_length
        else
            grip_width;

    // Check: the user's dimensions leave a 25 mm gap between the two
    // grip blocks (overall 110 - 2*30 - 2*25 = 25), so the profile is
    // well defined for every x in [-55, 55].
    hull() {
        for (x = [-overall_length / 2 : 1 : overall_length / 2])
            translate([x, 0, 0])
                cube([1, width_at(x), specimen_thickness]);
    }
}

flat_dogbone();
