// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
end_x = -total_length / 2;   // leftmost X
mid_x = total_length / 2;    // rightmost X

// ---- Model ----
module dog_bone() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([end_x + s * (mid_x - end_x - gauge_length - 2 * transition_len) / 2,
                       -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (linear width change)
        for (s = [-1, 1]) {
            x0 = end_x + s * (mid_x - end_x - gauge_length - 2 * transition_len) / 2 + grip_length;
            rotate([90, 0, s * 90])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [x0, -grip_width / 2],
                        [x0 + transition_len, -grip_width / 2],
                        [x0 + transition_len, -gauge_width / 2],
                        [x0, -gauge_width / 2]
                    ]);
        }
    }

    // Optional: small centre hole to avoid over-constraining in some slicers
    translate([0, 0, -1])
        cylinder(d = 2, h = thickness + 2);
}

dog_bone();
