// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions ----
thickness      = 3;     // Z thickness
total_length   = 130;   // overall length along X
gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
x0 = -total_length / 2;              // left end
w1 = grip_width;                     // grip width
l1 = grip_length;                    // grip length
w2 = gauge_width;                    // gauge width
l2 = gauge_length;                   // gauge length
halo = 0.5;                          // overlap for smooth transitions

// Width profile along X: left grip -> transition -> gauge -> transition -> right grip
function width(p) =
    linear(p,
        [x0, x0 + l1 - halo], w1, w2 + halo * (w1 - w2) / transition_len
    ) + linear(p,
        [x0 + l1 - halo, x0 + l1 + transition_len - halo],
        w2 + halo * (w1 - w2) / transition_len, w2
    ) + linear(p,
        [x0 + l1 + transition_len - halo, x0 + l1 + transition_len + l1 - halo],
        w2, w1
    );

difference() {
    // Body
    linear_extrude(height = thickness)
        scan(width, range = [x0, x0 + total_length]);

    // Small hole in gauge section
    translate([x0 + l1 / 2, 0, -1])
        cylinder(d = 3.5, h = thickness + 2);
}
