// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---------- Dimensions ----------
thickness     = 3;     // specimen thickness (Z)
total_len     = 130;   // overall length along X (mm)
gauge_w       = 8;     // gauge section width (Y)
gauge_len     = 30;    // gauge section length (X)
grip_w        = 15;    // grip section width (Y)
grip_len      = 35;    // grip section length (X)
transition_w  = 15;    // transition length (X), width changes linearly

// ---------- Derived ----------
grip_start    = -(total_len / 2) + grip_len / 2;   // grip inner end
gauge_start   = grip_start + grip_len;             // gauge inner end
// (symmetric about origin)

// ---------- Model ----------
module dog_bone_2d() {
    union() {
        // Grip sections
        translate([grip_start, -grip_w / 2, 0])
            cube([grip_len, grip_w, thickness]);
        translate([-grip_start, -grip_w / 2, 0])
            cube([grip_len, grip_w, thickness]);

        // Gauge section
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Transitions (linear width change via hull)
        for (s = [1, -1]) {
            hull() {
                translate([s * (total_len / 2 - gauge_start), -gauge_w / 2, 0])
                    cube([transition_w, gauge_w, thickness]);
                translate([s * (total_len / 2 - gauge_start), -grip_w / 2, 0])
                    cube([transition_w, grip_w, thickness]);
            }
        }
    }
}

difference() {
    dog_bone_2d();
    // Deburr / round edges
    translate([0, 0, -1])
        linear_extrude(height = thickness + 2)
            offset(d = 0.5)
                polygon([
                    [-(total_len / 2), -grip_w / 2],
                    [total_len / 2,  -grip_w / 2],
                    [total_len / 2,   grip_w / 2],
                    [-(total_len / 2), grip_w / 2]
                ]);
}
