```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

// ---------- Dimensions ----------
thickness      = 3;     // specimen thickness (Z)
overall_len    = 130;   // total length along X (mm)
gauge_width    = 8;     // width of central gauge section (Y)
gauge_len      = 30;    // length of gauge section (X)
grip_width     = 15;    // width of end grip sections (Y)
grip_len       = 35;    // length of each grip section (X)
trans_len      = 15;    // length of each transition zone (X)

eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Check ----------
// 2 * grip_len + 2 * trans_len + gauge_len = overall_len
assert(abs(2 * grip_len + 2 * trans_len + gauge_len - overall_len) < 0.001,
       "lengths do not add up");

// ---------- Model ----------
module transition(wx, wx2, len) {
    // Trapezoid in X-Y, extruded. Width changes linearly from wx to wx2.
    rotate([90, 0, 90])
        linear_extrude(height = len)
            polygon(points = [
                [0, 0],
                [len, 0],
                [len, wx2],
                [0, wx]
            ]);
}

module side_grip() {
    translate([-overall_len / 2 + grip_len / 2, -grip_width / 2, 0])
        cube([grip_len, grip_width, thickness]);
}

difference() {
    union() {
        two_gauges();      // gauge section + both transition zones
        two_side_grips();  // grip sections at each end
    }

    // Through-hole in the gauge section
    translate([0, 0, -eps])
        cube([gauge_len, gauge_width, thickness + 2 * eps]);
}

module two_gauges() {
    plus_trans = trans_len + trans_len;   // two transition zones
    half_t     = (overall_len - gauge_len - plus_trans) / 2;
    // half_t = grip_len in this layout

    for (sx = [-1, 1])
        translate([sx * half_t, -gauge_width / 2, 0])
            cube([gauge_len, gauge_width, thickness]);
}

module two_side_grips() {
    for (sx = [-1, 1])
        translate([sx * (overall_len / 2 - grip_len / 2),
                   -grip_width / 2, 0])
            cube([grip_len, grip_width, thickness]);
}
