        for (sx = [-1, 1]) {
            target_w = sx < 0 ? grip_width : gauge_width;
            hull() {
                translate([sx * left_grip_x0 - transition_len, -grip_width/2, 0])
                    cube([transition_len, grip_width, thickness]);
                translate([-sx * gauge_length/2 - transition_len, -target_w/2, 0])
                    cube([transition_len, target_w, thickness]);
            }
        }
    }
}

