// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// grip end x = -total_length/2 + half_grip ; gauge end x = -half_gauge
// check: -65 + 17.5 = -47.5 and -15, gap = 32.5 ? transition 15+15 = 30 -> overlap 1.25
// fix: shift grip outward by the overlap so the 15 mm transition runs cleanly
overlap = (grip_length + gauge_length - total_length) / 2; // 1.25 mm
grip_start_x = -total_length / 2 + grip_length - overlap;   // -48.75
gauge_end_x  = -half_gauge;                                 // -15
transition_end_x = gauge_end_x + transition_len;            // 0

module width(x) {
    if (x < grip_start_x)
        return grip_width;
    else if (x < transition_end_x)
        return grip_width - (x - grip_start_x) * (grip_width - gauge_width) / transition_len;
    else
        return gauge_width;
}

difference() {
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(height = thickness)
            polygon([for (x = [-total_length / 2 : 1 : total_length / 2])
                     [x, width(x)], [x, -width(x)]]);
}
