// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: lying flat on the bed, centred on the origin in X and Y.
// The thickness builds upward along +Z from z = 0.

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // width of the narrow gauge section (Y)
gauge_length   = 30;    // length of the gauge section (X)
grip_width     = 15;    // width of each grip section (Y)
grip_length    = 35;    // length of each grip section (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived values ----
grip_end_x     = grip_length / 2;          // grip section end offset from origin (+X)
trans_end_x    = gauge_length / 2 - 1;     // transition end, 1 mm short of gauge
overlap        = grip_end_x + transition_len - trans_end_x; // overlap = 15 mm
effective_grip = grip_length - overlap;   // visible grip length after overlap (15 mm)

// ---- Model ----
difference() {
    // Upper face (z = thickness), drawn with the 2D X/Y centred on the origin
    translate([-total_length / 2, -thickness / 2, thickness])
        linear_extrude(height = thickness)
            polygon([
                // Grip section (+X)
                [effective_grip / 2 - 15, -grip_width / 2],
                [effective_grip / 2 - 15, grip_width / 2],
                [grip_end_x, grip_width / 2],
                [grip_end_x, -grip_width / 2],
                // Transition (+X), width changing linearly from grip to gauge
                [trans_end_x, grip_width / 2],
                [trans_end_x, -grip_width / 2],
                // Gauge section (-X)
                [-gauge_length / 2 + 1, gauge_width / 2],
                [-gauge_length / 2 + 1, -gauge_width / 2],
                // Transition back to grip (-X), width changing linearly
                [-(trans_end_x - overlap), gauge_width / 2],
                [-(trans_end_x - overlap), -gauge_width / 2],
                // Grip section (-X)
                [-(effective_grip / 2 - 15), gauge_width / 2],
                [-(effective_grip / 2 - 15), -grip_width / 2]
            ]);
}
