// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
grip_start_x   = -total_length / 2 + grip_length;  // grip outer edge
gauge_start_x  = grip_start_x - transition_len;     // gauge inner edge
gauge_end_x    = gauge_start_x + gauge_length;     // gauge outer edge
transition_end_x = gauge_end_x - transition_len;   // grip inner edge (check: grip_start_x - 2*transition_len)

// width at a given X position, building outward from the gauge section
module width_at(x) {
    if (x < gauge_start_x - 0.001)
        return grip_width;
    else if (x < gauge_end_x + 0.001)
        return gauge_width;
    else if (x < transition_end_x + 0.001)
        // linearly interpolate from gauge_width (at x = gauge_end_x) to grip_width (at x = transition_end_x)
        return gauge_width + (x - gauge_end_x) * (grip_width - gauge_width) / transition_len;
    else
        return grip_width;
}

difference() {
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(height = thickness)
            polygon([for (x = [-total_length / 2 : 1 : total_length / 2])
                     [x, width_at(x)], [x, -width_at(x)]]);
}
