```openscad
// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 upward

// ---------- Parameters ----------
wheel_d      = 60;    // outer diameter of rim (mm)
rim_w        = 4;     // rim width (mm)
hub_d        = 16;    // hub diameter (mm)
axle_hole_d  = 5;     // axle hole diameter (mm)
spoke_count  = 5;     // number of spokes
spoke_w      = 5;     // spoke width (mm)
spoke_start  = 0;     // angle of first spoke (deg, 0 = +X axis)
eps          = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = wheel_d, h = rim_w);

        // Hub
        translate([0, 0, rim_w])
            cylinder(d = hub_d, h = rim_w);

        // Spokes: from hub radius to rim radius
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([0, 0, rim_w])
                rotate([0, 0, a])
                    translate([hub_d / 2 + 1, -spoke_w / 2, 0])
                        cube([spoke_w, spoke_w, rim_w]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_hole_d, h = rim_w + 2 * eps);
}
```

