// Spoked wheel for a small sample cart
// Flat part, printed lying on the bed

// ---- Dimensions (mm) ----
wheel_thickness = 5;     // overall thickness (Z)
outer_diameter  = 60;    // outer rim diameter
rim_width       = 4;     // rim width (radial)
hub_diameter    = 16;    // hub diameter
axle_hole       = 5;     // axle hole diameter
spoke_count     = 5;     // number of spokes
spoke_width     = 5;     // spoke width (radial)

// ---- Derived ----
outer_r = outer_diameter / 2;
rim_r   = outer_r - rim_width;

// ---- Model ----
difference() {
    union() {
        // Rim
        cylinder(d = outer_diameter, h = wheel_thickness, $fn = 128);
        translate([0, 0, -1])
            cylinder(d = rim_r, h = wheel_thickness + 2, $fn = 128);

        // Hub
        translate([0, 0, -1])
            cylinder(d = hub_diameter, h = wheel_thickness + 2);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_diameter / 2, -spoke_width / 2, -1])
                    cube([outer_r - hub_diameter / 2, spoke_width, wheel_thickness + 2]);
    }

    // Axle hole, first along +X
    translate([axle_hole / 2, 0, -1])
        rotate([90, 0, 0])
            cylinder(d = axle_hole, h = wheel_thickness + 2);
}
