outer_diameter    = 60;   // outer rim diameter
thickness         = 5;    // part thickness (Z)
rim_width         = 4;    // rim width (radial)
hub_diameter      = 16;   // hub outer diameter
axle_hole_d       = 5;    // axle hole diameter
spoke_count       = 5;    // number of spokes
spoke_width       = 5;    // spoke width (radial)
cut_extra         = 0.5;  // overshoot for clean boolean cuts
$fn               = 128;  // smoothness of curved shapes

// ---------- Derived ----------
rim_inner_d = outer_diameter - 2 * rim_width;
speaks_span = outer_diameter - hub_diameter;  // spoke tip to hub wall

// ---------- Model ----------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = outer_diameter, h = thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = rim_inner_d, h = thickness + 2 * cut_extra);

        // Hub
        cylinder(d = hub_diameter, h = thickness);

        // Spokes, evenly spaced, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_diameter / 2 - speaks_span / 2, -spoke_width / 2, 0])
                    cube([spokes_span, spoke_width, thickness]);
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = thickness + 2 * cut_extra);
}
