// Spoked wheel for small sample cart
// Flat part, prints on the bed, centred on origin

// ---------- Parameters ----------
wheel_d      = 60;   // outer diameter of rim (mm)
rim_w        = 4;    // rim width (mm)
hub_d        = 20;   // hub outer diameter (mm)
axle_hole_d  = 6;    // axle hole diameter (mm)
spoke_count  = 8;    // number of spokes
spoke_w      = 4;    // spoke width (mm)
spoke_start  = 0;    // angle of first spoke (deg, +X axis)
eps          = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = wheel_d, h = rim_w);

        // Hub (filled, extends into rim to fuse solidly)
        translate([0, 0, rim_w - eps])
            cylinder(d = hub_d, h = eps + 0.01);

        // Spokes: radial blocks from hub to rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            x0 = (hub_d / 2 - 1);   // spoke starts slightly inside hub
            x1 = (wheel_d / 2 - 1); // spoke ends slightly inside rim
            rotate([0, 0, a])
                translate([x0, -spoke_w / 2, rim_w - eps])
                    cube([x1 - x0, spoke_w, eps + 0.01]);
        }
    }

    // Axle hole through the centre (extends past both faces)
    translate([0, 0, -eps])
        cylinder(d = axle_hole_d, h = rim_w + 2 * eps);
}
