    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * cut_extra);

        // Spokes: from hub radius to rim outer radius
        for (i = [0 : spoke_count - 1]) {
