            translate([hub_diameter / 2 - 0.01, 0, -cut_extra])
                rotate([0, 0, a])
                    cube([spoke_width, outer_diameter / 2, wheel_thickness + 2 * cut_extra]);
        }
    }

    // Axle hole through centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra);
}
