// Spoked wheel for a small sample cart
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters ----------
wheel_thickness = 8;    // part thickness (Z)
outer_diameter  = 60;   // outer rim diameter
rim_width       = 4;    // rim width (radial)
hub_diameter    = 20;   // hub diameter
axle_hole       = 6;    // axle hole diameter
spoke_count     = 8;    // number of spokes
spoke_width     = 4;    // spoke width (radial)
spoke_start_ang = 0;    // first spoke along +X axis
overlap         = 0.01; // overlap to avoid zero-thickness joints

$fn = 96;

// ---------- Derived ----------
rim_inner_d = outer_diameter - 2 * rim_width;
hub_r       = hub_diameter / 2;
rim_r       = outer_diameter / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer ring
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub with axle hole
        translate([0, 0, -overlap])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * overlap);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_r - overlap, 0, -overlap])
                rotate([0, 0, a])
                    cube([spoke_width, rim_r, wheel_thickness + 2 * overlap]);
        }
    }

    // Axle hole through centre
    translate([0, 0, -overlap])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * overlap);
}
