// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 128;

// ---- Dimensions (mm) ----
wheel_od        = 100;   // outer rim diameter
wheel_width     = 5;     // rim width (thickness)
hub_d           = 14;    // hub diameter
axle_d          = 8;     // axle hole diameter
spoke_count     = 8;     // number of spokes
spoke_width     = 5;     // spoke width (radial)
spoke_start_ang = 0;     // first spoke along +X axis

eps             = 0.5;   // cutter overshoot

// ---- Derived ----
outer_r = wheel_od / 2;
hub_r   = hub_d / 2;

difference() {
    // Rim + hub body
    union() {
        cylinder(d = wheel_od, h = wheel_width);
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = wheel_width + 2 * eps);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_width + 2 * eps);

    // Spokes: from hub perimeter to rim perimeter
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_ang + i * 360 / spoke_count;
        translate([hub_r, 0, -eps])
            rotate([0, 0, a])
                translate([0, -spoke_width / 2, 0])
                    cube([outer_r - hub_r, spoke_width, wheel_width + 2 * eps]);
    }
}
