// ---------- Parameters ----------
wheel_d        = 100;   // outer diameter of rim
wheel_t        = 5;     // rim thickness (width)
spoke_count    = 8;     // number of spokes
spoke_w        = 5;     // spoke width (radial)
hub_d          = 14;    // hub diameter
axle_d         = 8;     // axle hole diameter
start_angle    = 0;     // first spoke along +X axis
eps            = 0.5;   // cutter overshoot past faces
$fn            = 128;   // curve resolution

// ---------- Model ----------
difference() {
    // Outer rim
    cylinder(d = wheel_d, h = wheel_t);

    // Spokes: from near hub to near rim
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / spoke_count])
            translate([0, -spoke_w / 2, -eps])
                cube([wheel_d / 2 - hub_d / 2, spoke_w, wheel_t + 2 * eps]);
    }

    // Hub (overlaps spokes, leaves a solid centre)
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = wheel_t + 2 * eps);

    // Axle hole through the centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_t + 2 * eps, $fn = 64);
}
