// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, builds upward in +Z

// ---------------- Parameters ----------------
part_thickness   = 8;     // overall part thickness (Z)
rim_outer_d      = 80;    // outer diameter of the rim
rim_width        = 4;     // rim width (radial, X)
hub_d            = 14;    // hub outer diameter
axle_hole_d      = 8;     // central axle hole diameter
spoke_count      = 6;     // number of spokes
spoke_width      = 5;     // spoke width (Y), hub to rim
spoke_start_ang  = 0;     // first spoke along +X axis
cut_extra        = 0.5;   // extra length for cutting shapes past faces
$fn              = 128;   // facet count for round features

// ---------------- Model ----------------
difference() {
    union() {
        // Rim (ring)
        translate([0, -rim_width/2, 0])
            rotate([90, 0, 0])
                cylinder(d = rim_outer_d, h = rim_width);

        // Hub (centre disc with axle hole)
        translate([0, 0, -cut_extra])
            cylinder(d = hub_d, h = part_thickness + 2 * cut_extra);

        // Spokes (radial, hub to rim)
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_d/2 - 0.01, -spoke_width/2, 0])
                rotate([0, 90, a])
                    cube([rim_outer_d/2 - hub_d/2 + 0.01,
                          spoke_width,
                          part_thickness]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        rotate([90, 0, 0])
            cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
}
