wheel_thick    = 8;    // overall part thickness (mm)
rim_width      = 4;    // rim width (mm)
hub_d          = 14;   // hub diameter (mm)
axle_hole      = 8;    // axle hole diameter (mm)
spokes         = 6;    // number of spokes
spoke_width    = 5;    // spoke width (mm)
spoke_start    = 0;    // angle of first spoke (deg, 0 = +X axis)
