rim_id = wheel_d - 2 * rim_width;   // rim inner diameter (hub diameter + gap)
gap    = wheel_d - hub_d - 2;       // radial gap between hub and rim (mm)

// ---------- Model ----------
union() {
    // 1. Outer rim (ring)
    difference() {
        cylinder(d = rim_od, h = wheel_thick);
        translate([0, 0, -eps])
            cylinder(d = rim_id + 0.5, h = wheel_thick + 2 * eps);
    }

    // 2. Hub with axle hole
    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = wheel_thick + 2 * eps);
            translate([0, 0, -eps])
                cylinder(d = axle_hole, h = wheel_thick + 2 * eps + 2);
        }

    // 3. Straight spokes from hub to rim
    for (i = [0 : spokes - 1]) {
        a = spoke_start + i * 360 / spokes;
        translate([0, 0, -eps])
            rotate([0, 0, a])
                difference() {
                    // cylinder along X, from hub edge to rim edge
                    translate([hub_d / 2 - 1, -spoke_width / 2, -eps])
                        cube([gap + 1, spoke_width, wheel_thick + 2 * eps]);
