$fn = 96;

// ---- Dimensions (mm) ----
wheel_thickness = 8;     // total part thickness
outer_diameter  = 80;    // outer rim diameter
rim_width       = 4;     // rim width (radial)
hub_diameter    = 14;    // hub outer diameter
axle_hole       = 8;     // centre axle hole diameter
spoke_count     = 6;     // number of spokes
spoke_width     = 5;     // spoke width (radial)
spoke_start_ang = 0;     // first spoke along +X axis

eps = 0.5;               // cutter overshoot

