            translate([a, 0, 0])
                rotate([0, 90, 0])
                    cube([spoke_reach, spoke_width, wheel_thickness]);
        }
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * eps);
}

wheel();
