```openscad
// Spoked wheel for sample cart
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
wheel_thickness = 8;    // overall part thickness (Z)
outer_diameter  = 80;   // outer rim diameter
rim_width       = 4;    // rim width (radial)
hub_diameter    = 14;   // hub diameter
axle_hole_d     = 8;    // axle hole diameter
spoke_count     = 6;    // number of spokes
spoke_width     = 5;    // spoke width (radial)
spoke_start     = 0;    // angle of first spoke (deg, +X axis)
overlap         = 0.01; // small overlap to fuse rim/hub/spokes

cut_extra       = 0.5;  // cutter overshoot past faces

$fn = 128;              // smoothness of curved shapes

// ---------- Derived ----------
spoke_length = outer_diameter / 2 - rim_width / 2;  // spoke tip into rim
pitch        = 360 / spoke_count;                   // angular spacing

// ---------- Model ----------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub
        translate([0, 0, -overlap])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * overlap);

        // Spokes: radial rectangle from hub to rim
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * pitch])
                translate([0, -spoke_width / 2, 0])
                    cube([spoke_length + overlap, spoke_width, wheel_thickness]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra);
}
