// T-shaped nut for aluminium extrusion
// Print orientation: flange on the XY plane, neck pointing up (+Z)

// ---------------- Parameters ----------------
flange_width = 14;    // flange size along Y (mm)
flange_t     = 2.5;   // flange thickness along Z (mm)
neck_width   = 6;     // neck size along Y and X (mm)
neck_h       = 6.5;   // neck top height along Z (mm)
screw_d      = 3.4;   // screw hole diameter (mm)
length_x     = 10;    // extrusion slot length along X (mm)
eps          = 0.5;   // overcut for clean differences (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Upside-down T profile
    union() {
        // Flange: z = 0 .. flange_t
        translate([-length_x/2, -flange_width/2, 0])
            cube([length_x, flange_width, flange_t]);
        // Neck: z = 0 .. neck_h
        translate([-neck_width/2, -neck_width/2, 0])
            cube([neck_width, neck_width, neck_h]);
    }

    // Central screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_h + flange_t + 2*eps);
}
