module flange() {
    translate([-flange_width/2, -flange_width/2, 0])
        cube([flange_width, flange_width, flange_thick]);
}

module neck() {
    translate([-neck_width/2, -neck_width/2, flange_thick - neck_overlap])
        cube([neck_width, neck_width, neck_h + neck_overlap]);
}

difference() {
    union([flange(), neck()]);

    // vertical through-hole
    translate([0, 0, hole_low])
        cylinder(d = hole_d, h = flange_thick + neck_h + 1);
