```openscad
// Anti-vibration foot - truncated cone with a rubber pad recess and a screw hole
// Units: mm. Print orientation: bottom face (with recess) on the bed at z = 0.

$fn = 128;                 // facet count for round features

// --- Frustum dimensions ---
foot_d_bottom = 50;        // diameter at the bed (z = 0)
foot_d_top    = 40;        // diameter at the flat top (z = 15)
foot_height   = 15;        // overall height of the foot

// --- Recess for the rubber pad ---
recess_d      = 42;        // recess diameter
recess_depth  = 3;         // recess depth from the bottom face

// --- Screw hole ---
screw_d       = 4.5;       // through-hole diameter for a screw

// --- Cutting overlap ---
eps           = 0.5;       // extension of cutters past the faces they cut

difference() {
    // Truncated cone, centred on the Z axis
    cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_height);

    // Round recess in the bottom face. The cutter extends below z = 0
    // so the bottom face is not coplanar with any cutting surface.
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Central screw hole running through the full height, extended above
    // and below the part to avoid coplanar faces at the top or bottom.
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_height + 2 * eps);
}
```

