```openscad
// Anti-vibration foot - truncated cone with bottom recess and screw hole
// Units: mm. Print orientation: base on bed (z = 0), top at z = 20.

$fn = 128;                 // facet count for curved surfaces

// --- Frustum dimensions ---
foot_d_bottom = 40;        // diameter at bottom (z = 0)
foot_d_top    = 32;        // diameter at top (z = 20)
foot_h        = 20;        // total height

// --- Recess in bottom face ---
recess_d      = 32;        // recess diameter
recess_depth  = 3;         // recess depth from bottom face

// --- Screw hole ---
screw_d       = 5.5;       // through-hole diameter
screw_overlap = 0.5;       // extra length below bottom face for clean cut

// --- Cutting overlap ---
eps           = 0.5;       // small overlap so cutters pass through faces

difference() {
    // Truncated cone (frustum), centred on Z axis
    cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_h);

    // Round recess for rubber pad, cut into bottom face
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Central screw hole, runs through full height
    translate([0, 0, -screw_overlap])
        cylinder(d = screw_d, h = foot_h + 2 * screw_overlap);
}
```

