recess_d       = 34;    // rubber pad recess diameter
recess_depth   = 2;     // rubber pad recess depth
screw_d        = 5.5;   // central screw hole diameter
eps            = 0.5;   // overshoot for clean boolean cuts

$fn = 128;              // resolution for curved surfaces

difference() {
    // Truncated cone, inverted so the wider end is at the top.
    // rotate([0,0,180]) maps the original z = 0 (small end) to the top.
    rotate([0, 0, 180])
        cylinder(h = frustum_h, d1 = top_d, d2 = bottom_d);

    // Round recess in the bottom face for a rubber pad
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through hole for a screw along the central axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = frustum_h + 2 * eps);
}
