// Stiffened cover panel - flat plate with 4 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 100;   // plate length along X (mm)
plate_wid   = 50;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

// ---- Ribs ----
rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 2..6
rib_count   = 4;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 20;    // distance of outer rib centres from plate ends (mm)

// ---- Modelling helpers ----
eps         = 0.5;   // overlap for clean booleans (mm)

// Derived: X position of first rib centre
rib_x0 = rib_offset;

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module ribs() {
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}

union() {
    plate();
    ribs();
}
