    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1]) {
        x = -plate_len/2 + rib_end_gap + i * rib_pitch;
        translate([x - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
