// ---------------- Derived ----------------
// Ribaln.run centres are 25 mm apart; the outer ones are 25 mm from the
// ends of the plate, so the ribs divide the length into 4 equal parts.
rib_pitch = (plate_length - 2 * rib_thickness) / (rib_count + 1); // 25 mm

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = -plate_length / 2 + rib_thickness / 2 + i * rib_pitch;
        translate([x_c, -plate_width / 2, plate_thick - rib_overlap])
            cube([rib_thickness, plate_width, rib_height + rib_overlap]);
    }
}
