// Powder measuring scoop
// Print orientation: bowl bottom touching the bed (z = 0), opening upward.
// Handle runs along +X, flush with the rim.

$fn = 128;

// ---- Scoop bowl ----
outer_radius = 12;      // mm, outer radius of the sphere
handle_z     = 8;      // mm, height of the handle top face (rim height)
wall         = 2;       // mm, wall thickness of the bowl

// ---- Handle ----
handle_len   = 62;      // mm, handle length (x = 10 .. 72)
handle_w     = 8;       // mm, handle width along Y
handle_t     = 4;       // mm, handle thickness along Z

// ---- Cutting overlap ----
eps          = 0.5;     // mm, extension past cut faces to avoid coplanarity

difference() {
    union() {
        // Lower half of the hollow sphere: bowl from z = 0 to z = outer_radius
        translate([0, 0, -outer_radius])
            sphere(r = outer_radius);

        // Flat handle along +X, centred on y = 0, top face at z = handle_z
        translate([10 - eps, -handle_w / 2, handle_z - handle_t])
            cube([handle_len + 2 * eps, handle_w, handle_t]);
    }

    // Remove the upper half of the sphere, keeping only z <= handle_z
    translate([0, 0, handle_z])
        cube([outer_radius * 2 + 2 * eps, outer_radius * 2, eps]);
}
