```openscad
// Powder measuring scoop
// Print orientation: handle horizontal, scoop pointing up

$fn = 96;

// --- Dimensions (mm) ---
scoop_radius      = 12;   // outer radius of sphere
scoop_thickness   = 2;    // wall thickness of scoop
handle_width      = 8;    // handle width (Y)
handle_thickness  = 4;    // handle thickness (Z)
handle_start_x    = 10;   // first handle point (X)
handle_end_x      = 72;   // last handle point (X)
support_thickness = 3;    // mounting plate under the scoop

merge_epsilon     = 0.5;  // overlap so the union is clean

difference() {
    union() {
        // Hollow sphere: lower half only
        translate([0, 0, scoop_radius])
            cylinder(r = scoop_radius, h = scoop_radius + 1,
                     d = 2 * scoop_radius + 2 * scoop_thickness);

        // Flat handle, top face flush with the rim (z = 8..12)
        translate([handle_start_x, -handle_width / 2,
                   scoop_radius - handle_thickness])
            cube([handle_end_x - handle_start_x, handle_width,
                  handle_thickness]);
    }

    // Sever the upper quarter of the sphere above the handle.
    // Its top is at z = 16, so the cut stays above the rim.
    translate([-(scoop_radius + merge_epsilon),
               -scoop_radius - merge_epsilon,
               scoop_radius + handle_thickness])
        cube([2 * (scoop_radius + merge_epsilon),
              2 * (scoop_radius + merge_epsilon),
              support_thickness]);
}

// --- Mounting hole ---
translate([0, 0, -support_thickness])
    cylinder(h = support_thickness + 1, d = 5.5);
