// Powder measuring scoop
// Print orientation: handle on the bed, bowl pointing up

$fn = 96;

// --- Scoop bowl ---
bowl_od      = 12;   // outer diameter of sphere
bowl_r       = bowl_od / 2;
bowl_wall    = 2;
bowl_floor_z = 10;  // z of bowl bottom (floor)
bowl_rim_z   = 12;  // z of bowl rim (top)

// --- Handle ---
handle_l     = 62;  // length along +X (10 to 72)
handle_w     = 8;   // width along Y
handle_t     = 4;   // thickness along Z, top flush with rim
handle_x0    = 10;  // start of handle

// --- Cut clearance ---
eps          = 0.5; // extension of cutters past faces

difference() {
    union() {
        // Bowled body: lower hemisphere plus wall thickness up to the rim
        translate([0, 0, 0])
            hull() {
                sphere(d = bowl_r);
                for (z = [bowl_floor_z : 1 : bowl_rim_z])
                    translate([0, 0, z])
                        cylinder(h = 0.01, d = bowl_od);
            }
        // Flat handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_l - handle_x0, handle_w, handle_t]);
    }
    // Remove the upper half of the volume to leave a solid wall
    translate([0, 0, bowl_rim_z - eps])
        cylinder(h = eps + 0.01, d = bowl_od);
}
