eps         = 0.5;   // extension of cutting shapes past faces (mm)

module bowl() {
    difference() {
        translate([0, 0, bowl_z])
            sphere(r = bowl_r);
        translate([0, 0, -eps])
            sphere(r = bowl_r + 2*eps);
    }
}

module handle() {
    translate([handle_x0, handle_y0, 0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

union() {
    bowl();
    translate([0, 0, bowl_rim_z - handle_t])
        mirror([1, 0, 0])   // flip so the 2 eps-thick slab spans z = 14..16
            translate([0, handle_y0, 0])
                cube([handle_x1 - handle_x0, handle_w, 2*eps]);
