        translate([0, 0, bottom])
            hull() {
                for (a = [-90, 0])
                    rotate([0, 0, a])
                        translate([0, -sphere_r, 0])
                            cylinder(r = sphere_r, h = sphere_r + 2 * wall, $fn = 128);
            }
        // Handle: flat plate, top face flush with rim (z = r)
        translate([handle_x0, -handle_w / 2, r - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Remove interior above the lower half to avoid zero-thickness walls
    translate([0, -sphere_r - eps, r])
        cube([2 * (sphere_r + eps), 2 * sphere_r + 2 * eps, eps + 0.01]);
}
