// Cable bridge - rectangular block with 3 semicircular tunnels along Y
// Print orientation: flat on bed, tunnels open downward

$fn = 96;

// ---- Block dimensions ----
block_len   = 60;   // X length
block_wid   = 30;   // Y width
block_h     = 12;   // Z height

// ---- Tunnel dimensions ----
tunnel_d    = 12;   // tunnel diameter
tunnel_n    = 3;    // number of tunnels
tunnel_pitch = 20;  // centre-to-centre spacing along X
tunnel_r    = tunnel_d / 2;  // tunnel radius

// ---- Cut clearance ----
eps         = 0.5;  // extension of cutters past faces

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels along Y at floor level
    for (i = [0 : tunnel_n - 1]) {
        x = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])
                cylinder(h = block_wid, r = tunnel_r, $fn = 96);
    }
}
