    // Torus body: cylinder along Z, revolved around Z axis
    // Placed with its middle plane at z = 8, so it rests on z = 0
    translate([0, 0, -torus_h / 2])
        linear_extrude(height = ring_outer_r + ring_inner_r)
            circle(d = torus_d);

    // Central bore: cylinder along Z, extended past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(r = ring_inner_r, h = torus_h + 2 * cut_extra);
}
