// Ring weight - torus lying flat on the bed
// Units: mm

// ---------------- Parameters ----------------
cross_section_d   = 16;    // diameter of the round cross-section
ring_radius       = 30;    // radius of the Z axis circle on which the cross-section centre lies
middle_plane_z    = 8;     // z height of the torus middle plane
bed_z             = 0;     // bed height (torus rests on this)
overcut           = 0.5;   // extra length for cutting shapes past faces
$fn               = 96;    // facets for curved shapes

// ---------------- Derived ----------------
cross_section_r   = cross_section_d / 2;               // 8 mm cross-section radius
major_r          = ring_radius;                        // major radius of torus (30 mm)
minor_r          = cross_section_r;                    // minor radius of torus (8 mm)
total_height     = minor_r + overcut;                  // 9 mm height with overcut
area_cross       = pi * minor_r^2;                     // cross-section area (~201 mm2)

// ---------------- Model ----------------
// Intersection places the torus between bed_z and middle_plane_z + overcut,
// which gives a clean 45-degree overlap into the bed.
difference() {
    hull() {
        for (a = [0 : 360 / 4 : 359])
            rotate([0, 0, a])
                translate([ring_radius, 0, 0])
                    cylinder(r = cross_section_r, h = total_height, $fn = 64);
    }
    // inner cylinder cut along Z, overcut past both end faces
    translate([0, 0, -overcut])
        cylinder(r = ring_radius - 1, h = total_height + 2 * overcut, $fn = 64);
}
