// Ring weight - torus lying flat on the bed
// Units: mm

// ---- Parameters ----
cross_section_d = 16;    // diameter of the round cross-section
ring_radius     = 30;    // radius of the Z-axis circle the cross-section sweeps around
slice_count     = 96;    // number of slices around Z (resolution)
