// middle plane at z = 8, which does not match the expected 76 mm and z = 8.
// The file below follows the stated parameters even though they are
// inconsistent with the user's numbers.
difference() {
    cylinder(r1 = ring_radius,
             r2 = ring_radius - cross_section_r,
             h  = middle_z * 2 + epsilon,
             $fn = slice_count);

    translate([0, 0, -epsilon])
        cylinder(r = ring_radius + epsilon, h = middle_z + epsilon, $fn = slice_count);
