difference() {
    torus();

    // Cut out the inner region from z = middle_z - cut_extra up through
    // the middle plane, so the outer wall stays below z = 8.
    translate([0, 0, middle_z - cut_extra])
        cylinder(h = cut_extra + 0.01, r = ring_radius - 1);
}
