// Each disc has its centre on the bed (z = 0), which gives the
// hull its lowest point at z = 0.
module ring_weight() {
    hull() {
        // Disc at the front of the ring (translate along Y)
        translate([0, axis_circle_r, 0])
            cylinder(d = torus_d, h = torus_h, $fn = 128);

        // Disc at the back of the ring (translate along -Y)
        translate([0, -axis_circle_r, 0])
            cylinder(d = torus_d, h = torus_h, $fn = 128);

        // Concave spacer that defines the ring width.
        // Its bottom face is at z = torus_d, so it never touches the bed.
        translate([0, 0, torus_d])
            rotate([90, 0, 0])
                cylinder(r = axis_circle_r, h = torus_h, $fn = 128);
    }
}

