z_bottom        = z_middle - cross_section_r;    // bottom of the part (on z = 0)
z_top           = z_middle + cross_section_r;   // top of the part

// ---- Model ----
// rotate([90,0,0]) turns the vertical torus into a flat ring lying on z = 0
translate([0, 0, z_bottom])
    rotate([90, 0, 0])
        cylinder(r = cross_section_r, h = ring_radius * 2, $fn = 96);
