// Leaf of a pin hinge
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------- Dimensions (mm) ----------
plate_len      = 40;    // plate length (X)
plate_wid      = 20;    // plate width (Y)
plate_thk      = 3;     // plate thickness (Z)

knuckle_d      = 7;     // knuckle diameter
knuckle_pitch  = 8;     // spacing between knuckle centres
knuckle_h      = 10;    // knuckle height above plate

pin_d          = 3;     // pin hole diameter

n_knuckles     = 5;     // number of segments
n_holes        = (n_knuckles + 1) / 2;  // holes in 1st, 3rd, 5th segments

eps            = 0.5;   // cutter overshoot

$fn = 64;

// ---------- Model ----------
difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge
        for (i = [0 : n_knuckles - 1]) {
            x = (i < n_knuckles / 2) ? -knuckle_pitch + (i + 1) * knuckle_pitch
                                     :  knuckle_pitch * (i - n_knuckles / 2 + 1);
            translate([x, plate_wid/2, 0])
                cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin holes
    for (i = [0 : n_holes - 1]) {
        x = (i < n_holes / 2) ? -knuckle_pitch + (i + 1) * knuckle_pitch
                              :  knuckle_pitch * (i - n_holes / 2 + 1);
        translate([x, plate_wid/2, -eps])
            cylinder(d = pin_d, h = knuckle_h + 2*eps);
    }
}
