```openscad
// Pin hinge - one leaf
// Flat plate lying on the bed, centred on the origin in X and Y.

// ---------- Parameters ----------
plate_length   = 50;   // plate length along X (mm)
plate_width    = 30;   // plate width along Y (mm)
plate_thick    = 3;    // plate thickness along Z (mm)

knuckle_count  = 5;    // number of segments along +Y edge
segment_length = 10;   // length of each segment (mm)
knuckle_dia    = 8;    // diameter of round knuckle cylinders (mm)
knuckle_y      = 15;   // common axis Y position of knuckles (mm)
knuckle_z      = 4;    // common axis Z height of knuckles (mm)

pin_dia        = 2;    // diameter of the pin hole running through knuckles (mm)

eps            = 0.5;  // overshoot for cutting shapes past faces (mm)
$fn            = 96;   // curve resolution

// ---------- Model ----------
difference() {
    // Base plate
    translate([-plate_length/2, -plate_width/2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Knuckles on the +Y edge, on the 1st, 3rd and 5th segments only.
    // Segment i (0-based) spans x = (i-2)*segment_length .. (i)*segment_length,
    // so only odd i (1, 3, 5) fall on 1st, 3rd, 5th segments.
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 1) {
            x0 = (i - 2) * segment_length;
            x1 = x0 + segment_length;
            translate([x0, knuckle_y, knuckle_z])
                cylinder(d = knuckle_dia, h = x1 - x0);
        }
    }

    // Pin hole along the common axis through every knuckle
    translate([0, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_dia, h = plate_length + 2*eps, center = true);
}
