// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
plate_len     = 50;   // plate length along X
plate_wid     = 30;   // plate width along Y
plate_thk     = 3;    // plate thickness along Z

knuckle_d     = 8;    // knuckle diameter
knuckle_z     = 4;    // knuckle axis height above plate top face
knuckle_count = 5;    // number of segments along +Y edge
knuckle_pitch = plate_len / knuckle_count;  // 10 mm segment length

pin_d         = 2;    // pin hole diameter
overcut       = 0.5;  // extension of cutters past faces

// ---- Derived ----
knuckle_y = plate_wid / 2;  // knuckle axis Y position (on +Y edge)
total_h   = plate_thk + knuckle_z;  // top of knuckles

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    // 1st, 3rd, 5th segments (odd segment numbers)
    for (i = [0 : knuckle_count - 1])
        if ((i + 1) % 2 == 0)
            translate([ (i + 0.5) * knuckle_pitch - knuckle_pitch/2,
                       knuckle_y,
                       knuckle_z ])
                cylinder(d = knuckle_d, h = 10);  // 10 mm height above axis
}

module pin_holes() {
    // run along X axis through every knuckle
    for (i = [0 : knuckle_count - 1])
        if ((i + 1) % 2 == 0) {
            x = (i + 0.5) * knuckle_pitch - knuckle_pitch/2;
            translate([x, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = plate_len + 2 * overcut,
                            center = true);
        }
}

union() {
    plate();
    knuckles();
}

difference() {
    // empty placeholder for the pin-hole cutter
    translate([0, 0, -1])
        cube([plate_len + 2 * overcut, knuckle_d + 2, 11]);
}

