    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_count - 1]) {
        x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = knuckle_h);
    }
}

difference() {
    union() {
        plate();
        knuckles();
    }
    // Pin holes through knuckle axes
    for (i = [0 : knuckle_count - 1]) {
        x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
        translate([x, knuckle_y, -eps])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_d + 2*eps);
    }
}
