// Pin hinge leaf
// Flat plate with two round knuckles along the +Y edge

// ---------------- Parameters ----------------
plate_length   = 60;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 3;     // plate thickness along Z (mm)

knuckle_count  = 3;     // number of knuckle segments
knuckle_dia    = 8;     // knuckle diameter (mm)
knuckle_x0     = -plate_length / 3; // first knuckle centre X (mm)
knuckle_pitch  = plate_length / knuckle_count; // segment length (mm)

pin_dia        = 2;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;               // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckle cylinders, axis along X at y = 12.5, z = 4
        for (i = [0 : knuckle_count - 1]) {
            x = knuckle_x0 + i * knuckle_pitch;
            translate([x - knuckle_dia / 2, 12.5, 0])
                cylinder(d = knuckle_dia, h = plate_thick + 2 * eps, center = true);
        }
    }

    // Pin hole along X, through every knuckle
    translate([knuckle_x0 - eps, 0, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_dia, h = plate_length + 2 * eps);
}
