                cylinder(d = knuckle_d, h = knuckle_h);
        }
    }

    // Pin hole along X through knuckles
    translate([-eps, plate_wid/2, -eps])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
