$fn = 96;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;     // knuckle diameter
knuckle_n   = 3;     // number of knuckles
knuckle_w   = plate_len / knuckle_n; // 20 mm segment width
knuckle_y   = plate_wid / 2; // 12.5 mm (on +Y edge)
knuckle_z   = 4;     // knuckle axis height above bed

// ---- Pin ----
pin_d       = 2;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on 1st and 3rd segments
        for (i = [0, 2]) {
            x0 = -plate_len/2 + i * knuckle_w;
            translate([x0, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_w);
        }
    }

    // Pin hole along X through every knuckle
    translate([-plate_len/2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
