```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 3;     // number of knuckles
knuckle_p   = 15;    // centre-to-centre spacing along X
knuckle_y   = plate_wid / 2; // knuckle axis Y position (12.5)
knuckle_z   = 3;     // knuckle axis height above bed

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments (0, 1, 2 -> 0 and 2)
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)
                translate([i * knuckle_p - (knuckle_n - 1) * knuckle_p / 2,
                           knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10);
    }

    // Pin hole through every knuckle along the X axis
    translate([-knuckle_p * (knuckle_n - 1) / 2, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_p * (knuckle_n - 1) + 2 * eps,
                     center = true);
}
```

