// Pin hinge leaf
// Flat plate with two round knuckles along the +Y edge

// ---- Dimensions (mm) ----
plate_len   = 45;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

knuckle_d   = 6;     // knuckle diameter
knuckle_y   = 12.5;  // knuckle axis Y position
knuckle_z   = 3;     // knuckle axis height above plate

pin_d       = 2.5;   // pin hole diameter

segment_len = 15;    // length of each of the 3 segments along +X

// ---- Modelling ----
overlap = 0.1;       // overlap so knuckles fuse with plate
cut_ext = 0.5;       // pin hole extension past knuckle faces

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (s = [0, 2]) {
            x = -plate_len/2 + (s + 1) * segment_len;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + overlap);
        }
    }

    // Pin hole along the shared axis through both knuckles
    translate([-segment_len, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = segment_len + 2 * cut_ext);
}
```

```openscad
// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_len    = 45;    // plate length (X)
plate_wid    = 25;    // plate width (Y)
plate_thk    = 2.5;   // plate thickness (Z)

knuckle_d    = 6;     // knuckle diameter
knuckle_h    = 6;     // knuckle height above plate
knuckle_pitch = 15;   // centre-to-centre spacing along X
knuckle_count = 3;    // total knuckles (1st, 2nd, 3rd)

pin_d        = 2.5;   // pin hole diameter
eps          = 0.5;   // cutter overshoot

// ---- Derived ----
knuckle_start_x = -knuckle_pitch * (knuckle_count - 1) / 2;  // -15, -15, 15 for the 3 segments

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_count - 1]) {
        x = knuckle_start_x + i * knuckle_pitch;
        translate([x, plate_wid/2, 0])
            cylinder(d = knuckle_d, h = knuckle_h);
    }
}

difference() {
    union() { plate(); knuckles(); }
    // Pin axis runs along X at y = 12.5, z = 3 (through the 2nd knuckle)
    translate([-100, plate_wid/2, plate_thk + eps])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = 2*eps);
}
```

