// Pin hinge leaf
// Flat plate on the bed, centred on the origin in X and Y.
// Along the +Y edge, 3 equal 15 mm segments have round knuckles on the 1st and 3rd.
// A 2.5 mm pin hole runs along X through each knuckle.

$fn = 96;

// ---- Plate ----
plate_len   = 45;    // X length of plate
plate_wid   = 25;    // Y width of plate
plate_thk   = 2.5;   // Z thickness of plate

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_z   = 3;     // knuckle axis height (Z)
knuckle_h   = 15;    // knuckle height (segment length)
knuckle_xs  = [ -15, 15]; // x positions of knuckles (1st and 3rd segments)

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // overlap for clean cuts/unions

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (x = knuckle_xs) {
        translate([x, 12.5, knuckle_z])
            cylinder(d = knuckle_d, h = knuckle_h);
    }
}

difference() {
    union() {
        plate();
        knuckles();
    }
    // Pin holes along X through every knuckle
    for (x = knuckle_xs)
        translate([x, 12.5, 0])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_h + 2*eps, center = true);
}
```

