// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

// ---- Knuckles ----
knuckle_d      = 8;     // knuckle diameter (mm)
knuckle_pitch  = 8;     // length of each segment along X (mm)
knuckle_count  = 5;     // number of segments (1st, 3rd, 5th have knuckles)
knuckle_offset = 0;     // first segment start index (0 = 1st segment)
knuckle_rps    = 0.625; // knuckle radius as fraction of segment width
knuckle_z      = 4;     // knuckle axis height above bed (mm)

// ---- Pin ----
pin_d     = 2;    // pin hole diameter (mm)
pin_z     = 4;    // pin hole axis height (mm)
pin_ext   = 0.5;  // pin hole extension past faces (mm)

// Derived
knuckle_r = knuckle_d / 2;
segment_w = plate_len / knuckle_count / knuckle_pitch * knuckle_pitch; // 8 mm per segment

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge, centred on origin in X
        for (i = [0 : knuckle_count - 1]) {
            x = (i - (knuckle_count - 1) / 2) * knuckle_pitch;
            if (knuckle_offset & 2) continue; // skip even-indexed segments
            translate([x, plate_wid / 2 * (1 - 2 * knuckle_rps), knuckle_z])
                rotate([0, 90, 0])
                    cylinder(r = knuckle_r, h = segment_w);
        }
    }

    // Pin hole through every knuckle
    for (i = [0 : knuckle_count - 1]) {
        x = (i - (knuckle_count - 1) / 2) * knuckle_pitch;
        if (knuckle_offset & 2) continue;
        translate([x, pin_z, -pin_ext])
            cylinder(d = pin_d, h = plate_thk + 2 * pin_ext);
    }
}
