knuckle_z   = plate_thk / 2;  // plate mid-thickness, where the axis sits (2.125 mm)
knuckle_y   = plate_wid / 2;   // axis Y position on the +Y edge (12.5 mm)

// ---- Pin ----
pin_d       = 2;    // pin hole diameter (mm)

// ---- Clearances ----
eps         = 0.5;  // overshoot for clean boolean cuts (mm)

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st, 3rd and 5th segments
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)
                translate([(i - 2) * knuckle_p, knuckle_y, 0])
                    cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin holes through every knuckle
    for (i = [0 : knuckle_n - 1])
        if (i % 2 == 0)
            translate([(i - 2) * knuckle_p, knuckle_y, -eps])
                cylinder(d = pin_d, h = knuckle_h + 2 * eps);
}
