```openscad
// 5-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

$fn = 96;                  // smoothness of curved shapes

// ---- Star dimensions ----
outer_r = 35;              // distance of outer points from centre
inner_r = 21;              // distance of inner points from centre
points  = 5;               // number of points (and inner points)
pitch   = 360 / points;    // angular spacing between points

// ---- Plate dimensions ----
plate_t = 4;               // plate thickness
hole_d  = 6;               // central through-hole diameter

// ---- Cutting overshoot ----
eps = 0.5;                 // extension of cutters past faces

// First outer point lies on the +X axis; inner points are offset by 180/5 = 36 degrees.
module star_outline() {
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * pitch])
                union() {
                    translate([outer_r, 0, 0])
                        cylinder(h = plate_t, $fn = 96);
                    translate([inner_r * cos(pitch / 2 + i * pitch),
                               inner_r * sin(pitch / 2 + i * pitch),
                               0])
                        cylinder(h = plate_t, $fn = 96);
                }
        }
    }
}

difference() {
    // Star plate
    linear_extrude(height = plate_t)
        star_outline();

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}
```

