// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 35;   // distance of outer points from centre (mm)
inner_r   = 21;   // distance of inner points from centre (mm)
point_n   = 5;    // number of points (5 outer, 5 inner)
plate_t   = 4;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;

// ---------------- Model ----------------
difference() {
    // Star outline: outer points at 0, 72, 144 ... deg, inner points shifted by 36 deg
    linear_extrude(height = plate_t) {
        polygon(points = [
            for (i = [0 : point_n - 1])
                each [
                    [outer_r * cos(i * 36), outer_r * sin(i * 36)],
                    [inner_r * cos(i * 36 + 180 / point_n),
                     inner_r * sin(i * 36 + 180 / point_n)]
                ]
        ]);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
```

