// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 30;   // distance of outer points from centre (mm)
inner_r   = 18;   // distance of inner points from centre (mm)
point_n   = 5;    // number of points (5 outer, 5 inner)
plate_t   = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // cutter overshoot past faces (mm)
$fn       = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline: outer points at 0, 72, ... deg; inner points at 36, 108, ... deg
    hull() {
        for (i = [0 : point_n - 1]) {
            rotate([0, 0, i * 360 / point_n])
                translate([0, 0, 0])
                    union() {
                        // outer point
                        translate([outer_r, 0, 0])
                            cube([outer_r, 2 * outer_r, plate_t]);
                        // inner point
                        translate([inner_r, 0, 0])
                            cube([inner_r, 2 * inner_r, plate_t]);
                    }
        }
    }

    // central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
