```openscad
// 5-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

// ---------------- Parameters ----------------
outer_r   = 30;   // distance of outer points from centre (mm)
inner_r   = 18;   // distance of inner points from centre (mm)
points    = 5;    // number of vertices (outer and inner)
thickness = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
overlap   = 0.5;  // vertex overlap between outer/inner shapes (mm)
eps       = 0.5;  // cutter overshoot past faces (mm)
$fn       = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline: outer points at 0°, 72°, ... ; inner points at 36°, 108°, ...
    union() {
        // outer points
        for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    square([outer_r, outer_r * 2], center = true);

        // inner points
        for (i = [0 : points - 1])
            rotate([0, 0, (i + 0.5) * 360 / points])
                translate([inner_r, 0, 0])
                    square([inner_r, inner_r * 2], center = true);
    }

    // central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
```

