```openscad
// 5-pointed star indexing wheel
// Print orientation: flat on bed, builds upward in +Z

$fn = 96;

// ---- Star parameters ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 18;   // distance of inner points from centre
points    = 5;    // number of points
start_ang = 0;    // angle of first outer point (deg, 0 = +X axis)

// ---- Plate parameters ----
plate_t   = 3;    // plate thickness
hole_d    = 6;    // central through-hole diameter

// ---- Derived ----
angle_step = 360 / points;   // 72 deg between matching features

module star_2d() {
    // Star outline: alternate between outer and inner points
    pts = [];
    for (i = [0 : points - 1]) {
        a = start_ang + i * angle_step;
        pts.push([outer_r * cos(a), outer_r * sin(a)]);   // outer
        a = start_ang + (i + 0.5) * angle_step;
        pts.push([inner_r * cos(a), inner_r * sin(a)]);   // inner
    }
    polygon(points = len(pts), pt = pts);
}

difference() {
    // Flat plate with star outline
    linear_extrude(height = plate_t) {
        star_2d();
    }

    // Central through-hole
    translate([0, 0, -1]) {
        cylinder(d = hole_d, h = plate_t + 2);
    }
}
```

