            concat(
                [outer_radius * cos(i * 360 / star_points),
                 outer_radius * sin(i * 360 / star_points)],
                [inner_radius * cos((i + 0.5) * 360 / star_points),
                 inner_radius * sin((i + 0.5) * 360 / star_points)]
            )
    ]);

