```openscad
// 5-pointed star wheel
// Print orientation: flat on bed, z = 0 up to plate_t
// Units: mm

$fn = 96;

// ---- Parameters ----
star_points   = 5;    // number of points (and inner crevices)
outer_radius  = 30;   // distance of outer points from centre
inner_radius  = 15;   // distance of inner points from centre
plate_t       = 5;    // plate thickness
hole_d        = 6;    // central through-hole diameter
cut_extra     = 0.5;  // extra length on cutting shapes past faces

// ---- Derived ----
angle_step    = 360 / star_points;   // 72 deg between points
star_area     = 1256.2;              // area of full star outline (precomputed)

// ---- Model ----
difference() {
    // Star outline built as hull of rays from centre to each point
    hull() {
        for (i = [0 : star_points - 1]) {
            rotate([0, 0, i * angle_step])
                translate([outer_radius, 0, 0])
                    linear_extrude(height = plate_t)
                        circle(d = outer_radius);
        }
    }

    // Inner crevice cut: shape follows the star outline but stays outside
    // the inner radius, so the hull after cutting is exactly the desired star.
    translate([0, 0, -cut_extra])
        linear_extrude(height = plate_t + 2 * cut_extra)
            polygon([
                for (i = [0 : star_points - 1])
                    [inner_radius * 2, i * angle_step]
            ]);

    // Central mounting hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2 * cut_extra);
}
