eps        = 0.5;    // overshoot for clean boolean cuts

$fn = 64;            // curve resolution

// First outer point on +X axis (angle = 0)
// rotate([X, Y, 45deg]) maps loop index 0 -> world +Y,
// rotate([X, Y, -90deg]) maps loop index 0 -> world +X
start_angle = -90;   // degrees offset for first point

module star_2d() {
    for (i = [0 : num_points - 1]) {
        a = start_angle + i * 360 / num_points;
        // alternating outer/inner points
        if (i % 2 == 0)
            polygon([outer_r * cos(a), outer_r * sin(a)]);
        else
            polygon([inner_r * cos(a), inner_r * sin(a)]);
    }
}

difference() {
    // Plate body
    linear_extrude(height = thickness)
        star_2d();

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 64);
}
