```openscad
// 8-pointed star indexing wheel
// Print orientation: flat on bed, z = 0 upward.
// Placed with one outer point on +X, so the star is not centred on the origin.

// ---------- Parameters ----------
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
points    = 8;     // number of spikes
thickness = 3;     // plate thickness (Z)
hole_d    = 6;     // diameter of the central through-hole
eps       = 0.5;   // extra length on cutters to avoid coplanar faces

// ---------- Derived ----------
angle_step = 360 / points;   // 45 degrees between adjacent points
// hull() needs a small overlap so the loop wraps around the 3D surface cleanly
overlap   = 0.01 * outer_r;

// ---------- Model ----------
difference() {
    // Star outline, built as a closed loop of outer/inner vertices
    hull() {
        for (i = [0 : points - 1]) {
            a = i * angle_step;
            // outer points lie on the +Y side of their radius line,
            // inner points on the -Y side, keeping the shape convex per sector
            translate([outer_r * cos(a), outer_r * sin(a), 0])
                rotate([0, 0, a + 90])
                    cube([outer_r - overlap, thickness, overlap]);
            translate([inner_r * cos(a), -inner_r * sin(a), 0])
                rotate([0, 0, a + 90])
                    cube([inner_r - overlap, thickness, overlap]);
        }
    }

    // Central through-hole
    translate([outer_r * 0.6, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
