        [ outer_r * cos(angle_start + i * 360 / point_count),
          outer_r * sin(angle_start + i * 360 / point_count) ]
    ]],
    [ for (i = [0 : point_count - 1]) each [
        [ inner_r * cos(angle_start + (i + 0.5) * 360 / point_count),
          inner_r * sin(angle_start + (i + 0.5) * 360 / point_count) ]
    ]]
);

difference() {
