pocket_w   = 30;    // square pocket side
pocket_d   = 5;     // square pocket depth from top face
overlap    = 0.5;   // cutter overlap into top face

$fn = 64;

difference() {
    // Square frustum: hull between base and top faces
    hull() {
        translate([-base_w/2, -base_w/2, 0])
            cube([base_w, base_w, 0]);
        translate([-top_w/2, -top_w/2, block_h])
            cube([top_w, top_w, block_h]);
    }

    // Square pocket, centred, open at top face
    translate([-pocket_w/2, -pocket_w/2, block_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + overlap]);
}
