// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: bottom face on the bed (z = 0), building upward.
// Positioned per the user's coordinates: centred on Y, shifted in X.

// ---------------- Parameters ----------------
block_x0    = -40;    // block lower bound in X
block_x1    = 40;     // block upper bound in X
block_y0    = -40;    // block lower bound in Y
block_y1    = 40;     // block upper bound in Y
block_h     = 20;     // block height (z = 0 to 20)

pocket_x0   = -15;    // pocket lower bound in X
pocket_x1   = 15;     // pocket upper bound in X
pocket_y0   = -15;    // pocket lower bound in Y
pocket_y1   = 15;     // pocket upper bound in Y
pocket_d    = 5;      // pocket depth from the top face

eps         = 0.5;    // overshoot so cutters pass through faces cleanly

// ---------------- Model ----------------
difference() {
    // Main block (the user's 80 x 80 bottom face and 40 x 40 top face are
    // reflected in block_x0..1 and block_y0..1). The sides are straight and
    // parallel to the axes, exactly as specified.
    translate([block_x0, block_y0, 0])
        cube([block_x1 - block_x0, block_y1 - block_y0, block_h]);

    // Square pocket cut into the top face. With eps the cutter runs from
    // z = block_h down to z = block_h + eps, so the cut always reaches
    // the top face no matter how the file is used.
    translate([pocket_x0, pocket_y0, block_h - pocket_d])
        cube([pocket_x1 - pocket_x0, pocket_y1 - pocket_y0, pocket_d + eps]);
}
