    // Hull of two equal-area vertical slices through the apexes.
    // The cross-section at each slice is a square aligned with X and Y.
    hull() {
        translate([-w / 2, -w / 2, z0])
            cube([w, w, h + 0.01]);
        translate([ w / 2, -w / 2, z0])
            cube([w, w, h + 0.01]);
    }
}

difference() {
