    // Solid square frustum: two vertical sides and two sloping sides.
    // Hull of a full-bottom rectangle and a full-top rectangle.
    hull() {
        translate([block_x0, block_y0, block_z0])
            cube([bottom_area / (block_y1 - block_y0),
                  block_y1 - block_y0,
                  block_z0]);
        translate([block_x0 + 80 / 2 - 50,   // shift so the 80 side lines up with the slope
                  block_y0 + 80 / 2 - 50,
                  block_z1])
            cube([80, 80, eps]);
    }
}

difference() {
    tapered_block();

    // Square pocket cut into the top face
    translate([pocket_x0, pocket_y0, block_z1 - pocket_depth])
        cube([pocket_x1 - pocket_x0,
              pocket_y1 - pocket_y0,
              pocket_depth + eps]);
}
