```openscad
// Tapered riser block with a square pocket
// Units: mm. Print orientation: bottom face on bed (z = 0).

$fn = 64;

// ---- Dimensions ----
base_size    = 100;   // bottom square side
top_size     = 70;    // top square side
block_height = 20;    // block height (z = 0 to z = 20)
pocket_size  = 60;    // pocket square side
pocket_depth = 8;     // pocket depth from top face

eps = 0.5;            // cutter overshoot past faces

// ---- Derived ----
pocket_top_z = block_height - pocket_depth;

module base_solids() {
    // Lower straight-walled section: base to min(top, pocket_top_z)
    h1 = min(top_size, pocket_top_z);
    translate([0, 0, 0])
        cube([base_size, base_size, h1]);
}

module pocket() {
    // Pocket open at top (cuts through if top < pocket_top_z)
    translate([0, 0, pocket_top_z])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

difference() {
    union() {
        base_solids();
        // Tapered section from min(top, pocket_top_z) up to block top
        translate([0, 0, h1])
            linear_extrude(height = block_height - h1)
                polygon([
                    [-(pocket_top_z < top_size ? top_size : pocket_top_z) / 2,
                     -(pocket_top_z < top_size ? top_size : pocket_top_z) / 2],
                    [(pocket_top_z < top_size ? top_size : pocket_top_z) / 2,
                     -(pocket_top_z < top_size ? top_size : pocket_top_z) / 2],
                    [(pocket_top_z < top_size ? top_size : pocket_top_z) / 2,
                     (pocket_top_z < top_size ? top_size : pocket_top_z) / 2],
                    [-(pocket_top_z < top_size ? top_size : pocket_top_z) / 2,
                     (pocket_top_z < top_size ? top_size : pocket_top_z) / 2]
                ]);
    }
    pocket();
}
