pocket_depth = 8;     // square pocket depth, centred
eps          = 0.5;   // overshoot for clean boolean cuts

$fn = 64;             // curve resolution (no curves here; kept per convention)

// ---------------- Derived ----------------
// Check the taper angle: side slope = (base_size - top_size) / (2 * height)
side_slope = (base_size - top_size) / (2 * height);   // 1.5 mm per mm of height (~56 deg)
half_p     = pocket_size / 2;                         // pocket half-width in X and Y

// ---------------- Model ----------------
difference() {
    // Solid square frustum: bottom face on the bed, flat top at z = height
    // Hull of two concentric squares gives a 45-degree taper, which matches the
    // user's stated dimensions (100 -> 70 over 20 mm).
    hull() {
        // Bottom face at z = 0
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 0.01]);   // tiny slab = the bed face
        // Top face at z = height
        translate([-top_size / 2, -top_size / 2, height])
            cube([top_size, top_size, 0.01]);
    }

    // Square pocket cut into the top face, centred, extending past the top
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
