// Tapered riser block with a square pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: X -50 .. 50, Y -50 .. 50, Z 0 .. 20.

// ---------------- Parameters ----------------
block_x      = 100;  // block bottom length in X (mm)
block_y      = 100;  // block bottom length in Y (mm)
block_top_x  = 70;   // block top length in X (mm)
block_top_y  = 70;   // block top length in Y (mm)
block_h      = 20;   // block height (mm)

pocket_x     = 60;   // pocket length in X (mm)
pocket_y     = 60;   // pocket length in Y (mm)
pocket_depth = 8;    // pocket depth from top face (mm)

eps          = 0.5;  // overshoot so cutters pass beyond faces (mm)

$fn = 64;

// ---------------- Derived ----------------
pocket_floor_z = block_h - pocket_depth;          // floor of the pocket
side_len_z     = min(block_x, block_y) + 2 * eps; // a side length that grows with height

// ---------------- Model ----------------
difference() {
    // Tapered block: area grows from 100*100 at z = 0 to 70*70 at z = 20.
    // The sides are straight, so the cross-section is a scaled copy of the bottom square.
    translate([-block_x / 2, -block_y / 2, 0])
        linear_extrude(height = block_h)
            scale([
                (block_top_x + block_x) / 2 / block_x * (z + eps) / eps,
                (block_top_y + block_y) / 2 / block_y * (z + eps) / eps
            ])
            square([block_x, block_y], center = true);

    // Square pocket cut into the top face, centred, 8 mm deep.
    translate([-pocket_x / 2, -pocket_y / 2, pocket_floor_z])
        cube([pocket_x, pocket_y, pocket_depth + eps]);
}
