```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

// ---- Dimensions (mm) ----
thickness   = 4;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 25;    // grip section length (X)
trans_len   = 15;    // transition section length (X)

$fn = 64;

// ---- Derived ----
mid_x = 0;
// right grip end = gauge end + trans + grip
right_x = gauge_len/2 + trans_len + grip_len/2;

module profile() {
    // upper y -> lower y (clockwise)
    concat(
        [for (s = [0:0.01:1])
            [mid_x + (right_x - mid_x) * s, grip_w/2 * (1 - s) + gauge_w/2 * s]],
        [for (s = [1: -0.01: 0])
            [mid_x - (right_x - mid_x) * s, grip_w/2 * (1 - s) + gauge_w/2 * s]],
        [mid_x, gauge_w/2],
        [mid_x, -gauge_w/2],
        [mid_x + (right_x - mid_x) * 0.01, -gauge_w/2 * 0.01 - grip_w/2 * 0.01],
        [right_x, -grip_w/2]
    );
}

difference() {
    // main plate
    linear_extrude(thickness) profile();
    // grip pockets
    for (x = [-right_x, right_x])
        translate([x, -grip_w/2 - 1, 0])
            cube([grip_len, grip_w + 2, thickness + 2]);
}
