```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: lying flat on the bed, symmetric about the origin.
// Total length along X is 130 mm.

// ---------------- Parameters ----------------
spec_thickness = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X (mm)

gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length along X (mm)

grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X (mm)

transition_length = 15; // length of each flank transition (mm)
// transition width changes linearly from grip_width (19) to gauge_width (6)

// ---------------- Derived ----------------
half_gauge = gauge_length / 2;   // +/-25 mm from origin in gauge
eps        = 0.5;                // cutter overshoot past faces

// Flank runs from the outer grip end inward over transition_length
// and its width changes from grip_width down to gauge_width.
// Centred on the origin, the two flanks meet at x = 0.
flank_start_x = (gauge_length + 2 * transition_length) / 2; // x where width = grip_width
flank_end_x   = -flank_start_x;                              // x where width = gauge_width

// ---------------- Model ----------------
module dogbone() {
    // Coarse 2D profile (2D x = X, 2D y = Y); extrude along +Z.
    hull() {
        // Grip sections (full width), centred at x = +/- (gauge_length/2 + transition_length)
        for (sx = [-1, 1])
            translate([sx * (gauge_length / 2 + transition_length), -grip_width / 2, 0])
                cube([grip_length, grip_width, spec_thickness]);

        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, spec_thickness]);

        // Flank transitions
        for (sx = [-1, 1])
            translate([sx * flank_start_x, -grip_width / 2, 0])
                linear_extrude(spec_thickness)
                    polygon([
                        [0, -gauge_width / 2],
                        [flank_start_x, -grip_width / 2],
                        [flank_start_x, grip_width / 2],
                        [0, gauge_width / 2]
                    ]);
    }
}

dogbone();
