```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds upward in +Z, centred on origin in X/Y

// ---------------- Parameters ----------------
spec_thickness = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X (mm)

gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)

grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)

transition_len = 15;    // each transition (grip -> gauge) length (X)

cut_extra      = 0.5;   // extra length for cutting shapes past faces (mm)

$fn = 64;

// ---------------- Derived ----------------
half_gauge = gauge_length / 2;        // 25
half_grip  = grip_length / 2;         // 12.5
x0         = -total_length / 2;       // -65

// Width profile seen from above: piecewise linear in X
function profile_w(x) =
    if (x < -half_gauge - half_grip) grip_width
    else if (x < -half_gauge)        (grip_width - gauge_width) * (x + half_grip + gauge_length / 2) / transition_len + gauge_width
    else if (x < half_gauge)         gauge_width
    else if (x < half_gauge + transition_len)
        (grip_width - gauge_width) * (x - half_gauge) / transition_len + gauge_width
    else grip_width;

// ---------------- Model ----------------
difference() {
    // Outer shape
    hull() {
        for (sx = [-1, 1])
            translate([sx * (half_gauge + half_grip + transition_len), -thickness / 2, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        circle(d = thickness, $fn = 64);
        // End faces (full grip width)
        for (z = [0, thickness])
            translate([-total_length / 2, -grip_width / 2, z])
                cube([total_length, grip_width, 1]);
    }

    // Through the middle: a longer central grip block + gauge block,
    // so the transitions remain at least 15 mm long on both ends
    split_len = gauge_length + 2 * transition_len + grip_length;
    translate([x0 - cut_extra, -grip_width / 2, 0])
        cube([split_len + 2 * cut_extra, grip_width, thickness]);

    translate([x0 - cut_extra, -gauge_width / 2, 0])
        cube([gauge_length + 2 * cut_extra, gauge_width, thickness]);
}
