$fn = 64;

// ---- Dimensions (mm) ----
thickness     = 4;     // specimen thickness
total_length  = 130;   // overall length along X
gauge_width   = 6;     // narrow gauge section width (Y)
gauge_length  = 50;    // gauge section length (X)
grip_width    = 19;    // grip section width (Y)
grip_length   = 25;    // grip section length (X)
transition    = 15;    // length of each grip-to-gauge transition
cut_extra     = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
half_trans = transition / 2;   // half-width change per side

difference() {
    // Outer shape: grip - transition - gauge - transition - grip
    translate([-total_length / 2, -thickness / 2, 0])
        hull() {
            // left grip end
            translate([-grip_length / 2, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
            // left transition
            translate([0, -transition / 2 + half_trans, 0])
                cube([transition, grip_width - (transition - 2 * half_trans), thickness]);
            // gauge
            translate([0, -gauge_width / 2, 0])
                cube([gauge_length, gauge_width, thickness]);
            // right transition
            translate([gauge_length, -transition / 2 + half_trans, 0])
                cube([transition, grip_width - (transition - 2 * half_trans), thickness]);
            // right grip end
            translate([total_length / 2 - grip_length / 2, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }

    // Removed end blocks so the grip sections run right up to the bed
    translate([-total_length / 2, -cut_extra, 0])
        cube([grip_length + transition + gauge_length + transition + grip_length,
              cut_extra,
              cut_extra]);
    translate([total_length / 2 - grip_length - transition - gauge_length - transition - grip_length,
               -cut_extra, 0])
        cube([grip_length + transition + gauge_length + transition + grip_length,
              cut_extra,
              cut_extra]);
