// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 .. thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness = 4;     // plate thickness (Z)
total_len = 130;   // overall length along X
gauge_w   = 6;     // narrow gauge width (Y)
gauge_len = 50;    // gauge section length (X)
grip_w    = 19;    // grip section width (Y)
grip_len  = 25;    // grip section length (X)
trans_len = 15;    // transition length between grip and gauge (X)
eps       = 0.5;   // cutter overshoot past faces

// ---- Derived ----
x0 = -total_len / 2;
half_grip = grip_len / 2;
half_trans = trans_len / 2;
half_gauge = gauge_len / 2;

// Width profile seen from above (piecewise linear)
function profile_w(x) =
    if (x < x0 - half_grip) grip_w
    else if (x < x0 - half_trans) grip_w - (x - (x0 - half_grip)) * (grip_w - gauge_w) / trans_len
    else if (x < x0) gauge_w
    else if (x < x0 + half_trans) gauge_w + (x - x0) * (grip_w - gauge_w) / trans_len
    else if (x < x0 + half_grip) grip_w
    else grip_w;

difference() {
    // Plate
    translate([x0, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([for (x = [x0 - 75 : 1 : x0 + 75]) [x, -profile_w(x) / 2],
                     for (x = [x0 + 75 : -1 : x0 - 75]) [x, -profile_w(x) / 2]]);

    // Gauge cutout (overcuts by eps)
    translate([x0 - half_grip - eps, -gauge_w / 2, -eps])
        cube([gauge_len + 2 * eps, gauge_w, thickness + 2 * eps]);
}
