$fn = 64;

// ---------- Derived ----------
a   = grip_width;           // end width (transition starts here)
d   = gauge_width;          // middle width (transition ends here)
L   = total_length;         // full length
h   = gauge_length;         // gauge section length
g   = grip_length;          // grip section length
t   = transition_length;    // transition length
th  = specimen_thickness;   // plate thickness

// Check: 2*g + 2*t + h = 130 mm
assert(abs(2*g + 2*t + h - L) < 0.001, "length mismatch");

// ---------- Model ----------
difference() {
    // Plate
    translate([-L/2, -a/2, 0])
        cube([L, a, th]);

    // Grip sections (outer third of the plate)
    for (sx = [-1, 1])
        translate([sx > 0 ? t : -t - g, -grip_width/2, -cut_overlap])
            cube([grip_length + cut_overlap, grip_width, th + 2*cut_overlap]);

    // Gauge section (middle third)
    translate([-h/2, -d/2, -cut_overlap])
        cube([h, d, th + 2*cut_overlap]);
}
