$fn = 64;

// ---------- Dimensions ----------
plate_thickness = 3;     // plate thickness (Z)
overall_length  = 130;   // total length along X (mm)

gauge_width     = 10;    // gauge section width (Y)
gauge_length    = 40;    // gauge section length (X)

grip_width      = 19;    // grip section width (Y)
grip_length     = 30;    // grip section length (X)

transition_len   = 15;    // length of each grip->gauge transition (X)

