grip_x1    = overall_length / 2 - grip_length; // right grip end
eps        = 0.5;                          // cutter overshoot

// ---------- Model ----------
module dogbone_2d() {
    hull() {
        // left grip
        translate([grip_x0, -grip_width / 2]) square([grip_length, grip_width]);
        // right grip
        translate([grip_x1, -grip_width / 2]) square([grip_length, grip_width]);
        // gauge
        translate([-half_gauge, -gauge_width / 2]) square([gauge_length, gauge_width]);
    }
}

difference() {
    linear_extrude(height = plate_thickness) dogbone_2d();

    // clean overlap between grip and transition sections
    for (s = [-1, 1]) {
        x = s > 0 ? grip_x1 : grip_x0;
        translate([x - eps, -grip_width / 2])
            cube([eps, grip_width, plate_thickness + 2 * eps]);
    }
}
