$fn = 64;

// ---- Dimensions (mm) ----
specimen_length = 130;   // overall length along X
thickness       = 3;     // plate thickness (Z)
gauge_length    = 40;    // middle gauge section length (X)
gauge_width     = 10;    // gauge section width (Y)
grip_length     = 30;    // each grip section length (X)
grip_width      = 19;    // grip section width (Y)
transition_len  = 15;    // each transition region length (X)
cut_extra       = 0.5;   // overshoot for cutting shapes past faces

// ---- Derived ----
n_grips      = 2;        // number of grip sections
total_width  = grip_width + 2 * transition_len + gauge_length;    // end-to-end width
hp_grip      = grip_length / 2;                                    // grip half-length in X

// ---- Model ----
module tensile_specimen() {
    difference() {
        // Plate body
        translate([-specimen_length / 2, -thickness / 2, 0])
            cube([specimen_length, thickness, thickness]);

        // Grip sections and transition regions (seen from above)
        for (i = [0 : n_grips - 1]) {
            x0 = -total_width / 2 + i * transition_len + grip_length;
            // width at the far end of the transition, changing linearly from grip to gauge
            w_end = grip_width + (transition_len - 1) * (gauge_width - grip_width) / (transition_len - 1);
            polygon(points = [
                [x0, grip_width / 2],
                [x0 + transition_len, w_end / 2],
                [x0 + transition_len + gauge_length, gauge_width / 2],
                [x0 + transition_len + gauge_length, -gauge_width / 2],
                [x0 + transition_len, -w_end / 2],
                [x0, -grip_width / 2]
            ]);
        }
    }
}

tensile_specimen();
