// Flat dog-bone tensile specimen for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

// ---------- Dimensions (mm) ----------
specimen_length = 130;   // overall length along X
thickness       = 3;     // plate thickness (Z)

grip_width      = 19;    // grip section width (Y)
grip_length     = 30;    // grip section length (X)

gauge_width     = 10;    // gauge section width (Y)
gauge_length    = 40;    // gauge section length (X)

transition_len   = 15;    // length of each grip-to-gauge transition (X)

// ---------- Derived ----------
total_grip_len    = 2 * grip_length;          // both end grips
total_trans_len   = 2 * transition_len;       // both transitions
gauge_centre_pos  = grip_length + transition_len;  // X of gauge centre
check_len         = grip_length + transition_len + gauge_length + transition_len + grip_length
                  = 130;                       // must equal specimen_length

// ---------- Model ----------
module flat_dogbone() {
    hull() {
        for (s = [-1, 1]) {
            translate([s * gauge_centre_pos, 0, 0])
                linear_extrude(thickness)
                    polygon([
                        [-grip_length, -grip_width / 2],
                        [ grip_length, -grip_width / 2],
                        [ grip_length,  grip_width / 2],
                        [-grip_length,  grip_width / 2]
                    ]);
        }
        translate([-transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [-grip_length, -grip_width / 2],
                    [ grip_length, -grip_width / 2],
                    [ gauge_centre_pos - gauge_length / 2, -gauge_width / 2],
                    [ gauge_centre_pos - gauge_length / 2, gauge_width / 2],
                    [ grip_length, gauge_width / 2]
                ]);
        translate([transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [ grip_length, -grip_width / 2],
                    [ gauge_centre_pos - gauge_length / 2, -gauge_width / 2],
                    [ gauge_centre_pos + gauge_length / 2, -gauge_width / 2],
                    [ gauge_centre_pos + gauge_length / 2, gauge_width / 2],
                    [ grip_length, gauge_width / 2]
                ]);
        translate([s = 1; s * (gauge_centre_pos + transition_len), 0, 0])
            linear_extrude(thickness)
                polygon([
                    [ gauge_centre_pos + gauge_length / 2, gauge_width / 2],
                    [ gauge_centre_pos + gauge_length / 2, -gauge_width / 2],
                    [ s * (gauge_centre_pos - gauge_length / 2), -gauge_width / 2],
                    [ s * (gauge_centre_pos - gauge_length / 2), gauge_width / 2]
                ]);
    }
}

