```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions ----
thickness      = 3;     // Z thickness
total_length   = 130;   // overall X length
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 40;    // gauge section X length
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section X length (each)
transition_len = 15;    // transition X length (each)

// ---- Derived ----
eps            = 0.5;   // cutter overshoot
grip_start     = grip_length / 2;   // 15
gauge_end      = total_length / 2 - grip_start;  // 40
cut_thickness  = thickness + 2 * eps;

// ---- Model ----
union() {
    // Left grip
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Right grip
    translate([total_length / 2 - grip_start, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge + transitions (sine-based width change)
    translate([-grip_start, -grip_width / 2, 0])
        hull() {
            for (s = [-1, 1])
                translate([s * grip_start - gauge_end, 0, 0])
                    rotate([0, 90, 0])
                        linear_extrude(thickness)
                            circle(d = gauge_width, h = grip_start + gauge_end + 0.01);
        }

    // Centralizing block (overlaps everything for a clean union)
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);
}

// Remove the diagonal flanks that the hull created above the flat top/bottom faces
difference() {
    module() {
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([total_length, grip_width, thickness]);
    }

    // upper flank
    translate([-grip_start, -grip_width / 2 - eps, thickness])
        rotate([90, 0, 0])
            linear_extrude(height = grip_start + gauge_end + 0.01)
                circle(d = gauge_width);

    // lower flank
    translate([-grip_start, grip_width / 2 + eps, 0])
        rotate([-90, 0, 0])
            linear_extrude(height = grip_start + gauge_end + 0.01)
                circle(d = gauge_width);
}
