// Flat tensile test specimen (dog-bone shape)
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters (mm) ----------
thickness    = 3;     // specimen thickness (Z)
total_len    = 120;   // overall length along X
gauge_w      = 8;     // narrow gauge width (Y)
gauge_len    = 30;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_len     = 35;    // grip section length (X)
transition_l = 10;    // length of each transition region (X)
eps          = 0.5;   // overcut for clean differences

$fn = 64;

// ---------- Derived ----------
half_gauge   = gauge_w / 2;
half_grip    = grip_w / 2;
grip_start_x = (total_len / 2) - grip_len;   // grip end near gauge (both sides)

// ---------- Model ----------
difference() {
    // Full plate
    translate([-total_len / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
                [-total_len / 2, -half_grip],
                [ total_len / 2, -half_grip],
                [ total_len / 2,  half_grip],
                [ -total_len / 2,  half_grip]
            ]);

    // Central gauge section
    translate([-gauge_len / 2, -half_gauge, eps])
        cube([gauge_len, gauge_w, thickness - 2 * eps]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s * grip_start_x, -half_grip, eps])
            cube([grip_len, grip_w, thickness - 2 * eps]);

    // Transition regions: width changes linearly from grip to gauge
    for (s = [-1, 1])
        translate([s * (grip_start_x - transition_l), -half_grip, eps])
            cube([transition_l,
                   half_gauge + (half_grip - half_gauge) * (eps / transition_l),
                   thickness - 2 * eps]);   // flatter profile in the taper
}
