// Flat tensile test specimen (dog bone)
// Print orientation: flat on the bed, z = 0 up to thickness

$fn = 64;

// ---------- Dimensions (mm) ----------
thickness  = 3;     // specimen thickness (Z)
total_len  = 120;   // overall length along X
gauge_w    = 8;     // gauge section width (Y)
gauge_len  = 30;    // gauge section length (X)
grip_w     = 20;    // grip section width (Y)
grip_len   = 35;    // grip section length (X)
trans_len  = 10;    // transition section length (X)

// ---------- Derived ----------
grip_h      = grip_w  / 2;   // grip half-width
gauge_h     = gauge_w / 2;   // gauge half-width
trans_start = grip_len;      // transition begins after grip
trans_end   = trans_start + trans_len; // end of transition
lenv2       = total_len / 2;  // right end of specimen

// ---------- Model ----------
module flat_dogbone() {
    // Outer contour seen from above, traced counter-clockwise
    contour = concat(
        [ for (x = [0 : trans_len : trans_start])      [ x, -grip_h ] ],  // bottom of left grip
        [ for (x = [trans_start : trans_len : trans_end])  [ x, -gauge_h + (gauge_h - grip_h) * (x - trans_start) / trans_len ] ],  // left transition
        [ for (x = [trans_end : -trans_len : -trans_start])    [ x, -gauge_h + (gauge_h - grip_h) * (x + trans_len - trans_end) / trans_len ] ],  // right transition
        [ for (x = [-trans_start : -trans_len : -grip_len])      [ x, -grip_h ] ],  // bottom of right grip
        [ lenv2, grip_h ],  // top right corner of right grip
        [ for (x = [lenv2 : -trans_len : lenv2 - trans_len])      [ x, grip_h + (gauge_h - grip_h) * (x - (lenv2 - trans_end)) / trans_len ] ],  // right transition (overlapping endpoints cancel the extra segment)
        [ -lenv2, grip_h ],  // top left corner of left grip
        [ for (x = [-lenv2 + trans_len : trans_len : -trans_start + trans_len])  [ x, grip_h + (gauge_h - grip_h) * (x + trans_len - lenv2 + trans_end) / trans_len ] ]  // left transition
    );

    // extrude and cut the material down to the specified thickness
    difference() {
        linear_extrude(height = thickness)
            polygon(points = contour);

        // gauge section, overcut past both end faces
        translate([ -gauge_len / 2, -gauge_h, -1 ])
            cube([ gauge_len, gauge_w, thickness + 2 ]);
    }
}

flat_dogbone();
