// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, builds upward in +Z

$fn = 64;

// ---------- Dimensions (mm) ----------
specimen_length = 120;   // overall length along X
thickness       = 3;     // constant thickness (Z)

gauge_width     = 8;     // narrow gauge section width (Y)
gauge_length    = 30;    // gauge section length (X)

grip_width      = 20;    // grip section width (Y)
grip_length     = 35;    // grip section length (X)

transition_1_len = 10;    // first transition length (X)
transition_2_len = 10;    // second transition length (X)

// ---------- Derived ----------
split_y = (grip_width + gauge_width) / 2;   // where the profile is split in Y

// ---------- Profile (top face) ----------
module top_profile() {
    // Grip
    translate([-grip_length / 2, -grip_width / 2]) square([grip_length, grip_width]);
    // Transition 1
    translate([-transition_1_len / 2, -split_y])
        linear_extrude(height = transition_1_len)
            polygon(points = [
                [-transition_1_len / 2, -split_y],
                [ transition_1_len / 2, -split_y],
                [ transition_1_len / 2, -gauge_width / 2],
                [ -transition_1_len / 2, -gauge_width / 2]
            ]);
    // Gauge
    translate([-gauge_length / 2, -gauge_width / 2]) square([gauge_length, gauge_width]);
    // Transition 2
    translate([gauge_length / 2 - transition_2_len / 2, -split_y])
        linear_extrude(height = transition_2_len)
            polygon(points = [
                [ transition_2_len / 2, -split_y],
                [ -transition_2_len / 2, -split_y],
                [ -transition_2_len / 2, -gauge_width / 2],
                [ -gauge_length / 2 + transition_2_len / 2, -gauge_width / 2]
            ]);
    // Grip
    translate([grip_length / 2, -grip_width / 2]) square([grip_length, grip_width]);
}

module specimen() {
