// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, builds upward in +Z

$fn = 64;

// ---------- Dimensions (mm) ----------
thickness      = 3;     // specimen thickness (Z)
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip -> gauge transition (X)
cut_extra      = 0.5;   // overshoot for cutting shapes

// ---------- Derived ----------
grip_x0   = -(grip_length + transition_len) / 2;   // left grip start
grip_x1   = (grip_length + transition_len) / 2;    // right grip start
tran_w    = [grip_width, gauge_width];            // transition end widths
total_len = gauge_length + 2 * transition_len + 2 * grip_length; // 120 mm

// ---------- Model ----------
module profile() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_x1, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions: width changes linearly from grip to gauge
        for (s = [-1, 1])
            for (i = [0 : transition_len - 1]) {
                w = grip_width + (i / (transition_len - 1)) * (gauge_width - grip_width);
                translate([s * (-grip_x1 + i * transition_len / transition_len),
                           -w / 2, 0])
                    cube([transition_len, w, thickness]);
            }
    }
}

difference() {
    linear_extrude(height = thickness) profile();
    // Horizontal cuts past the grip ends
    for (s = [-1, 1])
        translate([s * grip_x1 - cut_extra, -grip_width / 2 - cut_extra, -cut_extra])
            cube([grip_length + 2 * cut_extra + transition_len,
                  grip_width + 2 * cut_extra,
                  thickness + 2 * cut_extra]);
    // Horizontal cut past the gauge ends
    translate([-gauge_length / 2 - cut_extra, -gauge_width / 2 - cut_extra, -cut_extra])
        cube([gauge_length + 2 * cut_extra,
              gauge_width + 2 * cut_extra,
              thickness + 2 * cut_extra]);
}
