// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds upward in +Z, centred on origin in XY

$fn = 64;

// ---- Dimensions (mm) ----
specimen_thickness = 3;     // plate thickness (Z)
overall_length     = 120;   // total length along X
gauge_width        = 8;     // gauge section width (Y)
gauge_length       = 30;    // gauge section length (X)
grip_width         = 20;    // grip section width (Y)
grip_length        = 35;    // grip section length (X)
transition_length  = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
grip_x0   = -overall_length/2 + grip_length;  // grip end (towards gauge)
gauge_x0  = -gauge_length/2;                  // gauge end (towards grip)
overlap   = grip_x0 - gauge_x0;               // overlap length between grip/gauge
fault    = transition_length + overlap;       // extra transition added beyond overlap

// ---- Model ----
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([s * overall_length/2 - s * grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

    // Gauge section
    translate([gauge_x0, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, specimen_thickness]);

    // Grip-gauge transitions (45-degree profile in X-Y; no Z change)
    for (s = [-1, 1])
        translate([s * overall_length/2 - s * (grip_length + transition_length),
                    -grip_width/2, 0])
            linear_extrude(height = specimen_thickness)
                polygon(points = [
                    [0, -grip_width],
                    [transition_length, -grip_width],
                    [transition_length, 0],
                    [transition_length, grip_width],
                    [0, grip_width]
                ]);
}

// ---- Cleanup: remove the duplicated material where the transition overlaps the grip ----
difference() {
    module() {
        union() {
            // Grip sections (full thickness)
            for (s = [-1, 1])
                translate([s * overall_length/2 - s * grip_length, -grip_width/2, 0])
                    cube([grip_length, grip_width, specimen_thickness]);

            // Gauge section (full thickness)
            translate([gauge_x0, -gauge_width/2, 0])
                cube([gauge_length, gauge_width, specimen_thickness]);
        }

        // Cut out the extra transition block that lies inside the grip (only top half, z > 1.5)
        for (s = [-1, 1])
            translate([s * overall_length/2 - s * (grip_length + transition_length),
                        -grip_width/2, 0])
                translate([0, -grip_width, 0])
                    cube([transition_length, grip_width, specimen_thickness/2 + 0.01]);
    }
}
