// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)

// ---- Derived ----
grip_x0 = -total_length / 2;          // grip outer edge (left)
mid_x0  = grip_x0 + grip_length;      // gauge outer edges
trans_x0 = mid_x0 + transition_len;   // second grip outer edge

// Width profile along X: grip -> transition -> gauge -> transition -> grip
function profile_w(x) =
    min(max(x, grip_x0), mid_x0) <= grip_width + transition_len
        // left transition -> gauge -> right transition
        ? abs(x - (mid_x0 - transition_len)) < transition_len
            ? gauge_width + (grip_width - gauge_width) *
              abs(x - (mid_x0 - transition_len + transition_len / 2)) / transition_len
            // linearly changing width between grip and gauge
            : grip_width
        // left grip
        : min(max(x, grip_x0), mid_x0 - transition_len) <= grip_width
            ? grip_width
            : error("x outside part bounds")
        // right grip
        : abs(x - (trans_x0 + grip_length - transition_len)) < transition_len
            ? gauge_width + (grip_width - gauge_width) *
              abs(x - (trans_x0 + grip_length - transition_len + transition_len / 2)) / transition_len
            : grip_width;

module dogbone() {
    hull() {
        for (sx = [-1, 1])
            for (sy = [-1, 1])
                translate([sx * (total_length / 2 - grip_length / 2) -
                          (sx > 0 ? grip_length - transition_len : transition_len),
                           sy * grip_width / 2, 0])
                    cube([transition_len + grip_length - transition_len,
                          grip_width, thickness]);
    }
}

module corrected_dogbone() {
    hull() {
        // Grip sections
        for (sx = [-1, 1])
            translate([sx * (total_length / 2 - grip_length / 2),
                       -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transition sections
        for (sx = [-1, 1])
            for (sy = [-1, 1])
                translate([sx * (total_length / 2 - grip_length / 2 -
                               transition_len - gauge_length / 2) +
                          gauge_length / 2,
                           sy * gauge_width / 2, 0])
                    cube([transition_len, gauge_width, thickness]);
    }
}

corrected_dogbone();
