// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 .. thickness

// ---------- Dimensions (mm) ----------
thickness     = 3;     // specimen thickness (Z)
total_length  = 120;   // overall length along X
gauge_length  = 30;    // gauge section length (X)
gauge_width   = 8;     // gauge section width (Y)
grip_length   = 35;    // each grip section length (X)
grip_width    = 20;    // grip section width (Y)
transition    = 10;    // each transition section length (X), 20 -> 8 width

// ---------- Derived ----------
arm   = grip_length + transition;          // half-length of one end block
core  = gauge_length + 2 * transition;     // length from grip outer edge to gauge outer edge
offset = total_length - core - 2 * arm;    // overlap of the two end blocks

// ---------- Model ----------
union() {
    // Left end block (extends into the gauge region for a solid union)
    translate([-arm - offset/2, -grip_width/2, 0])
        cube([arm + offset/2, grip_width, thickness]);

    // Right end block
    translate([offset/2, -grip_width/2, 0])
        cube([arm + offset/2, grip_width, thickness]);

    // Gauge section
    translate([-gauge_length/2, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Right transition: 20 -> 8 width
    for (i = [0 : transition - 1])
        translate([transition - i, -grip_width/2, 0])
            cube([1, grip_width - i * 1.143, thickness]);

    // Left transition: 20 -> 8 width
    for (i = [0 : transition - 1])
        translate([-transition + i, -grip_width/2, 0])
            cube([1, grip_width - i * 1.143, thickness]);
}
