// Flat tensile test specimen (dog bone) for testing printed plastic
// Units: mm. Print orientation: lying flat on the bed, z = 0 up.

$fn = 64;

// ---- Dimensions ----
thickness      = 3;     // plate thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // length of each grip->gauge transition (X)
eps            = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
x0 = -total_length / 2;                     // left end of specimen
T  = grip_length + transition_len + gauge_length + transition_len + grip_length; // total = 110

// Width of the specimen at a given X (seen from above)
function width(x) =
    if (x < x0 + grip_length)
        grip_width;
    else if (x < x0 + grip_length + transition_len)
        // linear change from grip width (15) to gauge width (10)
        grip_width - (x - (x0 + grip_length)) * (grip_width - gauge_width) / transition_len;
    else if (x < x0 + T - grip_length - transition_len)
        gauge_width;
    else if (x < x0 + T - grip_length)
        // linear change from gauge width (10) to grip width (15)
        gauge_width + (x - (x0 + T - grip_length)) * (grip_width - gauge_width) / transition_len;
    else
        grip_width;

module dogbone() {
    // Outer plate
    translate([x0, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);

    // Gauge section, extended past both faces so the cut is clean
    translate([x0 + transition_len + grip_length - eps,
               -gauge_width / 2,
               -eps])
        cube([gauge_length + 2 * eps,
              gauge_width,
              thickness + 2 * eps]);
}

