    union() {
        // Left grip section
        translate([x_grip1, -half_grip_w, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip section
        translate([x_grip2, -half_grip_w, 0])
            cube([grip_length, grip_width, thickness]);

        // Central gauge section
        translate([x_gauge2, -half_gauge_w, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // Smooth the four transition regions with hull (no coplanar faces)
    for (sx = [x_grip1, x_gauge1, x_gauge2, x_grip2])
        for (sy = [-half_grip_w, half_grip_w])
            hull() = translate([sx, sy, 0])
                    cube([transition_length, 0.01, thickness + 0.01]);
