```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 up to specimen thickness
// Units: mm

$fn = 64;               // curve resolution (no curved features, set per rules)

// --- Specimen dimensions ---
specimen_thickness = 3;     // plate thickness (Z)
total_length       = 110;   // overall length along X
gauge_width        = 10;    // gauge section width (Y)
gauge_length       = 30;    // gauge section length (X)
grip_width         = 15;    // grip section width (Y)
grip_length        = 30;    // grip section length (X)
transition_length  = 10;    // each grip-gauge transition length (X)
overlap            = 0.5;   // overlap so cutting shapes pass through faces

// Derived
grip_end_x    = grip_length + transition_length;   // where grip ends in X
gauge_start_x = total_length - grip_end_x;         // where gauge ends in X
eps           = 0.01;                              // tiny step for linear interpolate

// Linear interpolation between two widths over a given X range
function lerp_w(x_start, w_start, x_end, w_end, x) =
    w_start + (w_end - w_start) * (x - x_start) / (x_end - x_start);

module specimen() {
    union() {
        // Left grip section
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Right grip section
        translate([total_length / 2 - grip_end_x, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Gauge section (narrow middle)
        translate([gauge_start_x, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Transitions: grip -> gauge and gauge -> grip
        for (sx = [gauge_start_x, total_length - grip_end_x])
            for (wx = [gauge_width, grip_width])
                for (ux = [sx, sx + transition_length])
                    translate([sx, -wx / 2, 0])
                        linear_extrude(height = specimen_thickness)
                            for (i = [0 : eps : transition_length])
                                polygon([[i, lerp_w(sx, wx, ux, wx + (eps > 0 ? 0.01 : 0)), 0],
                                        [transition_length - i, lerp_w(ux, wx + (eps > 0 ? 0.01 : 0), sx, wx), 0]]);
    }
}

specimen();
