// ---------- Model (top view extruded) ----------
module outer_profile_len() {
    // start at left grip, run through right grip
    x = -L_g + a/2;
    for (w = [a, a, b, a, a])
        translate([x, -w/2, 0])
            cube([L_g + L_t + L_m/2 + L_t + L_g, w, h]);
}

module cutter_profile_len() {
    // extend cutter past both side faces
    x = -L_g + a/2;
    for (w = [a, a, b, a, a])
        translate([x, -w/2, -eps])
            cube([L_g + L_t + L_m/2 + L_t + L_g, w, h + 2*eps]);
}

difference() {
    linear_extrude(height = h)
        outer_profile_len();
    linear_extrude(height = h + 2*eps)
        cutter_profile_len();
