                       -trans_width/2, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon([
                            [0, -trans_width/2],
                            [trans_len, -trans_width/2],
                            [trans_len, (trans_width - gauge_width)/2],
