// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, z = 0 upward, centred on origin in X/Y

// ---------- Parameters ----------
thickness      = 3;     // plate thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_t = transition_len;   // half distance between grip centres
L_grip = grip_length;

// ---------- Modules ----------
module grip(x0) {
    translate([x0 - L_grip / 2, -grip_width / 2, 0])
        cube([L_grip, grip_width, thickness + eps]);
}

module transition(x0, x1) {
    // x0 = grip end (w = grip_width), x1 = gauge end (w = gauge_width)
    rotate([90, 0, 0])
        linear_extrude(height = thickness + eps)
            polygon(points = [
                [x0, -grip_width / 2],
                [x1, -gauge_width / 2],
                [x1,  gauge_width / 2],
                [x0,  grip_width / 2]
            ]);
}

// ---------- Model ----------
difference() {
    union() {
        for (x0 = [-(total_length / 2 + L_grip / 2), total_length / 2 - L_grip / 2])
            grip(x0);
        for (s = [-1, 1]) {
            x0 = s * (total_length / 2 - L_grip / 2 - half_t);
            x1 = s * (total_length / 2 - half_t);
            transition(x0, x1);
        }
    }
    for (s = [-1, 1]) {
        x0 = s * (total_length / 2 - L_grip / 2 - half_t);
        x1 = s * (total_length / 2 - half_t);
        translate([x0, -grip_width / 2 - eps, 0])
            cube([half_t + eps, grip_width + 2 * eps, thickness + eps]);
        translate([x1, -gauge_width / 2, 0])
            cube([half_t + eps, gauge_width + 2 * eps, thickness + eps]);
    }
}
