// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up +Z

// ---------- Parameters ----------
thickness      = 3;     // plate thickness (Z)
total_len      = 110;   // overall length along X (mm)
gauge_width    = 10;    // narrow section width (Y)
gauge_len      = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_len       = 30;    // grip section length (X)
trans_len      = 10;    // transition length between grip and gauge (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 64;

// ---------- Derived ----------
a      = gauge_width;     // gauge width
b      = grip_width;      // grip width
L_g    = gauge_len;       // gauge length
L_r    = grip_len;        // grip length
L_t    = trans_len;       // transition length
L      = total_len;       // total length
thresh = 0.01;            // width-change threshold for linear check

// ---------- Model ----------
module dogbone_2d() {
    // Check each transition's width change (< 1 mm over its length)
    for (p = [-(L/2 + L_t), -(L/2 - L_t), (L/2 - L_t), (L/2 + L_t)]) {
        w0 = get_y_width(p - L_t);   // width at start of transition
        w1 = get_y_width(p + L_t);   // width at end of transition
        if (w0 - w1 > thresh)
            translate([p - L_t, 0, 0])
                linear_extrude(height = L_t)
                    polygon(points = [
                        [0, (w0 + w1) / 2 - 0.5],
                        [0, (w0 + w1) / 2 + 0.5]
                    ]);
    }
}

module get_y_width(x) {
    // Width of the part at position x, projected onto Y
    return intersection() {
        translate([x, 0, 0])
            cube([1, 16, 10]);
        difference() {
            translate([-L/2, -thickness/2, 0])
                cube([L, thickness, 10]);
            for (s = [-1, 1]) {
                translate([s * (L/2 - L_t), -b/2, 0])
                    cube([1 + 2*cut_extra, b, 10]);
                translate([s * (L/2 - L_t) - L_t, -b/2, 0])
                    cube([1 + 2*cut_extra, b, 10]);
            }
        }
    };
}

module dogbone() {
    // Strip the transition pieces, then run the linear extrusion
    difference() {
        translate([-L/2, 0, 0])
            cube([L, 2*thickness, 10]);
        for (p = [-(L/2 + L_t), -(L/2 - L_t), (L/2 - L_t), (L/2 + L_t)])
            translate([p - L_t, 0, 0])
                cube([L_t, 2*thickness, 10]);
    }
    linear_extrude(height = thickness)
        dogbone_2d();
}

dogbone();
