        translate([-grip_length, -half_grip, 0])
            cube([grip_length + grip_width / 2, grip_width, thickness]);
        // Gauge: -gauge_length/2 .. gauge_length/2
        translate([-gauge_length / 2, -half_gauge, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Left grip: -total_length/2 .. -grip_length
        translate([-total_length / 2, -half_grip, 0])
            cube([grip_width / 2 + grip_length, grip_width, thickness]);
