// ---- Model ----
union() {
    // grip sections
    for (s = [-1, 1])
        translate([s * left_gr[s], -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    // gauge section
    translate([mid_c - gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
    // transitions: width changes linearly from grip (20) to gauge (10)
    for (s = [-1, 1])
        translate([s * (total_length / 2 - transition_len - mid_c + gauge_length / 2),
                   -transition_width(s) / 2, 0])
            cube([transition_len, transition_width(s), thickness]);
}

// width at the given end of the transition (0..1: 20 -> 10)
function transition_width(t) = grip_width + (gauge_width - grip_width) * t;
