half_gauge    = gauge_width  / 2;
half_grip     = grip_width   / 2;
grip_start_x  = -(total_length / 2) + grip_length;   // left grip start
transition_x0 = grip_start_x + grip_length;          // gauge start / transition end

// Width profile along X (front and back edges follow the same curve -> no twist)
function w(x) =
    if (x < transition_x0 - transition_len)
        half_grip + (half_gauge - half_grip) * (x - (transition_x0 - transition_len)) / transition_len
    else if (x < transition_x0 + transition_len)
        half_gauge + (half_grip - half_gauge) * (x - transition_x0) / transition_len
    else
        half_grip;

module dogbone() {
    // Front half (y > 0), extruded through to y < 0 (symmetric thickness)
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            curve([
                for (x = [grip_start_x - grip_length / 2 : grip_length / 2 : transition_x0 - transition_len / 2])
                    [x, w(x)];
                for (x = [transition_x0 + transition_len / 2 : -grip_length / 2 : -grip_start_x + grip_length / 2])
                    [x, w(x)];
            ]);
}

