// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, builds up +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length (X), each end
transition_len = 10;    // transition section length (X), each end
eps            = 0.5;   // cutter overshoot past faces

// Derived
half_len = total_length / 2;
// check: grip + trans + gauge + trans + grip = 130
assert(abs(grip_length + transition_len + gauge_length + transition_len + grip_length - total_length) < 0.001, "length mismatch");

module width_at(x) {
    // x is in [-65, 65]; piecewise linear width profile
    if (x < -transition_len) return grip_width;
    if (x < -gauge_length)  return grip_width + (transition_len - (x + gauge_length)) * (grip_width - gauge_width) / transition_len;
    if (x <= 0)             return gauge_width;
    if (x <= gauge_length)  return gauge_width;
    if (x < transition_len)  return gauge_width + (x - gauge_length) * (grip_width - gauge_width) / transition_len;
    if (x <= half_len)      return grip_width;
    return grip_width;
}

module side_profile() {
    // (x, y) curve in the plane of the bed, extruded up
    hull() {
        for (s = [0 : 0.001 : 1]) {
            x = (s - 0.5) * half_len;
            translate([x, -width_at(x) / 2]) cube([1, width_at(x), thickness]);
        }
    }
}

side_profile();
