        // Left grip
        translate([x0, -grip_w/2, 0]) cube([grip_len, grip_w, 1]);
        // Right grip
        translate([x0 + grip_inset, -grip_w/2, 0]) cube([grip_len, grip_w, 1]);
        // Gauge section with linearly narrowing transition on each side
        hull() {
            for (s = [-1, 1]) {
                translate([s * trans_len + gauge_len/2,
                           s * (grip_w - gauge_w)/2,
                           0]) cube([gauge_len, gauge_w, 1]);
            }
        }
    }
}

