// Dog-bone tensile specimen - flat bar with a central narrow section
// Units: mm. Prints flat on the bed (z = 0 up to thickness).

$fn = 64;

// ---- Dimensions ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // width of the gauge section (Y)
gauge_length   = 50;    // length of the gauge section (X)
grip_width     = 19;    // width of each grip section (Y)
grip_length    = 25;    // length of each grip section (X)
transition_len = 15;    // length of each grip->gauge transition (X)

// ---- Derived ----
half_len = total_length / 2;
// Check: 2*25 + 50 + 2*15 = 130 mm

// Width profile seen from above: y = f(x)
module width_profile() {
    // Equally spaced points along X, from -half_len to +half_len
    for (i = [0 : total_length : total_length]) {
        x = i - half_len;
        if (x >= -grip_length && x <= grip_length - transition_len)
            // left grip (full width)
            y = grip_width;
        else if (x > grip_length - transition_len && x < 0)
            // left transition: linearly grip_width -> gauge_width
            y = grip_width + (gauge_width - grip_width) *
                (x - (grip_length - transition_len)) / transition_len;
        else if (x >= 0 && x < gauge_length)
            // gauge section
            y = gauge_width;
        else if (x > 0 && x < gauge_length + transition_len)
            // right transition: linearly gauge_width -> grip_width
            y = gauge_width + (grip_width - gauge_width) *
                (x - gauge_length) / transition_len;
        else
            // right grip (full width)
            y = grip_width;
        translate([x, -y/2, 0])
            cube([1, y, thickness]);
    }
}

width_profile();
