total_len   = 130;   // overall length along X (mm)
thickness   = 3;     // specimen thickness (mm)
gauge_w     = 6;     // gauge section width (Y) (mm)
gauge_len   = 50;    // gauge section length (X) (mm)
grip_w      = 19;    // grip section width (Y) (mm)
grip_len    = 25;    // grip section length (X) (mm)
trans_len   = 15;    // transition section length (X) (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// X span of each transition: from grip end to gauge end
trans_span = half_gauge + half_grip + trans_len;

// ---------- Model ----------
module dogbone() {
    difference() {
        // Outer area (seen from above), extruded to thickness
        linear_extrude(height = thickness) {
            union() {
                // Left grip
                translate([-trans_span, -grip_w / 2, 0])
                    square([grip_len, grip_w]);
                // Right grip
                translate([trans_span - grip_len, -grip_w / 2, 0])
                    square([grip_len, grip_w]);
                // Gauge
                translate([-half_gauge, -gauge_w / 2, 0])
                    square([gauge_len, gauge_w]);
                // Transitions: width changes linearly from grip_w to gauge_w
                for (sx = [-1, 1])
                    for (t = [0 : trans_len])
                        translate([sx * (trans_span - t),
                                   -grip_w / 2 + sx * (t / trans_len) * (gauge_w - grip_w) / 2,
                                   0])
                            square([1, grip_w + (t / trans_len) * (gauge_w - grip_w)]);
            }
        }

        // Remove the central ~2 mm thick band, leaving a solid border
        // (no faces are coplanar after the offset)
        translate([0, 0, -eps])
            linear_extrude(height = thickness + 2 * eps)
                circle(d = total_len - 2 * trans_len + 0.1, $fn = 6);
    }
}

