// Spoked wheel for a small sample cart
// Print orientation: flat on bed, builds upward in +Z

// ---------- Dimensions (mm) ----------
wheel_thickness = 8;     // overall part thickness
outer_diameter  = 80;    // outer rim diameter
rim_width       = 5;     // rim width (radial)
hub_diameter    = 16;    // hub diameter
axle_hole       = 8;     // axle hole diameter
spoke_count     = 8;     // number of spokes
spoke_width     = 5;     // spoke width (radial)
start_angle     = 0;     // first spoke along +X axis

build_extra = 0.5;       // extra length for cutters past faces
$fn = 96;                // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
rim_id  = outer_diameter - 2 * rim_width;   // rim inner diameter
hub_r   = hub_diameter / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer ring
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub with axle hole
        translate([0, 0, -build_extra])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * build_extra, $fn = 96);

        // Spokes: hub -> rim
        for (i = [0 : spoke_count - 1]) {
            a = start_angle + i * 360 / spoke_count;
            translate([hub_r, 0, -build_extra])
                rotate([0, 0, a])
                    cube([rim_id / 2 - hub_r, spoke_width, wheel_thickness + 2 * build_extra]);
        }
    }

    // Axle hole through everything
    translate([0, 0, -build_extra])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * build_extra, $fn = 64);
}
