// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
wheel_thickness   = 8;    // part thickness (Z)
outer_diameter    = 80;   // outer rim diameter
rim_width         = 6;    // rim width (radial)
hub_diameter      = 20;   // hub diameter
axle_hole_d       = 6;    // axle hole diameter
spoke_count       = 5;    // number of spokes
spoke_width       = 5;    // spoke width (radial)
spoke_start_angle = 0;    // first spoke along +X axis
cut_extra         = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---------- Derived ----------
hub_r     = hub_diameter / 2;
rim_od    = outer_diameter;
rim_id    = rim_od - 2 * rim_width;
spoke_r0  = hub_r + 1;   // spoke starts just outside hub
spoke_r1  = rim_id / 2;  // spoke ends just inside rim

// ---------- Model ----------
difference() {
    union() {
        // Rim
        hull() {
            for (i = [0 : spoke_count - 1]) {
                a = spoke_start_angle + i * 360 / spoke_count;
                translate([spoke_r1 * cos(a), spoke_r1 * sin(a), 0])
                    cylinder(d = rim_width, h = wheel_thickness);
            }
        }

        // Hub
        cylinder(d = hub_diameter, h = wheel_thickness);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_angle + i * 360 / spoke_count;
            translate([spoke_r0 * cos(a), spoke_r0 * sin(a), 0])
                cube([spoke_width, wheel_thickness, spoke_r1 - spoke_r0 + 1]);
        }
    }

    // Axle hole
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra);
}
