// ---- Dimensions (mm) ----
wheel_thickness = 8;     // part thickness (Z)
outer_diameter  = 80;    // outer rim diameter
rim_width       = 6;     // rim width (radial)
hub_diameter    = 20;    // hub outer diameter
axle_hole       = 6;     // centre axle hole diameter
spoke_count     = 5;     // number of spokes
spoke_width     = 5;     // spoke width (radial)

// ---- Derived ----
spoke_length = rim_width + wheel_thickness - 1; // hub -> rim
start_angle  = 0;        // +X axis

$fn = 128;

difference() {
    union() {
        // Rim
        cylinder(d = outer_diameter, h = wheel_thickness);
        // Hub
        translate([0, 0, -1])
            cylinder(d = hub_diameter, h = wheel_thickness + 2);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, start_angle + i * 360 / spoke_count])
                translate([spoke_width, 0, -1])
                    cube([spoke_length, spoke_width, wheel_thickness + 2]);
    }
    // Axle hole
    translate([0, 0, -1])
        cylinder(d = axle_hole, h = wheel_thickness + 2);
}
```

