// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, builds upward in +Z

// ---------------- Parameters ----------------
wheel_thickness = 8;     // overall part thickness (8 mm)
outer_diameter  = 80;    // outer rim diameter (80 mm)
rim_width       = 6;     // rim width (6 mm)
hub_diameter    = 20;    // hub outer diameter (20 mm)
axle_hole       = 6;     // centre axle hole diameter (6 mm)
spoke_count     = 5;     // number of spokes (5)
spoke_width     = 5;     // spoke width radially (5 mm)
spoke_start     = 0;     // angle of first spoke (deg, +X axis)
cut_overlap     = 0.5;   // extra length on cutters to avoid coplanar faces

$fn = 128;               // smoothness for curved shapes

// ---------------- Derived ----------------
rim_inner_d  = outer_diameter - 2 * rim_width;   // 68 mm
hub_outer_d  = hub_diameter;
spoke_length = rim_inner_d / 2 + 0.01;           // runs to the rim

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Hub
        translate([0, 0, -cut_overlap])
            cylinder(d = hub_outer_d, h = wheel_thickness + 2 * cut_overlap);

        // Spokes: radial rectangles from hub to rim, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([hub_outer_d / 2 - 0.01, 0, -cut_overlap])
                rotate([0, 90, a])
                    cube([spoke_length, wheel_thickness + 2 * cut_overlap, spoke_width]);
        }
    }

    // Centre axle hole through the hub
    translate([0, 0, -cut_overlap])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * cut_overlap);
}
