$fn = 96;

// ---- Dimensions (mm) ----
wheel_od        = 100;   // outer rim diameter
wheel_thick     = 6;     // rim width (also hub thickness)
hub_d           = 14;    // hub diameter
axle_d          = 8;     // axle hole diameter
spoke_count     = 6;     // number of spokes
spoke_w         = 5;     // spoke width (radial)
spoke_start_ang = 0;     // first spoke on +X axis
overcut         = 0.5;   // cutter overshoot past faces

hub_r = hub_d / 2;
rim_r = wheel_od / 2;

// ---- Model ----
difference() {
    union() {
        // Rim ring
        cylinder(d = wheel_od, h = wheel_thick);

        // Spokes: from slightly outside hub to slightly inside rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_r - 0.01, 0, 0])
                rotate([0, 0, a])
                    translate([0, -spoke_w / 2, 0])
                        cube([(rim_r - hub_r) + 0.02, spoke_w, wheel_thick]);
        }

        // Central hub (overlaps the spokes for a clean union)
        translate([0, 0, 0])
            cylinder(d = hub_d, h = wheel_thick + 0.01);
    }

    // Axle hole through the centre
    translate([0, 0, -overcut])
        cylinder(d = axle_d, h = wheel_thick + 2 * overcut);
}
