```openscad
// Spoked wheel for sample cart
// Flat printed part: rim, hub with axle hole, and straight spokes

// ---- Dimensions (mm) ----
part_thickness = 6;     // part thickness (Z)
outer_diameter = 100;   // outer rim diameter
rim_width      = 6;     // rim width (radial)
hub_diameter   = 14;    // hub diameter
axle_hole      = 8;     // axle hole diameter
spoke_count    = 6;     // number of spokes
spoke_width    = 5;     // spoke width (radial)
first_spoke    = 0;     // angle of first spoke (deg, 0 = +X axis)
overlap        = 0.5;   // radial overlap between spokes and rim/hub for a clean union

$fn = 128;              // resolution for curved shapes

// ---- Derived ----
outer_r      = outer_diameter / 2;
rim_inner_r  = outer_r - rim_width;
hub_r        = hub_diameter / 2;

// ---- Model ----
union() {
    // Outer rim (ring)
    difference() {
        cylinder(d = outer_diameter, h = part_thickness);
        translate([0, 0, -1])
            cylinder(d = rim_inner_r, h = part_thickness + 2);
    }

    // Hub with axle hole
    translate([0, 0, -1])
        difference() {
            cylinder(d = hub_diameter, h = part_thickness + 2);
            translate([0, 0, -1])
                cylinder(d = axle_hole, h = part_thickness + 2);
        }

    // Spokes, radially from hub to rim, evenly spaced
    for (i = [0 : spoke_count - 1]) {
        a = first_spoke + i * 360 / spoke_count;
        translate([hub_r, 0, -1])
            rotate([0, 0, a])
                cube([rim_inner_r - hub_r + overlap, spoke_width, part_thickness + 2]);
    }
}
```

