// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)
// Positioned per the user's coordinates: x -7.5 .. 7.5, y -6 .. 6, z 0 .. 6

$fn = 64;

// ---- Dimensions (mm) ----
flange_width   = 12;   // flange width along Y
flange_thick   = 3;    // flange thickness (z = 0 .. 3)
neck_width     = 6;    // neck width along Y
neck_height    = 3;    // neck height above flange (z = 3 .. 6)
screw_d        = 3.4;  // central screw hole diameter
length_x       = 15;   // part length along X
eps            = 0.5;  // overshoot for clean boolean cuts

difference() {
    // T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);
        // Centred neck
        translate([-neck_width / 2, -neck_width / 2, flange_thick])
            cube([neck_width, neck_width, neck_height]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_thick + neck_height + 2 * eps);
}
