neck_width     = 6;    // neck width along Y
neck_top_z     = 6;    // top of neck (neck runs z = 3 to z = 6)
screw_d        = 3.4;  // screw hole diameter
screw_top_z    = 7.5;  // screw hole exits here (extends past the top)
