difference() {
    union() {
        // Bottom flange: z = 0 .. 3
        translate([center_x - x_length / 2, center_y - flange_width / 2, 0])
            cube([x_length, flange_width, flange_thick]);

        // Neck, centred on the flange: z = 3 .. 6
        translate([center_x - neck_width / 2, center_y - neck_width / 2, flange_thick])
            cube([neck_width, neck_width, neck_top_z - flange_thick]);
    }

    // Screw hole, extends past the top face so the cut is clean
    translate([center_x, center_y, 0])
        cylinder(d = screw_d, h = screw_top_z - flange_thick);
}
