// T-shaped nut that slides in an aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// The profile is defined in YZ, extruded along X and centred on the origin.

// ---------- Dimensions (mm) ----------
flange_width   = 14;   // flange width along Y
flange_thick   = 2.5;  // flange thickness (z = 0 to 2.5)
neck_width     = 8;    // neck width along Y
neck_height    = 6.5;  // top of neck (z = 2.5 + 6.5 = 9.0)
screw_d        = 5.5;  // vertical screw hole diameter
length_x       = 10;   // extrusion length along X

eps            = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Upside-down T profile in YZ, extruded along X
    translate([-length_x / 2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    // flange
                    [-flange_width / 2, 0],
                    [ flange_width / 2, 0],
                    [ flange_width / 2, flange_thick],
                    [-flange_width / 2, flange_thick],
                    // neck (overlaps the flange area -> solid T)
                    [0, flange_width / 2],
                    [0, neck_width / 2],
                    [0, -neck_width / 2],
                    [0, -flange_width / 2],
                    // close the loop along the thickened spine
                    [flange_width / 2, flange_thick],
                    [flange_width / 2, flange_thick + (neck_height - flange_thick)],
                    [-flange_width / 2, flange_thick + (neck_height - flange_thick)],
                    [-flange_width / 2, flange_thick]
                ]);

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_height + eps);
}
