module t_profile() {
    hull() {
        // Bottom flange: full width at z = 0, centred on Y = 0
        translate([0, -flange_width / 2, 0])
            cube([part_length, flange_width, flange_thickness]);

        // Neck: centered on the origin, rising from flange top to neck_top_z
        translate([0, 0, flange_thickness])
            cube([part_length, neck_width, neck_top_z - flange_thickness]);
    }
}

difference() {
    t_profile();

    // Screw hole through the centre, extra past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = screw_d, h = neck_top_z + cut_extra);
}
