// T-shaped nut for aluminium extrusion
// Print orientation: flange flat on bed, neck pointing up (+Z)

$fn = 64;

// ---- Flange ----
flange_len   = 14;   // flange size in Y (called length in 2D profile)
flange_thk   = 2;    // flange thickness in Z

// ---- Neck ----
neck_len     = 7;    // neck size in Y
neck_h       = 6;    // neck top height in Z

// ---- Screw hole ----
screw_d      = 4.5;  // through-hole diameter

// ---- Misc ----
eps          = 0.5;  // cutter overshoot past faces
prof_len     = 15;   // length of 2D profile along X

module t_flange() {
    translate([0, -flange_len/2, 0])
        cube([flange_len, prof_len, flange_thk]);
}

module t_neck() {
    // extend neck down into flange so the union is one solid
    translate([0, -neck_len/2, -eps])
        cube([neck_len, prof_len, neck_h + eps]);
}

difference() {
    union() {
        t_flange();
        t_neck();
    }
    // vertical screw hole through the whole part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_h + 2*eps);
}
