// Anti-vibration foot for benchtop instrument
// Print orientation: recess facing down on the bed, then build upward.

$fn = 128;

// --- Frustum dimensions ---
bottom_d     = 50;    // diameter at the bottom (z = 0)
top_d        = 36;    // diameter at the top (z = 12)
frustum_h    = 12;    // height of the cone section

// --- Recess dimensions ---
recess_d     = 42;    // recess diameter
recess_depth = 2;     // recess depth from the bottom face

// --- Screw hole dimensions ---
screw_d      = 5.5;   // through-hole diameter
eps          = 0.5;   // overshoot for clean boolean cuts

// Derived: overall height with the recess
total_h = frustum_h + recess_depth;

difference() {
    // Truncated cone (frustum), centred on the Z axis
    translate([0, 0, recess_depth])
        cylinder(d1 = top_d, d2 = bottom_d, h = frustum_h);

    // Round recess for a rubber pad, centred on the axis
    translate([0, 0, 0])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through hole for a screw, centred on the axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2 * eps);
}
