```openscad
// Anti-vibration foot - truncated cone with a rubber pad recess and a screw hole
// Units: mm. Print orientation: bottom face (with recess) on the bed at z = 0.

$fn = 128;                 // facet count for round features

// --- Frustum dimensions ---
foot_d_bottom = 50;        // diameter at the bed (z = 0)
foot_d_top    = 36;        // diameter at the flat top (z = 15)
foot_height   = 15;        // overall height of the foot

// --- Recess for the rubber pad ---
recess_d      = 44;        // recess diameter
recess_depth  = 2;         // recess depth from the bottom face

// --- Screw hole ---
screw_d       = 5.5;       // through-hole diameter on the axis

// --- Clearances ---
eps           = 0.5;       // overshoot so cutters pass through faces
hull_eps      = 0.01;      // small thickness for the hull between the two disks

difference() {
    // Truncated cone built as a hull between two disks
    hull() {
        // bottom disk (touches the bed)
        cylinder(d = foot_d_bottom, h = eps, $fn = 128);
        // top disk (flat top at z = foot_height)
        translate([0, 0, foot_height - eps])
            cylinder(d = foot_d_top, h = eps, $fn = 128);
    }

    // Round recess cut into the bottom face for the rubber pad
    translate([0, 0, -recess_depth])
        cylinder(d = recess_d, h = recess_depth + eps, $fn = 128);

    // Screw hole running through the centre along the axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_height + 2 * eps, $fn = 64);
}
```

