// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_len    = 80;    // plate length along X
plate_wid    = 80;    // plate width along Y
plate_thk    = 2;     // plate thickness (z = 0 to 2)

rib_thk      = 2;     // rib thickness along X
rib_h        = 4;     // rib height above plate (z = 2 to 6)
rib_count    = 4;     // number of ribs
rib_pitch    = 16;    // centre-to-centre spacing of ribs
rib_offset   = 16;    // distance of outer ribs from plate ends

eps          = 0.5;   // overlap for clean boolean unions

// ---- Derived ----
rib_x0 = -rib_offset;   // first rib centre (leftmost)
rib_xi = rib_x0 + i * rib_pitch; // centre of rib i

// ---- Model ----
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs
    for (i = [0 : rib_count - 1])
        translate([rib_xi - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
}
```

