```openscad
// Stiffened cover panel - flat plate with 3 straight ribs running along Y
// Print orientation: plate flat on bed (z = 0), ribs build upward (+Z)

// ---------------- Parameters ----------------
plate_len    = 120;   // plate length along X (mm)
plate_wid    = 60;    // plate width along Y (mm)
plate_thk    = 3;     // plate thickness (mm), z = 0..3

rib_thk      = 2;     // rib thickness along X (mm)
rib_h        = 5;     // rib height from top of plate (mm), z = 3..8
rib_count    = 3;     // number of ribs
rib_pitch    = 30;    // centre-to-centre spacing of ribs along X (mm)
rib_offset   = 30;    // distance of outer ribs from plate ends (mm)

overlap      = 0.01;  // small overlap so ribs fuse with plate (mm)

$fn = 64;             // no curved features, set per rules

// ---------------- Derived ----------------
// Ribs divide length into 4 equal parts: centres at 30, 60, 90 (already 30 apart)
// outer ones are 30 mm from the ends, which the pitch/offset give

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1]) {
        x = (i - (rib_count - 1)/2) * rib_pitch + rib_offset;
        translate([x - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
```

