// Powder measuring scoop
// Units: mm. Print orientation: handle along +X, bowl opening upward.

// ---------- Parameters ----------
bowl_r      = 10;    // bowl outer radius
bowl_t      = 2;     // bowl wall thickness
handle_w    = 12;    // handle width (Y)
handle_t    = 3;     // handle thickness (Z)
handle_x0   = 8;     // handle start (X)
handle_x1   = 90;    // handle end (X)
overlap     = 0.5;   // handle / bowl overlap for a clean union
$fn         = 96;    // curve resolution

// ---------- Derived ----------
bowl_h = bowl_r;     // bowl height: bottom at z = 0, rim at z = 10
flange_t = 3;        // flange above the rim (7 .. 10)

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower hemisphere)
    translate([0, 0, bowl_t])
        difference() {
            sphere(r = bowl_r);
            translate([0, 0, -overlap])
                sphere(r = bowl_r - bowl_t + overlap);
        }

    // Flange continuing above the rim
    translate([0, 0, bowl_h])
        difference() {
            cylinder(r = bowl_r + 4, h = flange_t);
            translate([0, 0, -overlap])
                cylinder(r = bowl_r + 2, h = flange_t + overlap);
        }

    // Flat handle, top face flush with flange top (z = 13)
    translate([handle_x0, -handle_w / 2, bowl_h + flange_t - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
