// Measuring scoop for powders: bowl (half hollow sphere) + flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), opening upward.

$fn = 96;

// ---- Bowl ----
bowl_outer_radius = 10;    // outer radius of spherical bowl
bowl_wall         = 2;     // wall thickness
bowl_rim_z        = 10;    // z of rim (top of outer hemisphere)
bowl_bottom_z     = 0;     // z of bowl bottom (south pole)

// ---- Handle ----
handle_length    = 102;    // length along X (x = 8 to x = 110)
handle_width     = 12;     // width along Y
handle_top_z     = bowl_rim_z; // handle top face flush with rim
handle_thick     = 3;      // handle thickness (z = 7 to 10)

// ---- Misc ----
eps = 0.5;                 // cutter overshoot past faces

// Derived
bowl_inner_radius = bowl_outer_radius - bowl_wall;

module bowl() {
    // Lower half of hollow sphere: outer shell down to equator,
    // inner cavity from equator up to north pole (through thin rim)
    difference() {
        translate([0, 0, bowl_bottom_z])
            hull() {
                for (a = [0 : 90] )
                    translate([bowl_outer_radius * cos(a), 0,
                               bowl_bottom_z + bowl_outer_radius * sin(a)])
                        sphere(r = bowl_outer_radius, $fn = 96);
            }
        translate([0, 0, bowl_rim_z - eps])
            hull() {
                for (a = [0 : 90])
                    translate([bowl_inner_radius * cos(a), 0,
                               bowl_bottom_z + bowl_inner_radius * sin(a)])
                        sphere(r = bowl_inner_radius, $fn = 96);
            }
    }
}

module handle() {
    translate([8, -handle_width / 2, handle_top_z - handle_thick])
        cube([handle_length, handle_width, handle_thick]);
}

union() {
    bowl();
    handle();
}
