// Measuring scoop for powders
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

$fn = 96;

// ---- Bowl ----
outer_radius   = 10;    // outer radius of spherical bowl
wall_thickness = 2;     // wall thickness (lower half only)
bowl_center_z  = 10;    // z of sphere centre (rim at z = 10)

// ---- Handle ----
handle_length  = 102;   // X length of handle (x = 8 to x = 110)
handle_width   = 12;    // Y width of handle
handle_thick   = 3;     // Z thickness of handle
handle_top_z   = 7;     // handle top face height (flush with rim interior)

// ---- Helpers ----
eps    = 0.5;           // cutter overshoot past faces
x0     = 8;             // handle start X
union_ = union;          // cleaner scope for repeated unions

module lower_hollow_sphere() {
    hull() {
        for (a = [0, 90])
            rotate([0, 0, a])
                translate([0, -outer_radius, 0])
                    cylinder(r = outer_radius, h = wall_thickness, $fn = 96);
    }
    // remove the upper half of the volume, leaving a solid lower half
    difference() {
        translate([0, 0, bowl_center_z])
            sphere(r = outer_radius);
        translate([0, 0, bowl_center_z - eps])
            sphere(r = outer_radius + 2 * eps);
    }
}

module straight_handle() {
    translate([x0, -handle_width / 2, handle_top_z])
        cube([handle_length, handle_width, handle_thick]);
}

module lower_bowl() {
    // thin floor under the hemispherical shell so the part rests on z = 0
    difference() {
        translate([-(outer_radius + 1), -1, 0])
            cube([2 * outer_radius + 2, 2, 1]);
        translate([0, 0, 1])
            sphere(r = wall_thickness + 1);
    }
}

union_([lower_hollow_sphere(), straight_handle(), lower_bowl()]);
