            difference() {
                sphere(r = bowl_outer_r);
                translate([0, 0, -eps])
                    sphere(r = bowl_outer_r - bowl_wall);
            }
        // Hull between a disc at z = 6 and a disc at z = 18,
        // centred on the origin in X and Y
