        // Bowl: lower half of a hollow sphere, centred at (0, 0, 10)
        translate([0, 0, 10 - bowl_r])
            difference() {
                sphere(r = bowl_r);
                translate([0, 0, -eps])
                    sphere(r = bowl_r - bowl_wall);
            }

        // Handle: flat plate, top face flush with the rim (z = 10)
        translate([handle_x0, -handle_w / 2, 10 - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Ghost cut: clears the upper half of the sphere and any overlap into +X,
    // so the bowl stays strictly in its lower half.
    translate([0, 0, 10 + eps])
        difference() {
            sphere(r = bowl_r + eps);
            translate([-eps, -eps, -eps])
                cube([eps, 2 * (bowl_r + eps), 2 * (bowl_r + eps)]);
        }
