// Measuring scoop for powders
// Print orientation: bowl bottom touching bed (z = 0), handle extending along +X

$fn = 96;

// --- Bowl dimensions ---
bowl_outer_radius = 10;     // outer radius of spherical bowl
bowl_wall_thick   = 1.5;    // wall thickness of bowl
bowl_rim_z        = 10;     // z of bowl rim (half sphere centred at z = 10)

// --- Handle dimensions ---
handle_length   = 81.5;     // handle runs from x = 8.5 to x = 90 (length 81.5)
handle_width    = 10;       // handle width along Y
handle_top_z    = bowl_rim_z; // handle top face flush with rim
handle_thick    = 3;        // handle thickness along Z

// --- Cutting overlap ---
eps = 0.5;                  // extension past cut faces to avoid coplanar faces

difference() {
    union() {
        // Bowl: outer sphere, lower half kept
        translate([0, 0, bowl_rim_z])
            sphere(r = bowl_outer_radius);

        // Handle: flat plate along +X
        translate([8.5, -handle_width/2, handle_top_z])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Bowl cavity: inner sphere, lower half removed (opening upward)
    translate([0, 0, bowl_rim_z - eps])
        sphere(r = bowl_outer_radius - bowl_wall_thick);

    // Handle pocket: remove material below handle top face down to z = 0
    translate([8.5, -handle_width/2, 0])
        cube([handle_length + eps, handle_width, handle_top_z - eps]);
}
