    // rotate([90,0,0]) turns the 2D (r, y) plane into (y, z), then extrude along X
    rotate([90, 0, 0])
        linear_extrude(height = ring_radius * 2)
            circle(d = cross_section, center = [0, ring_radius]);

    // Convex ring-shaped block that removes the inner region and a little of the outside
    translate([-(ring_width / 2 + eps), -cross_section / 2 - eps, bottom_z])
