// Ring weight for flask neck in water bath
// Torus with flat cross-section, printed lying on its side

// ---------------- Parameters ----------------
cross_section_d   = 12;   // cross-section diameter (circle thickness)
ring_radius       = 30;   // radius of torus centreline
total_width       = 72;   // overall ring width (2 * ring_radius)
cross_section_h   = 6;    // cross-section height (diameter/2) -> middle plane at z = 6
cut_extra         = 0.5;  // overcut past faces for clean differences
fn_curves         = 96;   // facets for curved surfaces

// ---------------- Model ----------------
difference() {
    // Solid cylinder along Z, centred on the origin in XY
    // Radius = ring_radius + cross_section_d/2, height = ring_radius*2
    // -> ring centred on origin, resting on z = 0
    cylinder(
        r = ring_radius + cross_section_d/2,
        h = ring_radius * 2,
        $fn = fn_curves
    );

    // Central hole: axis along Z, radius = ring_radius,
    // extended past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(
            r = ring_radius,
            h = ring_radius * 2 + 2 * cut_extra,
            $fn = fn_curves
        );

    // Two horizontal cuts defining the flat cross-section
    // (top at z = 6 + cross_section_d/2, bottom at z = 6 - cross_section_d/2)
    for (dz = [-cross_section_d/2, cross_section_d/2]) {
        translate([-(ring_radius + cut_extra), 0, 6 + dz])
            rotate([90, 0, 0])
                cylinder(
                    r = cross_section_d/2,
                    h = ring_radius * 2 + 2 * cut_extra,
                    $fn = fn_curves
                );
    }
}
