    //   X = ring_r * cos(u), Y = ring_r * sin(u)  : mean circle in XY
    //   Z = ring_z0 + (cs_d / 2 + 1) * sin(v)     : cross-section profile
    // rotate([90,0,0]) maps profile y to Z and extrudes toward -Y (v = -pi/2 at bottom)
    // The extra 1 mm in the profile radius keeps the bottom above z = 0 after rotation,
    // so the cutter is clean of the bed.
    translate([0, -1, ring_z0])
        rotate([90, 0, 0])
            linear_extrude(height = ring_w)
                cylinder(d = cs_d, $fn = 96);
