// Ring weight that sits around the neck of a flask in a water bath
// Print orientation: flat on the bed, building upward in +Z

// ---------------- Parameters ----------------
cross_section_d   = 12;    // diameter of the torus cross-section (mm)
ring_center_r     = 30;    // radius of the ring's centre line (mm)
