ring_height    = ring_middle_z - ring_bottom_z;   // 6 mm
start_angle    = 0;                               // ring runs full 360 deg

// ---------------- Model ----------------
// A torus is the solid swept by a circle (cross-section) as its centre
// moves along a larger circle (centre line). The rotation axis is Z.
module ring_weight() {
    // rotate([axis, start_angle, 0]) moves the cross-section to the
    // starting position on the centre-line circle (angle 0)
    rotate([0, 0, start_angle])
        rotate([90, 0, 0])           // circle lies in the XZ plane -> sweep in +Y
            linear_extrude(height = ring_height, center = true)
                circle(r = cross_section_r, $fn = 128);

    // Centre the ring on the origin in X and Y, and place its bottom at z = 0
    translate([0, 0, ring_bottom_z])
        rotate([0, 90, 0])
            translate([0, ring_center_r, 0])
                rotate([0, 0, -start_angle])
                    linear_extrude(height = ring_height * 2, center = true)
                        circle(r = cross_section_r, $fn = 128);
}

ring_weight();
