// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len     = 40;   // plate length along X (mm)
plate_wid     = 25;   // plate width along Y (mm)
plate_thk     = 3;    // plate thickness along Z (mm)

knuckle_count = 5;    // number of knuckle segments
knuckle_len   = 8;    // length of each segment along X (mm)
knuckle_d     = 7;    // knuckle cylinder diameter (mm)
knuckle_z     = 3.5;  // knuckle axis height above bed (mm)
knuckle_y     = 12.5; // knuckle axis Y position (mm)

pin_d         = 2;    // pin hole diameter (mm)

overlap       = 0.5;  // overlap so cylinders fuse into one solid (mm)

$fn = 96;             // curve resolution

// ---------- Derived ----------
knuckle_start = -knuckle_count * knuckle_len / 2;  // first segment centre X
pitch         = knuckle_count * knuckle_len;       // overall X span of segments

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments (odd indices)
    for (i = [0 : knuckle_count - 1]) {
        if ((i + 1) % 2 == 1) {
            translate([knuckle_start + i * knuckle_len, knuckle_y, 0])
                cylinder(d = knuckle_d, h = knuckle_z + overlap);
        }
    }

    // Pin hole along the knuckle axis
    translate([0, knuckle_y, -overlap])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = pitch + 2 * overlap);
}
