            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on odd segments along +Y edge
        for (i = [knuckle_start : 2 : knuckle_end])
            translate([(i - 1) * sl - 2 * sl, plate_wid/2, plate_thk])
                cylinder(d = knuckle_d, h = knuckle_h);
