    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            x = (i + 1) * (plate_len / knuckle_count) / 2 -
                (knuckle_d / 2 + eps);
            translate([x, knuckle_y, plate_thk + knuckle_z0])
                cylinder(d = knuckle_d, h = 10); // 10 mm knuckle height
