            x = (i + 1) * (plate_len / knuckle_count) / 2 -
                (knuckle_d / 2 + eps);
            translate([x, knuckle_y, plate_thk + knuckle_z0 - eps])
                cylinder(d = pin_d, h = 10 + 2 * eps);
