// Leaf of a pin hinge
// Print orientation: flat plate on the bed (z = 0), centred on the origin in X and Y.
// All dimensions are in millimetres.

// ---------------- Parameters ----------------
plate_length   = 40;    // plate length along X
plate_width    = 30;    // plate width along Y
plate_thick    = 2.5;   // plate thickness along Z

knuckle_count  = 5;     // number of segments along the plate length
knuckle_dia    = 8;     // diameter of each round knuckle cylinder
knuckle_pitch  = plate_length / knuckle_count; // spacing between knuckle centres (8 mm)
knuckle_y      = 15;    // Y position of knuckle axis (on the +Y edge of the plate)
knuckle_z      = 4;     // height of knuckle axis above the bed

pin_dia        = 3;     // diameter of the pin hole running through each knuckle

overlap        = 0.5;   // extra length of knuckles past the plate faces to fuse solidly
$fn            = 96;    // curve resolution

// ---------------- Modules ----------------
module plate() {
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);
}

module knuckles() {
    // Odd segments: 1, 3, 5 (0-based indices 0, 2, 4)
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            translate([i * knuckle_pitch - overlap, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    difference() {
                        cylinder(d = knuckle_dia, h = plate_length + 2 * overlap);
                        translate([0, 0, 0])
                            rotate([0, 90, 0])
                                cylinder(d = pin_dia, h = plate_length + 2 * overlap);
                    }
        }
    }
}

// ---------------- Assembly ----------------
union() {
    plate();
    knuckles();
}
