knuckle_z   = 4;    // knuckle axis height above bed
knuckle_n   = 5;    // number of equal segments along X
knuckle_m   = [1, 3, 5]; // segment indices (1-based) with knuckles

// ---- Pin hole ----
pin_d = 3;

