plate_width  = 30;    // plate width along Y (mm)
plate_thick  = 2.5;   // plate thickness along Z (mm)

knuckle_d    = 8;     // knuckle cylinder diameter (mm)
knuckle_h    = 8;     // knuckle cylinder height (mm), apex at z = 4
knuckle_y    = 15;    // knuckle axis Y position (mm)
knuckle_n    = 5;     // number of equal segments along plate length
knuckle_x0   = 0;     // first segment start (mm), lower X bound

pin_d        = 3;     // pin hole diameter (mm)

eps          = 0.5;   // overshoot for clean cuts (mm)
$fn          = 128;   // resolution for curved surfaces

// ---------------- Derived ----------------
segment_w = plate_length / knuckle_n;   // 8 mm per segment
// X of each knuckle centre (1st, 3rd, 5th segments)
