    union() {
        // Base plate
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckle cylinders, axis along X, centred at y = 15, z = 4
        for (i = [0 : knuckle_n - 1])
            translate([knuckle_x(i), knuckle_y, knuckle_z = 4])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = knuckle_h, $fn = 128);
    }

    // Pin holes running along the knuckle axis through every knuckle
    for (i = [0 : knuckle_n - 1])
        translate([knuckle_x(i), knuckle_y, 0])
            rotate([0, 90, 0])
                cylinder(d = pin_d,
                         h = knuckle_h + 2 * eps,
                         center = true,
