// Pin hinge leaf
// Print orientation: plate flat on the bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 20;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments along +Y edge
knuckle_pitch  = 10;    // segment length (mm)
knuckle_dia    = 8;     // knuckle cylinder diameter (mm)
knuckle_axis_y = 10;    // Y position of knuckle axis (mm)
knuckle_axis_z = 4;     // Z height of knuckle axis (mm)

pin_dia        = 2.5;   // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X and Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge: 1st, 3rd, 5th segments
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0) {
                x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
                translate([x, knuckle_axis_y, knuckle_axis_z])
                    cylinder(d = knuckle_dia, h = 10);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
            translate([x, knuckle_axis_y, knuckle_axis_z])
                cylinder(d = pin_dia, h = 10 + 2*eps);
        }
    }
}
