```openscad
// Pin hinge - one leaf
// Print orientation: flat plate on bed (XY plane), building up in +Z

// ---------------- Parameters ----------------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 20;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness (mm)

segment_count  = 5;     // number of equal segments along +Y edge
segment_length = 10;    // length of each segment (mm)
knuckle_dia    = 8;     // knuckle cylinder diameter (mm)

pin_dia        = 2.5;   // pin hole diameter (mm)
overcut        = 0.5;   // extra length on cutting shapes past faces (mm)

$fn = 64;               // curve resolution

// ---------------- Model ----------------
difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_length/2, -plate_width/2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Knuckles on 1st, 3rd, 5th segments, axis along X at y = 10, z = 4
    for (i = [0 : segment_count - 1]) {
        // skip even segments (0, 2, 4) -> keep 1st, 3rd, 5th
        if (i % 2 == 0) continue;
        translate([-(segment_count - 1) * segment_length / 2 + i * segment_length,
                   10, 4])
            cylinder(d = knuckle_dia, h = segment_length + overcut);
    }

    // Pin hole along the same axis, through every knuckle
    translate([-(segment_count - 1) * segment_length / 2, 10, 0])
        translate([0, 0, overcut])
            cylinder(d = pin_dia, h = segment_count * segment_length + 2 * overcut);
}
