    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on 1st and 3rd segments
        for (i = [0, knuckle_count - 1])
            if (i % 2 == 0)
                translate([i * segment_len - segment_len/2,
                           knuckle_axis_y,
                           knuckle_axis_z])
                    cylinder(d = knuckle_dia, h = 8);
    }

    // Pin hole along the knuckle axis
    translate([-segment_len/2, knuckle_axis_y, -eps])
        cylinder(d = pin_dia, h = plate_length + 2*eps);
}
