// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len    = 45;    // plate length along X (mm)
plate_wid    = 30;    // plate width along Y (mm)
plate_thk    = 2.5;   // plate thickness along Z (mm)

knuckle_d    = 7;     // knuckle cylinder diameter (mm)
knuckle_y    = 15;    // knuckle axis Y position (mm)
knuckle_z    = 3.5;   // knuckle axis height above bed (mm)
knuckle_axle = 15;    // centre of each knuckle block along X (mm)
knuckle_w    = 15;    // knuckle block width along X (mm)

pin_d        = 2;     // pin hole diameter (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;             // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles: round cylinders, 1st and 3rd segments only
        for (i = [0, 2]) {
            translate([knuckle_axle[i]*15 - knuckle_w/2, knuckle_y, 0])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = knuckle_w);
        }
    }

    // Pin hole along X through every knuckle (and into the plate)
    translate([-plate_len/2 - eps, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
