```openscad
// Star-shaped indexing wheel: 5-pointed flat plate, even spacing
// Print orientation: lying flat on the bed, z = 0 upward

// ---------- Parameters ----------
star_points   = 5;    // number of points (and inner nodes)
outer_radius  = 35;   // distance of outer points from centre
inner_radius  = 17.5; // distance of inner points from centre
plate_t       = 4;    // plate thickness (z)
hole_d        = 8;    // central through-hole diameter
cut_extra     = 0.5;  // extra length on cutting shapes past faces
$fn           = 160;  // facet count for round features

// ---------- Model ----------
difference() {
    // 5-pointed star outline (joined in order: outer, inner, outer, ...)
    polygon(points = [
        for (i = [0 : star_points - 1])
            // each i is an outer point at angle 2pi*i/5;
            // its inner neighbour is at angle 2pi*(i+0.5)/5
            [
                outer_radius * cos(2 * pi * i / star_points),
                outer_radius * sin(2 * pi * i / star_points)
            ],
            [
                inner_radius * cos(2 * pi * (i + 0.5) / star_points),
                inner_radius * sin(2 * pi * (i + 0.5) / star_points)
            ]
    ])
    linear_extrude(height = plate_t) { }

    // central through hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2 * cut_extra);
}
