```openscad
// Star-shaped indexing wheel - 6-pointed flat plate
// Print orientation: flat on bed, z = 0 upward

$fn = 96;

// ---- Dimensions (mm) ----
outer_r   = 30;  // distance of outer points from centre
inner_r   = 15;  // distance of inner points from centre
points    = 6;   // number of points (outer and inner)
plate_t   = 5;   // plate thickness
hole_d    = 6;   // central through-hole diameter
overlap   = 1;   // extra length so polygon edges meet at the centre

// ---- Model ----
difference() {
    // Star outline, built with a for loop that alternates radii.
    // The loop runs for 180 degrees (points/2 steps), and each step
    // contributes two vertices: one at the outer radius and one at the
    // inner radius, so the full 360-degree polygon is formed.
    linear_extrude(height = plate_t)
