$fn            = 96;   // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline: 8 outer points (0°, 45°, ...) and 8 inner points (22.5°, ...)
    star_2d() {
        for (i = [0 : star_points - 1]) {
            angle = i * 360 / star_points;
            // every other point is an inner point, so toggle a flag
            if (i % 2 == 0)
                point_r = outer_point_r;
            else
                point_r = inner_point_r;
            polygon([
                [point_r * cos(angle), point_r * sin(angle)]
            ]);
        }
    }

    // Centre hole, extends past both faces
    translate([0, 0, -cut_extra])
        cylinder(d = center_hole_d, h = plate_thick + 2 * cut_extra);
}
