// First outer point on +X axis => angle step * (points-1)/2 centres it
start_a = -(points - 1) * 180 / (2 * points);

difference() {
    // Star outline, 1 mm below top face
    linear_extrude(height = plate_t - overcut)
        rotate([0, 0, start_a])
            polygon([
                for (i = [0 : points - 1])
                    [outer_r * cos(start_a + i * 360 / points),
                     outer_r * sin(start_a + i * 360 / points)]
                for (i = [0 : points - 1])
                    [inner_r * cos(start_a + (i + 0.5) * 360 / points),
                     inner_r * sin(start_a + (i + 0.5) * 360 / points)]
            ]);

    // Central through-hole
    translate([0, 0, -overcut])
        cylinder(d = hole_d, h = plate_t + 2 * overcut);
}
