```openscad
// Star-shaped indexing wheel - 6-pointed flat plate
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
outer_r  = 40;   // distance of outer points from centre (mm)
inner_r  = 20;   // distance of inner points from centre (mm)
points   = 6;    // number of outer/inner points
thickness = 3;   // plate thickness (mm)
hole_d   = 8;    // central hole diameter (mm)
overlap  = 0.5;  // overlap between adjacent point shapes (mm)
$fn      = 64;   // curve resolution

// ---------- Model ----------
difference() {
    // Star outline: union of outer and inner point shapes
    union() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    union() {
                        // Outer point
                        cylinder(r = outer_r, h = thickness, $fn = 64);
                        // Inner point (overlaps outer by 'overlap' mm)
                        translate([0, 0, -overlap])
                            cylinder(r = inner_r, h = thickness + 2 * overlap, $fn = 64);
                    }
        }
    }

    // Central through hole
    translate([0, 0, -overlap])
        cylinder(d = hole_d, h = thickness + 2 * overlap, $fn = 64);
}
