```openscad
// 5-pointed star indexing wheel
// Print orientation: flat on the bed, z = 0 upward

// ---------------- Parameters ----------------
outer_r  = 35;    // distance of outer points from centre (mm)
inner_r  = 17.5;  // distance of inner points from centre (mm)
n        = 5;     // number of points
t        = 3;     // plate thickness (mm)
hole_d   = 6;     // central hole diameter (mm)
overlap  = 1.5;   // extra length so inner points overlap outer ones (mm)

$fn = 96;

// ---------------- Model ----------------
difference() {
    union() {
        // Outer star outline, first point on +X axis
        for (i = [0 : n - 1])
            rotate([0, 0, i * 360 / n])
                translate([0, 0, 0])
                    linear_extrude(height = t)
                        polygon([[outer_r, 0], [0, outer_r], [0, -outer_r]]);

        // Inner points (180 deg offset, so they fall between the outer ones)
        for (i = [0 : n - 1])
            rotate([0, 0, (i + 0.5) * 360 / n])
                translate([0, 0, -overlap])
                    linear_extrude(height = t + 2 * overlap)
                        circle(r = inner_r);
    }

    // Central through hole
    translate([0, 0, -overlap])
        cylinder(d = hole_d, h = t + 2 * overlap);
}
