hole_d    = 8;    // diameter of the central through-hole
eps       = 0.5;  // overshoot for clean boolean cuts

$fn = 96;         // curve resolution

// ---------- Model ----------
difference() {
    // Two-circle "flower" profile in XY, extruded to plate_t.
    // With points = 8 and the phase offset, the 2D shape is 8-fold
    // symmetric: outer points on +X, inner points on the axes.
    rotate([0, 0, points * 180 / 360])
        linear_extrude(height = plate_t)
            circle(d = outer_r, d2 = inner_r, $fn = 2 * points);

    // Central through-hole (extends past both faces)
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}
