// ---------------- Derived ----------------
// Half-diagonal of the top face. The tapered sides follow 45-degree slopes,
// so the horizontal reach from any vertical cross-section to the sloped wall
// equals the vertical distance from that section to the top face.
top_half_diag = (pocket_size + block_top) / 2 + eps;   // outer corner at top z
pocket_half   = pocket_size / 2;

// ---------------- Model ----------------
difference() {
    // Square frustum: solid block from bottom face (z = 0) to top face (z = 25).
    // The hull connects the full bottom square to the outer corners of the top face.
    translate([-top_half_diag, -top_half_diag, block_h])
        cube([top_half_diag * 2, top_half_diag * 2, eps]);
    hull() {
        translate([-block_bottom / 2, -block_bottom / 2, 0])
            cube([block_bottom, block_bottom, block_h]);
        translate([-top_half_diag, -top_half_diag, block_h - eps])
            cube([top_half_diag * 2, top_half_diag * 2, eps]);
    }

    // Square pocket: 20 x 20 mm, 8 mm deep, centred on the top face.
    // The cutter extends eps above the top face and runs from the top
    // up to (block_h - pocket_depth), so the hole is exactly pocket_depth deep.
    translate([-pocket_half, -pocket_half, block_h - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
