```openscad
// Tapered riser block - solid square frustum with a square pocket in the top face
// Print orientation: base on the bed (z = 0), pocket facing up

$fn = 64;

// ---- Frustum dimensions ----
base_side   = 100;  // side length at z = 0
top_side    = 70;   // side length at z = 30
height      = 30;   // total height
overlap     = 0.01; // small overlap so the hull is a single solid

// ---- Pocket dimensions ----
pocket_w    = 62;   // pocket side length (X and Y)
pocket_d    = 8;    // pocket depth from the top face
eps         = 0.5;  // overshoot past the top face for a clean cut

// ---- Derived ----
bottom_half = base_side / 2;
top_half    = top_side / 2;
slope       = (bottom_half - top_half) / height;  // side slope (dX per dZ)

module frustum() {
    hull() {
        translate([-bottom_half, -bottom_half, 0])
            cube([base_side, base_side, overlap]);
        translate([-top_half, -top_half, height - overlap])
            cube([top_side, top_side, overlap]);
    }
}

module pocket_cutter() {
    // Extend the cutter above the top face along the side slope
    translate([-pocket_w / 2 - slope * eps, -pocket_w / 2 - slope * eps, height])
        cube([pocket_w + 2 * slope * eps,
              pocket_w + 2 * slope * eps,
              pocket_d + eps]);
}

difference() {
    frustum();
    pocket_cutter();
}
