```openscad
// Tapered riser block - solid square frustum with a centred square pocket
// Print orientation: bottom face on the bed (z = 0), building upward (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
riser_height    = 30;    // block height (z = 0 to z = 30)
base_side       = 100;   // bottom square side length
top_side        = 70;    // top square side length
pocket_side     = 62;    // pocket opening side length
pocket_depth    = 8;     // pocket depth from top face
cut_overlap     = 0.5;   // extra cutter length past the top face

// ---- Derived ----
pocket_floor_z  = riser_height - pocket_depth;              // floor of pocket (z = 22)
taper_per_mm    = (base_side - top_side) / riser_height;    // side contraction per mm of height

// Tolerance for self-intersection detection
eps             = 0.01;

module tapered_block() {
    // Hull of two thick plates: a full-sized base plate and a reduced top plate.
    // Their overlap defines the frustum with flat sides parallel to X and Y.
    hull() {
        translate([-base_side / 2, -base_side / 2, 0])
            cube([base_side, base_side, 3 * eps]);
        translate([-top_side / 2, -top_side / 2, riser_height - 3 * eps])
            cube([top_side, top_side, 3 * eps]);
    }
}

module square_pocket() {
    // Pyramidal pocket: walls follow the same taper as the block,
    // extended above the top face while keeping the 62 mm opening at z = 22.
    translate([-pocket_side / 2, -pocket_side / 2, pocket_floor_z])
        rotate([90, 0, 0])
            linear_extrude(height = pocket_side + 2 * cut_overlap, center = true)
                polygon([
                    [-pocket_side / 2 - cut_overlap * taper_per_mm,
                       -pocket_side / 2 - cut_overlap * taper_per_mm],
                    [ pocket_side / 2 + cut_overlap * taper_per_mm,
                       -pocket_side / 2 - cut_overlap * taper_per_mm],
                    [ pocket_side / 2 + cut_overlap * taper_per_mm,
                       pocket_side / 2 + cut_overlap * taper_per_mm],
                    [-pocket_side / 2 - cut_overlap * taper_per_mm,
                       pocket_side / 2 + cut_overlap * taper_per_mm]
                ]);
}

difference() {
    tapered_block();
    square_pocket();
}
