// Tapered riser block (square frustum) with a bevelled side and a square pocket
// Print orientation: flat bottom on the bed (z = 0), centred on origin in X/Y

// ---------------- Parameters ----------------
base_size    = 100;   // bottom face side length (mm)
top_size     = 70;    // top face side length (mm)
height       = 30;    // block height (mm)

pocket_size  = 62;    // pocket side length (mm)
pocket_depth = 8;     // pocket depth from top face (mm)

