half_ext    = bevel_r + pocket_depth;   // 10 mm outward reach of the pocket

// ---------------- Model ----------------
difference() {
    union() {
        // Full pyramid between z = 0 and z = height + bevel_r, centred on origin
        // (circle with $fn = 64 has vertices at 45 deg, so X/Y extremes are equal)
        cylinder(h = height + bevel_r, r = base_size / 2 + bevel_r, $fn = 64);

        // Squared-off top half (from z = height up to height + bevel_r)
        translate([0, 0, height])
            linear_extrude(h = bevel_r)
                square([side_len, side_len], center = true);
    }

    // Square pocket, open at the top, centred on X/Y
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overcut]);

    // Four corner through-cuts that overlap the pocket by 'overcut'
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * (side_len / 2 - half_ext),
                   sy * (side_len / 2 - half_ext),
                   -overcut])
            cube([half_ext, half_ext, height + bevel_r + 2 * overcut]);
}
