    translate([-pocket_half_ext - top_side / 2,
               -pocket_half_ext - top_side / 2,
               pocket_floor_z - half_thickness])
        cube([pocket_side + top_side,
              pocket_side + top_side,
              block_height + half_thickness]);
}

difference() {
    tapered_block();
    pocket_cutter();
