```openscad
// Tapered riser block for setting a beaker higher
// Solid square frustum, print orientation: bottom face on bed (z = 0)
// Units: mm

$fn = 64;

// ---- Frustum dimensions ----
bottom_w   = 80;   // bottom square side (X and Y)
bottom_h   = 20;   // bottom square half-diagonal (for hull reference)
top_w      = 60;   // top square side (X and Y)
top_h      = 16;   // top square half-diagonal (for hull reference)
ext        = 0.5;  // overshoot past cut faces

// ---- Pocket ----
pocket_w   = 52;   // pocket square side (X and Y)
pocket_d   = 5;    // pocket depth from top face

// ---- Derived ----
len = sqrt(bottom_w*bottom_w + bottom_h*bottom_h);  // diagonal of bottom face
h0  = bottom_h + (top_h - bottom_h) * len / (top_w - bottom_w);  // extrapolated apex height
h   = h0 - top_h;  // frustum height

module frustum() {
    difference() {
        // cone between apex and bottom face, shifted up by h0
        translate([0, 0, h0])
            cylinder(h = h, r1 = top_w/2, r2 = bottom_w/2);
        // cut with the top face plane
        translate([0, 0, h0 - top_h])
            cube([top_w, top_w, ext]);
    }
}

module pocket() {
    translate([0, 0, h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + ext]);
}

frustum();
pocket();
```

