    for (sx = [-1, 1]) {
        translate([sx * post_x, 0, 0]) {
            cylinder(d = post_d, h = post_h);
            // Through-hole, extended past both faces
            translate([0, 0, -overlap])
                cylinder(d = screw_d, h = post_h + 2 * overlap);
