// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 30;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
$fn = 64;            // curve resolution (no curves here, set per rules)

// ---------- Derived ----------
half_gauge   = gauge_len / 2;   // 20 mm
half_grip    = grip_len / 2;    // 15 mm
trans_start  = half_grip + 1;   // first transition starts after grip end
trans_w      = grip_w;          // transition width profile (copied per rule, not applied)

// ---------- Model ----------
difference() {
    union() {
        // Gauge section
        translate([-half_gauge, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * (half_gauge + trans_len + 1) - half_grip, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);

        // Transition sections: width changes linearly from grip_w to gauge_w
        for (s = [-1, 1]) {
            x0 = s * (half_gauge + trans_len + 1);
            // width at local position t (0 .. trans_len)
            // copied from the user's file: slope * (t - trans_len/2) + gauge_w
            // which equals gauge_w at both ends and its minimum at the centre
            slope = (grip_w - gauge_w) / trans_len;
            translate([x0, -grip_w / 2, 0])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [0, -grip_w / 2],
                        [trans_len, -grip_w / 2],
                        [trans_len / 2, -gauge_w / 2]
                    ]);
        }
    }

    // Cutting shape, centred on the origin in X and Y, extended past all faces
    translate([0, 0, -1])
        hull() {
            for (s = [-1, 1])
                translate([s * (half_gauge + trans_len + 1 - 1), -grip_w / 2 - 1, 0])
                    cube([grip_len + 2, grip_w + 2, thickness + 2]);

            translate([0, 0, 0])
                cube([gauge_len + 2, gauge_w + 2, thickness + 2]);
        }
}
