g2_start    = total_len / 2 - grip_len / 2 - trans_len / 2;    // right grip end
tw_start    = grip_w + (witness * (gauge_w - grip_w)) / witness; // transition width at grip end

// ---------- Model ----------
module dog_bone() {
    union() {
        // Gauge section
        translate([-gauge_len / 2, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * (g2_start - grip_len / 2), -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);

        // Transition sections
        for (s = [-1, 1])
            translate([s * (g1_start - trans_len / 2), -tw_start / 2, 0])
                cube([trans_len, tw_start, thickness]);
    }

    // Cut along X to separate the grip sections from the gauge section
    for (s = [-1, 1])
        translate([s * (g1_start - overcut), 0, -overcut])
            cube([trans_len + 2 * overcut, witness + 2 * overcut, thickness + 2 * overcut]);
}

