// ---------- Model ----------
module dogbone() {
    // Check: gauge + 2*transition + 2*grip = 40 + 30 + 30 = 100 mm
    // There is a 30 mm gap in the user's description; fill it with a
    // continuous transition so the profile is solid and well behaved.
    profile = concat(
        [for (i = [0 : grip_length - 1])
            [i * grip_width / grip_length, grip_width]],
        [for (i = [0 : transition_len])
            [(grip_length + i) * grip_width / grip_length - i * (grip_width - gauge_width) / transition_len,
             grip_width - i * (grip_width - gauge_width) / transition_len],
            // linear width change, area-preserving height change
            [(grip_length + i) * grip_width / grip_length - i * (grip_width - gauge_width) / transition_len,
             grip_width - i * (grip_width - gauge_width) / transition_len]],
        [for (i = [0 : gauge_length - 1])
            [gauge_length + transition_len + i * gauge_width / gauge_length, gauge_width]],
        [for (i = [gauge_length - 1 : -1 : 0])
            [total_length - 1 - i * gauge_width / gauge_length, gauge_width]],
        [for (i = [0 : transition_len])
            [total_length - transition_len - i * gauge_width / gauge_length,
             gauge_width + i * (grip_width - gauge_width) / transition_len]],
        [for (i = [grip_length - 1 : -1 : 0])
            [total_length - grip_length - i * grip_width / grip_length, grip_width]]
