// ---------------- Profile (seen from above) ----------------
// Points are given counter-clockwise: start with the lower edge of the
// gauge section, run along it to its upper edge, then follow the two
// grip sections and their transition zones back to the start.
profile_pts = concat(
    // Gauge section: lower edge (x from -15 to +15), then upper edge back
    [for (x = [0 : -1 : -15]) [x, -half_gauge],
     for (x = [0 : 1 : 15])    [x, -half_gauge]],
    // Left grip: lower edge (x from -45 to -15), then upper edge back
    [for (x = [-10 : -1 : -45]) [x, half_gauge],
     for (x = [-10 : 1 : 15])    [x, half_gauge]],
