    [for (x = [45 : 1 : 85])     [x, half_gauge],
     for (x = [45 : -1 : 15])     [x, half_gauge]],
    // Transition from right grip back to gauge: lower edge (x from 85 to 35)
    [for (x = [85 : -1 : 35])    [x, half_gauge]]
);

