    hull() {
        // Extrude the profile to full thickness.
        // rotate([90,0,0]) maps the 2D profile (X,Y) to (Y,Z), so the
        // extrusion axis points along -Y and the solid sits on z = 0.
        rotate([90, 0, 0])
