// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, building upward in +Z
// Positioned per user coordinates: X -60 to +60, Y -7.5 to +7.5, Z 0 to 3

// ---------------- Parameters ----------------
specimen_thickness = 3;     // part thickness (Z)
total_length       = 120;   // overall length along X (mm)

// Grip sections
grip_width         = 15;    // grip section width (Y)
grip_length        = 35;    // grip section length (X)

// Gauge section
gauge_width        = 6;     // gauge section width (Y)
gauge_length       = 30;    // gauge section length (X)

// Transition sections
transition_length  = 10;    // transition length (X) from grip to gauge

// ---------------- Derived ----------------
half_grip_w = grip_width / 2;   // 7.5
half_gauge_w = gauge_width / 2; // 3
// Check: 2*grip_len + 2*trans_len + gauge_len = 120
assert(abs(2*35 + 2*10 + 30 - 120) < 0.001, "Length mismatch in segments")

// ---------------- Model ----------------
module tensile_specimen() {
    // Outer hull of grip -> transition -> gauge -> transition -> grip
    hull() {
        for (s = [-1, 1]) {
            // Grip section
            translate([s * (total_length / 2 - grip_length), -half_grip_w, 0])
                cube([grip_length, grip_width, specimen_thickness]);

            // Transition section (width changes linearly from grip to gauge)
            // Start at grip end (x = grip_length), end at gauge end (x = -gauge_length)
            translate([s * transition_length, -half_gauge_w, 0])
                cube([transition_length, gauge_width, specimen_thickness]);
        }
    }
}

tensile_specimen();
