// ---------- Dimensions (mm) ----------
thickness    = 3;     // specimen thickness (Z)
total_length = 120;   // overall length along X
gauge_width  = 6;     // width of the narrow gauge section (Y)
gauge_length = 30;    // length of the gauge section along X
grip_width   = 15;    // width of each grip section (Y)
grip_length  = 35;    // length of each grip section along X
trans_length = 10;    // length of each transition section along X

// Derived positions
grip_start   = -(total_length / 2 + trans_length + gauge_length / 2);  // left grip start
trans_start  = -trans_length;                                           // transition start (from gauge end)

// ---------- Model ----------
union() {
    // Left grip section
    translate([grip_start, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Transition from left grip to gauge (width 15 -> 6)
    // rotate([90,0,0]) maps our 2D x -> world Y, 2D y -> world Z, extrude -> world X
    rotate([90, 0, 0])
        linear_extrude(height = trans_length)
            polygon(points = [
                [-trans_length, grip_width / 2],
                [ 0, gauge_width / 2]
            ]);

    // Gauge section
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transition from gauge to right grip (width 6 -> 15)
    rotate([90, 0, 0])
        linear_extrude(height = trans_length)
            polygon(points = [
                [0, gauge_width / 2],
                [trans_length, grip_width / 2]
            ]);

    // Right grip section
    translate([grip_start + gauge_length + trans_length * 2, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);
}
