        // Grip sections
        for (s = [-1, 1])
            translate([s * reach, -a, 0])
                cube([grip_l, grip_w, thickness]);

        // Gauge section
        translate([-gauge_l / 2, -c, 0])
            cube([gauge_l, gauge_w, thickness]);

