        for (s = [-1, 1])
            translate([s * reach - ext, 0, 0])
                rotate([90, 0, s * 90])
                    linear_extrude(height = thickness)
                        polygon([
                            [0, c - a],
                            [ext, a - c],
                            [ext, c - a],
                            [-ext, c - a],
                            [-ext, a - c],
                            [0, c - a]
                        ]);
