x_gauge_right   = total_len / 2 - grip_len - trans_len;    // 57.5
x_trans_left    = -total_len / 2 + trans_len;              // -55
x_trans_right   = total_len / 2 - trans_len;               // 55

// ---- Width at a given X (in the gauge/transition region) ----
// gauge: constant 6; transition: linear from 15 down to 6
function width_at(x) =
    if (x < x_gauge_left || x > x_gauge_right)
        grip_w
    else if (x < 0)
        grip_w - (x - x_trans_left) * (grip_w - gauge_w) / trans_len
    else
        grip_w + (x - x_trans_right) * (grip_w - gauge_w) / trans_len;

// ---------- Model ----------
difference() {
    // Plate
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([total_len, grip_w, thickness]);

    // Grip pockets, cut from the top face
    for (s = [-1, 1])
        translate([s * (total_len / 2 - grip_len), -half_grip,
                   thickness - eps])
            cube([grip_len, grip_w, eps + 1]);
