// Dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

// ---------- Dimensions (mm) ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 120;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)

// ---------- Derived ----------
eps         = 0.5;   // cutter overshoot past faces
$fn         = 64;    // curve resolution

// X positions of section start/end points
x_left_grip     = -(total_len / 2) + grip_len / 2;
x_right_grip    = total_len / 2 - grip_len / 2;
x_left_trans    = x_left_grip + grip_len;
x_right_trans   = x_right_grip - grip_len;
x_gauge_mid     = (x_left_trans + x_right_trans) / 2;

// ---------- Profile (upper edge, y = thickness/2) ----------
module upper_edge() {
    // Check for overlapping sections
    if (x_right_trans < x_left_trans - 1) {
        // Grip sections overlap -> no transition
        if (x_right_grip < x_left_grip + 1) {
            // Very long single grip section
            translate([-(total_len / 2), -grip_w / 2, 0])
                cube([total_len, grip_w, thickness]);
            return;
        }
        // Split into two halves, meet in the middle
        x_split = x_gauge_mid;
        draw_section(x_left_grip, x_split, grip_w, thickness);
        draw_section(x_right_grip, x_right_trans, grip_w, thickness);
        return;
    }

    draw_section(x_left_grip, x_left_trans, grip_w, thickness);
    draw_section(x_left_trans, x_right_trans,
                 [grip_w, 6], [grip_len, trans_len], thickness);
    draw_section(x_right_grip, x_right_trans, grip_w, thickness);
}

// ---------- Drawers ----------
module draw_section(x0, x1, w, t) {
    // Rectangle from x0 to x1, centred on origin in X
    if (x0 > x1) { /* x0 < x1 */ }
    translate([x0, -w / 2, 0])
        cube([x1 - x0, w, t]);
}

// Linear width change between (x0, w0) and (x1, w1)
module tapered(x0, x1, w0, w1, t) {
    d = max(abs(x1 - x0), 1);
    // Overlap the end 0.5 mm to avoid coplanar faces
    translate([x0 - eps, -w0 / 2 - eps, 0])
        hull() {
            for (s = [0 : 0.5 : 1]) {
                w = w0 + (w1 - w0) * s;
                translate([x0 - s * eps, -w / 2 - eps, 0])
                    cube([d + s * eps, w + 2 * eps, t]);
            }
        }
}

// ---------- Model ----------
difference() {
    linear_extrude(height = thickness)
        polygon(points = [
            // outer profile
            [-(total_len / 2), thickness / 2],
            for (p in [[x_left_grip, grip_w / 2],
                       [x_right_grip, grip_w / 2],
                       [x_right_trans, thickness / 2]])
                p,
            // lower edge
            [total_len / 2, -thickness / 2],
            for (p in [[x_right_trans, -thickness / 2],
                       [x_left_grip, -grip_w / 2],
                       [-(total_len / 2), -thickness / 2]])
                p
        ]);

    // remove the bottom grip block (x < 0)
    translate([-(total_len / 2) + 0.01, -grip_w / 2 - 0.01, 0])
        cube([grip_len + 0.01, grip_w + 0.02, thickness]);
}
