grip_offset = (total_length - gauge_length - 2*half_grip - 2*transition_length) / 2;
x0          = -total_length / 2;

// ---------- Model ----------
module dogbone() {
    difference() {
        // Outer shape
        linear_extrude(height = specimen_thickness)
            polygon(points = [
                // left grip
                for (s = [0 : 1]) [x0 - half_grip - grip_offset + s * grip_length, -grip_width / 2 + s * grip_width / 2],
                // left transition
                for (s = [0 : 1]) [x0 - grip_offset - half_grip + s * transition_length, -grip_width / 2 + s * (gauge_width - grip_width) / 2],
                // gauge section
                for (s = [0 : 1]) [x0 - gauge_length / 2 + s * gauge_length, -gauge_width / 2],
                // right transition
                for (s = [0 : 1]) [x0 + gauge_length / 2 - s * transition_length, -gauge_width / 2 + s * (grip_width - gauge_width) / 2],
                // right grip
                for (s = [0 : 1]) [x0 + half_grip + grip_offset - s * grip_length, -grip_width / 2 + s * grip_width / 2]
            ]);

        // Grip end cutouts
        for (dx = [-1, 1])
            translate([dx > 0 ? x0 + half_grip + grip_offset - cut_overlap : x0 - half_grip - grip_offset - cut_overlap,
                       -grip_width / 2 - cut_overlap, -cut_overlap])
                cube([half_grip + grip_offset + cut_overlap, grip_width + 2 * cut_overlap,
                      specimen_thickness + 2 * cut_overlap]);
    }
}

dogbone();
