    translate([-half_gauge, -w_gauge / 2, -eps])
        cube([l_gauge, w_gauge, thickness + 2 * eps]);

    // Grip sections
    for (s = [-1, 1])
        translate([s * (half_gauge + l_trans - half_grip), -w_grip / 2, -eps])
            cube([l_grip, w_grip, thickness + 2 * eps]);

