    for (s = [-1, 1]) {
        x0 = s * (half_gauge + l_trans);
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon([
                    [x0 - l_trans, -w_grip / 2],
                    [x0 - l_trans, w_grip / 2],
                    [x0, w_trans / 2],
                    [x0, -w_trans / 2]
                ]);
