a = grip_w / 2;        // grip half-width
b = gauge_w / 2;       // gauge half-width
c = transition_w / 2;  // transition half-width
L = total_len / 2;     // half total length

// ---------- Model ----------
module tensile_specimen() {
    difference() {
        // Upper half (z > 1.5)
        union() {
            for (s = [-1, 1])
                translate([s * (L - grip_len + 1), -a, 0])
                    cube([grip_len, a, thickness]);   // grip sections
            for (s = [-1, 1])
                translate([s * (L - gauge_len + 1), -c, 0])
                    cube([trans_len, c, thickness]);   // transition sections
            translate([-L + gauge_len - 1, -b, 0])
                cube([gauge_len, b, thickness]);       // gauge section
        }
        // Lower half (z < 1.5)
        mirror([0, 0, -1])
            union() {
                for (s = [-1, 1])
                    translate([s * (L - grip_len + 1), -a, 0])
                        cube([grip_len, a, thickness]);   // grip sections
                for (s = [-1, 1])
                    translate([s * (L - gauge_len + 1), -c, 0])
                        cube([trans_len, c, thickness]);   // transition sections
                translate([-L + gauge_len - 1, -b, 0])
                    cube([gauge_len, b, thickness]);       // gauge section
            }
    }
