// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // each transition zone length (X)
overlap        = 1;     // overlap between grip and transition for clean union

// ---- Derived ----
left_grip_x0   = -(total_length / 2) + grip_length;
right_grip_x0  = (total_length / 2) - grip_length;

module grip() {
    translate([-grip_length / 2, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);
}

module transition() {
    // rotate([90,0,0]) maps local Y to global X, local Z to global Y
    // linear_extrude then runs along global Z
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                [0, grip_width / 2],
                [transition_len, grip_width / 2],
                [transition_len, gauge_width / 2],
                [-transition_len, gauge_width / 2],
                [-transition_len, grip_width / 2],
                [0, grip_width / 2]
            ]);
}

module gauge_section() {
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
}

union() {
    for (s = [-1, 1])
        translate([s * (left_grip_x0 - overlap), 0, 0])
            grip();
    for (s = [-1, 1])
        translate([s * (right_grip_x0 - overlap), 0, 0])
            grip();
    for (s = [-1, 1])
        translate([s * left_grip_x0, 0, 0])
            transition();
    for (s = [-1, 1])
        translate([s * right_grip_x0, 0, 0])
            transition();
    gauge_section();
}
