```openscad
// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, builds up +Z, centred on origin in X/Y

$fn = 64;

// ---------- Dimensions ----------
specimen_thickness = 3;     // plate thickness (Z)
total_length       = 100;   // overall length along X
gauge_width        = 10;    // narrow gauge section width (Y)
gauge_length       = 30;    // gauge section length (X)
grip_width         = 20;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)
transition_length  = 10;    // each transition section length (X)
cut_extra          = 0.5;   // overshoot for cutting shapes past faces

// ---------- Derived ----------
gauge_x0      = -(total_length / 2 + transition_length);  // gauge start X
gauge_x1      = total_length / 2 - transition_length;     // gauge end X
half_grip     = grip_length / 2;                          // grip half-length (X)
half_trans    = transition_length / 2;                    // transition half-length (X)
eps           = 0.01;                                     // hull facet threshold

// ---------- Model ----------
module dogbone() {
    union() {
        // Central gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Grip sections at each end
        for (s = [-1, 1])
            translate([s * (total_length / 2 - half_grip), -grip_width / 2, 0])
                cube([grip_length, grip_width, specimen_thickness]);

        // Transition regions: width changes linearly from gauge to grip
        for (s = [-1, 1])
            hull() {
                translate([s * half_trans - gauge_x1, -gauge_width / 2])
                    circle(d = gauge_width, $fn = 64);
                translate([s * half_trans + gauge_x0, -gauge_width / 2])
                    circle(d = grip_width, $fn = 64);
            }
    }

    // Cut a small central window so the two end grips are one solid
    translate([0, 0, -cut_extra])
        linear_extrude(height = specimen_thickness + 2 * cut_extra)
            polygon([
                [-(total_length / 2 - half_grip - half_trans), -gauge_width / 2],
                [-(total_length / 2 - half_grip - half_trans), gauge_width / 2],
                [total_length / 2 - half_grip - half_trans, gauge_width / 2],
                [total_length / 2 - half_grip - half_trans, -gauge_width / 2]
            ]);
}

dogbone();
