        translate([ total_length / 2 - grip_length, -half_grip, 0])
            cube([grip_length, grip_width, specimen_thickness]);
    }
    hull() {
        // 2D hull in X/Y, extruded through thickness
        translate([-total_length / 2 - overlap, -a, 0])
            rotate([90, 0, 0])
                linear_extrude(height = specimen_thickness)
                    polygon([
                        for (sx = [-1, 1])
                            for (sy = [-a, a])
                                [sx * (total_length / 2 + overlap), sy]
                    ]);
    }
    // cut out the central gauge, leaving a 10 mm wide neck
    translate([0, half_gauge, -overlap])
        rotate([-90, 0, 0])
            linear_extrude(height = specimen_thickness + 2 * overlap)
                polygon([
                    for (tx = [-gauge_length / 2, gauge_length / 2])
                        [tx, half_gauge];
                    for (ty = [-b, b])
                        [0, ty];
