// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds upward in +Z

$fn = 64;

// ---- Dimensions (mm) ----
thickness     = 4;     // specimen thickness
total_length  = 140;   // overall length along X
gauge_width   = 8;     // narrow gauge section width (Y)
gauge_length  = 50;    // gauge section length (X)
grip_width    = 20;    // grip section width (Y)
grip_length   = 30;    // grip section length (X)
transition    = 15;    // length of each grip->gauge transition (X)
cut_extra     = 0.5;   // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    union() {
        // Gauge section (centred on origin)
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s*(gauge_length/2 + transition), -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions: width changes linearly from grip width to gauge width
        for (s = [-1, 1]) {
            x0 = s*(gauge_length/2 - transition);   // start of transition
            // Hull between the two end segments; the two neighbouring
            // blocks overlap by cut_extra so the hull is well defined.
            hull() {
                translate([x0, -grip_width/2, 0])
                    cube([transition, grip_width, thickness]);
                translate([x0 + transition, -gauge_width/2, 0])
                    cube([transition, gauge_width, thickness]);
            }
        }
    }

    // Remove the central gauge region outside the grip zones
    // (leaves only the two grip blocks and the two transition blocks)
    translate([-gauge_length/2 - transition, -gauge_width/2, -cut_extra])
        cube([gauge_length + 2*transition, gauge_width, thickness + 2*cut_extra]);
}
