// ---------- Derived ----------
half_gauge = gauge_length / 2;
// x span of gauge section
x_gauge_w   = -half_gauge + overlap .. half_gauge - overlap;
// x span of each grip section
x_grip      = [-(total_length / 2 + overlap) .. -x_gauge_w[0] - overlap,
               x_gauge_w[1] + overlap .. total_length / 2 - overlap];
// x span of transitions (between grip and gauge)
x_trans     = [-(x_gauge_w[0] + transition_len + overlap) .. -half_gauge - overlap,
               half_gauge + overlap .. x_gauge_w[1] + transition_len + overlap];

// ---------- Model ----------
module dogbone() {
    union() {
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * (total_length / 2 - grip_length + overlap),
                       -grip_width / 2, 0])
                cube([grip_length - 2 * overlap, grip_width, thickness]);

        // Transition sections (width changes linearly from grip to gauge)
        for (sx = [-1, 1]) {
            // x -> width map, extended off the board with the same slope
            function w(p) = gauge_width + (grip_width - gauge_width) *
                (p - (-half_gauge - overlap)) / transition_len;
            rotate([90, 0, sx * 90])
                linear_extrude(height = thickness)
                    polygon(points = [
                        [w(sx * (half_gauge + overlap)),      -grip_width / 2],
                        [w(sx * (half_gauge + overlap) + transition_len + overlap), -grip_width / 2],
                        [w(sx * (half_gauge + overlap) + transition_len + overlap),  grip_width / 2],
                        [w(sx * (half_gauge + overlap)),      grip_width / 2]
                    ]);
        }
    }
}

