// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, building upward in +Z

// ---------- Dimensions (mm) ----------
specimen_length = 140;   // overall length along X
thickness       = 4;     // specimen thickness (Z)

// Grip sections (outer ends)
grip_width      = 20;    // grip width (Y)
grip_length     = 30;    // grip length along X

// Gauge section (middle, narrow)
gauge_width     = 8;     // gauge width (Y)
gauge_length    = 50;    // gauge length along X

// Transition: grip -> gauge
transition_width_diff = grip_width - gauge_width;  // 12 mm total width change
transition_length     = 15;                         // length of each transition (X)

// ---------- Model ----------
difference() {
    // Union of all sections
    union() {
        // Left grip
        translate([-grip_length - transition_length, -grip_width / 2, 0])
            cube([grip_length + transition_length, grip_width, thickness]);

        // Left transition: width changes linearly from grip_width -> gauge_width
        translate([-grip_length - transition_length, -transition_width_diff / 2, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [0, 0],
                    [transition_length, 0]
                ]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right transition: width changes linearly from gauge_width -> grip_width
        translate([gauge_length / 2, -transition_width_diff / 2, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [0, 0],
                    [-transition_length, 0]
                ]);

        // Right grip
        translate([gauge_length / 2 + transition_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    }

    // Remove duplicate/overlapping faces between adjacent sections
    for (s = [-1, 1]) {
        translate([s * (gauge_length / 2 + transition_length) - 0.01, -grip_width / 2, 0])
            cube([0.02, grip_width, thickness + 1]);
    }
}
