// Flat tensile test specimen (dog bone) for printed plastic
// Units: mm. Print orientation: flat on bed, z = 0 upward.

// ---------------- Parameters ----------------
spec_thickness  = 4;     // plate thickness (Z)

total_length    = 140;   // overall length along X

gauge_width     = 8;     // width of central gauge section (Y)
gauge_length    = 50;    // length of gauge section (X)

grip_width      = 20;    // width of grip sections (Y)
grip_length     = 30;    // length of each grip section (X)

transition_len  = 15;    // length of each grip-to-gauge transition (X)
transition_w0   = 20;    // transition width at grip end (Y)
transition_w1   = 8;     // transition width at gauge end (Y)

eps             = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Derived ----------------
half_gauge = gauge_length / 2;   // gauge runs from -half_gauge to +half_gauge

// transition start positions (outer end of each grip)
trans_start = [-(half_gauge + transition_len),
                +(half_gauge + transition_len)];

// ---------------- Model ----------------
module dog_bone() {
    hull() {
        // grip blocks at each end
        for (s = [-1, 1]) {
            translate([s * (half_gauge + transition_len),
                       -grip_width / 2,
                       0])
                cube([grip_length, grip_width, spec_thickness]);
        }

        // gauge block in the middle
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, spec_thickness]);

        // transition blocks: width changes linearly from w0 to w1
        for (i = [0, 1]) {
            pos = trans_start[i];
            w(t) = transition_w0 + (transition_w1 - transition_w0) *
                           (t - pos) / transition_len;
            linear_extrude(height = spec_thickness)
                polygon(points = [
                    [pos - transition_len, -w(-transition_len + eps) / 2],
                    [pos - transition_len,  w(-transition_len + eps) / 2],
                    [pos + transition_len,  w(transition_len - eps) / 2],
                    [pos + transition_len, -w(transition_len - eps) / 2]
                ]);
        }
    }
}

