            linear_extrude(height = thickness)
                polygon(points = [
                    [x0, -grip_width / 2],
                    [x0 + transition_len, -gauge_width / 2],
                    [x0 + transition_len, gauge_width / 2],
                    [x0, gauge_width / 2]
