// Width along X in a transition (linear change from grip to gauge)
function trans_w(x) = grip_w + (gauge_w - grip_w) * (x - half_gauge) / transition_len;

outline() =
    union(
        // gauge
        translate([-half_gauge, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]),
        // grips
        for (s = [-1, 1])
            translate([s * end_x, -grip_w/2, 0])
                cube([grip_len, grip_w, thickness]),
        // transitions
        for (s = [-1, 1])
            translate([s * half_gauge, -transition_len/2, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, -transition_len/2],
                        [transition_len, -transition_len/2],
                        [transition_len, trans_w(transition_len)],
                        [0, trans_w(0)]
                    ])
    );

difference() {
    linear_extrude(height = thickness) outline();
    // cut overlapping regions so the solid is not coplanar with cuts
    for (s = [-1, 1])
        translate([s * (end_x - 1), 0, -1])
            cube([grip_len + 2, grip_w + 4, thickness + 2]);
}
