grip_length    = 30;    // grip section length (X)
transition_len = 15;    // grip-to-gauge transition length (X)

// ---- Derived ----
eps      = 0.5;         // overlap for smooth transitions
g1_start = -total_length/2 + grip_length + transition_len;
g1_end   = -total_length/2 + grip_length;
g2_start =  total_length/2 - grip_length - transition_len;
g2_end   =  total_length/2 - grip_length;

// ---- Model ----
union() {
    // Left grip
    translate([-total_length/2, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);
    // Right grip
    translate([total_length/2 - grip_length, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);
    // Gauge
    translate([-gauge_length/2, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, thickness]);
    // Transitions (overlapping grip end into gauge by eps)
    for (s = [-1, 1]) {
        x0 = s > 0 ? g2_start : g1_start;
        x1 = s > 0 ? g2_end + eps : g1_end + eps;
        // width moves linearly from grip_width at x0 to gauge_width at x1
        translate([-total_length/2, -grip_width/2, 0])
            rotate([90, 0, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [x0, (grip_width - gauge_width)/2 * (t - 0) + gauge_width/2],
                        [x1, (grip_width - gauge_width)/2 * (t - 0) + gauge_width/2]
                    ]);
    }
}
