// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on the bed, building upward in +Z
// Positioned per user coordinates: left end at x = -70, right end at x = 70

// ---------- Parameters (mm) ----------
specimen_length   = 140;   // total length along X
plate_thickness   = 4;     // thickness along Z
grip_width        = 15;    // grip section width (Y)
grip_length       = 30;    // grip section length (X)
gauge_width       = 10;    // gauge section width (Y)
gauge_length      = 50;    // gauge section length (X)
transition_length = 15;    // length of each grip -> gauge transition (X)

eps               = 0.5;   // cutter overshoot past faces

// ---------- Derived ----------
model_center = 0;
// X positions: left grip, left trans, gauge start/center/end, right trans, right grip
x_grip_w     = -model_center - grip_length - transition_length;   // -85
x_trans_start= -model_center - transition_length;                  // -70
x_trans_end  = -model_center + transition_length;                   // 70
x_gauge_center = model_center;                                      // 0

// ---------- Model ----------
difference() {
    union() {
        // Grip sections
        translate([x_grip_w, -grip_width/2, 0])
            cube([grip_length, grip_width, plate_thickness]);
        translate([ model_center + grip_length + transition_length, -grip_width/2, 0])
            cube([grip_length, grip_width, plate_thickness]);
        // Transition regions (trapezoid in XY, extruded)
        for (s = [-1, 1]) {
            translate([s * x_trans_end, -grip_width/2, 0])
                rotate([90, 0, s * 90])
                    linear_extrude(height = plate_thickness)
                        polygon(points = [
                            [0, -grip_width/2], [transition_length, -grip_width/2],
                            [transition_length, grip_width/2], [0, grip_width/2]
                        ]);
        }
        // Gauge section
        translate([x_gauge_center - gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, plate_thickness]);
    }

    // Optional through-hole, centred in the gauge section
    translate([x_gauge_center, 0, -eps])
        cylinder(d = 4, h = plate_thickness + 2*eps);
}
