x_grip_in      = grip_length + transition_len;          // grip -> transition
x_gauge        = x_grip_in + half_gauge;                // transition -> gauge
x_gauge_end    = x_gauge + half_gauge;                  // gauge -> transition
x_transition   = [x_grip_in - transition_len,           // transition -> grip
                  x_gauge_end + transition_len];

// ---------- Profile (top face) ----------
profile_pts = concat(
    // left grip
    [[-x_gauge_end - transition_len, -grip_width / 2],
     [-x_gauge_end - transition_len, grip_width / 2]],
    // left transition (width 15 -> 10)
    [for (t = [0 : transition_len / 2 : transition_len])
     [t - grip_length - transition_len,
      (grip_width - t / 2 * (grip_width - gauge_width)) / 2]],
    // gauge
    [for (x = [-half_gauge : gauge_length / (2 * $fn) : half_gauge])
     [x, gauge_width / 2]],
    // right transition (width 10 -> 15)
    [for (t = [0 : transition_len / 2 : transition_len])
     [x_gauge_end + t,
      (grip_width - t / 2 * (grip_width - gauge_width)) / 2]],
    // right grip
    [[x_gauge_end + transition_len + grip_length, -grip_width / 2],
     [x_gauge_end + transition_len + grip_length, grip_width / 2]]
);

// ---------- Model ----------
difference() {
    // plate
    linear_extrude(height = thickness)
        polygon(profile_pts);

    // optional small hole in gauge section
    translate([0, 0, -eps])
        cylinder(d = 4, h = thickness + 2 * eps);
