// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, builds upward in +Z

// ---------- Dimensions (mm) ----------
specimen_thickness = 4;     // plate thickness (Z)
total_length       = 140;   // overall length along X
gauge_width        = 10;    // narrow gauge section width (Y)
gauge_length       = 50;    // gauge section length (X)
grip_width         = 15;    // grip section width (Y)
grip_length        = 30;    // grip section length (X)
transition_length  = 15;    // each grip->gauge transition length (X)
overlap            = 0.01;  // small overlap to avoid coplanar faces

$fn = 64;

// ---------- Derived ----------
grip_inner_x = grip_length - transition_length;   // where grip width starts dropping
half_gauge   = gauge_length / 2;

// ---------- Model ----------
module specimen() {
    difference() {
        // Main body
        linear_extrude(height = specimen_thickness)
            polygon(points = [
                // left grip
                for (s = [-1, 1]) [s * (total_length / 2 - grip_inner_x - overlap), -grip_width / 2],
                // left transition
                for (t = [0 : 1 : grip_inner_x + overlap]) [t - grip_inner_x - overlap, -grip_width / 2],
                // gauge section
                for (x = [-half_gauge : 1 : half_gauge]) [x, -gauge_width / 2],
                // right transition
                for (t = [0 : 1 : -grip_inner_x - overlap]) [t + grip_inner_x + overlap, -grip_width / 2],
                // right grip
                for (s = [-1, 1]) [s * (total_length / 2 - grip_inner_x - overlap), -grip_width / 2]
            ]);

        // Central relief: a slightly larger shape, centred on origin,
        // extended past top and bottom faces so no faces are coplanar.
        translate([0, 0, -overlap])
            linear_extrude(height = specimen_thickness + 2 * overlap)
                polygon(points = [
                    [0, 0],
                    [half_gauge + overlap, gauge_width / 2 + overlap],
                    [half_gauge - overlap, gauge_width / 2 + overlap],
                    [-(half_gauge - overlap), gauge_width / 2 + overlap],
                    [-(half_gauge + overlap), gauge_width / 2 + overlap]
                ]);
    }
}

specimen();
