    translate([-total_length / 2 + half_grip - transition_len,
               -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
                [0, grip_width / 2],
                [transition_len, gauge_width / 2],
                [transition_len, -gauge_width / 2],
                [0, -grip_width / 2]
            ]);

    // right transition (gauge -> grip)
    translate([half_gauge - transition_len,
               -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
