d      = gauge_w / 2;            // gauge half-width
twist  = grip_l + 2 * trans_l;   // width-constant region length
centre = (overall - twist) / 2;  // offset of gauge centre to origin

// ---------- Model ----------
module flat_dogbone() {
    difference() {
        linear_extrude(height = thickness)
            hull() {
                translate([-overall / 2, 0]) circle(r = a);
                translate([ overall / 2, 0]) circle(r = a);
                translate([ centre - trans_l, 0]) circle(r = d);
                translate([centre + trans_l, 0]) circle(r = d);
            }

        // thin central core removed, leaving a ring in the gauge
        translate([centre - trans_l - eps, -d - eps, -eps])
            cube([twist + 2 * eps, 2 * (d + eps), thickness + 2 * eps]);
    }
}

