                 gauge_width + (grip_width - gauge_width) * x / transition_len],
            // Left grip
            for (x = [0 : grip_length : total_length / 2 - transition_len - gauge_length / 2])
                [total_length / 2 + transition_len + gauge_length / 2 - x - grip_length,
