// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 .. thickness

// ---------- Dimensions (mm) ----------
thickness      = 3;     // plate thickness
gauge_width    = 10;    // narrow section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // each grip->gauge transition length (X)
total_length   = 140;   // overall length along X

// ---------- Model ----------
module dogbone() {
    // Width profile in X: left grip -> transition -> gauge -> transition -> right grip
    profile = concat(
        [for (x = [-total_length/2, total_length/2]) [x, grip_width]],
        [for (x = [-grip_length/2, grip_length/2]) [x, grip_width]],
        [for (i = [0 : transition_len]) [
            -(half_gauge + transition_len - i),
            grip_width - (i / transition_len) * (grip_width - gauge_width)
        ]],
        [gauge_length],
        [for (i = [0 : transition_len]) [
            half_gauge + transition_len - i,
            grip_width - (i / transition_len) * (grip_width - gauge_width)
        ]],
        [for (x = [-grip_length/2, grip_length/2]) [x, grip_width]],
        [for (x = [-total_length/2, total_length/2]) [x, grip_width]]
    );

    // hull() expects (x, y) points; each width appears as a vertical segment,
    // so the hull reduces to the 2D profile extruded along Z.
    hull() {
        linear_extrude(height = thickness) profile;
    }
}

dogbone();
