difference() {
    union() {
        // Outer rim ring
        cylinder(d = wheel_d, h = wheel_t);
        translate([0, 0, -eps])
            cylinder(d = rim_d, h = wheel_t + 2 * eps);

        // Hub with axle hole
        cylinder(d = hub_d, h = wheel_t);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_t + 2 * eps);

