// Spoked wheel for a small sample cart
// Flat part, printed lying on the bed, centred on the origin

// ---------- Dimensions (mm) ----------
wheel_diameter      = 100;   // outer diameter of the wheel
wheel_thickness     = 6;     // width of the wheel (rim and spokes)
spoke_count         = 4;     // number of spokes
spoke_width         = 5;     // width of each spoke (both dimensions, since they are square)
hub_diameter        = 20;    // diameter of the central hub
axle_bore_diameter  = 6;     // diameter of the axle hole through the hub
cut_extra           = 0.5;   // extra length for cutting shapes past faces

// ---------- Derived ----------
wheel_radius        = wheel_diameter / 2;
hub_radius          = hub_diameter / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim: a ring from the edge inwards to rim_d
        cylinder(d = wheel_diameter, h = wheel_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = wheel_diameter - 2 * wheel_radius + 2 * spoke_width,
                     h = wheel_thickness + 2 * cut_extra);

        // Spokes, first one along +X, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_radius, -spoke_width / 2, 0])
                    cube([wheel_radius - hub_radius, spoke_width, wheel_thickness]);
        }

        // Hub around the axle bore
        cylinder(d = hub_diameter, h = wheel_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = axle_bore_diameter, h = wheel_thickness + 2 * cut_extra);
    }
}
