axle_d      = 8;     // axle hole diameter (mm)
spokes      = 6;     // number of straight spokes
spoke_w     = 5;     // spoke width (mm)
start_angle = 0;     // first spoke along +X axis (deg)
eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 128;   // facet count for round features

