        translate([0, 0, rim_w * 0.9])
            cylinder(d = hub_d, h = thickness - rim_w + 0.01, $fn = 64);

        // 3. Straight spokes, radially from hub to rim
        for (i = [0 : spokes - 1]) {
            a = start_angle + i * 360 / spokes;
            translate([spoke_w / 2, 0, 0])
                rotate([0, 0, a])
                    linear_extrude(height = thickness)
                        polygon([
                            [spoke_w / 2, 0],
                            [spoke_w, 0],
                            [spoke_w, hub_d / 2 + eps],
                            [spoke_w / 2, hub_d / 2 + eps + 0.01],
                            [spoke_w / 2, -hub_d / 2 - eps - 0.01],
                            [spoke_w / 2, -hub_d / 2 - eps],
                            [spoke_w, -hub_d / 2 - eps + 0.01],
                            [spoke_w / 2, -hub_d / 2 - eps + 0.01],
                        ]);
        }
    }

    // 4. Axle hole through the hub (and a little past each face)
    translate([0, 0, -eps])
