        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_d, h = wheel_width + 2 * cut_extra);

        // Spokes: radial hall-of-mars cut, centred on a radial line
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([0, 0, -cut_extra])
                rotate([0, 0, a])
                    translate([0, -spoke_w / 2, 0])
                        linear_extrude(height = wheel_width + 2 * cut_extra)
                            polygon([
                                [-(hub_r + 2 * cut_extra), -spoke_w / 2],
                                [-(hub_r + 2 * cut_extra), spoke_w / 2],
                                [hub_r + 2 * cut_extra, spoke_w / 2],
