                translate([outer_diameter / 2, 0, 0])
                    cube([rim_width, outer_diameter, wheel_thickness]);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_diameter, h = wheel_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra);
    }

    // Spokes
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_angle + i * 360 / spoke_count;
        translate([spoke_width, 0, 0])
            rotate([0, 90, a])
                cube([spoke_length, wheel_thickness, spoke_width]);
    }
}
