// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

// ---- Dimensions (mm) ----
wheel_thickness = 8;     // overall part thickness (Z)
outer_diameter  = 80;    // outer rim diameter
rim_width       = 5;     // rim width (radial)
hub_diameter    = 14;    // hub outer diameter
axle_hole       = 8;     // central axle hole diameter
spoke_count     = 5;     // number of spokes
spoke_width     = 5;     // spoke width (radial)

// ---- Derived ----
outer_r      = outer_diameter / 2;
rim_inner_r  = outer_r - rim_width;
hub_r        = hub_diameter / 2;
spoke_root_r = hub_r + 2;          // where spokes meet the hub
spoke_tips_r = outer_r - rim_width; // spoke end at rim inner surface
cut_extra    = 0.5;                // overshoot for clean cuts

$fn = 96;

difference() {
    union() {
        // Rim (torus-like ring)
        translate([0, 0, 0])
            linear_extrude(height = wheel_thickness)
                circle(d = outer_diameter, $fn = 128);

        // Spokes: first along +X, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_root_r, -spoke_width / 2, 0])
                    cube([spoke_tips_r - spoke_root_r,
                          spoke_width,
                          wheel_thickness]);
        }

        // Hub disc
        translate([0, 0, 0])
            cylinder(d = hub_diameter, h = wheel_thickness, $fn = 96);
    }

    // Axle hole through centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole, h = wheel_thickness + 2 * cut_extra, $fn = 64);
}
