// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

$fn = 96;

// --- Dimensions (mm) ---
part_thickness   = 6;    // total thickness of the wheel
outer_diameter   = 60;   // outer diameter of the rim
rim_width        = 4;    // width of the rim (radial)
hub_diameter     = 16;   // diameter of the central hub
axle_hole        = 6;    // diameter of the axle hole through the hub
spoke_count      = 4;    // number of spokes
spoke_width      = 5;    // width of each spoke (radial)
spoke_start_ang  = 0;    // angle of the first spoke (deg, 0 = +X axis)
overlap          = 0.5;  // radial overlap between spokes and rim for a clean union

// Derived
rim_inner_d = outer_diameter - 2 * rim_width;

module wheel() {
    union() {
        // Rim
        cylinder(d = outer_diameter, h = part_thickness);
        // Hub with axle hole
        translate([0, 0, -overlap])
            cylinder(d = hub_diameter, h = part_thickness + 2 * overlap,
                     $fn = 96);
        translate([0, 0, -1])
            cylinder(d = axle_hole, h = part_thickness + 2);
        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_diameter / 2 - overlap, 0, -overlap])
                rotate([0, 0, a])
                    cube([overlap, spoke_width, part_thickness + 2 * overlap]);
        }
    }
}

wheel();
