    translate([rim_outer_d / 2 - rim_width, 0, -cut_extra])
        rotate([0, 90, spoke_start_ang])
            cylinder(d = rim_width + cut_extra, h = rim_outer_d + 2 * cut_extra);

    // Hub
    translate([0, 0, 0])
        cylinder(d = hub_d, h = part_thickness);

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);

