spoke_count   = 5;     // number of spokes
spoke_w       = 4;     // width of each spoke
spoke_start   = 0;     // angle of the first spoke (deg, +X axis)
cut_extra     = 0.5;   // extra length so cutters pass through faces
$fn           = 96;    // facet count for curved shapes

