difference() {
    // Rim (ring), Hub, and Spokes as one solid
    union() {
        // Outer rim
        cylinder(d = wheel_od, h = wheel_w);
        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_d, h = wheel_w + 2 * cut_extra);
        // Spokes, radially from the hub to the rim
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([(wheel_od - hub_d) / 2 + 1,
                          spoke_w,
                          wheel_w]);
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_d, h = wheel_w + 2 * cut_extra);
