// T-shaped nut for aluminium extrusion
// Print orientation: flange flat on bed, neck pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
flange_w    = 12;   // flange width (Y)
flange_t    = 2;    // flange thickness (Z: 0..2)
neck_w      = 6;    // neck width (Y)
neck_h      = 5;    // neck top height (Z: 0..5)
screw_d     = 3.4;  // screw hole diameter
x_length    = 15;   // profile length along X
eps         = 0.5;  // cutter overshoot

// ---- Model ----
difference() {
    // Upside-down T profile
    union() {
        // Flange
        translate([-x_length/2, -flange_w/2, 0])
            cube([x_length, flange_w, flange_t]);
        // Neck
        translate([-neck_w/2, -neck_w/2, 0])
            cube([neck_w, neck_w, neck_h]);
    }

    // Central screw hole through the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
