// Positioned per the user's coordinates: x -10..10, y -7..7, z 0..7

$fn = 64;

// ---- Dimensions (mm) ----
flange_width   = 14;   // flange width along Y
flange_thick   = 3;    // flange thickness (z = 0 to 3)
neck_width     = 7;    // neck width along Y
neck_height    = 4;    // neck height above flange (z = 3 to 7)
screw_d        = 3.4;  // central screw hole diameter
length_x       = 20;   // part length along X
eps            = 0.5;  // overshoot for clean boolean cuts

difference() {
    // T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-length_x/2, -flange_width/2, 0])
            cube([length_x, flange_width, flange_thick]);
        // Centred neck
        translate([-neck_width/2, 0, flange_thick])
            cube([neck_width, 0, neck_height]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_thick + neck_height + 2*eps);
}
```

