```openscad
// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on XY plane (z = 0), neck builds upward (+Z)

// ---------------- Parameters ----------------
flange_width   = 12;   // flange width along Y (mm)
flange_thick   = 3;    // flange thickness along Z (mm), z = 0..3
neck_width     = 7;    // neck width along Y (mm), centred on flange
neck_height    = 4;    // neck height above flange top (mm), z = 3..7
screw_d        = 4.5;  // central screw hole diameter (mm)
length_x       = 20;   // part length along X (mm), centred on origin
eps            = 0.5;  // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Upside-down T profile, extruded along X
    translate([-length_x / 2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    [-flange_width / 2, 0],
                    [ flange_width / 2, 0],
                    [ flange_width / 2, flange_thick],
                    [ neck_width / 2,  flange_thick + neck_height],
                    [-neck_width / 2,  flange_thick + neck_height],
                    [-flange_width / 2, flange_thick]
                ]);

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_thick + neck_height + 2 * eps);
}
