```openscad
// T-shaped nut that slides into an aluminium extrusion slot
// Print orientation: flange flat on the bed (z = 0), neck pointing up

// ---------------- Parameters ----------------
flange_width = 14;   // flange size in Y (mm)
flange_t     = 3;    // flange thickness (mm), z = 0..3
neck_width   = 8;    // neck size in Y (mm)
neck_top_z   = 6;    // top of neck (mm)
screw_d      = 3.4;  // central screw hole diameter (mm)
length_x     = 15;   // part length along X (mm)
eps          = 0.5;  // cutter overshoot past faces (mm)

$fn = 64;            // curve resolution

// Derived
neck_h = neck_top_z - flange_t;   // neck height above flange (3 mm)
overlap = 0.01;                   // small overlap so neck fuses with flange

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: 14 wide (Y) x 15 long (X), z = 0..3
        translate([-length_x/2, -flange_width/2, 0])
            cube([length_x, flange_width, flange_t]);

        // Neck: 8 wide (Y), centred, runs from z = 2.99 to z = 6
        translate([-neck_width/2, -neck_width/2, flange_t - overlap])
            cube([neck_width, neck_width, neck_h + overlap]);
    }

    // Vertical screw hole through the whole part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
