// Anti-vibration foot for benchtop instrument
// Print orientation: flat on bed, recess facing down

// ---- Dimensions (mm) ----
bottom_d     = 40;   // frustum diameter at z = 0
top_d        = 30;   // frustum diameter at z = 12
height       = 12;   // frustum height
recess_d     = 34;   // rubber pad recess diameter
recess_depth = 3;    // rubber pad recess depth
screw_d      = 5.5;  // central screw hole diameter
eps          = 0.5;  // cutter overshoot past faces

$fn = 128;

difference() {
    // Truncated cone, centred on Z axis
    cylinder(d1 = top_d, d2 = bottom_d, h = height);

    // Round recess in bottom face for rubber pad
    translate([0, 0, -eps])
        cylinder(d = recess_d, h = recess_depth + eps);

