// Stiffened cover panel
// Print orientation: flat on bed, ribs pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_len     = 100;   // plate length (X)
plate_wid     = 80;    // plate width (Y)
plate_thk     = 2;     // plate thickness (z = 0..2)

rib_count     = 3;     // number of ribs
