rib_height    = 5;     // rib total height (z = 0..5)
rib_centre_sp = 25;    // centre-to-centre spacing of ribs
rib_outer_off = 25;    // distance of outer rib centres from plate ends

overlap       = 0.01;  // small overlap so ribs fuse into the plate

// ---- Model ----
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running the full width along Y
    for (i = [0 : rib_count - 1]) {
        x = (i < rib_count - 1) ? rib_outer_off + i * rib_centre_sp : -plate_len/2 + rib_thk/2;
        translate([x - rib_thk/2, -plate_wid/2, 0])
            cube([rib_thk, plate_wid, rib_height]);
    }
}
