```openscad
// Stiffened cover panel - flat plate with 5 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_count   = 5;     // number of ribs
rib_thk     = 3;     // rib thickness along X (mm)
rib_hgt     = 4;     // rib height above plate (mm), z = 2..6
rib_pitch   = 20;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 20;    // distance of outer rib centres from plate ends (mm)

eps         = 0.01;  // small overlap for clean boolean fusion (mm)

$fn = 64;            // curve resolution (set per rules, no curves used)

// ---------------- Derived ----------------
plate_x0 = -plate_len/2;   // plate left end
plate_x1 = plate_len/2;    // plate right end

// Rigidly position the ribs on the plate using overlap 'eps'
// (same Y window for both, so the union is one solid)
module positioned_ribs() {
    for (i = [0 : rib_count - 1]) {
        x_c = (i < rib_count/2) ? -rib_offset + (i + 1)*rib_pitch :
              rib_offset - (rib_count - 1 - i)*rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - eps])
            cube([rib_thk, plate_wid, rib_hgt + eps]);
    }
}

// ---------------- Model ----------------
union() {
    // Base plate
    translate([plate_x0, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs
    positioned_ribs();
}
