// Powder measuring scoop
// Units: mm. Print orientation: handle along +X, bowl end at x = 90.

$fn = 64;

// ---- Handle ----
handle_w     = 12;    // handle width (Y)
handle_t     = 4;     // handle thickness (Z)
handle_x0    = 8;     // handle start (X)
handle_x1    = 90;    // handle end (X)
handle_top_z = 6;     // handle top face height (Z)

// ---- Bowl ----
bowl_r       = 10;    // outer bowl radius
bowl_wall    = 2;     // bowl wall thickness
bowl_end_x   = 90;    // bowl end point (X)
bowl_rim_z   = 10;    // bowl rim height (Z)
eps          = 0.5;   // cut overshoot

// ---- Derived ----
inner_r      = bowl_r - bowl_wall;   // inner radius at end (X)
total_l      = handle_x1 - handle_x0; // handle length (X)

module handle() {
    translate([handle_x0, -handle_w/2, 0])
        cube([total_l, handle_w, handle_t]);
}

module bowl() {
    // Hull of a profile drawn in (X, Y), extruded along Z, then
    // shifted so the rim sits at z = bowl_rim_z.
    translate([0, -bowl_r, 0])
        rotate([90, 0, 0])
            hull() {
                for (s = [0, 1]) {
                    x = handle_x0 + s * total_l;
                    y = (s < 0.5 ? -bowl_r : bowl_r) + s * (bowl_r + inner_r);
                    translate([x, 0, 0])
                        circle(d = y < 0 ? bowl_r : inner_r);
                }
            }
        translate([0, 0, bowl_rim_z]);

    // Cut out the hollow, extend past the rim and the end wall
    translate([handle_x0, -bowl_r, -eps])
        rotate([90, 0, 0])
            linear_extrude(height = total_l + 2*eps, center = true)
                circle(d = y < 0 ? bowl_r + 2*eps : inner_r + 2*eps, $fn = 64);
}

union() {
    handle();
    bowl();
}
