// Measuring scoop for powders
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

$fn = 96;

// ---- Dimensions (mm) ----
bowl_outer_radius = 12;    // outer radius of spherical bowl
bowl_wall         = 2;     // bowl wall thickness
bowl_rim_z        = 12;    // z of bowl rim (outer surface)
handle_width      = 8;     // handle width along Y
handle_thick      = 3;     // handle thickness along Z
handle_start_x    = 10;    // handle start point along X
handle_end_x      = 112;   // handle end point along X
embed_depth       = 0.5;   // handle overlap into bowl rim for a clean union

// ---- Derived ----
bowl_inner_radius = bowl_outer_radius - bowl_wall;

module bowl() {
    // Lower half of a hollow sphere, centred at (0, 0, bowl_rim_z)
    translate([0, 0, bowl_rim_z])
        difference() {
            cylinder(h = bowl_rim_z, r = bowl_outer_radius);
            translate([0, 0, -bowl_wall])
                cylinder(h = bowl_rim_z + 2 * bowl_wall, r = bowl_inner_radius);
        }
}

module handle() {
    translate([handle_start_x, -handle_width / 2, 0])
        cube([handle_end_x - handle_start_x + embed_depth,
              handle_width,
              handle_thick]);
}

union() {
    bowl();
    handle();
}
