// Measuring scoop for powders
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

$fn = 96;

// ---- Bowl ----
outer_radius   = 12;    // outer radius of hemisphere (mm)
wall_thickness = 1.5;   // wall thickness (mm)
rim_radius     = outer_radius + wall_thickness;  // radius at rim (mm)
bottom_z       = 0;     // bowl bottom height (mm)

// ---- Handle ----
handle_width   = 8;     // handle width along Y (mm)
handle_thick   = 4;     // handle thickness along Z (mm)
handle_x0      = 10.5;  // handle start along X (mm)
handle_x1      = 112;   // handle end along X (mm)
