// ---- Cutting overlap ----
eps            = 0.5;   // extension past cut faces (mm)

difference() {
    union() {
        // Lower half of hollow sphere: bowl with open top
        translate([0, 0, bottom_z])
            difference() {
                cylinder(r = outer_radius, h = outer_radius + 0.01);
                translate([0, 0, 0.01])
                    cylinder(r = outer_radius - wall_thickness,
                              h = outer_radius + 0.01 + eps);
            }

        // Flat handle along +X
        translate([handle_x0, -handle_width / 2, handle_top_z - handle_thick])
            cube([handle_x1 - handle_x0, handle_width, handle_thick]);
    }

    // Remove the upper portion of the sphere above z = rim_z - eps,
    // so the bowl opens upward with its rim at z = rim_z
    translate([0, 0, rim_z - eps])
        cylinder(r = rim_radius + eps, h = eps + 1);
}
