handle_len    = handle_x1 - handle_x0;           // handle length along X
rim_z         = outer_radius;                    // rim height (same as sphere centre)

// ---------------- Model ----------------
union() {
    // Bowl: lower half of a hollow sphere.
    // The cut is made at z = rim_z + cut_margin, so the lower half includes the rim.
    translate([0, 0, 0])
        difference() {
            // Outer shell of the sphere, from bottom up to z = 12.5
            cylinder(r = outer_radius, h = outer_radius + cut_margin, $fn = 128);

            // Empty inner space, from z = 12.5 up to z = 24.5 (extends past the bottom)
            translate([0, 0, rim_z + cut_margin])
                cylinder(r = inner_radius, h = outer_radius + 2 * cut_margin, $fn = 128);
        }

    // Flat handle running along +X from x = 10.5 to x = 112
    translate([handle_x0, handle_y0 - handle_width / 2, rim_z - handle_thick])
        cube([handle_len, handle_width, handle_thick]);
}
