// Powder measuring scoop
// Print orientation: handle horizontal along +X, bowl hanging below the rim.
// Placed at the user's coordinates (handle x = 10.5..112, y = -4..4) instead of being centred on the origin.

// ---------- Parameters ----------
bowl_od     = 12;    // outer diameter of the spherical bowl (mm)
bowl_wall   = 1.5;   // bowl wall thickness (mm)
rim_z       = 12;    // z height of the bowl rim (mm)
handle_w    = 8;     // handle width in Y (mm)
handle_t    = 4;     // handle thickness in Z (mm)
handle_x0   = 10.5;  // handle start in X (mm)
handle_x1   = 112;   // handle end in X (mm)
overlap     = 0.5;   // overlap between bowl and handle for a clean union (mm)

$fn = 96;            // curve resolution

// ---------- Derived ----------
bowl_r = bowl_od / 2;
// bowl_span is the length of the bowl in X and Y (a square that circumscribes the sphere)
bowl_span = sqrt(2) * bowl_r;

// ---------- Model ----------
union() {
    // Bowl: a slice through a sphere centred at (0, 0, rim_z), kept below the rim.
    // rotate([90,0,0]) maps the sphere's Z to world Y, so hull() spans rim_z - bowl_r .. rim_z.
    rotate([90, 0, 0])
        hull() {
            translate([-bowl_span, -bowl_span, rim_z - bowl_wall])
                cube([bowl_span * 2, bowl_span * 2, bowl_wall]);   // outer shell
            translate([-bowl_r, -bowl_r, rim_z - overlap])
                cube([bowl_r * 2, bowl_r * 2, overlap]);           // solid core (no hole)
        }

    // Flat handle running along +X
    translate([handle_x0, -handle_w / 2, 0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
