// Powder measuring scoop
// Print orientation: handle flat on bed, top face flush with bowl rim

// ---------------- Parameters ----------------
bowl_r      = 12;    // outer radius of spherical bowl (mm)
bowl_t      = 1.5;   // bowl wall thickness (mm)
handle_w    = 12;    // handle width along Y (mm)
handle_t    = 3;     // handle thickness along Z (mm)
handle_x0   = 10.5;  // handle start position along X (mm)
handle_x1   = 72;    // handle end position along X (mm)
overlap     = 0.5;   // handle overlap into bowl for a clean union (mm)

// Derived values
bowl_vestibule_r = bowl_r + bowl_t;   // radius of the open top of the bowl
handle_top_z    = bowl_vestibule_r;   // height of handle top face (flush with rim)

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half only, opening upward
    translate([0, 0, bowl_vestibule_r])
        difference() {
            sphere(r = bowl_vestibule_r);
            translate([0, 0, bowl_t])
                sphere(r = bowl_r);
        }
    // Scale the sphere down by 0.01 so its vertices do not coincide with
    // the cutting shapes. This avoids coplanar faces and possible errors.
    translate([0, 0, -bowl_t])
        sphere(r = bowl_vestibule_r - 0.01);

    // Straight flat handle along +X
    translate([handle_x0, -handle_w / 2, 0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

// ---------------- Modules ----------------
module sphere(r, h) {
    linear_extrude(height = h)
        circle(r = r);
}
