// Ring weight that sits around the neck of a flask in a water bath
// Print orientation: flat on bed, middle plane at z = 4

// ---- Dimensions (mm) ----
tube_d      = 8;    // tube (cross-section) diameter
ring_radius = 28;   // radius of the ring (centre of tube on this circle)
cut_extra   = 0.5;  // overshoot for clean boolean cuts

$fn = 96;

difference() {
    // Torus: tube along Z, axis on circle of radius ring_radius in XY
    translate([ring_radius, 0, 0])
        rotate([0, 90, 0])
            cylinder(d = tube_d, h = ring_radius * 2 + tube_d);

    // Outer block that holds the tube (radius 32, height 12)
    translate([0, 0, -cut_extra])
        cylinder(r = 32, h = tube_d + 2 * cut_extra);

    // Cut out the tube and its neighbours, leaving a single ring
    for (a = [0 : 15 : 360])
        rotate([0, 0, a])
            translate([ring_radius - cut_extra, -cut_extra, -cut_extra])
                cube([(ring_radius - cut_extra) * 2 + tube_d,
                      tube_d + cut_extra,
                      tube_d + 2 * cut_extra]);
}
