```openscad
// Ring weight for a flask neck, printed flat in a water bath
// Units: mm. Coordinates follow the user's spec (not centred).

$fn = 96;

// --- Dimensions ---
cs_d      = 8;     // cross-section diameter
ring_r    = 28;    // radius of the centre-circle (on Z)
ring_w    = 64;    // overall across diameter
mid_z     = 4;     // z of the cross-section's centre plane
eps       = 0.5;   // cutter overshoot past faces

// --- Derived ---
cs_r = cs_d / 2;
// hull outer radius = ring_r + cs_r ; check against ring_w (64)

module ring_weight() {
    difference() {
        // Solid body: hull of two vertical end-discs
        hull() {
            translate([-ring_r - cs_r, 0, mid_z])
                cylinder(d = cs_r, h = ring_w, $fn = 96);   // note: $fn controls X/Y resolution
            translate([ ring_r + cs_r, 0, mid_z])
                cylinder(d = cs_r, h = ring_w, $fn = 96);
        }
        // Flat cutters below and above the middle plane
        translate([-(ring_r + cs_r) - eps, -eps, -eps])
            cube([2 * (ring_r + cs_r) + 2 * eps, 2 * eps, ring_w + 2 * eps]);
        translate([-(ring_r + cs_r) - eps, [ring_r + cs_r] + eps, -eps])
            cube([2 * (ring_r + cs_r) + 2 * eps, 2 * eps, ring_w + 2 * eps]);
    }
}

ring_weight();
```

