    // Solid body: a torus lying flat on the bed, centred on the Z axis
    // rotate([90,0,0]) maps the default Z axis of the torus onto the bed's X axis,
    // so the cross-section spans Y and Z and the ring rests on z = 0
    rotate([90, 0, 0])
        cylinder(r = ring_centre_radius, h = ring_width, $fn = 96);

