// rotated around that axis so its cross-section circle lies in the XY plane.
// The cylinder's height becomes the ring width.
difference() {
    // Torus body
    rotate([0, 90, 0])
        cylinder(r = cross_section_r, h = ring_width, $fn = 96);

    // Cutting shapes: one at the top, one at the bottom.
