    // radius is cross_section_r. The cylinder spans z = -cross_section_r
    // to z = +cross_section_r (middle plane at z = 0).
    translate([ring_radius, 0, 0])
        rotate([0, 90, 0])
            cylinder(h = ring_radius + cut_extra, r = cross_section_r);

    // The region between the two faces of the torus (from z = -cross_section_r
    // up to z = cross_section_r - cut_extra), centred on the Z axis.
    // This leaves a solid shell of thickness cross_section_d.
    translate([0, 0, -cross_section_r])
        difference() {
            cylinder(h = ring_radius + 2 * cut_extra + 1);
            translate([0, 0, cross_section_r - cut_extra])
                cylinder(h = ring_radius + 2 * cut_extra + 1);
