ring_r     = 35;   // ring radius (distance from Z axis to tube centre)
ring_d     = 80;   // ring diameter (2 * ring_r), check: 80 mm across
middle_z   = 5;    // height of the middle plane of the torus
bottom_z   = 0;    // z = 0 is the lowest point of the tube

// ---------- Derived ----------
outer_r    = ring_r + tube_r;   // distance from Z axis to tube outer edge
inner_r    = ring_r - tube_r;   // distance from Z axis to tube inner edge
tube_h     = tube_d;            // tube height, used as extrusion length

// ---------- Model ----------
// A circle drawn in the XY plane at z = middle_z, extended along Z.
// The lower half (below the middle plane) forms the flat bottom face,
// and the side walls run from z = 0 up to z = tube_d.
module ring_weight() {
    translate([0, 0, bottom_z])
        hull() {
            for (a = [0 : 1 : 360]) {
                rotate([0, 0, a])
                    translate([ring_r, 0, 0])
                        linear_extrude(height = tube_h)
                            circle(r = tube_r, $fn = 96);
            }
        }
}

ring_weight();
