// Ring weight that sits around the neck of a flask in a water bath.
// Print orientation: flat on the bed, middle plane at z = 5.
// A torus with a 10 mm round cross-section sweeping around the Z axis
// on a circle of radius 35 mm (80 mm across).

// ---------------- Parameters ----------------
cross_section_d = 10;    // diameter of the torus cross-section (10 mm)
ring_radius     = 35;    // radius of the circle the cross-section centre sweeps (35 mm)
middle_z        = 5;     // z height of the torus middle plane
cut_margin      = 0.5;   // extra length on cutting shapes to avoid coplanar faces

$fn = 128;               // facet count: 64 per circle x 2 axes = 128

// ---------------- Derived ----------------
cross_section_r = cross_section_d / 2;            // 5 mm cross-section radius
ring_d          = 2 * ring_radius;                // 80 mm overall diameter
ring_h          = cross_section_d;                // height equals cross-section diameter
lower_z         = middle_z - cross_section_r;     // underside touches z = 0
upper_z         = middle_z + cross_section_r;     // top at z = 10

// ---------------- Model ----------------
difference() {
    // The torus: a cylinder whose axis runs along a circle around Z
    rotate([0, 90, 0])
        cylinder(h = ring_d, r = cross_section_r, $fn = 128);

    // A straight cylinder along Z that carves out the hole and extends
    // past both the underside (z = 0) and the top (z = 10) by 'cut_margin'
    translate([0, 0, -cut_margin])
        cylinder(h = ring_h + 2 * cut_margin,
                 r = ring_radius + cut_margin,
                 $fn = 128);
}
