```openscad
// Pin hinge leaf
// Flat plate on the bed, centred on the origin in X and Y.
// Knuckles run along X at the +Y edge; a pin hole goes through each.

// ---------------- Parameters ----------------
plate_len    = 40;    // plate length (X)
plate_wid    = 20;    // plate width (Y)
plate_t      = 2.5;   // plate thickness (Z)

knuckle_d    = 6;     // knuckle diameter
knuckle_h    = 10;    // knuckle height above bed
knuckle_z    = 3;     // knuckle axis Z position
knuckle_n    = 5;     // number of knuckle segments
knuckle_pitch = plate_len / (knuckle_n - 1);  // 8 mm segment length
knuckle_m    = 3;     // knuckles per leaf (1st, 3rd, 5th)

pin_d        = 2.5;   // pin hole diameter

eps          = 0.5;   // cutter overshoot past faces
$fn          = 96;    // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_t]);

        // Knuckles along +Y edge
        for (i = [0 : knuckle_m - 1]) {
            x = (i - (knuckle_m - 1) / 2) * knuckle_pitch;
            translate([x, plate_wid/2, 0])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = $fn);
        }
    }

    // Pin hole along the knuckle axis
    translate([0, plate_wid/2, -eps])
        cylinder(d = pin_d, h = knuckle_h + 2*eps, $fn = $fn);
}
