// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_h   = 6;     // knuckle height above plate
knuckle_z   = 3;     // knuckle axis Z height
knuckle_xs  = [-16, -8, 0, 8, 16]; // segment centre X positions (8 mm pitch)
knuckle_ids = [1, 3, 5];    // 1st, 3rd, 5th segments have knuckles

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, sitting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st, 3rd, and 5th segments
        for (id = knuckle_ids) {
            x = knuckle_xs[id - 1];
            translate([x, 10, 0])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = 64);
        }
    }

    // Pin hole along X through every knuckle
