// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_len   = 60;    // plate length (X)
plate_wid   = 30;    // plate width (Y)
plate_t     = 3;     // plate thickness (Z)

knuckle_d   = 7;     // knuckle diameter
knuckle_h   = 10;    // knuckle height above plate (y = 15 to top face)
knuckle_z0  = 3.5;   // knuckle axis height (Z)

pin_d       = 2.5;   // pin hole diameter

segment_w   = 12;    // hinge segment width (X)
num_segs    = 5;     // total segments
active_seg  = [1, 3, 5]; // knuckle segments (1-based)

eps         = 0.5;   // cutter overshoot

// ---- Model ----
difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_t]);

        // Knuckles
        for (i = 0; i < num_segs; i++) {
            x = -plate_len/2 + i * segment_w;
            if (index_to_seg(i) in active_seg)
                translate([x, plate_wid/2, 0])
                    cylinder(d = knuckle_d, h = knuckle_h, $fn = 64);
        }
    }

    // Pin hole along X through active knuckles
    for (i = 0; i < num_segs; i++) {
        x = -plate_len/2 + i * segment_w;
        if (index_to_seg(i) in active_seg)
            translate([x, plate_wid/2, -eps])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = plate_len + 2*eps, $fn = 64);
    }
}

// Helper: map 0..4 to 1..5
function index_to_seg(i) = i + 1;
