// Pin hinge leaf
// Print orientation: flat plate on the bed (z = 0), centred on the origin in X and Y.
// The plate runs along X; the hinge axis runs along X at y = plate_w/2 (the +Y edge).

$fn = 96;

// ---------------- Plate ----------------
plate_len   = 60;   // plate length along X
plate_w     = 30;   // plate width along Y
plate_t     = 3;    // plate thickness along Z

// ---------------- Knuckles (cylinders) ----------------
knuckle_d      = 8;     // knuckle diameter (plate thickness = 6 mm)
knuckle_h      = 16;    // knuckle height above the plate top surface
knuckle_pitch  = 20;    // centre-to-centre spacing along X
knuckle_start  = -10;   // X position of the first knuckle
knuckle_count  = 3;     // total knuckles on the hinge line

// ---------------- Pin hole ----------------
pin_d      = 3;     // pin hole diameter
pin_clear  = 0.5;   // extra length so the hole passes through every knuckle

// Derived values
plate_top_z = plate_t;
knuckle_x0  = knuckle_start;

// Check: 3 * 20 = 60, so the last knuckle is at x = 30, which is the edge of the plate.
plate_check = plate_len - knuckle_pitch * (knuckle_count - 1) - plate_w / 2; // 30 mm
module plate() {
    translate([-plate_len / 2, -plate_w / 2, 0])
        cube([plate_len, plate_w, plate_t]);
}

module knuckle(x_pos) {
    translate([x_pos, plate_top_z, 0])
        cylinder(d = knuckle_d, h = knuckle_h);
}

// ---------------- Assembly ----------------
difference() {
    union() {
        module plate();
        for (i = [0 : knuckle_count - 1]) {
            translate([knuckle_x0 + i * knuckle_pitch, 0, 0])
                knuckle(0);
        }
    }

    // Pin holes along the hinge axis through every knuckle
    translate([knuckle_x0, plate_top_z, -pin_clear])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_h + 2 * pin_clear);
}
