knuckle_d      = 6;   // knuckle cylinder diameter (mm)
knuckle_axis_y = 10;  // knuckle axis Y position (mm)
knuckle_n      = 5;   // number of segments along X
knuckle_pitch  = 12;  // segment length along X (mm)
knuckle_offset = 0;   // segment 0 start offset (mm)
knuckle_h      = 3;   // knuckle height above plate top (mm)

// ---------------- Pin hole ----------------
pin_d = 2;   // pin hole diameter (mm)

// ---------------- Helpers ----------------
cut_ext = 0.5;   // extra length on cutters to avoid coplanar faces (mm)

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    // Run over all segments; 0, 2, 4 (1st, 3rd, 5th) carry knuckles
    for (i = [0 : knuckle_n - 1]) {
        x = knuckle_offset + i * knuckle_pitch;
        if (i % 2 < knuckle_n % 2) {   // select 0,2,4 for n=5
            translate([x, knuckle_axis_y, 0])
                cylinder(d = knuckle_d, h = plate_thk + knuckle_h);
        }
    }
}

module pin_hole() {
    // runs along X at y = 10, z = 3 through every knuckle
    translate([knuckle_offset - cut_ext, knuckle_axis_y, plate_thk])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_pitch * knuckle_n + 2 * cut_ext);
}

union() {
    plate();
    knuckles();
    pin_hole();
}
