start_a = 0;            // angle of first outer point (deg, +X axis)
step_a  = 360 / points; // angular spacing between adjacent points

// ---- Plate ----
thickness = 4;          // plate thickness (Z)
hole_d    = 6;          // central through-hole diameter

// ---- Cut clearance ----
eps = 0.5;              // overshoot for cutting shapes past faces

difference() {
    // Star outline: for each crest, travel from its base radius out to the
    // tip at 90 deg, then back in along the same line. The crests are spaced
    // by step_a and the whole pattern is rotated by start_a.
    linear_extrude(height = thickness)
        polygon([
            for (i = [0 : points - 1])
                rotate([0, 0, start_a + i * step_a])
                    union() {
                        // outer point
                        translate([inner_r, 0, 0])
                            cylinder(r = outer_r - inner_r, h = thickness, $fn = 16);
                        // inner point (a narrower crest toward the centre)
                        translate([(outer_r - 1) / 2, 0, 0])
                            cylinder(r = inner_r - (outer_r - 1) / 2, h = thickness, $fn = 16);
                    }
        ]);

    // Central through-hole, extending past both faces so no surface is coplanar
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
