hole_d  = 8;               // central through-hole diameter

// ---- Cutting overshoot ----
eps = 0.5;                 // extension of cutters past faces

// First outer point lies on +X axis; inner points are offset by 180/points degrees.
// The hull() call connects them in angular order to form the star outline.
module star_2d() {
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * pitch])
                translate([outer_r, 0, 0])
                    cube([1, 2 * inner_r, 1]);
        }
    }
}

difference() {
    // Star-shaped plate
    linear_extrude(height = plate_t)
        star_2d();

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
