            // so the outline stays at the full 35 mm radius.
            for (i = [0 : points - 1])
                rotate([0, 0, i * 360 / points])
                    translate([outer_r, 0, 0]);
        }

    // Central through-hole, extended past both faces
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra);
