```openscad
// 8-pointed star indexing wheel
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;    // distance of outer points from centre
inner_r   = 20;    // distance of inner points from centre
point_n   = 8;     // number of points (and inner points)
plate_t   = 4;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // overshoot for cutting shapes

ang0      = 0;     // angle of first outer point (deg, 0 = +X axis)
overlap   = 2;     // extra hull vertices past each end to avoid coplanar faces

$fn = 96;          // resolution for curved shapes

// ---------------- Model ----------------
module star_plate() {
    // Collect vertices of the star outline in XY
    var vertices = [ for (i = [0 : point_n - 1])
                      translate([outer_r * cos(ang0 + i * 360 / point_n),
                                 outer_r * sin(ang0 + i * 360 / point_n)]) ];
    // Every outer edge is met by an inner edge, so walk one extra outer vertex
    // and one extra inner vertex to keep the hull clean.
    for (k = [0 : overlap - 1]) {
        for (i = [point_n - 1 : -1 : 0])
            vertices.append(translate([outer_r * cos(ang0 + (i + 1) * 360 / point_n),
                                        outer_r * sin(ang0 + (i + 1) * 360 / point_n)]));
        for (i = [0 : point_n - 1])
            vertices.append(translate([inner_r * cos(ang0 + (i + 0.5) * 360 / point_n),
                                        inner_r * sin(ang0 + (i + 0.5) * 360 / point_n)]));
    }

    difference() {
        // Extrude the 2D outline, then slice off the top and bottom eps
        linear_extrude(height = plate_t)
            polygon(vertices = vertices);

        // Central through-hole
        translate([0, 0, -eps])
            cylinder(d = hole_d, h = plate_t + 2 * eps);
    }
}

star_plate();
