    [ for (i = [0 : 4])
        each [
            [inner_r * cos((i + 0.5) * 36), inner_r * sin((i + 0.5) * 36)],  // prev inner
            [outer_r * cos(i     * 36), outer_r * sin(i     * 36)],           // outer
            [inner_r * cos((i + 1.5) * 36), inner_r * sin((i + 1.5) * 36)]    // next inner
        ]
    ]
);

difference() {
    // Flat plate
    linear_extrude(height = plate_t)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2 * cut_extra, $fn = 64);
}
