// Tapered riser block with a square pocket
// Print orientation: bottom face on the bed (z = 0), builds upward

// ---------------- Parameters ----------------
block_h      = 30;    // block height (z = 0 to z = 30)
bottom_w     = 60;    // bottom face: 60 x 60 mm square
top_w        = 40;    // top face: 40 x 40 mm square
pocket_w     = 30;    // square pocket: 30 x 30 mm
pocket_depth = 5;     // pocket depth from top face
eps          = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------------- Derived ----------------
// Frustum sides slope inward by (bottom - top) / (2 * height) per mm height.
// At z = block_h - eps the side width is just over top_w, so the pocket
// sits near the top end of the hull (no internal cavities).
pocket_z0    = block_h - pocket_depth - 0.01;   // pocket bottom (below top face)
side_overlap = (bottom_w - top_w) / 2 / block_h * eps; // side slope over eps

// ---------------- Model ----------------
difference() {
    // Square frustum: hull between full bottom and top faces
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, 0])
            cube([bottom_w, bottom_w, block_h]);
        translate([-top_w / 2, -top_w / 2, top_w / 2])
            cube([top_w, top_w, block_h - top_w / 2 + 0.01]);
    }

    // Square pocket, centred, open at the top face
    translate([-pocket_w / 2, -pocket_w / 2, pocket_z0])
        cube([pocket_w, pocket_w, pocket_depth + eps]);

    // Optional: trim the uppermost eps of the hull so no faces are coplanar at the top
    translate([-top_w / 2 - side_overlap, -top_w / 2 - side_overlap, block_h - eps])
        cube([top_w + 2 * side_overlap, top_w + 2 * side_overlap, eps]);
}
