    // Faces are at 45 deg, so the hull wall is steeper than the cut on the top face.
    hull() {
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 1]);
        translate([-top_size / 2, -top_size / 2, top_z])
            cube([top_size, top_size, 1]);
