    // Centre the pocket on the top face and extend above it.
    translate([-pocket_size / 2, -pocket_size / 2, top_z - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overcut]);
}

difference() {
    frustum();
    pocket();
