```openscad
// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), centred on the origin in X and Y.

// ---------------- Parameters ----------------
bottom_w     = 100;   // side length of the bottom square face (mm)
bottom_z     = 0;     // height of the bottom face above the bed (mm)
top_w        = 60;    // side length of the top square face (mm)
top_z        = 25;    // height of the top face above the bed (mm)
pocket_w     = 52;    // side length of the square pocket (mm)
pocket_depth = 5;     // depth of the pocket measured downward from the top face (mm)
eps          = 0.5;   // small overshoot used for clean boolean cuts (mm)

$fn = 64;             // not strictly needed since all faces are axis-aligned, set per style

// ---------------- Derived values ----------------
// Length of the diagonal of a square with side s
diag = function(s) { return s * sqrt(2); };

// How far the sides have to be extended upward so that their diagonals
// still meet at the original top corner.  With a 60 / 100 mm square the
// diagonal grows by 40 mm over 25 mm of height, i.e. 1.6 mm per mm of height,
// so extending by 0.5 mm in X and Y requires a 0.8 mm extension in Z.
overlap = function(dw) {
    // diagonal growth per unit height for the full 25 mm span
    g = dw / 25;
    // extend the top half-diagonal by the same amount and resolve the Z increase
    return g * dw / 2;
};

// ---------------- Model ----------------
difference() {
    // Solid square frustum: bottom square at z = 0, top square at z = 25,
    // with flat sloping sides and edges parallel to X and Y.
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, bottom_z])
            cube([bottom_w, bottom_w, 1]);
        translate([-top_w / 2 - overlap(diag(top_w)),
                   -top_w / 2 - overlap(diag(top_w)),
                   top_z - overlap(diag(top_w))])
            cube([top_w + 2 * overlap(diag(top_w)) + 2 * eps,
                  top_w + 2 * overlap(diag(top_w)) + 2 * eps,
                  1]);
    }

    // Square pocket 52 by 52 mm and 5 mm deep, centred, cut into the top face.
    // The cutter runs past the top face by 'eps' so no faces are coplanar.
    translate([0, 0, top_z - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
