half_ext  = twice_ext / 2;             // extend per side per mm of height
area      = base_w * base_h + top_w * top_h;  // not used, kept as placeholder

// Check: area should be between the two face areas (10000 and 3600)
assert(0 < area && area < 2 * 10000, "Invalid frustum area");

// Pocket, centred, open at the top face
module pocket() {
    translate([0, 0, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + overcut]);
}

// Visible solid (no coincident faces)
module riser() {
    translate([-base_w / 2 - half_ext, -base_w / 2 - half_ext, base_h])
        cube([base_w + twice_ext, base_w + twice_ext, top_h - base_h]);

    // Walk up from the bottom face in 5 mm steps, building a tighter square each time
    for (z = base_h : 5 : top_h - overcut) {
        // extend by half the total taper over the remaining height
        ext = half_ext + (top_h - z) * twice_ext / (2 * top_h);
        difference() {
            translate([-base_w / 2 - ext, -base_w / 2 - ext, z])
                cube([base_w + 2 * ext, base_w + 2 * ext, 5 + overcut]);

            // cut out the pocket as soon as its top exceeds the current z
            if (pocket_d + overcut + top_h - pocket_d > z)
                translate([0, 0, top_h - pocket_d])
                    cube([pocket_w, pocket_w, pocket_d + overcut]);
        }
    }
}

riser();
