p        = (top_w - base_w) / top_h;  // taper rate (change in width per mm of height)

// The block is built as one frustum and then the pocket is cut out.
// A small epsilon is used so that the cutters pass beyond the faces they cut.
module tapered_block() {
    difference() {
        union() {
            // Bottom section: from the bed up to pocket_top (z = 15)
            // Every cross-section is a square whose sides run parallel to X and Y.
            translate([base_w / 2, base_h / 2, 0])
                linear_extrude(height = pocket_t + eps)
                    polygon(points = [
                        [0, base_w],
                        [base_w, base_w],
                        [base_w, 0],
                        [0, 0]
                    ]);

            // Upper section: from pocket_top (z = 15) up to the top face (z = 20)
            translate([top_w / 2, top_h / 2, pocket_t])
                linear_extrude(height = top_h - pocket_t + eps)
                    polygon(points = [
                        [0, top_w],
                        [top_w, top_w],
                        [top_w, 0],
                        [0, 0]
                    ]);
        }

        // Square pocket centred on the top face, cut to z = 15
        translate([0, 0, pocket_t])
            cube([pocket_w, pocket_w, pocket_d + eps]);
    }
}

// ---- Model ----
translate([-base_w / 2, -base_h / 2, base_h])
    tapered_block();
