```openscad
// Tapered riser block - square frustum with a top pocket
// Units: mm. Print orientation: bottom face on the bed (z = 0).

// ---- Dimensions ----
base_size   = 80;   // bottom square side length
top_size    = 40;   // top square side length
height      = 25;   // block height (z = 0 to z = 25)
pocket_w    = 30;   // pocket side length
pocket_d    = 5;    // pocket depth from the top face

// ---- Derived ----
half_base   = base_size / 2;    // 40
half_top    = top_size / 2;     // 20
overcut     = 0.5;              // extension of cutters past faces

// Taper factor: how much the half-width changes per mm of height
twist = (half_base - half_top) / height;   // 0.2 mm per mm

module frustum() {
    // hull() connects the bottom square at z = 0 with the top square
    // extended slightly above z = height, so the sides are flat and
    // the extra chunk has the same slope as the real sides.
    hull() {
        translate([-half_base, -half_base, 0])
            cube([base_size, base_size, height + overcut]);
        translate([-half_top - overcut * twist,
                   -half_top - overcut * twist,
                   height])
            cube([top_size + 2 * overcut * twist,
                  top_size + 2 * overcut * twist,
                  overcut]);
    }
}

module pocket_cutter() {
    // extends above the top face (and through the thin hull chunk)
    translate([-pocket_w / 2, -pocket_w / 2, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + overcut]);
}

difference() {
    frustum();
    pocket_cutter();
}
```

