// Tapered riser block - square frustum with a top pocket
// Units: mm. Print orientation: bottom face on the bed (z = 0).

$fn = 64;

// ---- Dimensions ----
base_size    = 100;   // bottom square side length (z = 0)
top_size     = 60;    // top square side length (z = 20)
height       = 20;    // overall height of the frustum
pocket_size  = 52;    // square pocket side length
pocket_depth = 5;     // square pocket depth from the top face
overlap      = 0.5;   // extra cut length past faces to avoid coplanar faces

// ---- Derived ----
top_z = height;

// Taper factor: how much the side contracts per mm of height
alpha = (base_size - top_size) / 2 / height;

// Check: size at the top face (should be 60.0)
echo(str("Size at top face: ", (base_size - 2 * alpha * top_z), " mm"));

module frustum() {
    // Two blocks that meet at mid-height: their union is the frustum.
    // Each block is a frustum over a 10 mm height, which keeps the
    // sides straight and avoids any zero-volume overlap.
    n_blocks = 2;
    block_h  = 10;
    for (i = [0 : n_blocks - 1]) {
        z0 = i * block_h;
        z1 = (i + 1) * block_h;
        rotate([90, 0, 0])
            linear_extrude(height = block_h)
                polygon([
                    [-base_size / 2 + alpha * z0, -base_size / 2 + alpha * z0],
                    [ base_size / 2 - alpha * z0, -base_size / 2 + alpha * z0],
                    [ base_size / 2 - alpha * z0,  base_size / 2 - alpha * z0],
                    [-base_size / 2 + alpha * z0,  base_size / 2 - alpha * z0]
                ]);
    }
}

difference() {
    frustum();

    // Square pocket, centred, cut from the top face
    translate([0, 0, top_z - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overlap]);
}
