        translate([sx * post_x, 0, 0])
            cylinder(d = post_d, h = post_h);

    // Straight bar, overlapping posts slightly for a solid union
    translate([-bar_len / 2, -bar_w / 2, post_h - eps])
        cube([bar_len, bar_w, bar_top_z - post_h + eps]);

    // Screw holes in each post, from bottom face upward along axis
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(d = screw_d, h = post_h + eps + screw_depth);
