```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: lying flat on the bed, builds upward in +Z
// Positioned using the user's coordinates (not centred on the origin)

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness
total_length   = 100;   // overall length along X
gauge_width    = 10;    // width of the narrow gauge section
gauge_length   = 30;    // length of the gauge section
grip_width     = 15;    // width of each grip section
grip_length    = 25;    // length of each grip section
transition_len = 10;    // length of each grip–gauge transition

// ---- Derived values ----
each_wid      = grip_width;            // width at the start of a transition
each_len      = transition_len;        // distance over which the width changes
each_end_wid  = gauge_width;          // width at the end of a transition
each_hull_pt  = [each_len, each_wid];  // hull point at the start end
cup_size      = each_len * 0.5;        // cup radius for the end cone
overlap       = 0.01;                  // small overlap so cones fuse into the grips

module grip() {
    hull() {
        translate([0, -each_wid / 2, 0]) cube([each_len, each_wid, thickness]);
        translate([each_len, -each_wid / 2, 0]) cube([each_len, each_wid, thickness]);
    }
}

module transition() {
    // A linear width change from 15 mm down to 10 mm over 10 mm
    // is drawn as a cone seen from above, then extruded.
    rotate([90, 0, 90])
        linear_extrude(height = thickness)
            cone(r1 = each_wid / 2, r2 = each_end_wid / 2, h = each_len);
}

module specimen() {
    union() {
        for (sx = [-1, 1])
            translate([sx * (grip_length + transition_len), 0, 0])
                grip();
        for (sx = [-1, 1])
            translate([sx * (grip_length + transition_len + gauge_length / 2)], 0)
                transition();
        translate([0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }
}

specimen();
