        for (s = [-1, 1])
            translate([s * grip_start - grip_length, -half_grip, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1])
            translate([s * grip_start - transition, s * half_gauge, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [0, -half_grip],
                            [transition, -half_gauge],
                            [transition * 2, half_gauge],
                            [transition * 2, half_grip]
                        ]);

        // Gauge section
        translate([grip_start - gauge_length, -half_gauge, 0])
            cube([gauge_length, gauge_width, thickness]);
    }
}

