total_len     = 130;   // overall length along X
gauge_w       = 10;    // gauge section width (Y)
gauge_len     = 30;    // gauge section length (X)
grip_w        = 19;    // grip section width (Y)
grip_len      = 35;    // grip section length (X)
transition_w0 = 19;    // transition width at grip end
transition_w1 = 10;    // transition width at gauge end
transition_len = 15;   // transition length (X)

// ---- Derived ----
half_gauge = gauge_len / 2;        // 15
half_grip  = grip_len / 2;         // 17.5
x0 = -total_len / 2 + half_grip;   // -47.5  (grip start)

// ---- Model ----
union() {
    // Grip sections
    for (s = [-1, 1])
        translate([x0 + s * (half_grip - transition_len), -grip_w / 2, 0])
            cube([grip_len, grip_w, thickness]);

    // Gauge section
    translate([-half_gauge, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, thickness]);

    // Transitions (tanh profile, extended past faces for a clean union)
    for (s = [-1, 1]) {
        extend = 0.5;
        translate([x0 + s * (half_grip - transition_len), 0, 0])
            linear_extrude(thickness)
                rotate([0, 90, 0])
                    module_ext(t0 = transition_w0, t1 = transition_w1,
                               l = transition_len, ext = extend);
    }
}

// ---- tanh-based width vs X ----
module module_ext(t0, t1, l, ext) {
    c = (t1 - t0) / 2;
    x0 = -l / 2 - ext;
    x1 = l / 2 + ext;
    hull() {
        for (x = [x0, x1])
            translate([x, 0, 0])
                cylinder(d = t0 - ext + 0.01, h = thickness);
        for (x = [x0, x1])
            translate([x, 0, 0])
                rotate([0, 90, 0])
                    linear_extrude(thickness)
                        circle(d = abs(c * tanh(x / extend)), $fn = 64);
    }
}
