// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, symmetric about the origin.
// Units: mm

// ---------- Parameters ----------
specimen_thickness = 3;     // plate thickness (Z)
total_length       = 130;   // overall length along X
gauge_width        = 10;    // width of the narrow gauge section (Y)
gauge_length       = 30;    // length of the gauge section (X)
grip_width         = 19;    // width of each grip section (Y)
grip_length        = 35;    // length of each grip section (X)
transition_length  = 15;    // length of each grip->gauge transition (X)
overcut            = 0.5;   // extra length on cutting shapes to avoid coplanar faces

$fn = 64;

// ---------- Derived ----------
grip_half_w     = grip_width  / 2;
gauge_half_w    = gauge_width / 2;
grip_start_x    = -total_length / 2 + grip_length / 2;   // -42.5
gauge_start_x   = -gauge_length / 2;                      // -15
transition_start= grip_start_x + grip_length;             // -7.5
transition_end  = gauge_start_x - transition_start;       // 7.5 (mirrored offset)

// ---------- Model (seen from above) ----------
module dogbone_2d() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_start_x, -grip_half_w, 0])
                cube([grip_length, grip_width, specimen_thickness]);

        // Gauge section
        translate([gauge_start_x, -gauge_half_w, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Transitions: width changes linearly from grip width to gauge width
        for (s = [-1, 1]) {
            x0 = s * transition_start;
            x1 = s * transition_end;
            // Hull of two rectangular prisms gives a linearly tapered block
            hull() {
                translate([x0, -grip_half_w, 0])
                    cube([transition_length, grip_width, specimen_thickness]);
                translate([x1, -gauge_half_w, 0])
                    cube([transition_length, gauge_width, specimen_thickness]);
            }
        }
    }
}

difference() {
    dogbone_2d();

    // Ghost cutters, extended past the faces they cut
    for (s = [-1, 1]) {
        translate([s * grip_start_x - overcut, -grip_half_w - overcut, -overcut])
            cube([grip_length + 2 * overcut, grip_width + 2 * overcut,
                  specimen_thickness + 2 * overcut]);
    }
    translate([gauge_start_x - overcut, -gauge_half_w - overcut, -overcut])
        cube([gauge_length + 2 * overcut, gauge_width + 2 * overcut,
              specimen_thickness + 2 * overcut]);
}
