// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: lying flat on the bed, symmetric about the origin

// ---------------- Parameters ----------------
specimen_thickness = 3;     // thickness in Z (mm)
total_length       = 130;   // overall length along X (mm)

gauge_width        = 10;    // narrow gauge section width in Y (mm)
gauge_length       = 30;    // gauge section length along X (mm)

grip_width         = 19;    // grip section width in Y (mm)
grip_length        = 35;    // grip section length along X (mm)

transition_length  = 15;    // length of each grip->gauge transition along X (mm)

overlap            = 0.01;  // small overlap so adjacent blocks fuse cleanly (mm)

$fn = 64;                   // no curved features, set per guidelines

// ---------------- Derived ----------------
// X positions of feature boundaries (alternating grip/gauge/transition blocks)
function boundary(i) =
  if (i % 2 == 0)
    -total_length / 2 + i * (grip_length + transition_length) / 2
  else
    total_length / 2 - i * (grip_length + transition_length) / 2;

// ---------------- Model ----------------
module flat_dogbone_2d() {
    // 2D shape drawn in X/Y, scaled in Y by specimen thickness
    scale([1, specimen_thickness])
      union() {
        // Grip blocks at each end
        for (s = [-1, 1])
          translate([s * (-total_length / 2 + grip_length / 2),
                     -grip_width / 2, 0])
            cube([grip_length, grip_width, overlap]);

        // Gauge block in the centre
        translate([-gauge_length / 2, -gauge_width / 2, 0])
          cube([gauge_length, gauge_width, overlap]);

        // Transition blocks between grip and gauge (width changes linearly)
        for (s = [-1, 1]) {
          x0 = s * (-total_length / 2 + grip_length / 2);   // grip end
          x1 = s * (-gauge_length / 2);                      // gauge end
          w0 = grip_width;
          w1 = gauge_width;
          hull() {
            translate([x0, -w0 / 2, 0])
              cube([transition_length, w0, overlap]);
            translate([x1, -w1 / 2, 0])
              cube([transition_length, w1, overlap]);
          }
        }
      }
}

linear_extrude(height = specimen_thickness)
  flat_dogbone_2d();
