// Width profile seen from above (Y), left to right along X
module width_at(x) {
    if (x < -65) return grip_width;          // left grip
    if (x <= -60) return 19 - (x + 60);      // left transition (19 -> 8)
    if (x <= -50) return 8 + (x + 50);       // left 10 mm tail (8 -> 19)
    if (x <= 0)  return grip_width;          // left grip
    if (x <= 50) return transition_len;       // right 10 mm tail (19 -> 8)
    if (x <= 60) return 19 - (x - 60);       // right transition (19 -> 8)
    return grip_width;                        // right grip
}

difference() {
    // Outer plate
    translate([-total_length / 2, -100, 0])
        cube([total_length, 200, thickness]);

    // Cut out the V-shaped central region so only the gauge remains
    translate([-50, -gauge_width / 2, -1])
        linear_extrude(thickness + 2)
            polygon([for (s = [-1, 1]) each [
                [0, s * gauge_width / 2],
                [50 - half_trans, s * (gauge_width + 2 * half_trans) / 2],
                [50 + half_trans, s * (gauge_width + 2 * half_trans) / 2]
            ]]);
