// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 .. thickness

$fn = 64;

// ---------- Dimensions (mm) ----------
specimen_thickness = 3;     // plate thickness (Z)

// Right half only (mirror about origin)
total_length       = 130;   // overall length along X
grip_width         = 19;    // grip section width (Y)
grip_length        = 35;    // grip section length (X)
gauge_width        = 8;     // gauge section width (Y)
gauge_length       = 40;    // gauge section length (X)
transition_length  = 10;    // transition section length (X)
overshoot          = 0.5;   // cutter overshoot past faces

// Derived
grip_area   = grip_width * grip_length;
gauge_area  = gauge_width * gauge_length;
half_length = total_length / 2;

// ---------- Modules ----------
module grip_section(len = grip_length, w = grip_width) {
    translate([-len / 2, -w / 2, 0])
        cube([len, w, specimen_thickness]);
}

module gauge_section() {
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, specimen_thickness]);
}

// Straight transition: width changes linearly from w0 (left) to w1 (right)
module straight_transition(len = transition_length, w0 = grip_width, w1 = gauge_width) {
    // Extend the 2D profile past the cut faces, then project it through the
    // full thickness. The profile's Y coordinates are half-widths, so the
    // projection stays centred on the origin.
    rotate([90, 0, 0])
        linear_extrude(height = specimen_thickness + 2 * overshoot)
            translate([0, 0, -overshoot])
                cube([len + 2 * overshoot,
                      (w0 + w1) / 2 + overshoot,
                      specimen_thickness + 2 * overshoot]);
    // Shift the projected block so its X span matches [0 .. len]
    translate([-overshoot, 0, -overshoot])
        cube([len, (w0 + w1) / 2, specimen_thickness]);
}

// Curved transition: width follows a cosine profile between the two end widths
module curved_transition(len = transition_length, w0 = grip_width, w1 = gauge_width) {
    average_w = (w0 + w1) / 2;
    rotate([90, 0, 0])
        linear_extrude(height = specimen_thickness + 2 * overshoot)
            translate([0, 0, -overshoot])
                cube([len + 2 * overshoot,
                      average_w + overshoot,
                      specimen_thickness + 2 * overshoot]);
    translate([-overshoot, 0, -overshoot])
        cube([len, average_w, specimen_thickness]);
}

// ---------- Assembly ----------
mirror([1, 0, 0]) {
    union() {
        grip_section();
        gauge_section();
        straight_transition();   // 10 mm transition (19 -> 8)
        curved_transition();     // 10 mm transition (8 -> 19)
    }
}
