module top_profile() {
    // grip | trans | gauge | trans | grip
    union() {
        translate([x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness + 2 * eps]);
        for (s = [-1, 1])
            translate([s * half_trans - gauge_length, -gauge_width / 2, 0])
                cube([gauge_length + transition_length, gauge_width, thickness + 2 * eps]);
        for (s = [-1, 1])
            translate([x0 + (s < 0 ? -half_trans : grip_length + half_trans),
                       -gauge_width / 2, 0])
                cube([transition_length, gauge_width + s * (grip_width - gauge_width) / 2,
                      thickness + 2 * eps]);
    }
}

