module dogbone() {
    hull() {
        translate([0, 0, -eps])
            linear_extrude(height = thickness + 2 * eps)
                top_profile();
        rotate([90, 0, 0])
            linear_extrude(height = thickness + 2 * eps)
                top_profile();
