            cube([grip_length, grip_width, thickness]);

    // Gauge block
    translate([centre_x - gauge_length / 2, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transitions (width changes linearly from grip to gauge)
    for (t = [0, 1]) { // t = 0: left, t = 1: right
        rotate([0, 0, t * 180])
            linear_extrude(height = thickness)
                polygon([
                    [0, -half_w],
                    [transition_len, -half_w],
                    [transition_len, half_w],
                    [0, half_w]
                ]);
        translate([(t == 0 ? 0 : centre_x - gauge_length / 2) + (t == 1 ? transition_len : 0)])
            rotate([0, 0, t == 0 ? 0 : 180])
                linear_extrude(height = thickness)
                    polygon([
                        [0, -half_w],
                        [transition_len, -half_w],
                        [transition_len, half_w],
                        [0, half_w]
                    ]);
