// Flat dog-bone tensile specimen
// Units: mm. Prints flat on the bed (z = 0 upward).

// ---------------- Parameters ----------------
specimen_length = 140;   // overall length along X (grip to grip)
thickness       = 4;     // specimen thickness (Z)

grip_width      = 19;    // grip section width (Y)
grip_length     = 35;    // grip section length along X
transition_len  = 15;    // length of each width-transition zone
gauge_width     = 10;    // gauge section width (Y)
gauge_length    = 40;    // gauge section length along X

cut_extra       = 0.5;   // overshoot of the gauge cut past end faces

$fn = 64;

// ---------------- Derived ----------------
half_specimen = specimen_length / 2;          // 70
edge_x        = half_specimen - grip_length;  // grip end, -35
transition_x  = edge_x + transition_len;      // 20 (start of gauge)
centre        = transition_x - transition_len; // -20 (start of gauge)

// ---------------- Model ----------------
module tensile_specimen() {
    width_profile = concat(
        [grip_width + (transition_len > 0 ? 0 : 0)],   // left grip
        [for (t = [0 : transition_len])
            grip_width - (grip_width - gauge_width) * t / transition_len],  // left transition
        [for (t = [0 : gauge_length])
            gauge_width + (gauge_width > 0 ? 0 : 0)],    // gauge (held at width 10)
        [for (t = [0 : transition_len])
            gauge_width + (grip_width - gauge_width) * t / transition_len],  // right transition
        [grip_width]                                     // right grip
    ];

    hull() {
        for (i = [0 : len(width_profile) - 1]) {
            translate([i > 0 ? -1 : 0, -width_profile[i] / 2, 0])
                cube([i > 0 ? 1 : specimen_length, width_profile[i], thickness]);
        }
    }
}

difference() {
    tensile_specimen();

    // Gauge cut, centred, extending past both end faces
    translate([centre - transition_len - cut_extra,
               -gauge_width / 2,
               -cut_extra])
        cube([gauge_length + 2 * cut_extra + 2 * transition_len,
              gauge_width,
              thickness + 2 * cut_extra + 2]);
}
