// Flat dog-bone tensile specimen for FDM printed plastic
// Units: mm. Print orientation: flat on bed, building up +Z.

$fn = 64;

// ---- Dimensions ----
total_len    = 140;  // overall length (X)
thickness    = 3;    // specimen thickness (Z)
gauge_width  = 6;    // narrow gauge width (Y)
gauge_len    = 50;   // gauge length (X)
grip_width   = 19;   // grip section width (Y)
grip_len     = 30;   // grip section length (X)
trans_len    = 15;   // transition length (X)
eps          = 0.5;  // cutter overshoot past faces

// ---- Derived ----
g1 = grip_len + trans_len;      // length of one grip+transition end
origin_x = -(total_len - gauge_len) / 2;  // X where the profile is centred

// ---- Profile (seen from above) ----
function profile_y(x) =
    if (x < origin_x - g1)
        grip_width + 2 * (x - (origin_x - g1)) / trans_len * (gauge_width - grip_width);
    else if (x < origin_x - trans_len)
        grip_width - (x - (origin_x - g1)) / trans_len * (gauge_width - grip_width);
    else if (x < origin_x + trans_len)
        gauge_width + (x - (origin_x + trans_len)) / trans_len * (gauge_width - grip_width);
    else
        grip_width + (x - (origin_x + g1)) / trans_len * (gauge_width - grip_width);

difference() {
    // Main plate
    linear_extrude(height = thickness)
        translate([origin_x - 2 * g1 - 10, -50, 0])
            rotate([90, 0, 0])
                linear_extrude(height = 110)
                    polygon(points = [for (x = [-80 : 0.5 : 80]) [x, profile_y(x)]]);

    // Central grip relief (overlaps the grip sections; no faces are coplanar)
    translate([origin_x - g1 - eps, -grip_width / 2 - eps, -eps])
        rotate([90, 0, 0])
            linear_extrude(height = thickness + 2 * eps)
                square([gauge_len + 2 * eps, grip_width + 2 * eps]);
}
