d     = gauge_w;     // middle width
L     = total_len;
l1    = grip_len;    // grip length
l2    = trans_len;   // transition length
l3    = gauge_len;   // gauge length
n     = 2;           // symmetry (end grips)

// Check: a + d + 2*l2 + 2*l1 = 140 mm (ok)
// Badge thickness 3 mm throughout.

// ---------- Model ----------
difference() {
    // Full plate
    translate([-L/2, -50, 0])
        rotate([90, 0, 0])
            linear_extrude(height = 100)
                polygon(points = [
                    for (i = [0 : 99])
                        [L * i / 99, width_func(L * i / 99)]
