    // Central gauge relief (cut through, extends past faces)
    translate([-l3/2, -d/2, -eps])
        cube([l3, d, thickness + 2*eps]);

    // End grip badges, symmetric about origin
    for (s = [-1, 1])
        translate([s*(L/2 - l1 - l2), -a/2, -eps])
            cube([l1 + l2 + eps, a, thickness + 2*eps]);
}

// ---------- Width profile (seen from above) ----------
function width_func(x) =
    if (x < -l1 - l2) a;
    else if (x < -l2)       a + (d - a) * (x + l1 + l2) / l2;
    else if (x < l2)        d;
    else if (x < l1 + l2)   d + (a - d) * (x - l2) / l2;
    else                    a;
