// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on the bed, z = 0 upward. Symmetric about origin.

// ---------- Dimensions (mm) ----------
thickness    = 3;     // specimen thickness (Z)
total_length = 140;   // overall length along X
gauge_width  = 6;     // narrow gauge section width (Y)
gauge_length = 50;    // gauge section length (X)
grip_width   = 19;    // grip section width (Y)
grip_length  = 30;    // grip section length (X)
transition_length = 15; // width transition length between grip and gauge (X)

// ---------- Derived ----------
half_gauge   = gauge_length / 2;            // gauge end from center (X)
half_grip    = grip_length / 2;             // grip end from center (X)
grip_start_x = -total_length / 2 + half_grip; // grip inner end (X)
deceler     = transition_length / (grip_width - gauge_width); // X change per Y mm in transition

// ---------- Model ----------
difference() {
    // Full plate
    translate([-total_length / 2, -50, 0])
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [for (x = [-total_length / 2 : 1 : total_length / 2])
                    [x, get_width(x)]]);

    // Central relief: gauge section + transitions, overcut in Z
    translate([0, 0, -1])
        linear_extrude(height = thickness + 2)
            polygon(points = [
                [-half_gauge, gauge_width / 2],
                [ half_gauge, gauge_width / 2],
                [ half_gauge - transition_length, grip_width / 2],
                [ grip_start_x, grip_width / 2],
                [ grip_start_x, -grip_width / 2],
                [ -grip_start_x, -grip_width / 2],
                [ -grip_start_x, grip_width / 2],
                [ -half_gauge + transition_length, grip_width / 2],
                [ -half_gauge, gauge_width / 2]
            ]);
}

// Width at a given X
function get_width(x) =
    if (x < -half_gauge + transition_length)
        grip_width - (x + half_gauge - transition_length) / deceler
    elif (x < half_gauge - transition_length)
        gauge_width
    elif (x < half_gauge)
        gauge_width + (x - (half_gauge - transition_length)) / deceler
    else
        grip_width;
