// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness    = 3;     // plate thickness (Z)
gauge_width  = 6;     // narrow gauge section width (Y)
gauge_length = 50;    // gauge section length (X)
grip_width   = 19;    // grip section width (Y)
grip_length  = 30;    // grip section length (X)
transition   = 15;    // grip-to-gauge transition length (X)
total_length = 140;   // overall length along X

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
overcut    = 0.5;     // cutter extension past faces

// Width at the start of the transition (outer end of grip)
function w_start(sx) = grip_width + (transition / 2) * (gauge_width - grip_width) / (half_gauge + transition);

module half_spec() {
    difference() {
        hull() {
            // Grip block
            translate([-half_grip, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
            // Transition
            translate([-(half_gauge + transition), -w_start(-1) / 2, 0])
                cube([transition + half_gauge, w_start(-1), thickness]);
            // Gauge section
            translate([-half_gauge, -gauge_width / 2, 0])
                cube([gauge_length, gauge_width, thickness]);
        }
        // Remove the upper half to keep only z = 0..thickness
        translate([-half_gauge - transition - overcut, -w_start(-1) / 2, thickness])
            cube([half_gauge + transition + 2 * overcut, w_start(-1), overcut]);
    }
}

union() {
    half_spec();
    mirror(x = 0)
        half_spec();
}
