    for (s = [-1, 1])
        translate([s * (grip_length - overlap), -grip_width / 2, 0])
            cube([grip_length + overlap, grip_width, thickness]);

    // Transition sections
    for (s = [-1, 1])
        translate([centre + s * (gauge_length / 2 + transition - overlap),
                   -grip_width / 2, 0])
            cube([transition + overlap, grip_width, thickness]);

    // Gauge section
    translate([centre, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
};

// Translate to the user's stated total length origin
