total_len     = 120;   // overall length
gauge_len     = 50;    // length of the narrow gauge section
gauge_w       = 6;     // width of the gauge section
grip_len      = 25;    // length of each grip section (both ends)
grip_w        = 20;    // width of the grip sections
trans_len     = 10;    // length of each transition section
thickness     = 4;     // specimen thickness (Z)

eps           = 0.5;   // overshoot for clean boolean cuts

// ---------- Derived ----------
half_grip     = grip_len / 2;
half_gauge    = gauge_len / 2;

// marginal overlap so the grip / transition blocks fuse cleanly
overlap       = 0.01;

// ---------- Model ----------
union() {
    // left grip + transition
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([grip_len + trans_len, grip_w, thickness]);

    // gauge section
    translate([-half_gauge, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, thickness]);

    // right grip + transition
    translate([total_len / 2 - (grip_len + trans_len), -grip_w / 2, 0])
        cube([grip_len + trans_len, grip_w, thickness]);
}

// ---------- Cutting pockets (from top and bottom) ----------
difference() {
    // copy of the body before the cuts
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([total_len, grip_w, thickness]);

    // left: grip pocket, transition pocket, gauge pocket
    translate([-grip_len - trans_len - eps, -grip_w / 2, -eps])
        cube([grip_len + trans_len + 2 * eps, grip_w, thickness + 2 * eps]);

    translate([-half_gauge - eps, -gauge_w / 2, -eps])
        cube([gauge_len + 2 * eps, gauge_w, thickness + 2 * eps]);

    // right: grip pocket, transition pocket, gauge pocket
    translate([eps, -grip_w / 2, -eps])
        cube([grip_len + trans_len + 2 * eps, grip_w, thickness + 2 * eps]);

    translate([half_gauge - eps, -gauge_w / 2, -eps])
        cube([gauge_len + 2 * eps, gauge_w, thickness + 2 * eps]);
}
