gauge_len     = 50;    // gauge section length (X)
grip_w        = 20;    // grip section width (Y)
grip_len      = 25;    // grip section length (X)
transition_w  = 6;     // transition section width (Y) at its thinnest end
trans_len     = 10;    // transition section length (X)
cut_ext       = 0.5;   // extension of cutters past faces

$fn = 64;

// ---------- Derived ----------
a     = grip_w;      // grip width
b     = transition_w; // transition width
c     = gauge_w;     // gauge width
L     = total_len;   // total length
l     = gauge_len;   // gauge length
L1    = grip_len;    // grip length
L2    = trans_len;   // transition length
t     = thickness;   // thickness

// ---------- Model ----------
difference() {
    // Outer block
    translate([-L/2, -a/2, 0])
        cube([L, a, t]);

    // Central gauge section
    translate([-l/2, -c/2, -cut_ext])
        cube([l, c, t + 2*cut_ext]);

    // Transition sections
    for (s = [-1, 1]) {
        translate([s * (L/2 - L1), -b/2, 0])
            cube([L2, b + s * (b - c), t]);
    }
}
