// Flat tensile test specimen (dog-bone shape)
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters ----------
thickness   = 4;     // plate thickness (Z)
total_len   = 120;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 25;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
overlap     = 1;     // overlap between adjacent sections (X)
$fn         = 64;    // curve resolution

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;

// ---------- Model ----------
union() {
    // Left grip
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([grip_len, grip_w, thickness]);

    // Right grip
    translate([total_len / 2 - grip_len, -grip_w / 2, 0])
        cube([grip_len, grip_w, thickness]);

    // Gauge section (may overlap into grips by 'overlap')
    translate([-half_gauge + overlap, -gauge_w / 2, 0])
        cube([gauge_len - 2 * overlap, gauge_w, thickness]);

    // Transition: grip (w = grip_w) -> gauge (w = gauge_w)
    for (len = [trans_len, trans_len]) {
        translate([-half_gauge - len + overlap, -grip_w / 2, 0])
            linear_extrude(height = thickness)
                polygon([
                    [0, -grip_w / 2],
                    [len, -gauge_w / 2],
                    [len, gauge_w / 2],
                    [0, gauge_w / 2]
                ]);
    }
}
