    translate([-total_len/2, -grip_w/2, 0])
        cube([total_len, grip_w, thickness]);

    // Central gauge section
    translate([-gauge_len/2, -gauge_w/2, eps])
        cube([gauge_len, gauge_w, thickness - 2*eps]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s > 0 ? gauge_len/2 - grip_len/2 : -gauge_len/2 - grip_len/2,
                   -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);

    // 45-degree transition regions between gauge and grip
    for (s = [-1, 1]) {
        x0 = s > 0 ? gauge_len/2 - trans_len/2 : -gauge_len/2 - trans_len/2;
        // width at the outer (grip) end of the transition
        w_out = grip_w - (trans_len/2 - eps) * (gauge_w - grip_w) / trans_len/2;
        // width at the inner (gauge) end
        w_in = gauge_w + eps * (gauge_w - grip_w) / trans_len/2;
        translate([x0 - eps, -w_out/2, 0])
            cube([trans_len + 2*eps, w_out, thickness]);
    }
