// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, builds up in +Z
// Units: mm

// ---------- Dimensions ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 6;     // width of the narrow gauge section (Y)
gauge_length   = 50;    // length of the gauge section (X)
grip_width     = 20;    // width of each grip section (Y)
grip_length    = 25;    // length of each grip section (X)
transition_len = 10;    // length of each grip-to-gauge transition (X)

$fn = 64;

// ---------- Derived ----------
grip_start    = gauge_length / 2 + transition_len;  // X where grip begins
grip_half_wid = grip_width / 2;

// ---------- Profile (top face) ----------
module top_profile() {
    union() {
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2])
            rectangle([gauge_length, gauge_width]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_start - grip_length / 2, -grip_half_wid])
                rectangle([grip_length, grip_width]);

        // Transitions (width changes linearly from 20 -> 6)
        for (t = [transition_len, -transition_len])
            for (s = [-1, 1])
                translate([s * (gauge_length / 2 + t), -grip_half_wid])
                    linear_extrude(height = grip_half_wid)
                        polygon(points = [
                            [0, 0],
                            [transition_len, 0],
                            [transition_len, grip_half_wid],
                            [0, grip_half_wid]
                        ]);
    }
}

// ---------- Solid ----------
difference() {
    // Outer block, centred in X and Y, resting on z = 0
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out the dog-bone volume, using the top profile
    translate([0, 0, thickness])
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                top_profile();
}
