// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, builds upward in +Z
// Units: mm

// ---------- Dimensions ----------
specimen_thickness = 4;     // plate thickness (Z)
total_length       = 120;   // overall length along X
gauge_width        = 6;     // narrow gauge section width (Y)
gauge_length       = 50;    // gauge section length (X)
grip_width         = 20;    // grip section width (Y)
grip_length        = 25;    // grip section length (X)
transition_length  = 10;    // each grip-to-gauge transition length (X)

$fn = 64;                    // no curved features, set per rules

// ---------- Derived ----------
grip_outer_x      = gauge_length / 2 + transition_length;   // grip end X
difference_len    = total_length - 2 * grip_outer_x;        // central region length (gauge + 2*trans)

// ---------- Profile (top face) ----------
module top_profile() {
    union() {
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            rectangle([gauge_length, gauge_width]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_outer_x - grip_length / 2, -grip_width / 2, 0])
                rectangle([grip_length, grip_width]);

        // Transition regions (trapezoid widths: grip -> gauge)
        for (s = [-1, 1])
            translate([s * (gauge_length / 2 - transition_length), -grip_width / 2, 0])
                linear_extrude(height = transition_length)
                    polygon(points = [
                        [0, -grip_width / 2],
                        [transition_length, -grip_width / 2],
                        [transition_length, grip_width / 2],
                        [0, grip_width / 2]
                    ]);
    }
}

// ---------- Part ----------
difference() {
    // Central region (gauge + transitions)
    linear_extrude(height = specimen_thickness)
        translate([-difference_len / 2, -grip_width / 2, 0])
            top_profile();

    // Grip blocks (extend past both end faces)
    for (s = [-1, 1]) {
        extend = 1;
        translate([s * grip_outer_x - grip_length / 2, -grip_width / 2, -extend])
            cube([grip_length, grip_width, specimen_thickness + 2 * extend]);
    }
}
