```openscad
// Dog-bone flat tensile test specimen
// Units: mm. Prints flat on the bed (z = 0 upward).

// ---------- Parameters ----------
thickness  = 4;     // specimen thickness (Z)
totalLen   = 130;   // overall length along X
gaugeW     = 6;     // gauge section width (Y)
gaugeL     = 30;    // gauge section length (X)
gripW      = 20;    // grip section width (Y)
gripL      = 35;    // grip section length (X)
transL     = 15;    // transition section length (X)
eps        = 0.5;   // cutter overshoot past faces

$fn = 64;           // curve resolution (no curves here; kept per convention)

// ---------- Derived ----------
halfGripW  = gripW / 2;
halfGaugeW = gaugeW / 2;

// Check: grip + trans + gauge + trans + grip = totalLen ?
// 35 + 15 + 30 + 15 + 35 = 130 mm -> OK

// ---------- Model ----------
// Width profile along X: two grip blocks at each end, two transition
// blocks next to them, and the gauge block in the middle.
module widthAtX(x) {
    // Normalize x to [0, totalLen]
    t = x / totalLen;

    if (t < gripL / totalLen) {
        // left grip
        return gripW;
    } else if (t < (gripL + transL) / totalLen) {
        // left transition: gripW -> gaugeW
        return gripW + (gaugeW - gripW) * (t - gripL / totalLen) / (transL / totalLen);
    } else if (t < (gripL + transL + gaugeL) / totalLen) {
        // gauge
        return gaugeW;
    } else if (t < (totalLen - transL - gripL) / totalLen) {
        // right transition: gaugeW -> gripW
        return gaugeW + (gripW - gaugeW) * (t - (totalLen - transL - gripL) / totalLen) / (transL / totalLen);
    } else {
        // right grip
        return gripW;
    }
}

difference() {
    // Solid body
    hull() {
        for (x = [-totalLen : totalLen : totalLen])
            translate([x, 0, 0])
                cube([1, widthAtX(x), thickness]);
    }

    // Centre the gauge section under the cutter (it may cross into the transitions)
    translate([-gaugeL / 2, -eps, -eps])
        cube([gaugeL, gaugeW + 2 * eps, thickness + 2 * eps]);
}
