// Flat dog-bone tensile specimen
// Print orientation: lying flat on the bed, centred on the origin.
// Units: mm.

// ---------- Parameters ----------
total_len    = 130;   // overall length along X
thickness    = 4;     // specimen thickness (Z)

grip_len     = 35;    // grip section length (X)
grip_w       = 20;    // grip section width (Y)

trans_len    = 15;    // transition section length (X)
trans_w_start = 20;   // transition width at grip end (Y)
trans_w_end  = 6;     // transition width at gauge end (Y)

gauge_len    = 30;    // gauge section length (X)
gauge_w      = 6;     // gauge section width (Y)

eps          = 0.5;   // cutter overshoot past faces

$fn = 64;             // circle resolution (no curves used, kept for consistency)

// ---------- Derived ----------
half_gauge = gauge_len / 2;               // 15
w_pos      = grip_len + trans_len;        // 50 : position of gauge centre
w_outline = max(grip_w, trans_w_start);   // 20 : width at the outermost X

// ---------- Model ----------
difference() {
    // Solid plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, thickness + 2 * eps]);

    // Cutout (dog-bone shape), extended past top/bottom faces
    translate([-total_len / 2, -w_outline / 2, -eps])
        linear_extrude(height = thickness + 2 * eps)
            polygon(points = [
                // Grip end (left)
                [-w_pos, 0],
                // Grip section
                for (s = [-1, 1])
                    [s * (grip_len / 2 - grip_w / 2) - w_pos,
                     s * w_outline / 2],
                // Grip section (inner end)
                for (s = [-1, 1])
                    [s * (grip_len / 2 - grip_w / 2) - w_pos + grip_len,
                     s * w_outline / 2],
                // Transition (left)
                for (t = [0 : 1])
                    [(t * trans_len - trans_len / 2) - trans_len / 2 + grip_len
                     + s * (trans_w_start - gauge_w) * t / 2
                     - w_pos,
                     s * (trans_w_start - gauge_w) * t / 2 + gauge_w / 2],
                // Gauge section
                for (s = [-1, 1])
                    [s * (gauge_len / 2 - gauge_w / 2) - trans_len / 2 + grip_len,
                     s * gauge_w / 2],
                // Transition (right)
                for (t = [0 : 1])
                    [s * (trans_w_start - gauge_w) * t / 2 + gauge_w / 2,
                     s * (trans_w_start - gauge_w) * t / 2 + gauge_w / 2,
                     t * trans_len - trans_len / 2 + grip_len + gauge_len / 2 - gauge_w / 2],
                // Grip section (right)
                for (s = [-1, 1])
                    [s * (grip_len / 2 - grip_w / 2) + w_pos - grip_len,
                     s * w_outline / 2],
                // Grip section (outer end)
                for (s = [-1, 1])
                    [s * (grip_len / 2 - grip_w / 2) + w_pos,
                     s * w_outline / 2],
                // Back to the start
                [w_pos - grip_len - trans_len, 0]
            ]);
}
