grip_start = (total_length - grip_length - gauge_length - grip_length) / 2;
// grip_start = -50: gauge centred on origin, grips at each end

// ---------- Model ----------
module flat_dogbone() {
    // Width profile seen from above (Y), piecewise linear in X
    function profile_w(x) =
        if (x < grip_start) grip_width
        else if (x < grip_start + transition_len)
            grip_width - (x - grip_start) * (grip_width - gauge_width) / transition_len
        else if (x < grip_start + transition_len + gauge_length)
            gauge_width + (x - grip_start - transition_len) * (grip_width - gauge_width) / transition_len
        else if (x < total_length - grip_start - transition_len)
            gauge_width
        else if (x < total_length - grip_start)
            gauge_width + (x - total_length + grip_start + transition_len) * (grip_width - gauge_width) / transition_len
        else
            grip_width;

    hull() {
        // End grips, full width over their lengths
        for (s = [-1, 1])
            translate([s * (total_length / 2 - grip_length), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section, centred on origin
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }
}

