grip_length     = 35;    // length of each grip section (X)

transition_width_in      = 20;   // grip-end width of transition (Y)
transition_width_out     = 6;    // gauge-end width of transition (Y)
transition_length        = 15;   // length of each transition (X)

eps = 0.5;              // overlap for clean cuts / unions

$fn = 64;

