module dogbone() {
    // x runs from -specimen_length/2 to +specimen_length/2
    function w(x) =
        if (abs(x) <= grip_length)
            grip_width
        else if (abs(x) <= grip_length + transition_length)
            lerp(abs(x) - grip_length, transition_length,
                 transition_width_in, transition_width_out)
        else if (abs(x) > specimen_length / 2 - transition_length)
            lerp(specimen_length / 2 - x, transition_length,
                 transition_width_out, transition_width_in)
        else
            gauge_width;

    hull() {
        for (s = [-1, 1])
            translate([s * specimen_length / 2, 0, 0])
                cube([grip_length, grip_width, thickness]);
    }
}

difference() {
    dogbone();

    // central slot through the gauge section
    translate([0, 0, -eps])
        cube([gauge_length, grip_width + 2 * eps, thickness + 2 * eps]);
