                        for (t = [0 : transition_len/2 : grip_length/2 - transition_len/2])
                            [
                                sx * (t - transition_len/2) - transition_len/2, // start of transition
                                width(t - transition_len/2)
                            ],
                        sx * (grip_length/2 - transition_len/2)
                    ]),
                for (x = [0 : total_length/2 - transition_len : grip_length/2 - transition_len/2])
                    [x - transition_len/2, width(x - transition_len/2)],
                for (x = [total_length/2 - transition_len : -1 : grip_length/2 - transition_len/2])
                    [x - transition_len/2, width(x - transition_len/2)]
