grip_width    = 20;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition    = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
x0 = gauge_length / 2 + transition;  // where grip ends / gauge begins

// ---- Model ----
difference() {
    // Solid block
    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    // Cutout (leaves a wall of 1 mm on each face)
    translate([-total_length / 2 - 1, -thickness / 2 - 1, -1])
        linear_extrude(thickness + 2)
            polygon(points = [
                [-x0, -thickness / 2],
                [ x0, -thickness / 2],
                [ x0,  transition / 2 + gauge_width / 2],
                [ x0 + gauge_length / 2, thickness / 2 + transition / 2],
                [ x0 + gauge_length / 2, thickness / 2 + transition / 2],
                [total_length / 2 - transition, thickness / 2 + transition / 2],
                [total_length / 2 - transition, thickness / 2],
                [-total_length / 2 + transition, thickness / 2],
                [-total_length / 2 + transition, thickness / 2 + transition / 2],
                [-x0 - gauge_length / 2, thickness / 2 + transition / 2],
                [-x0 - gauge_length / 2, thickness / 2],
                [-x0, thickness / 2]
            ]);
}
