    union() {
        // Outer rim
        cylinder(d = rim_od, h = rim_w, $fn = fn_res);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_d, h = rim_w + 2 * cut_extra, $fn = fn_res);

        // Spokes, first along +X
        for (i = [0 : spokes - 1])
            rotate([0, 0, i * 360 / spokes])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([spoke_w, spoke_w, spoke_len]);
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_d, h = rim_w + 2 * cut_extra, $fn = fn_res);
