// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

// ---- Dimensions (mm) ----
wheel_thickness = 5;    // part thickness (Z)
outer_diameter  = 60;   // outer rim diameter
rim_width       = 6;    // rim width (radial)
hub_diameter    = 16;   // hub diameter
axle_hole       = 6;    // axle hole diameter
spoke_count     = 5;    // number of spokes
spoke_width     = 4;    // spoke width (radial)
spoke_start     = 0;    // angle of first spoke (deg, +X axis)
overlap         = 0.01; // overlap to avoid coplanar faces

$fn = 96;

inner_diameter = outer_diameter - 2 * rim_width;   // 48 mm

module rim() {
    translate([0, 0, -overlap])
        cylinder(d = outer_diameter, h = wheel_thickness + 2 * overlap);
}

module hub() {
    translate([0, 0, -overlap])
        difference() {
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * overlap);
            translate([0, 0, -overlap])
                cylinder(d = axle_hole, h = wheel_thickness + 2 * overlap + 2);
        }
}

module spokes() {
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([hub_diameter / 2 - overlap, 0, -overlap])
            rotate([0, 0, a])
                cube([spoke_width, (outer_diameter - hub_diameter) / 2,
                     wheel_thickness + 2 * overlap]);
    }
}

difference() {
    union() {
        rim();
        hub();
        spokes();
    }
    // remove the core that spokes leave hollow (between hub and rim)
    for (i = [0 : spoke_count + 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([hub_diameter / 2 + overlap, 0, -overlap])
            rotate([0, 0, a])
                cube([spoke_width, (outer_diameter - hub_diameter) / 2,
                     wheel_thickness + 2 * overlap]);
    }
}
