        translate([-(rim_outer_d / 2 - rim_width), -rim_width, 0])
            cube([rim_outer_d / 2 - rim_width, 2 * rim_width, part_thickness]);

        // Hub
        translate([0, -hub_d / 2, 0])
            cube([hub_d, hub_d, part_thickness]);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
                translate([-(hub_d / 2 + rim_width), -spoke_width / 2, 0])
                    cube([hub_d / 2 + rim_width, spoke_width, part_thickness]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
