// Spoked wheel for a small sample cart
// Print orientation: flat on bed, z = 0 upward

$fn = 96;

// --- Dimensions (mm) ---
part_thickness = 8;     // part thickness (Z)
outer_d        = 60;    // outer rim diameter
rim_width      = 4;     // rim width (radial)
hub_d          = 20;    // hub diameter
axle_hole      = 8;     // axle hole diameter
spoke_count    = 5;     // number of spokes
spoke_width    = 5;     // spoke width (radial)
first_spoke    = 0;     // angle of first spoke (deg, +X axis)

// --- Derived ---
outer_r = outer_d / 2;
rim_od  = outer_r - rim_width;   // outer diameter of ring (inner diameter of part)

// --- Model ---
union() {
    // Flat ring (outer rim)
    difference() {
        cylinder(d = outer_d, h = part_thickness);
        translate([0, 0, -1])
            cylinder(d = rim_od, h = part_thickness + 2);
    }

    // Hub with axle hole
    translate([0, 0, -1])
        difference() {
            cylinder(d = hub_d, h = part_thickness + 2);
            translate([0, 0, -1])
                cylinder(d = axle_hole, h = part_thickness + 2);
        }

    // Spokes, radially from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = first_spoke + i * 360 / spoke_count;
        // Each spoke spans from (hub_d/2 - 1) out to the outer radius
        translate([0, 0, -1])
            cylinder(r2 = hub_d / 2 - 1,
                     r1 = outer_r,
                     h  = part_thickness + 2,
                     rot = [0, 0, a]);
    }
}
