// Spoked wheel - flat part on bed, centred on origin
// Print orientation: lying flat on bed, z = 0 upward

$fn = 96;

// --- Dimensions (mm) ---
part_thickness   = 8;     // overall part thickness (Z)
outer_rim_d      = 60;    // outer diameter of rim
rim_width        = 4;     // radial width of rim
hub_d            = 20;    // outer diameter of hub
axle_hole_d      = 8;     // diameter of axle hole through hub
spoke_count      = 5;     // number of spokes
spoke_width      = 5;     // width of each spoke (radial)
cut_overlap      = 0.5;   // overlap for cutting shapes to avoid coplanar faces

// Derived
rim_id = outer_rim_d - 2 * rim_width;   // rim inner diameter (hub outer + gap)
spoke_start_angle = 0;                  // first spoke along +X axis

module wheel() {
    difference() {
        union() {
            // Outer rim (ring)
            cylinder(d = outer_rim_d, h = part_thickness);
            // Hub
            translate([0, 0, -cut_overlap])
                cylinder(d = hub_d, h = part_thickness + 2 * cut_overlap);
            // Spokes: radial from hub to rim, evenly spaced
            for (i = [0 : spoke_count - 1]) {
                a = spoke_start_angle + i * 360 / spoke_count;
                translate([hub_d / 2 - cut_overlap, 0, -cut_overlap])
                    rotate([0, 90, a])
                        cube([(rim_id - hub_d) / 2 + cut_overlap,
                              spoke_width,
                              part_thickness + 2 * cut_overlap]);
            }
        }
        // Axle hole through centre of hub
        translate([0, 0, -cut_overlap])
            cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_overlap);
    }
}

wheel();
