$fn = 96;

// ---- Dimensions (mm) ----
wheel_thickness = 8;     // overall Z thickness
outer_d         = 60;    // outer rim diameter
rim_width       = 4;     // rim width (radial)
hub_d           = 14;    // hub outer diameter
axle_d          = 6;     // axle hole diameter
spoke_count     = 6;     // number of spokes
spoke_width     = 5;     // spoke width (radial)
spoke_start_ang = 0;     // first spoke on +X axis

eps = 0.5;               // cutter overshoot

