rim_od     = outer_d;
rim_id     = outer_d - 2 * rim_width;
spoke_hub  = hub_d / 2 + 0.01;   // slight overlap into hub for clean union
spoke_rim  = rim_id / 2 - spoke_width; // spokes end inside rim

union() {
    // Rim
    difference() {
        cylinder(d = rim_od, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = wheel_thickness + 2 * eps);
    }

    // Hub
    cylinder(d = hub_d, h = wheel_thickness);

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_thickness + 2 * eps);

    // Spokes
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_ang + i * 360 / spoke_count;
        rotate([0, 0, a])
            translate([0, -spoke_width / 2, 0])
                cube([spoke_hub, spoke_width, wheel_thickness]);
        rotate([0, 0, a + 180])
            translate([0, -spoke_width / 2, 0])
                cube([spoke_rim - spoke_hub, spoke_width, wheel_thickness]);
    }
}
