hub_od       = 14;    // hub outer diameter
axle_d       = 6;     // axle hole diameter
spoke_count  = 5;     // number of spokes
spoke_w      = 4;     // spoke width
spoke_start  = 0;     // angle of first spoke (deg, +X axis)
cut_extra    = 0.5;   // cutter overshoot past faces

// Derived
rim_id = wheel_od - 2 * wheel_w;   // rim inner diameter

// Model
difference() {
    union() {
        // Rim
        cylinder(d = wheel_od, h = wheel_w);
        translate([0, 0, -cut_extra])
            cylinder(d = rim_id, h = wheel_w + 2 * cut_extra);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_od, h = wheel_w + 2 * cut_extra);

        // Spokes: hub -> rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([hub_od / 2 - 1, -spoke_w / 2, -cut_extra])
                rotate([0, 0, a])
                    cube([(wheel_od - hub_od) / 2 + 1, spoke_w, wheel_w + 2 * cut_extra]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_d, h = wheel_w + 2 * cut_extra + 2);
}
